pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        // Gap that cannot fit even the smallest plausible item is pure dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
        // Dead space relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits, mild penalty (dead space trap for lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bin pressure: discourage scattering across many open bins;
    // encourage filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Encourage closing bins that are nearly full (post_residual small but usable).
    if post_residual > 0 && post_residual <= 15 && post_residual >= 10 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (emptier bins get filled
    // when mean is high, tightening overall spread).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in stream or when
        // existing bins would leave large dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0 - progress * 10.0;
        if post_residual > 40 {
            // Opening a new bin for a big item may be better than wrecking a small bin
            new_bin_score -= 15.0;
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            // New bin can host both current and next item: attractive
            new_bin_score -= 20.0;
        }
        score = score.max(new_bin_score.min(score)) + new_bin_score - score; // blend
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that can't fit even the smallest
    // plausible item are wasted. Penalize unusable residue quadratically.
    if post_residual > 0 && post_residual < item_size {
        // gap smaller than the current item is likely dead space
        score += 2.0 * (item_size as f64 - post_residual as f64);
    }
    if post_residual > 0 && post_residual < 20 {
        score += 3.0 * (20.0 - post_residual as f64); // tiny-gap penalty
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.5;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 1.0; // next item won't fit here -> residue becomes dead space
    }

    // Slightly prefer bins below mean residual (spread load / keep big gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
