        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * it / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count == 2 && it > 0.6 * cap { score += 0.5 ; }
