                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // borrowed from best: deeper multi-tile lookahead with next item
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 25.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 15.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            // near-multiple tiling of chain residual
            let k = (cr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0) ;
                if rem <= 3.0 { score -= 18.0 * (1.0 - rem / 3.0) * (0.6 + 0.4 * progress) ; }
            }
            // chain residual well below mean item scale strands space
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
