            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    // gentle open-bin pressure early in the stream to avoid bin sprawl
    score += 3.0 * open_bins_count as f64 * (1.0 - progress) / (total_items . max (1) as f64).sqrt () ;
    score
}

