        if next_item_size > 0 && fitting_bins_count >= 2 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let fresh_rem = new_pr - nx . floor ();
            if new_pr >= nx {
                let fresh_after = new_pr - nx;
                let fresh_tile = (fresh_after % nx . max (1.0)) / nx . max (1.0);
                if fresh_tile < 0.05 && fresh_after < mean_residual . max (1.0) {
                    score -= 0.22 * (1.0 - fresh_tile / 0.05) * (0.5 + 0.5 * progress);
                }
            }
            let _ = fresh_rem;
        }
        // gen-149 mutation: item-size matching gate — when the current item's
        // size is close to the mean residual scale of open bins, a fresh bin
        // wastes capacity; prefer open bins in that regime
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let isz = item_size as f64;
            if (isz - mean_residual) . abs () <= 0.15 * mean_residual && new_pr / cap > 0.5 {
                score += 0.18 * (1.0 - (isz - mean_residual) . abs () / (0.15 * mean_residual)) * (0.6 + 0.4 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect-fill reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead-space avoidance: unusable residue penalized.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0 * (item_size as f64 - post_residual as f64) / cap;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 0.5 * (20.0 - post_residual as f64) / cap;
    }

    // Lookahead chain: if next item fits, how good is the chain leftover?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.0;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.3 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.8; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            // second-order lookahead: room for another next-item
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.4 * (1.0 - r2 / 15.0); }
            }
            // multiplicative fit: residual divisible by next item
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // sliver leftover after chain is future dead space
            if mean_residual > 0.0 && chain > 0.0 && chain < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            // next item won't fit: near-miss penalty
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.6 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress); }
            if (nx - pr) as f64 <= 3.0 { score += 0.9 * (1.0 - (nx - pr) as f64 / 3.0); }
            score += 0.2 + 0.5 * progress;
        }
    }

    // Tight-fit reward.
    let tightness = 1.0 - pr / cap;
    score -= 3.0 * tightness * tightness;

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure: fill existing bins, stronger late.
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (keep large gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // NEW-BIN CANDIDATE logic (borrowed from best, adapted).
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // fresh-bin residual usable across many future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - 0.5 * progress); }
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
            } else if nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // multi-step exact tiling: chain residual that tiles repeatedly
            // with the next item leaves zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 45.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 25.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // near-multiple of the next item: k*nx + tiny remainder is good
            let k = (cr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0) ;
                if rem <= 2.0 { score -= 35.0 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress) ; }
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // sliver relative to mean residual scale is nearly dead
            if mean_residual > 0.0 && cr > 0.0 && cr < 0.06 * cap {
                score += 30.0 * (1.0 - cr / (0.06 * cap)) ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // chain residual near mean residual tiles with typical items
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem_m = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem_m <= 3.0 { score -= 20.0 * (1.0 - rem_m / 3.0) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            // residual near mean scale: future items likely to fit well
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 15.0 * (1.0 - dev / 0.05) ; }
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // exact multiple of next item: zero future dead space in fresh bin
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 1.0 && new_pr - k * nx . max (1.0) == 0.0 {
                score -= 35.0 * (0.5 + 0.5 * progress) ;
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        // fresh residual near a multiple of mean residual: easy future fills
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 25.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // late-stream: opening a fresh bin with generous slack is fine late
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.4 { score -= 30.0 * ((slack - 0.4) / 0.6) . min (1.0) ; }
        }
        // fresh residual just below next item: dead space penalty
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 35.0 * (1.0 - (nx - new_pr) / 8.0) * (0.6 + 0.4 * progress) ;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
        // near-miss with tiny gap: leaving this residual is very costly late
        let miss = (next_item_size - post_residual) as f64 ;
        if miss >= 1.0 && miss <= 2.0 {
            score += 35.0 * (1.0 - (miss - 1.0)) * (0.5 + 0.5 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose post_residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            1000.0 + (next_item_size - post_residual) as f64 * 2.0
        };
        score += gap * 0.6;

        // Perfect chain: this bin's leftover exactly fits the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item also fits in this bin's leftover without wasting it.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 12.0;
        }
    }

    // Penalize dead space below the minimum item size (unusable residual).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: bins already tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // the fit is terrible (large dead space would be created).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 20.0 + waste * 0.4 - progress * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin chains nicely with next item
        }
    }

    // Prefer filling bins that are already mostly full (low residual before placement).
    score += (bin_residual as f64) * 0.15;

    // Mild pressure when many bins are open: consolidate.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

