    score -= (1.0 - norm_pr).powi(2) * (20.0 + 30.0 * progress);

    // Penalize opening new bins when existing bins fit, especially early/mid stream
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0 + 25.0 * (1.0 - progress);
