        // (10, 20, 25, 50) are more likely to be exactly consumed later.
        if pr % 10 == 0 || pr % 25 == 0 {
            score -= 15.0;
        }
        if pr % 5 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
