        score += 40.0;
        // Early in stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins are open with high mean residual, prefer spreading load.
        if mean_residual > 50.0 && open_bins_count > 2 {
