    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: residual close to zero is very valuable.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: close this bin completely
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: does the leftover match the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // next item fits perfectly in leftover
        } else if post_residual >= next_item_size {
            // leftover can still hold next item; reward proportional slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to lookahead: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 * gap;
        }
    }

    // Penalize residuals far below mean (fragmented bin) unless it's a perfect fit.
    let pr = post_residual as f64;
    if pr > 0.0 && mean_residual > 0.0 {
        score += 0.5 * (mean_residual - pr).abs();
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening new bins early in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        score += 120.0 + 8.0 * open_bins_count as f64;
        // but allow new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild phase pressure: later in stream, prefer tightening existing bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 30.0 * (1.0 - phase) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is best.
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);

    // Penalize dead space that is too small to hold the next item (likely wasted).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item (good chains).
            score -= 3.0 + 0.05 * post_residual as f64;
        }
    } else {
        // Last item: any fit is fine, prefer tightest.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit_bonus = if next_item_size > 0 && post_residual < next_item_size { 6.0 } else { 0.0 };
        score += 25.0 - 4.0 * crowding - 10.0 * progress + poor_fit_bonus;
        // Opening a new bin is cheap early / when many bins already open anyway.
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for bins whose residual is close to item_size (best-fit flavor).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.02 * tightness;

    // Penalize leaving residuals in the awkward 1..10 range (unusable slivers).
    if post_residual >= 1 && post_residual < 10 {
        score += 4.0;
    }

    // Slight global balance: prefer bins below mean residual to keep spread even.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear coupling: post-residual waste weighted by stream progress.
    // Late in the stream, dead space matters more; weight grows smoothly.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * 40.0 * pr_norm * pr_norm;

    // Perfect-fit reward (smooth quadratic dip near zero post-residual)
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: penalize if next item can't use the post residual (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score += 25.0 * gap_norm * gap_norm;
        // Reward when next item fits snugly after this placement
        if pr >= nxt {
            score -= 15.0 * (1.0 - ((pr - nxt) / cap));
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += 50.0 * pr_norm;
    }

    // Last-chance bin bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize bins far below mean residual (fragmentation smoothing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    // Residuals that are "clean" fractions of capacity are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Reward residuals near harmonic anchors: 0, 1/4, 1/3, 1/2, 2/3, 3/4
    let anchors = [0.0f64, 0.25, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.75, 1.0];
    let mut anchor_bonus = f64::INFINITY;
    for a in anchors.iter() {
        let d = (frac - a).abs();
        if d < anchor_bonus {
            anchor_bonus = d;
        }
    }
    score -= 18.0 * (1.0 - anchor_bonus.min(0.25) / 0.25);

    // --- Integer-division threshold classes on post_residual ---
    // Class residual by 10-wide buckets; small post residuals (<10) are dead space.
    let bucket = post_residual / 10;
    match bucket {
        0 => score += 30.0,           // dead space: strongly penalize
        1 => score += 12.0,           // hard to refill (items >=10 but few fit)
        2 => score -= 4.0,            // decent small-slot
        3 => score -= 6.0,
        4 => score -= 8.0,
        5 => score -= 10.0,           // half-full: very reusable
        _ => score -= 6.0,            // large residual: fine but less urgent
    }

    // --- Modulo coupling: does next_item_size divide into post_residual cleanly? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        let rem = post_residual % next_item_size.max(1);
        let fill_ratio = next_item_size as f64 / post as f64;
        if rem == 0 {
            score -= 14.0; // perfect chained fit
        } else if rem < 10 {
            score += 6.0; // leaves another dead sliver
        } else {
            score -= 5.0 * fill_ratio; // partial reuse reward
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item cannot use this bin's remainder
    }

    // --- Last-chance bin: closing this bin avoids opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive early in the stream or when
        // existing residuals are badly fragmented relative to the item.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - item_size as f64).abs();
        score = 45.0 + 25.0 * progress + fragmentation.min(60.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0; // a fresh bin can always chain the next item
        }
    }

    // --- Mild congestion pressure: many open bins -> prefer filling existing ones ---
    score += 0.15 * open_bins_count as f64;

    // --- Tiny lookahead tiebreak: prefer bins whose residual matches next item scale ---
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += 0.05 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (<= 9) are pure waste. Penalize the worst "dead zone" band hardest.
    if post_residual <= 9 {
        score += 40.0;
    } else if post_residual <= 19 {
        // Small gap likely unusable soon; mild penalty.
        score += 10.0;
    } else if post_residual >= 60 {
        // Large leftover is flexible; reward keeping big residual.
        score -= 8.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely; if next item won't fit but the
    // current bin could have held it, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 9 {
            score += 6.0; // leaves a gap just below next item's size
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when bin count is low (early stream, cheap to open).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = 55.0 + 3.5 * open_bins_count as f64;
        // Early stream: opening bins is cheaper (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // Don't open a bin if some bin fits nearly perfectly.
        if post_residual < bin_residual && (bin_residual - item_size) as f64 <= 5.0 {
            score += 15.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= 0.5 * open_bins_count as f64;
        // Prefer bins with below-average residual (consolidate fullness).
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals next item size -> perfect chain fill.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nx).abs() < 0.5 {
            score -= 60.0; // perfect lookahead fit
        } else if pr > nx {
            // next item still fits after this placement; reward closeness
            score -= 25.0 * (nx / pr.max(1.0));
        } else {
            // next item won't fit; penalize proportionally to wasted residual gap
            score += 10.0 * ((nx - pr) / 100.0);
        }

        // Two-step chain: can both item and next item leave tiny residual?
        let two_step = item_size as f64 + nx;
        if (bin_residual as f64 - two_step).abs() < 0.5 {
            score -= 80.0; // exact two-item fill of the bin
        }
    } else {
        // Last item: prefer minimal post_residual (best fit)
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative residual coupling: bins with residual near item size are precious.
    let res_gap = (bin_residual as f64 - item_size as f64).abs();
    if res_gap < 1.0 {
        score -= 50.0; // perfect fill now
    }

    // Penalize creating dead space unusable for typical items (small post_residual but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space below minimum item size
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 { 0.0 } else { 20.0 };
        score += 45.0 + pressure + 5.0 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // but allow new bin when mean residual is low (open bins nearly full)
        score -= 40.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            score += 6.0 * (next_item_size as f64 / cap);
        }
        // Perfect closure: residual exactly consumed by next item
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else {
        // Last item: prefer tightest fit (post_residual already handles this),
        // slight bonus for completely filling the bin.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: penalize slightly to encourage spreading across bins
    // and preserving the tightest ones (post_residual already differentiates).
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Global residual pressure: if mean residual is large, prefer filling
    // existing bins rather than opening new ones (penalize new-bin candidate).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 + 25.0 * pressure + 10.0 * progress;
        // Opening a bin early with many open bins is wasteful
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward bins tighter than average
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Discourage leaving tiny unusable slivers unless next item can use them.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = x * (1.0 + progress) * (1.0 + 0.5 * x);

    // Non-linear coupling: tight fits (small post_residual) get rewarded more later in stream
    score -= (1.0 - x).powi(3) * (1.0 + 2.0 * progress);

    // Penalize bins whose residual drifts far below mean (fragmentation)
    score += ((mean_residual - pr) / cap).abs() * 0.3;

    // Last-chance bin bonus: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.5 * (1.0 - x) * (1.0 + progress);
    } else if next_item_size > 0 && (next_item_size as u32) == post_residual {
        // Perfect fill for next item: huge reward
        score -= 8.0;
    }

    // Slight penalty for many open bins (encourage consolidation early)
    score += open_bins_count as f64 * 0.01 * (1.0 - progress);

    // New-bin candidate: only attractive when residual is large and stream early
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Tiered penalty on residual: space below 10 is unusable (items >= 10... but
    // sizes 1..100 possible), so weight residual by its "usability class".
    // Class boundaries via integer division on post_residual with quantum 10.
    let quantum: u32 = 10;
    let usable = if post_residual >= quantum { post_residual } else { 0 };
    let dead = post_residual - usable;
    score += dead as f64 * 3.0; // heavy penalty for dead space

    // Harmonic discount: residual that is a near-exact multiple of common item
    // classes (10, 20, 25, 50) is more likely reusable.
    let mods = [
        post_residual % 10 == 0,
        post_residual % 20 == 0,
        post_residual % 25 == 0,
        post_residual % 50 == 0,
    ];
    let harmonic_bonus = mods.iter().filter(|&&m| m).count() as f64;
    score -= harmonic_bonus * 4.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // penalize leaving awkward gap relative to next item
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.5;
            if gap % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here anyway; mild bonus for larger leftover
            score -= (post_residual as f64).sqrt() * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline so it only wins when open bins
    // score badly (large dead space / poor fit).
    if bin_residual == bin_capacity {
        // fresh bin: score = full capacity worth of residual, slight penalty
        // that grows as the stream progresses (prefer consolidating late).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap_f + 10.0 + progress * 20.0;
        // if many bins open, discourage adding more
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer tighter bins overall relative to mean residual
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Small penalty when this bin's residual is far from harmonic class sizes
    let half_class = (post_residual % 10) as f64;
    if half_class > 0.0 && half_class < 5.0 {
        score += 2.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are unusable "dead space". Penalize super-linearly as gap shrinks.
    let pr = post_residual as f64;
    let dead_threshold = 25.0;
    if pr > 0.0 && pr < dead_threshold {
        let severity = (dead_threshold - pr) / dead_threshold; // 0..1
        score += severity * severity * 60.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item can't fit in the post residual,
    // this placement likely forces a new bin later -> penalize.
    if next_item_size > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += 12.0;
        } else {
            score -= 6.0;
            // extra reward if next item fills the remaining gap exactly-ish
            if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
                score -= 10.0;
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // gives a decent fit. Make the empty bin attractive only for large items
    // or when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score = 55.0 + item_size as f64 * 0.2;
        if item_size >= 60 {
            score -= 20.0; // large items start fresh bins happily
        }
        if open_bins_count > 0 && mean_residual >= item_size as f64 + 20.0 {
            score += 25.0; // open bins still roomy -> don't open new one
        }
        let _ = fragmentation;
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate similar remaining gaps).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual).abs() * 0.3;
    }

    // Slight late-stream tightening: as stream progresses, favor tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly / well in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            score -= 150.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
            // Extra reward for tiny dead space after chaining.
            if chain_residual <= 10 {
                score -= 100.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a residual that nothing useful can use.
            score += 30.0;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual is below average
    // (packing tightly into fuller bins), penalize draining very full bins.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Make the empty bin attractive only for large items / bad fits.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: slightly worse than a good fit in an open bin.
        score += 40.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 0.4 * item_size as f64;
        // If many bins are open and mean residual is high, opening a new bin is cheap.
        score -= 0.05 * mean_residual;
        // Late in the stream, consolidating is better than spawning.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 * progress;
        // If only this bin fits (no competition), new bin should not win over it.
        if fitting_bins_count == 1 {
            score += 250.0;
        }
    }

    // Small penalty for many open bins to encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (k=2 lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // penalize leaving a sliver that next item can't use
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post-residual) or few bins can fit the item.
    if bin_residual == bin_capacity {
        let waste_existing = if fitting_bins_count > 0 {
            // approximate best existing post-residual via mean residual
            (mean_residual - item_size as f64).max(0.0)
        } else {
            100.0
        };
        // Prefer new bin only if existing bins would waste a lot
        let threshold = 35.0 - 10.0 * (fitting_bins_count as f64).min(3.0) / 3.0;
        if waste_existing > threshold {
            score -= 15.0;
        } else {
            score += 30.0;
        }
        // Late in the stream, avoid opening new bins (harder to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Tightness coupling: favor bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Penalize creating small unusable slivers (< next typical item scale)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Fragmentation pressure: if many open bins with high mean residual,
    // prefer consolidating into bins below the mean (filling emptier bins first)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild time-varying exploration term (deterministic, grounded in step/total)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (progress - 0.5) * (post_residual as f64 - mean_residual) * 0.1;

    // Discourage spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let t = progress;
    let dead_weight = 1.0 + 2.0 * t * t + 1.5 * t * (1.0 - t);
    score += dead_weight * (pr / cap).powi(2);

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Penalize spreading when many bins open; reward consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean residual alignment: prefer bins whose residual is near mean (avoid fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Lookahead: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr) / cap;
        if gap > 0.0 && gap < 0.25 {
            score += 1.5 * (1.0 - gap / 0.25) * (1.0 - t * 0.5);
        }
        // Reward residual that exactly accommodates next item
        if pr >= nx && (pr - nx) / cap < 0.1 {
            score -= 1.0 * (1.0 - t * 0.5);
        }
    }

    // New-bin candidate: keep it attractive early, less so late
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the post-residual: residues that are "useful"
    // for typical item sizes (multiples of 10, and small residues)
    // are penalized less than mid-range dead space.
    let res = post_residual % 10;
    let dead_penalty = match res {
        0 => 0.0,               // clean multiple of 10
        1..=4 => 2.0,           // small sliver
        5 => 5.0,               // half-class, hard to fill
        _ => 8.0,               // 6..9 awkward dead zone
    };
    score += dead_penalty;

    // Integer-division thresholds: how many items of the *next* size fit?
    if next_item_size > 0 {
        let fits_next = post_residual / next_item_size.max(1);
        score -= (fits_next.min(4) as f64) * 12.0;

        // Perfect pairing: next item exactly fills the bin.
        if next_item_size == post_residual {
            score -= 300.0;
        }
        // Next item leaves another multiple-of-10 residue (harmonic chain).
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 40.0;
        }
        // Next item cannot fit here at all: this residual is likely dead.
        if next_item_size > post_residual {
            score += 25.0 + 0.3 * (post_residual as f64);
        }
    }

    // Capacity-fraction coupling: reward filling large fractions of capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        let tight_fit_exists = (bin_residual - item_size) <= 20 && fitting_bins_count > 1;
        let mut new_bin_score = 60.0 + 0.5 * (bin_capacity - item_size) as f64;
        if tight_fit_exists { new_bin_score += 90.0; }
        if item_size >= 70 { new_bin_score -= 40.0; }
        new_bin_score += pressure * 0.15;
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += progress * 20.0;
        score = new_bin_score.max(1.0);
        return score;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (tighter bins), pushing toward compact packing.
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.2;

    // Mild preference to keep few open bins when many bins fit the item.
    if fitting_bins_count > 3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps disproportionately.
    let dead_zone = 15.0; // residuals below this are rarely reusable (items >= 1..100 though)
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < dead_zone {
            // small gap: heavy superlinear penalty
            score += (dead_zone - pr) * (dead_zone - pr) * 0.8;
        }
        // reward residuals that exactly match plausible future item sizes
        if next_item_size > 0 && (pr - next_item_size as f64).abs() < 1.0 {
            score -= 25.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // more open bins => more pressure to fill existing ones => new bin costlier
        score += open_bins_count as f64 * 6.0;
        // late in the stream, opening new bins is cheaper (fewer future items to place)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 25.0;
        // if the item would leave a large usable residual in the new bin, mild discount
        score -= (bin_capacity - item_size) as f64 * 0.15;
    } else {
        // existing bin: reward tight packing relative to mean residual
        score -= (mean_residual - pr) * 0.4;
        // pressure: with many open bins, prefer filling existing ones
        score -= open_bins_count as f64 * 2.0;
        // lookahead: if next item fits the post residual, big reward
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size as u32).min(20) as f64 * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual that can still fit the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Penalize dead space: post_residual too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Compare against mean residual across open bins: tighter-than-average fit is good.
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.35 * mean_diff;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer filling existing bins more when many bins are open.
    score -= 1.5 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    // Early in stream, slightly favor opening fresh bins for large items to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for exact full utilization.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward small residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 15.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // More tolerable early in the stream and when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score += 0.15 * open_bins_count as f64;
        // If mean residual across open bins is small, opening fresh space is reasonable.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 30.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Slight preference for bins below-average fullness to balance load,
        // but keep tight-fit dominance.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs().signum()
            * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = post;

    // Squared dead-space penalty: strongly discourage medium-size leftovers
    let post_frac = post / cap;
    score += 30.0 * post_frac * post_frac * cap;

    // Cubic coupling with stream progress: early on tolerate slack less
    score += 20.0 * (1.0 - progress) * post_frac * post_frac * post_frac * cap;

    // Reward filling bins nearly exactly (post close to 0)
    score -= 15.0 * (-post / 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins whose residual is far below the mean residual (fragmented bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 12.0 * (1.0 - (post - nx) / cap);
        } else {
            score += 8.0 * (nx - post) / cap;
        }
    }

    // Mild penalty for opening a new bin when many bins are open and it's late
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues that pair well with common item sizes ---
    // Items 1..100; small residuals (<=10) are near-dead space, penalize gently.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 25.0; // near-perfect fill
    } else if pr <= 15 {
        score += 15.0; // awkward dead zone
    } else if pr <= 30 {
        score += 5.0;
    } else if pr <= 50 {
        score -= 8.0; // still useful for mid-size items
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // the common size grid and are easier to fill exactly later.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Odd small residues are hardest to fill.
    if pr % 2 == 1 && pr <= 20 {
        score += 4.0;
    }

    // --- Lookahead coupling (k=2): reward residuals that can host next_item_size ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, scaled by tightness of fit
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - slack * 0.15;
            // exact pairing bonus
            if pr == next_item_size {
                score -= 12.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.12;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- Capacity fraction thresholds: prefer leaving >1/2 or ~0 of capacity ---
    let half = bin_capacity / 2;
    if pr > half {
        score -= 4.0; // residual above half stays flexible
    } else if pr > half / 2 && pr < half {
        score += 3.0; // quarter-to-half zone is moderately wasteful
    }

    // --- Stream progression: late in the stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // --- Mean-residual coupling: when open bins are already loose, prefer tight fits ---
    score += (mean_residual - pr as f64) * 0.08;

    // --- New-bin candidate handling: empty bin should only win when fits are bad ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // (spreading load can help) or late in the stream.
        score = 55.0 - (open_bins_count.min(20) as f64) * 1.2 - progress * 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.0; // new bin always hosts next item; no penalty
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

