            let orphan = (post_residual as f64 - mean_residual).max(0.0);
            score += 30.0 + 0.3 * orphan;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual is below average
    // (packing tightly into fuller bins), penalize draining very full bins.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
