        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // very tight new bin: avoid creating a fresh near-full bin
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // late stream: opening fresh bins is cheaper
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // lookahead on the new bin's residual
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        // prefer opening when many bins are open and item is large
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        // mid-stream moderate slack new bins are attractive
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        // next item won't fit in the new bin either
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // dead space vs mean residual in the new bin
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual . max (new_pr . min (mean_residual))) / cap ;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead . min (0.2) ; }
        }
        // identical consecutive items pair well in a fresh bin
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable, zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of post_residual with next item is a gift.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild bonus proportional to leftover slack after both.
            let two_step_slack = post_residual - next_item_size;
            score -= (two_step_slack as f64) * 0.5;
        } else {
            // Next item won't fit: small residual is wasted dead space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize creating tiny unusable slivers (< 10 by classical range, be safe: < 5).
    if post_residual > 0 && post_residual < 5 {
        score += 50.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Relative tightness against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream, consolidation matters more: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above using an existing decent bin.
        score += 10.0 + 40.0 * progress;
    }

    // Mild penalty for very full open bins count growth pressure.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best; add convex penalty for waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small post-residual that could still host a typical small item is fine;
    // penalize residual in the "dead zone" (1..10) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 18.0 - 0.3 * slack as f64;
    }
    // If next item cannot fit in post_residual, mild penalty proportional to leftover.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer fuller bins (smaller residual).
        score += 0.05 * bin_residual as f64;
    }

    // Prefer bins whose residual is below the mean residual (fuller than average).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream: be picky, favor opening fresh bins for large items to
    // keep flexibility; later: consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when the item is large relative
        // to mean residual and fits would be poor.
        let early_bonus = 20.0 * (1.0 - progress);
        let poor_fit = if post_residual < 10 { 15.0 } else { 0.0 };
        let many_open = 0.5 * open_bins_count as f64;
        score -= early_bonus + poor_fit + many_open - 5.0;
    } else {
        // Late in the stream: penalize opening new bins; reward consolidation.
        score += 10.0 * progress;
    }

    // Slight preference to keep number of open bins small overall.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling: penalize small unusable residuals more strongly
    // as the stream progresses (dead space matters more late in the stream).
    let dead_penalty = (1.0 - x).powi(3) * (1.0 + 2.0 * progress);
    score += dead_penalty * 8.0;

    // Reward tight fits with smooth quadratic term (low post residual rewarded).
    score -= (x * x) * 4.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead coupling: if next item fits in post residual, reward smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 3.0 * (1.0 - slack).powi(2);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving residual close to next size.
        let gap = (pr - (next_item_size as f64 - 1.0)).abs() / cap;
        score += 1.5 * (1.0 - gap).powi(2);
    }

    // Contextual smooth terms: crowded bin pools and low mean residual favor consolidation.
    let density = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += density * (mean_residual / cap) * 2.0;

    // Brand-new bin candidate: penalize opening a new bin unless residual would be large.
    if bin_residual == bin_capacity {
        score += 5.0 - 3.0 * progress;
        if fitting_bins_count >= 1 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    let dead_weight = 1.0 + 2.5 * t * t + 1.2 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = (pr - nx) / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        let gap = (nx - pr) / cap ;
        if gap > 0.0 && gap < 0.25 {
            score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
        }
        if pr >= nx && nx > 0.0 {
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 { score -= 0.2 * (1.0 - t * 0.3) ; }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / (mean_residual . max (1.0)) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count == 2 { score += 0.7 * (1.0 - t) ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 { score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ; }
            if new_pr < nx && nx - new_pr <= 8.0 { score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 { score -= 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "coarse" residue class (multiple of 10) are more reusable.
    let post_class = post_residual % 10;
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else if post_class == 0 {
        score -= 12.0; // nicely aligned leftover, likely reusable
    } else if post_class <= 3 {
        score += 6.0; // small awkward sliver -> dead space risk
    } else if post_class >= 7 {
        score += 3.0;
    }

    // Integer-division thresholds on post_residual: classify leftover size bands.
    let band = post_residual / 10; // 0..10
    score += match band {
        0 => 20.0,           // leftover < 10: nearly dead space
        1 => 8.0,            // 10..19: fits only small items
        2 | 3 => -4.0,       // 20..39: decent
        4 | 5 => -8.0,       // 40..59: very reusable
        _ => -10.0,          // 60+: large leftover, great bin
    };

    // Coupling with next item: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + (next_item_size as f64) * 0.05;
            // harmonic check: leftover after hypothetically placing next item
            let rr = post_residual - next_item_size;
            if rr % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 7.0; // this bin cannot take the next item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: encourage consolidation into
    // already-open bins rather than spawning more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large and would leave a badly fragmented residual elsewhere.
    if bin_residual == bin_capacity {
        let frag_penalty = if post_class <= 3 { 18.0 } else { 0.0 };
        score = 45.0 + frag_penalty - (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score -= 10.0; // no open bin helps the next item either
        }
    }

    // Slight recency tiebreak via step progression to stabilize selection.
    score += 0.001 * (step_index % 7) as f64;

    score
}

