        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 { score -= 0.15 ; }
        // mutation: penalize opening a new bin when the item nearly fills an existing fit
        if fitting_bins_count >= 1 && item_size as f64 >= 0.85 * cap { score += 1.2 ; }
        // mutation: prefer new bins early for large items to avoid fragmentation later
        if t < 0.25 && item_size as f64 <= 0.4 * cap { score += 0.2 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 { score += 0.65 * (1.0 - t * 0.3) ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else {
        // Tight fits are good: reward small (but usable) post residuals.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 18.0 * tightness;

        // Bonus when the leftover space can still accommodate the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize leftovers that are big enough to look useful but smaller than
        // the next item (tempting dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new ones;
    // the empty new-bin candidate gets a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well (large dead space elsewhere), allow opening:
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Mild reward for consolidating when many bins are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Early in the stream, be more willing to open bins (better long-run packing);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress;
    }

    // Prefer bins whose residual is below the mean (consolidating tighter bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    let mut score = pr / cap;

    // Dead space penalty, weighted by progress
    let dead_weight = 1.0 + 2.0 * t * t + 1.5 * t * (1.0 - t);
    score += dead_weight * (pr / cap).powi(2);

    // Perfect fill is the strongest signal
    if post_residual == 0 {
        score -= 8.0;
    }

    // Reward tight fits
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus: only fitting open bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Penalize spreading when many bins open; reward consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean residual alignment
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Lookahead: chain-fit analysis with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 4.8;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 {
                score -= 0.9;
            }
            if chain_residual >= 20.0 && chain_residual <= 60.0 {
                score -= 0.25;
            }
            // Second-level chain: residual after next item fits yet another copy
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 {
                    score -= 0.45 * (1.0 - r2 / 15.0);
                }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 {
                        score -= 0.25 * (1.0 - r3 / 8.0);
                    }
                }
            }
        } else {
            // Residual too small for next item: orphan penalty, worse late
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * t;
            let miss = nx - pr;
            if miss <= 3.0 {
                score += 1.0 * (1.0 - miss / 3.0);
            }
        }
        // Barely-miss penalty
        let gap = (nx - pr) / cap;
        if gap > 0.0 && gap < 0.25 {
            score += 1.5 * (1.0 - gap / 0.25) * (1.0 - t * 0.5);
        }
        // Multiplicity alignment: residual near k*next_item
        if pr >= nx {
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 {
                score -= 0.35 * (1.0 - mult_err / 2.0);
            }
        }
        // Residual near multiple of current item
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && k <= 4.0 && (pr - k * isz).abs() <= 1.5 {
                score -= 0.2 * (1.0 - t * 0.3);
            }
        }
    }

    // New-bin candidate logic (borrowed refinements)
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64;
        score -= 0.45 * fit_ratio;
        if fitting_bins_count == 1 {
            score += 2.5; // don't open new bin when only one fits
        }
        if fitting_bins_count >= 4 {
            score -= 0.4; // prefer new bin when spread is wide
        }
        if next_item_size as f64 > 0.7 * cap {
            score -= 0.6;
        }
        if item_size as f64 >= 0.9 * cap {
            score -= 0.55;
        }
        if t > 0.7 {
            score -= 0.25 * (t - 0.7) / 0.3;
        }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 {
                score -= 0.55 * (1.0 - r / 5.0);
            }
            if new_pr >= 2.0 * next_item_size as f64 && 2.0 * next_item_size as f64 - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * next_item_size as f64 - new_pr) / 6.0);
            }
        }
        if next_item_size as f64 > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 {
                score += 1.3 * (1.0 - slack / 0.1);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Orphan residual that narrowly misses next item
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3);
        }
        score += 0.2 * post_residual as f64 / cap;
    }

    score
}

