pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convex penalty
    // so that small residuals are strongly favored over medium ones.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, heavily reward this bin (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 60.0;
        } else if nxt <= pr {
            // Next item fits: reward proportionally to how well it uses the leftover.
            score -= 25.0 * (nxt / pr.max(1.0));
        } else {
            // Next item will NOT fit here: penalize leaving a residual that is
            // "almost but not quite" large enough (wasted dead space).
            let waste = (nxt - pr) / bin_capacity as f64;
            score += 40.0 * waste;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are good targets;
    // bins looser than the mean should be saved for larger future items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that would be nearly emptied.
        score -= 10.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // New-bin candidate: only attractive when nothing fits well or the stream
    // is early with plenty of future items needing space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins when a decent fit exists elsewhere.
        if post_residual == 0 {
            // impossible for empty bin, guard anyway
            score -= 50.0;
        }
        score += 45.0;
        score -= 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is the right call
        }
    }

    // Slight preference to fill bins that are already small relative to capacity.
    score += 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0 (non-linear).
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Penalize dead space proportional to how unusable it is relative to
    // typical item sizes (approximated via mean residual scale).
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item could co-fit in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here too: chain placement is good
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if next_item_size > post_residual && next_item_size > bin_residual {
            // next item is huge; keep current bin tight anyway
            score -= 2.0;
        } else {
            // next item won't fit residual: mild penalty for wasting space
            score += 0.03 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Time horizon: early in stream, be more selective (avoid fragmenting bins
    // early); late in stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, especially when open bins have room.
        let mut new_bin_penalty = 20.0;
        new_bin_penalty += 3.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            new_bin_penalty += 10.0 * (mean_residual / bin_capacity as f64);
        }
        // Late in the stream, opening new bins is less harmful.
        new_bin_penalty *= (1.0 - 0.5 * progress);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            new_bin_penalty -= 12.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: mild bonus when its residual is below mean (compact bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Prefer bins whose residual is close to item size (best-fit flavor).
        let fit_gap = (bin_residual - item_size) as f64;
        score -= 4.0 * (1.0 - fit_gap / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
