    // Lookahead: if the next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / pr.max(1.0);
            score -= 20.0 * fill * (1.0 + t);
        } else {
            // penalize leaving residual that cannot serve the next item
            score += 10.0 * t * (nxt - pr) / cap;
        }
    }

    // Coupling with mean residual: avoid making this bin an outlier vs. fleet
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Mild penalty for many open bins: prefer consolidating into existing bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * t;
    }

    score
}

