            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
        }
        let gap = (nx - pr) / cap ;
        if gap > 0.0 && gap < 0.25 {
            score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
        }
        // near-miss: barely cannot fit next item
        if pr < nx && (nx - pr) <= 3.0 {
            score += 1.0 * (1.0 - (nx - pr) / 3.0) ;
        }
        // item itself fills residual with minimal waste
        let isz = item_size as f64 ;
        if pr >= isz && isz > 0.0 {
            let k = (pr / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (pr - k * isz) . abs () <= 1.5 {
                score -= 0.25 * (1.0 - t * 0.3) ;
            }
        }
    }
    // congestion: penalize spreading across many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual . max (1.0) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        // new-bin candidate
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // tight new-bin slack: opening wastes little
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = new_pr / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap > 0.0 && gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if nx - pr <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        if pr >= nx {
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (pr - k * isz) . abs () <= 1.5 { score -= 0.2 * (1.0 - t * 0.3) ; }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / (mean_residual . max (1.0)) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 { score += 0.65 * (1.0 - t * 0.3) ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "clean"
    // fractions of capacity are more reusable by future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible into fine classes of 10 (harmonic grid).
    let class = post_residual / 10; // 0..=10
    let class_center = (class * 10) as f64;
    let in_class_offset = post - class_center;

    // Reward low classes (small waste) with a multiplicative discount.
    let class_bonus = (11.0 - class as f64) * 3.0;
    score -= class_bonus;

    // Penalize residual that is just above a common item-size multiple
    // (dead space that no typical item can fill nicely).
    for m in [10u32, 20, 25, 30, 40, 50].iter() {
        if *m > post_residual {
            let gap = (*m - post_residual) as f64;
            if gap <= 9.0 {
                score += (10.0 - gap) * 1.5; // just below a harmonic size: bad
            }
        } else if *m == post_residual {
            score -= 8.0; // perfect harmonic fit leftover
        }
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chainability; prefer residual that exactly chains.
            score -= 6.0 + (9.0 - slack.min(9.0)) * 0.8;
        } else {
            // Cannot chain: penalize proportionally to overflow distance.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.5;
        }
    } else {
        // Last item: pure waste minimization.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has high raw post_residual,
    // add a mild opening penalty so it only wins when open bins are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap and diversifies residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score -= (1.0 - progress) * 10.0;
    }

    // Mean residual context: prefer bins whose post-residual brings the
    // portfolio of residuals toward balance (harmonic diversity).
    let dev = (post - mean_residual).abs();
    score += dev * 0.15;

    // Mild congestion control: many open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Small tie-break on in-class offset (prefer rounder residuals).
    score += in_class_offset * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0; // only fits tiny items
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        // Usable gap: reward proportionally to how well next item could use it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // lookahead fits into leftover
        }
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0 * (1.0 - progress * 0.5);
    score += pressure;

    // New-bin candidate handling: baseline cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only if all existing fits are terrible
        score = 80.0 + pressure * 0.5;
        if fitting_bins_count == 0 {
            score = -50.0; // forced: no open bin fits
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 20.0; // room for lookahead in fresh bin
        }
        return score;
    }

    // Mild bonus for keeping residual near mean (balance across bins)
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), like best-fit.
    score += (post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect chain fit: place here strongly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one; better the tighter the leftover after both.
            let chain_left = post - nxt;
            score -= 25.0 - chain_left * 0.4;
        } else {
            // Next item won't fit here after placing current item.
            // Penalize proportionally to how much of next item is "wasted" capacity-wise,
            // but soften if post_residual is small (dead space is minimal anyway).
            let gap = nxt - post;
            score += gap * 0.6;
            if post_residual < 10 {
                score += 8.0; // tiny unusable sliver, mildly worse
            }
        }

        // Coupling with mean residual: if this bin's post residual deviates far below
        // mean, it's a good consolidation; if far above, it's fragmenting.
        let dev = post - mean_residual;
        score += dev * 0.15;

        // If next item could have fit in the pre-placement residual but not post,
        // we destroyed a chance for the next item — penalize.
        if bin_residual >= next_item_size && post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // Last item: pure best-fit, minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (huge post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (post_residual as f64) * 0.2;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open
    // bin offers a decent fit. Penalize the empty bin so we prefer reuse unless
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // New bin: post_residual = capacity - item_size.
        // Penalize mildly; the reward for tight fits elsewhere should dominate.
        score += 20.0;
        // But if the item is huge, a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If many open bins are nearly full (low mean residual), new bin is fine.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Slight preference to fill older/crowded bin sets: keep open_bins_count low.
    score += open_bins_count as f64 * 0.05;

    // Late in the stream, be more conservative (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Perfect chain: item + next fills the bin exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream be conservative (favor new bins for big items),
    // later be aggressive about filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon_bonus = progress * 8.0;
    if bin_residual < bin_capacity {
        score -= horizon_bonus;
    }

    // Global state coupling: penalize using bins whose residual deviates from mean
    // (keep residual distribution uniform for future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // When many bins are open, prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * fullness;

    // New-bin candidate: baseline cost so it's chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
        // If the item is large and would leave a big hole elsewhere, new bin is attractive.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let early = (1.0 - progress) * (1.0 - progress);
    score += 8.0 * early * norm_pr * norm_pr * cap * 0.01;
    score -= 6.0 * progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth interaction with mean residual
    let mean_gap = mean_residual - pr;
    score += 0.15 * mean_gap * (0.5 + progress);

    // Dead-space penalty: post residual too small for typical next items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (1.0 - pr / nxt) * (0.5 + progress);
        } else {
            let fit_quality = pr / nxt;
            score -= 4.0 * (1.0 - (fit_quality - 1.0).min(1.0).max(0.0)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize opening new bins as stream progresses, unless residual is tiny
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 3.0 * (open_bins_count as f64).sqrt();
        if pr > 0.0 && pr < 20.0 {
            score -= 8.0;
        }
    }

    // Tight fit reward (non-linear)
    let tight = 1.0 - (pr / cap);
    score -= 5.0 * tight * tight * tight * cap * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" slots
    let r = post_residual % 10;
    // Dead-space penalty: post_residual in 1..9 is worst (can't fit min-size-10 style items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward post_residuals that are "harmonically clean": multiples of 25 or 50
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 {
        score -= 4.0;
    }
    // Small residue classes (r in 0..3) are nearly dead space at small magnitudes
    if r > 0 && r <= 3 && post_residual < 25 {
        score += 8.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains where the next item also fits (harmonic nesting)
            let nested = post_residual % next_item_size;
            score -= 4.0 + (nested as f64) * 0.15;
            if nested == 0 {
                score -= 6.0; // exact divisibility: perfect harmonic chain
            }
        } else {
            // Next item won't fit here: penalize leaving tight residuals that strand it
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 5.0 + gap * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let crowded = mean_residual / bin_capacity as f64;
        // Early stream: open bins freely; late stream: prefer filling existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - progress * 12.0 + crowded * 10.0 - pressure * 0.5;
        // If current fit leaves ugly residue, new bin becomes relatively better
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
    }

    // Slight preference for bins tighter than the mean (best-fit flavor)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Integer-division threshold on residual tier: bins with residual in [50,74] are prime targets
    let tier = post_residual / 25;
    match tier {
        0 => score -= 3.0,           // 0..24: tight, good if not dead
        1 => score -= 5.0,           // 25..49: sweet spot
        2 => score -= 1.0,           // 50..74
        _ => {}                       // 75..99: loose
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
        }
        let gap = (nx - pr) / cap ;
        if gap > 0.0 && gap < 0.25 {
            score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
        }
        if pr < nx && (nx - pr) <= 3.0 {
            score += 1.0 * (1.0 - (nx - pr) / 3.0) ;
        }
        if pr > nx {
            let wasted = (pr - nx) / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
        }
        if pr >= nx && nx > 0.0 {
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / (mean_residual . max (1.0)) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual . max (new_pr . min (mean_residual))) / cap ;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead . min (0.2) ; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual gaps are unusable (items >= 10 in classic,
    // but sizes 1..100 unknown, so treat tiny gaps < 8 as dead space).
    if post_residual > 0 && post_residual < 8 {
        score += (8 - post_residual) as f64 * 12.0;
    }

    // Reward very tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack < 8 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would NOT fit in post_residual, this gap may be wasted.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // (penalize the new-bin candidate implicitly via count term on all bins equally,
    //  but add mild bonus to reuse when few bins fit).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets post_residual = capacity - item_size.
    if bin_residual == bin_capacity {
        // Prefer new bin only when item is large relative to residuals and
        // existing residuals are fragmented (high mean_residual spread vs item).
        if mean_residual > item_size as f64 * 1.8 && open_bins_count > 3 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for bins with residual close to item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    score
}

