pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it moderately attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // Penalize opening a new bin when the item fits snugly in an existing bin.
        if post_residual as f64 <= mean_residual {
            score += 25.0;
        }
        // Early stream: prefer reusing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.5 {
            score += 15.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // next item still fits
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            let over = (next_item_size - post_residual) as f64;
            score += 0.3 * over.min(60.0);
        }
    }

    // Reward tight fits relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize large dead space strongly (non-linear).
    if pr > 0.0 {
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

