pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small unusable leftovers (< 10 becomes dead space).
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus when next item exactly pairs with leftover.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if bin_residual >= next_item_size && post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; mild penalty for wasting space now.
            score += 3.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: early in the stream, be more conservative (prefer keeping
    // large residuals for the future); late, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Crowding: with many open bins, prefer consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is huge relative to typical
    // residual or nothing fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Large items start fresh bins more willingly early on.
        score -= progress * 10.0;
    }

    // Small coupling: reward near-perfect fits nonlinearly.
    let perfect = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * perfect * perfect * fill_ratio;

    score
}

