            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / (mean_residual . max (1.0)) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    // NEW: penalize stranded residual — post_residual that cannot host the next item
    // and is too small to be useful later becomes dead space; scale with progress.
