    // Exact-fill bonus: residual fully consumed
    if post_residual == 0 {
        score -= 7.5;
    }

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let t = progress;
    let dead_weight = 1.0 + 2.0 * t * t + 1.5 * t * (1.0 - t);
    score += dead_weight * (pr / cap).powi(2);

    // Reward tight fits
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Penalize spreading when many bins open; reward consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean residual alignment
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Lookahead: chain planning around the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            // Perfect chain: next item exactly fills this bin
            score -= 4.5;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.2 * (1.0 - chain_residual / cap);
