        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = pr / cap ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            let wasted = (pr - nx) / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress) ; }
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * progress ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5) ;
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0) ;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3) ;
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) ;
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / (mean_residual . max (1.0)) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
        let dead = pr / cap ;
        if dead > 0.4 { score += 0.3 * (dead - 0.4) ; }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    // Fill ratio of the bin after placement (0..1)
    let fill = 1.0 - (post_residual as f64 / cap);

    // Non-linear tightness reward: strongly favor placements that leave little residual.
    // Tight-fit bonus grows as fill^3, and intensifies as the stream progresses.
    let tight_bonus = (fill * fill * fill) * (30.0 + 50.0 * progress);
    score -= tight_bonus;

    // Smooth penalty for residual that is awkwardly small-but-nonzero:
    // residual near 1..20 is dead space; near cap it's a fresh bin (fine).
    let r = post_residual as f64;
    let dead = ((r / cap) * std::f64::consts::PI).sin(); // peaks at r = cap/2 (useless mid residuals)
    score += 12.0 * dead * dead;

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin, especially early/mid stream.
    if fitting_bins_count == 1 {
        score -= 25.0 + 40.0 * (1.0 - progress);
    }

    // New-bin candidate handling: a fresh bin should only win when no open bin
    // fits well. Penalize the empty-bin candidate smoothly by how much slack
    // already exists across open bins, but relax late in the stream.
    if bin_residual == bin_capacity {
        let slack = mean_residual * open_bins_count as f64;
        score += 15.0 + (slack / cap).sqrt() * 20.0 * (1.0 - progress);
        // But if the next item is large, a fresh bin is attractive (pairing potential)
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 18.0;
        }
    } else {
        // Reward bins whose residual still accommodates the lookahead item
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 10.0 + 8.0 * progress;
        }
        // Mild penalty when bin residual diverges from mean residual (keeps bin pool uniform)
        let dev = (post_residual as f64 - mean_residual).abs() / cap;
        score += 6.0 * dev * dev;
    }

    // Slight preference to consolidate into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
