pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" capacity fractions (0, cap/4, cap/2, 3cap/4) are more reusable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * quarter;
    let harmonic_bonus = if post_residual == 0 {
        60.0
    } else if post_residual == quarter || post_residual == threeq {
        35.0
    } else if post_residual == half {
        30.0
    } else if post_residual % 10 == 0 {
        18.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division dead-space class: leftover smaller than the smallest
    // plausible item is nearly dead; penalize by how far below thresholds.
    let small_thresh = 10u32;
    if post_residual < small_thresh && post_residual > 0 {
        score += (small_thresh - post_residual) as f64 * 6.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the
    // post residual (perfect chaining), or at least fits comfortably.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // mod-4 class of slack: small slack = tight, good packing
            score -= 20.0 - (slack % 4.0) * 2.0 + slack * 0.15;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by the overflow amount's integer-division class
            let over = (next_item_size - post_residual) as f64;
            score += (over / 8.0).floor() * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it attractive
    // only when open bins are crowded or the current fit is very loose.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / cap; // high = open bins are full
        let fit_quality = 1.0 - (post_residual as f64 / cap);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_bonus = (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= tightness * 45.0 + open_bonus + progress * 5.0;
        score += (1.0 - fit_quality) * 10.0; // empty bin has max post_residual, mild penalty baseline
    }

    // Prefer tighter fits generally: exact-fill class via integer division.
    let fill_class = (item_size * 4) / bin_capacity; // 0..=3 quarter classes
    score -= fill_class as f64 * 4.0;

    // Mild preference to spread load when many bins are open and mean
    // residual is low (avoid overloading the single best bin).
    if open_bins_count > 3 && mean_residual < cap * 0.2 && bin_residual > post_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.4 * t * t + 1.3 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // multi-step lookahead: item + next + next-next
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // multiplicity fit: residual is k * next_item (near-exact repeated packing)
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0) ;
            }
        }
        // small gap: leaving too little room for next item wastes space
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // crowd penalty grows slightly with progress to consolidate late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / (mean_residual . max (1.0)) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        // new-bin candidate: open when item is large or few fitting bins
        let it = item_size as f64 ;
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * it / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if it > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if it >= 0.9 * cap { score -= 0.55 ; }
        // avoid opening a bin that will strand a tiny residual
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
