}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space), with a mild non-linear kick.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving residuals that are unlikely to be usable later.
    // Small residuals (<10) are dead space; mid residuals (10..50) are useful.
    if post_residual < 10 {
        score -= 6.0; // filling a bin completely is great
    } else if post_residual > 50 {
        score += 4.0; // leaving a huge residual means poor fit choice
    }

    // Lookahead: if the next item fits exactly in the post-residual, strong bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next == 0 {
                score -= 15.0; // perfect chain
            } else if slack_after_next < 10 {
                score -= 8.0; // near-perfect chain
            } else {
                score -= 3.0; // next item still fits, mild bonus
            }
        } else {
            // Next item won't fit here; if this bin was the only option, prefer
            // using it rather than blocking it with a bad choice.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual < bin_capacity {
        score -= 2.0 * pressure.min(5.0);
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps residual distribution uniform and predictable for future items).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // New-bin candidate handling: an empty bin is a costly resource.
    // Only attractive when the item is large relative to capacity (few future
    // chances to pack it well) or no good existing fit exists (many competing bins).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin.
        score += 18.0;
        // Large items are hard to place later, so a fresh bin is more acceptable.
        score -= 20.0 * fill_ratio * fill_ratio;
        // If few bins can fit this item, opening new is less wasteful.
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheaper (long horizon to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
        // If mean residual across open bins is small, existing bins are crowded;
        // a new bin is more justified.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

