    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * t + (open_bins_count as f64) * 0.2;
    }

    // Discourage opening extra bins when many are open with slack
    score += (open_bins_count as f64).ln().max(0.0) * p * 2.0;

    score
}

