    if post_residual == 0 { score -= 800.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nx {
            score -= 450.0;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 120.0 * (1.0 - chain_residual / cap);
            if chain_residual <= 10 { score -= 80.0; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0; }
            // second-fit lookahead: prefer residuals that fit next item twice
            if chain_residual > nx {
