            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 30.0 * (1.0 - mult_err / 2.0); }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 25.0 + 0.3 * orphan + 50.0 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 150.0 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 80.0 * (1.0 - (nx - pr) / 3.0); }
        }
    }
    if bin_residual == bin_capacity {
        score += 40.0;
        score -= 0.4 * item_size as f64;
        score -= 0.05 * mean_residual;
        score += 50.0 * progress;
        if fitting_bins_count == 1 { score += 250.0; }
        if fitting_bins_count >= 4 { score -= 30.0; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0; }
        if item_size as f64 >= 0.9 * cap { score -= 55.0; }
        // prefer new bin when its post-residual nearly matches next item
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 55.0 * (1.0 - r / 5.0); }
        }
        // avoid opening bins that strand the next item
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 50.0 * miss.min(0.3);
        }
        // tight slack penalty when other bins could also fit
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 130.0 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 25.0 * (progress - 0.7) / 0.3; }
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 65.0 * (1.0 - progress * 0.3);
        }
    }
    // mild dispersion penalty: avoid bins far from mean residual (dead-space control)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 30.0 * dev * dev * (1.0 - progress * 0.5);
    score
}

