pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Residuals in a "good" class (small, or large
    // enough to host a typical next item) are rewarded; awkward mid-range
    // residuals are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // in [0,1]

    // Integer-division harmonic classes on post_residual (bucket width 10):
    // class 0 => near-perfect fit, class k grows worse.
    let harmonic_class = post_residual / 10;
    let class_penalty = match harmonic_class {
        0 => -30.0,           // near-perfect fit: strongly favor
        1 => -12.0,           // 10..19 leftover: still very usable
        2 | 3 => -4.0,        // 20..39: moderately usable
        4 | 5 => 8.0,         // 40..59: dead-space risk zone
        6 | 7 => 2.0,         // 60..79: large residual, item was small
        _ => -6.0,            // 80..99: item tiny, bin mostly empty
    };
    score += class_penalty;

    // Modulo-3 style harmonic refinement: residuals congruent to small
    // multiples of common item sizes (e.g. 10/20/25/50) are more reusable.
    let m25 = post_residual % 25;
    let m50 = post_residual % 50;
    if m25 == 0 && post_residual > 0 { score -= 5.0; }
    if m50 == 0 && post_residual > 0 { score -= 4.0; }
    if m25 <= 5 && post_residual >= 25 { score += 3.0; } // awkward sliver

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Next item fits here: reward proportionally to tightness.
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 10.0 + 15.0 * tight;
        } else {
            // Next item won't fit here; penalize more if the gap is small
            // (we "wasted" a near-fit) and if this bin was the last chance.
            let gap = (next_item_size as u32 - post_residual) as f64;
            score += 4.0 + 8.0 * (1.0 - (gap / cap).min(1.0));
        }
        // Harmonic class of next item vs post residual divisibility:
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0; // residual is an exact multiple of next size
        }
    } else {
        // Last item of the stream: prefer filling existing bins fully.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using
    // it over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_frac > 0.5 { score += 10.0; } // but not if it wastes > half
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified for large items or when existing
        // bins are crowded; otherwise discourage proliferation.
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 6.0 * crowd.min(6.0) as f64 - 10.0 * progress;
        if item_size as f64 > 0.6 * cap { score -= 22.0; }
        if mean_residual < 0.15 * cap { score -= 12.0; } // existing bins nearly full
    }

    // Mild tie-breaking: prefer bins whose residual deviates from the mean
    // in the direction of tighter packing.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev;

    // Progress-based consolidation: late in the stream, favor existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_frac);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 4.8;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual.max(1.0);
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio); }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5).min(1.0); }
    }
    // NEW: dead-space penalty for open bins — residual that nothing remaining can use
    if bin_residual < bin_capacity && pr > 0.0 {
        let unusable = if next_item_size as f64 > pr { pr } else { 0.0 };
        if unusable > 0.0 {
            score += 0.22 * (unusable / cap) * (0.5 + 0.5 * progress);
        }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
