        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving a gap that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // dead space relative to known next item
        }
    }

    // Fit tightness: reward filling a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But a fresh bin is attractive if no open bin fits well (post_residual is large).
        if post_residual >= 30 {
            score -= 20.0;
        }
    }

    // Mild preference for spreading load across bins over the stream.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    let mut score = pr / cap;

    // Dead-space penalty growing with progress
    let t = progress;
    score += (1.0 + 2.0 * t * t) * (pr / cap).powi(2);

    // Exact fill is excellent
    if post_residual == 0 {
        score -= 8.0;
    }

    // Tightness reward
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Consolidation pressure
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean residual alignment
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Lookahead chain logic (borrowed & adapted)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 4.8;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.35 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if chain / cap > 0.05 { score += 0.4 * (chain / cap) * (0.4 + 0.6 * t); }
        } else {
            // Residual too small for next item: penalize near-misses
            let gap = (nx - pr) / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5);
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
            score += 0.25 + 0.55 * t;
        }
        // Item-multiple residual check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3);
            }
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64;
        score -= 0.45 * fit_ratio;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if fit_ratio >= 0.9 * cap / cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 5.0 {
                score -= 0.55 * (1.0 - (new_pr - nx) / 5.0);
            }
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
            if new_pr > 0.0 && new_pr < nx {
                let miss = (nx - new_pr) / cap;
                score += 0.5 * miss.min(0.3);
            }
        }
        if open_bins_count >= 6 && fit_ratio > 0.6 { score -= 0.3; }
    } else if next_item_size > post_residual && post_residual > 0 {
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does next item exactly fill the new residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize by leftover after next placement
            let two_step_left = (post_residual - next_item_size) as f64;
            score += two_step_left * 0.5;
        } else {
            // next item won't fit here: slight penalty proportional to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: keep residuals homogeneous
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless it enables a good two-step chain
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            200.0
        } else {
            0.0
        };
        score += 150.0 - chain_bonus;
    }

    // Late in stream: prefer tighter packing (smaller residual weighted more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Many open bins: discourage spreading, favor filling existing ones
    score += open_bins_count as f64 * 0.1;

    score
}

