                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // refined: penalize chain residuals that no small future item can use
            if chain_residual > 0.0 && chain_residual < mean_residual * 0.5 {
                score += 0.2 * (1.0 - chain_residual / (mean_residual * 0.5));
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual.max(1.0);
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio); }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5).min(1.0); }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual.max(new_pr.min(mean_residual))) / cap;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead.min(0.2); }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // new: dead-space coupling — opening a bin whose residual is far from the
        // running mean residual wastes space; penalize proportionally, softened late
        if mean_residual > 0.0 && new_pr > 0.0 {
            let d = ((new_pr - mean_residual) / cap).abs();
            score += 0.25 * d * (0.5 + 0.5 * progress);
        }
        // new: avoid opening near-duplicate small residual bins when many are open
        if open_bins_count >= 4 && new_pr < 0.25 * cap && new_pr < mean_residual {
            score += 0.3 * (1.0 - new_pr / (0.25 * cap));
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear interaction: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 20.0;
    // Penalize dead space quadratically, scaled by stream progress
    score += norm_pr * norm_pr * (1.0 + progress) * 10.0;
    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }
    // Lookahead: favor bins whose post residual can fit the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }
    // Coupling with mean residual: bins far from mean get smooth penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0;
    // Mild new-bin preference when many bins open and fit is poor
    let new_bin_bias = 5.0 + 10.0 * norm_pr * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    if bin_residual == bin_capacity {
        score -= new_bin_bias * (1.0 - tightness);
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
