        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio); }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5).min(1.0); }
        // dead-space penalty: residual too small to be useful for anything typical
        if pr < mean_residual * 0.5 && pr > 0.0 {
            score += 0.2 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) * (0.5 + 0.5 * progress);
        }
