}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // capacity fractions (cap/2, cap/3, cap/4) are more reusable -> reward.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual == half {
        score -= 12.0;
    } else if post_residual == third || post_residual == 2 * third {
        score -= 9.0;
    } else if post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 6.0;
    }

    // Modulo-10 class: residuals divisible by 10 pair better with integer item sizes.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<=10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap_f);
        }
        // If next item cannot fit here, slight penalty scaled by next size class.
        let next_class = next_item_size / 20; // 0..4 harmonic size class
        score += next_class as f64 * 1.5;
    }

    // Integer-division threshold on post_residual quartiles: prefer leaving
    // mid-range residuals over near-full bins that become junk.
    let q = post_residual / (bin_capacity / 4).max(1);
    score += match q {
        0 => 6.0,   // nearly full: likely dead space
        1 => 0.0,
        2 => -1.0,
        _ => 2.0,   // nearly empty: wasteful use
    };

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when all open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score = cap_f * 0.35 + progress * 10.0 - waste_elsewhere
            + (open_bins_count as f64) * 0.5;
    }

    // Mild preference for tighter (smaller-residual) bins overall.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
