    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals below the typical item size are near-waste.
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits proportionally
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Pressure from number of open bins: prefer consolidating into fewer bins
    // when many bins are open; allow new bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += bin_pressure * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can use this bin's post_residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to known next item
    }

    // New-bin candidate: make it attractive only when open bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - post_residual as f64;
        if mean_gap > 30.0 {
            score -= 25.0; // open bins are wasteful, prefer fresh bin
        } else {
            score += 20.0 + bin_pressure * 0.5; // prefer reusing open bins
        }
    }

    // Mild alignment with mean residual: bins deviating far from mean are
    // either unusually full (good) or unusually empty (bad)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

