        if diff == 0.0 {
            score -= 1000.0;
        } else {
            // Discount proportional to closeness of the match
            score -= (60.0 / (1.0 + diff)).min(50.0);
            // Penalize if next item cannot fit the post residual (dead space for lookahead)
            if (post_residual as f64) < next_item_size as f64 {
                score += 15.0 + 0.5 * next_item_size as f64;
            }
        }
    } else {
        // Last item: prefer minimal waste
        score += 0.0;
    }

    // Penalize creating tiny unusable residuals (dead space) that no typical item (>=1) fits well
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
