            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual.max(1.0);
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio); }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5).min(1.0); }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual.max(new_pr.min(mean_residual))) / cap;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead.min(0.2); }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // new: discourage opening a bin whose post-fill residual is unusable dead space
        if new_pr > 0.0 && next_item_size > 0 && new_pr < next_item_size as f64 {
            let dead_ratio = 1.0 - new_pr / next_item_size as f64;
            if dead_ratio > 0.5 { score += 0.4 * (dead_ratio - 0.5) * 2.0; }
        }
        // new: reward opening when new bin can chain next item nearly exactly
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let chain2 = new_pr - next_item_size as f64;
            if chain2 <= mean_residual.max(1.0) * 1.5 { score -= 0.2; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a tight fit (small dead space).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 45.0 * tightness;

    // Lookahead: reward if next item fits into the post residual (chaining),
    // penalize if post residual is too small for the next item (dead space risk).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize proportionally to unusable leftover space.
            score += 0.25 * post_residual as f64;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early/late
    // when consolidation into open bins is generally preferable.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But if mean residual of open bins is very small (all nearly full),
        // opening a new bin becomes more attractive: reduce penalty.
        score -= 40.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // Late in the stream, avoid leaving a nearly full new bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 20.0 * progress;
        }
    }

    // Mild preference for bins below mean residual (spread load evenly
    // among partially filled bins, preserving large residuals).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

