                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual.max(1.0);
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio); }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5).min(1.0); }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual.max(new_pr.min(mean_residual))) / cap;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead.min(0.2); }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // dead-space reduction: penalize new bins whose residual is unlikely to be
        // filled by the mean-sized remaining demand
        if new_pr > 0.0 && mean_residual > 0.0 {
            let fill = (new_pr / mean_residual).round();
            if fill < 1.0 {
                let orphan = (mean_residual - new_pr) / cap;
                score += 0.45 * orphan.min(0.25) * (0.5 + 0.5 * progress);
            }
        }
        // prefer opening bins whose post residual is a tight multiple of next item
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx).round();
            if k >= 2.0 && (new_pr - k * nx).abs() <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - k * nx).abs() / 2.0);
            }
        }
        // late stream: strongly avoid opening bins with large leftover slack
        if progress > 0.6 {
            let slack = new_pr / cap;
            if slack > 0.5 { score += 0.5 * (slack - 0.5) * 2.0 * (progress - 0.6) / 0.4; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes are more reusable. Reward (subtract) when post_residual
    // lies in a "friendly" class modulo 10 (item sizes 10..80 multiples
    // of 10 dominate well-behaved streams).
    let class = (post_residual % 10) as f64;
    score -= 6.0 * (1.0 - class / 10.0); // perfect multiple-of-10 residual gets max reward

    // Integer-division thresholds: residual buckets that can host typical
    // next items (>= 10) are valuable.
    if post_residual >= 10 {
        score -= 2.0 + (post_residual / 10) as f64;
    } else if post_residual > 0 {
        // dead space penalty: unusable sliver
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            // harmonic class of the double-placed residual
            let c2 = (rem2 % 10) as f64;
            score -= 8.0 * (1.0 - c2 / 10.0);
        } else {
            // next item cannot follow here; mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin offers a decent fit, or when the item is huge (near full load).
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize opening a new bin normally...
        score += 30.0;
        // ...unless the item nearly fills a bin outright (perfect class)
        if (bin_capacity - item_size) % 10 == 0 && item_size >= bin_capacity / 2 {
            score -= 22.0;
        }
        // late in the stream with many bins, prefer compacting into open bins
        score += progress * 5.0 * (open_bins_count as f64).sqrt();
        // huge items pack cleanly alone
        score -= load_frac * 8.0;
    }

    // Prefer filling bins below mean residual (compactness pressure),
    // i.e. a bin with residual below mean is tighter -> reward.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    // Modulo threshold on item size: items in awkward classes (not
    // multiples of 10) waste more space; require tighter fits.
    if item_size % 10 != 0 {
        score += (10 - (item_size % 10)) as f64 * 0.3;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 4.8;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
