    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize leaving dead space that is hard to fill (post_residual small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let lookahead_waste = post_residual - next_item_size;
            if lookahead_waste == 0 {
                score -= 40.0;
            } else if lookahead_waste < 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
