            // next item would have to go elsewhere; mild penalty if this bin becomes stranded
            score += 8.0;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral baseline, only chosen when open bins look bad
    if bin_residual == bin_capacity {
        // discourage opening new bins early / when mean residual is large
        score += 10.0 + mean_residual * 0.3 + (open_bins_count as f64) * 0.5;
        // late in stream, prefer filling existing bins even more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
        score -= open_bins_count as f64 * 0.2;
    }

    score
}

