}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post-residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match
        } else if post_residual > next_item_size {
            // partial reward proportional to how well the next item fills remaining space
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residual far below mean residual (creating unusable slivers relative to fleet)
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when decent fits exist, especially early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    // Mildly prefer tighter existing bins
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
