pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 1.5;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // chain broken
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor
    // (item small relative to residuals or residual barely exceeds item).
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        let poor_fits = if bin_residual >= item_size {
            (bin_residual - item_size) as f64
        } else { 0.0 };
        // A fresh bin is good for small items (lots of room for future pieces),
        // bad if an existing bin would be nearly perfectly filled.
        score = 8.0 + 0.35 * waste as f64 - 30.0 * fit_ratio;
        if poor_fits < 8.0 && bin_residual < bin_capacity {
            score += 25.0; // existing bin nearly perfect -> strongly prefer it
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative anyway
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64;
        score += 0.03 * (mean_residual - bin_residual as f64);
    }

    // Mild time-horizon scaling: early on, keep bins flexible (favor mid residuals),
    // late in stream, greedily minimize post_residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.08 * (post_residual as f64 - mean_residual).abs();
    score -= progress * 0.10 * post_residual as f64;

    score
}

