pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling a bin substantially (large item in this bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item can still fit in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If the next item cannot fit anywhere else but fits here after placement, keep it viable.
    if next_item_size > 0 && post_residual >= next_item_size && next_item_size as f64 > mean_residual * 0.8 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 2.0;

    // Deviation from mean residual: prefer bins that are either much fuller or much emptier than average
    // (avoid mediocre fits that fragment the bin population).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.3;

    // New-bin candidate handling: an empty bin is a fallback; penalize it moderately so it only wins
    // when all open bins have poor fits (their dead-space penalties push them above this).
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 3.0;
    }

    score
}

