        } else if (post_residual as i64 - next_item_size as i64) >= 0 {
            // next item fits after current placement: reward closeness
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item won't fit in the leftover: penalize dead space
            score += 0.6 * gap;
        }
    } else {
        // Last item: simply prefer tightest fit
        score -= 10.0;
    }

    // Prefer bins whose residual is below mean (compact usage) — tighten packing.
    score += 0.15 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for using more open bins early vs. late in stream:
    // late in the stream, avoid leaving many near-empty bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score -= 12.0 * (0.5 + 0.5 * progress); // nearly-full bin is great
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
