        // Many options: prefer the bin with least post-residual (handled by base term),
        // but slightly penalize consuming a bin that others could also use if fit is loose.
        score += 5.0 * (1.0 - tightness);
    }

    // New-bin candidate logic: opening a fresh bin has post_residual == bin_capacity.
    // Penalize opening new bins when open bins are few or stream is late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
