    // Global residual pressure: if mean residual is high, prefer reusing existing space.
    let mean_tight = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - mean_tight);
    }

    // Prefer filling bins that are already relatively full.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness;

    score
}

