        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // NEW: penalize new-bin opens whose post-residual is small dead space
        // that no open bin could absorb better (fragmentation guard)
        if new_pr > 0.0 && new_pr < 0.12 * cap && fitting_bins_count >= 2 {
            score += 0.35 * (1.0 - new_pr / (0.12 * cap));
        }
