        // by next item) promises near-perfect future fills
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx).round();
            if k >= 1.0 && (new_pr - k * nx).abs() <= 1.0 {
                score -= 0.3 * (1.0 - progress * 0.4);
            }
        }
        // NEW: prefer opening fresh bins early when open-bin pool is small,
        // giving future items more placement options
        if open_bins_count <= 2 && progress < 0.5 {
            score -= 0.2 * (1.0 - progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // NEW: extra penalty when this placement strands residual just below
        // the next item by more than a typical gap (dead space growth)
        let miss = (next_item_size - post_residual) as f64;
        if miss > 8.0 {
            score += 0.12 * ((miss - 8.0) / cap).min(0.25);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "harmonic" classes (small,
    // near-fillable by common item sizes) are cheap; mid-range dead zones
    // are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;

    // Integer-division thresholds on post_residual.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny unusable sliver: near-perfect fill, reward.
        score -= 45.0;
    } else if post_residual <= quarter {
        // Class A: leftover up to 25% — still fillable by small items (1..25).
        score -= 18.0;
    } else if post_residual <= fifth * 2 {
        // Class B: 25-40% — moderately fillable.
        score -= 6.0;
    } else if post_residual <= fifth * 3 {
        // Class C: 40-60% dead zone — penalize, hard to fill exactly.
        score += 12.0;
    } else if post_residual <= fifth * 4 {
        // Class D: 60-80% — this bin was barely used; penalize mildly.
        score += 5.0;
    } else {
        // Class E: 80-100% — nearly empty bin chosen; discourage unless new bin.
        score += 8.0;
    }

    // Modulo arithmetic: residual congruence classes. Residuals that are
    // multiples of common item sizes (10, 20, 25, 50) are easier to fill
    // exactly with typical item granularity.
    let r = post_residual;
    if r % 10 == 0 {
        score -= 10.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 4.0;
    }
    // Odd "awkward" classes: r mod 10 in {1,3,7,9} with r>10 are hard to fill.
    if r > 10 && (r % 10 == 1 || r % 10 == 3 || r % 10 == 7 || r % 10 == 9) {
        score += 7.0;
    }

    // Next-item lookahead coupling: reward if next item fits the post-residual
    // exactly or nearly; penalize if post-residual is just barely too small.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // Next item fits: the smaller the gap, the better.
            let gap = pr - ni;
            if gap <= 5.0 {
                score -= 22.0;
            } else if gap <= 20.0 {
                score -= 10.0;
            } else {
                score -= gap * 0.15;
            }
        } else {
            // Next item does NOT fit this residual: the closer post_residual
            // is to next_item_size, the more wasteful this bin choice is.
            let miss = ni - pr;
            if miss <= 5.0 {
                score += 15.0;
            } else if miss <= 15.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= quarter {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity,
    // so post_residual == capacity - item_size. Opening a new bin is good
    // when existing bins would be badly fragmented, and bad when a good
    // fit exists. Estimate fragmentation via mean_residual.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: discourage mildly.
        score += 14.0;
        // If mean residual across open bins is small (bins are tight),
        // opening a new bin is more attractive.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 18.0;
        } else if mean_residual < 30.0 {
            score -= 6.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If many bins already open, discourage adding more.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Tightness bonus: prefer bins whose fill ratio is high.
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_ratio * 12.0;

    // Mild preference to spread across bins when few are open early on.
    if open_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mean-residual alignment: bins close to the mean residual keep the
    // bin set homogeneous and easier to pack later.
    let dev = (pr - mean_residual).abs();
    score += dev * 0.08;

    score
}

