pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any small leftover gap (1..=9) is unusable
    // for typical items; penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins whose residual is much larger than the item (wasteful use
    // of a roomy bin when a tighter one exists).
    if bin_residual > item_size + 20 {
        score += 8.0;
    }

    // Open-bin pressure: discourage adding bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good fit exists elsewhere
        // or open bins are few and residuals are large.
        score = 90.0
            - 6.0 * open_bins_count as f64
            + 0.5 * mean_residual
            - if fitting_bins_count <= 1 { 70.0 } else { 0.0 }
            - if post_residual == 0 { 0.0 } else { 0.0 };
        // Late in the stream, opening new bins is cheaper to avoid dead space.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit / 100.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    score
}

