pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match reward: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match reward: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is tight vs. average.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 20.0 + 15.0 * progress - 22.0 * poor_fit;
    }

    // Mild penalty for very large leftover fragments (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny residual is fine, bin nearly full
    }

    // Slight preference for fuller bins as stream progresses.
    score -= 0.05 * (bin_capacity as f64 - post_residual as f64);

    score
}

