pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable dead space (< smallest item size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into the post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for wasting this bin's future.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or
        // mean residual is still large (existing bins have room).
        score += 10.0 + 4.0 * open_pressure + 0.15 * mean_residual;
        // But if mean residual is tiny (all bins nearly full), new bin is fine.
        if mean_residual < 10.0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward when mean residual is high (spread the load).
        score -= 0.05 * mean_residual;
    }

    // Time horizon: early in the stream, be conservative (favor tight packing
    // to build good structure); late in stream, prioritize just fitting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very loose fits regardless of phase.
    if post_residual > bin_capacity / 2 {
        score += 4.0;
    }

    score
}

