    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Dead-space penalty: residuals too small for typical future items
    let dead = if pr > 0.0 { (cap - pr) / cap } else { 0.0 };
    score += 20.0 * dead * dead * norm_pr;

    // Stream-progress coupling: tighten packing more aggressively as stream advances
    let tight = (1.0 - norm_pr).powi(3);
    score -= 15.0 * progress * tight;

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
        } else {
            score += 5.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild preference against spreading across many open bins when residuals align with mean
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish baseline, penalized slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

