pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual bucketed by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class A: post_residual <= 10 -> near-perfect, strong reward.
    if post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 2.0;
    }
    // Class B: 10 < post <= 20 -> dead-space risk zone (small items 10..20 may not arrive).
    else if post_residual <= 20 {
        score += 15.0;
    }
    // Class C: 20 < post <= 50 -> medium zone, moderate.
    else if post_residual <= 50 {
        score -= 5.0;
    }
    // Class D: post > 50 -> large leftover, but usable for future large items.
    else {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 are
    // "harmonic" with the size granularity and easier to fill later.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    }
    // Odd residuals that are prime-ish (not divisible by 5) are harder to fill.
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            // Reward chains where the two-step leftover is also harmonic/small.
            if nxt_post == 0 {
                score -= 120.0;
            } else if nxt_post <= 10 {
                score -= 30.0;
            } else if nxt_post % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover is dead unless refillable.
            score += 10.0 + post_f / cap_f * 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are poor fits (large post_residual after placement) or few fitting bins.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: moderately low, but worse than good fits.
        score = 60.0 + post_f;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 80.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If open bins exist but none fit well, new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's tighter
    // than average -> prefer it (fills the fullest bins first, Best-Fit-like).
    score -= (mean_residual - post_f) * 0.3;

    // Mild preference to keep number of open bins from exploding.
    score += open_bins_count as f64 * 0.05;

    score
}

