        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual.max(new_pr.min(mean_residual))) / cap;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead.min(0.2); }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // new: prefer new bin when its residual can exactly host the next item chain
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr == nx { score -= 0.7; }
            else if new_pr >= nx {
                let chain = new_pr - nx;
                if chain > 0.0 && chain < 0.08 * cap { score -= 0.3 * (1.0 - chain / (0.08 * cap)); }
            }
            // avoid opening a bin whose residual is a near-dead sliver
            if new_pr > 0.0 && new_pr < 0.06 * cap { score += 1.2; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: small post residual relative to capacity scale.
    score = post_residual as f64 * 1.0 + (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize leftover dead space
            score += 10.0 + gap * 0.3;
        }
    } else {
        // last item: prefer tightest fit
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against mean residual: bins with below-average residual
    // (tight bins) are better targets; loose bins get penalized.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: keep it as a fallback, slightly discouraged
    // unless its residual (full capacity) is genuinely the best fit.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (1.0 - progress);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 20.0; // fresh bin can chain current + next item
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
