}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to capacity (relative waste).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect fit leaves negligible dead space
    }

    // Penalize creating dead space smaller than the smallest possible item (1..100 range, min item unknown but <= 10 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack * 0.1); // moderate bonus, decaying with slack
        } else {
            // next item cannot use this residual: penalize proportionally to leftover size
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score -= pressure * 2.0;

    // Time horizon: early in stream, be conservative (favor new bins for large items to keep flexibility);
    // late in stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += (1.0 - progress) * (item_size as f64 / 10.0); // early: slight penalty for large items in open bins

    // New-bin candidate handling: empty bin gets a baseline cost so it's chosen only when open bins are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if no open bin fits, opening new bin is inevitable — soften.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // early stream: opening bins cheaply builds flexible capacity
        score -= (1.0 - progress) * 15.0;
    }

    // Mild coupling: item size vs residual ratio — favor bins where item consumes a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
