    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: non-linear penalty on post residual (dead space), amplified by progress
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Cubic dead-space coupling: small residuals are increasingly bad late in stream
    score += 0.8 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth exponential-like term
    score -= 2.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (0.5 + progress);
    }

    // Penalize bins far below mean residual (wasteful large-bin use) via smooth coupling
    let mean_norm = mean_residual / cap;
    score += 0.6 * (mean_norm - norm_pr) * (mean_norm - norm_pr) * (1.0 - progress);

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = pr - nx;
        if slack >= 0.0 {
            score -= 1.2 * (slack / cap) * (1.0 - progress);
        } else {
            score += 0.9 * (-slack / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for excessive open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: smooth sigmoid-ish gate on opening fresh bins
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-8.0 * (norm_pr - 0.35)).exp());
        score += 3.0 * gate * (1.0 - progress) + 1.0;
    }

    score
}

