pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "composable" residue class (small and divisible into common item sizes)
    // are rewarded, since future items can still fill them.
    let pr = post_residual;
    let class = pr / 10; // integer-division threshold classes: 0..10
    match class {
        0 => score -= 25.0,                 // perfect / near-perfect fit
        1 => score -= 14.0,                 // residual 10-19: fits small items
        2 => score -= 8.0,                  // residual 20-29: decent
        3 | 4 => score -= 3.0,              // residual 30-49: mediocre
        5 | 6 => score += 2.0,              // residual 50-69: half-empty bin risk
        _ => score += 6.0,                  // residual 70+: wasteful placement
    }

    // Modulo-5 harmonic bonus: residuals divisible by 5 align with common
    // item sizes (multiples of 5/10), making leftovers reusable.
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Residuals that are exact multiples of 10 are especially reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is part of a harmonic chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to tightness of the chain
            score -= 6.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, using it
    // avoids opening a new bin -> reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Prefer it only when no open bin offers a tight fit; otherwise penalize
    // opening a new bin to keep fragmentation low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin, softened late in the stream
        // when many bins are open and consolidation matters less.
        score += 30.0 - 10.0 * progress;
