    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_fraction;

    // Mean-residual context: if the average open-bin residual is large,
    // prefer bins below the mean (tighter bins) to consolidate waste.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
