                if dead > 0.0 { score += 0.5 * dead.min(0.25) * (0.5 + progress); }
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual.max(1.0);
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio); }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5).min(1.0); }
    }
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dead = (new_pr - mean_residual.max(new_pr.min(mean_residual))) / cap;
            if dead > 0.0 && new_pr < next_item_size as f64 { score += 0.3 * dead.min(0.2); }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // new-bin dead-space lookahead: penalize residuals no open bin could absorb better
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            let frac = (new_pr / nx).fract();
            let near_mult = frac.min(1.0 - frac);
            if near_mult * nx > 6.0 {
                score += 0.2 * (near_mult * nx / cap).min(0.2);
            }
        }
        // avoid opening a bin when open bins already have tight residuals
        if fitting_bins_count >= 3 && mean_residual > 0.0 {
            let tight = mean_residual / cap;
            if tight < 0.15 { score += 0.35 * (0.15 - tight) / 0.15; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.2 * t * t + 1.3 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // multi-step lookahead: reward residuals that fit next item plus more
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // divisibility: residual fits an integer number of next items
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            // small gap: leaving too little room for next item wastes space
            let gap = (nx - pr) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
            }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // exact multipack with current item
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // congestion: penalize spreading across many bins early, relax late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual . max (1.0) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        // new-bin candidate: open when item is large or few fitting bins
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // nearly-full new bin: prefer packing it exactly now
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // late stream: opening fresh bins is cheaper, dead space matters less
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if next_item_size == item_size { score -= 0.15 ; }
        } else if next_item_size as f64 > 0.0 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are almost unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual as i32).abs() as f64 * 2.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tight fit reward: residual within next-item reach is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for the lookahead item -> dead space risk
        score += 8.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // but reward using a nearly-full bin to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.35 * (1.0 - progress);

    // Deviation from mean residual: prefer bins that keep the residual profile balanced,
    // unless it is a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // fits poorly everywhere else (large dead space would be created).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.2;
        // with few open bins, reusing is cheaper; make new bin less attractive
        score += (open_bins_count as f64) * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative -> allow new bin
        }
    }

    score
}

