            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small post-residual that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver under min item size 10 (soft guard)
    }
    score += 0.15 * (post_residual as f64).powf(1.3);

    // Lookahead (k=2): if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 20.0 + 15.0 * chain_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual can't host next item: mild penalty proportional to wasted opportunity.
        score += 5.0 * (1.0 - (post_residual as f64 / cap));
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (mean_residual / cap);
        // Late in the stream, consolidation matters more.
        score -= 6.0 * progress * (mean_residual / cap);
    }

    // New-bin candidate handling (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // existing bins would leave very tight/awkward fits.
        let size_ratio = item_size as f64 / cap;
        let best_possible_waste = (bin_residual - item_size) as f64;
        let mut new_bin_score = best_possible_waste; // always some baseline waste
        // Reward opening a fresh bin for big items when alternatives are scarce.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        } else if size_ratio > 0.6 && fitting_bins_count <= 2 {
            new_bin_score -= 12.0 * size_ratio;
        } else {
            new_bin_score += 20.0 + 10.0 * (fitting_bins_count as f64);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        new_bin_score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is high, reuse instead of opening.
        new_bin_score += 8.0 * (mean_residual / cap);
        score = new_bin_score;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
