pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic in normalized post-residual (favor tight fits)
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate slack; late, strongly punish residual waste
    let progress_coupling = (1.0 + 3.0 * progress * progress) * norm_pr * norm_pr * 30.0;
    score += progress_coupling;

    // Interaction: post_residual vs item size (wasted space relative to item)
    score += norm_pr * norm_item * 15.0;

    // Lookahead: reward residual that could fit the next item (smooth quadratic match)
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= (1.0 - gap.min(1.0)) * (1.0 - gap.min(1.0)) * 12.0;
    }

    // Last-chance bonus: if only this bin fits, strongly discourage opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.05 * (1.0 + progress);

    // Mean residual coupling: penalize bins far from the mean slack (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0;

    // New-bin candidate: make empty bin moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score = 20.0 - norm_item * 18.0 + progress * 5.0;
    }

    score
}

