            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if next_item_size == item_size { score -= 0.15 ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = (cap / 4.0).floor() as u32; // 25
    let eighth = (cap / 8.0).floor() as u32;  // 12

    // Dead-space penalty: leftovers that no plausible item can use.
    // Items are 1..100, but small leftovers (< typical small item) are near-dead.
    if post_residual > 0 && post_residual < eighth {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    }

    // Modulo-class logic on post_residual: leftovers divisible by common item sizes
    // (10, 20, 25) are more likely to be filled later.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % quarter.max(1) == 0 {
        score -= 6.0;
    }
    // Odd harmonic classes (not multiples of 5) are harder to fill.
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 5.0;
    }

    // Integer-division threshold: post_residual bucket by quarter-capacity.
    let bucket = post_residual / quarter.max(1); // 0..4
    score += bucket as f64 * 2.5;

    // Next-item compatibility: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's class matches leftover class.
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else if next_item_size >= post_residual / 2 {
                score -= 8.0; // good tight fill next
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; leftover risks becoming dead space.
            score += 12.0;
            if post_residual < next_item_size / 2 {
                score += 8.0; // badly fragmented leftover
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity as u32 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the current
    // fit is poor (large post_residual relative to item) or late in the stream.
    if bin_residual == bin_capacity as u32 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = post_residual as f64; // full capacity left as residual for next round
        // Penalize new bins, but relax penalty when existing fit is very tight/dead-spacey.
        let mut new_bin_score = waste + 55.0 - 30.0 * progress;
        if item_size > (cap * 0.6) as u32 {
            new_bin_score -= 20.0; // big items: fresh bin often fine
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            new_bin_score -= 10.0; // next item needs fresh space anyway
        }
        // Compare against mean residual: if open bins are mostly full, new bin less bad.
        new_bin_score -= (mean_residual / cap).min(1.0) * 10.0;
        score = new_bin_score;
    } else {
        // Prefer tighter fits among open bins: reward small post_residual.
        score -= (cap - post) / cap * 10.0;
        // Slight penalty for spreading across too many open bins when mean residual is high.
        if (mean_residual / cap) > 0.5 && open_bins_count > 3 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
