}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward near-perfect match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead fit (post_residual == next_item_size) is heavily rewarded.
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Penalize post_residual that is only slightly larger than next_item_size
        // (leaves awkward slivers) less than huge unusable residuals.
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space: next item cannot fit here at all.
            score += 10.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // free space is wasteful; leaving tight fits is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty scaled by how many bins already fit.
        if fitting_bins_count > 0 {
            score += 15.0 + 5.0 * fitting_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper; later, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins that are already partially filled (tight packing).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

