pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 30.0 + (dead_threshold - post_residual as f64) * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward; if next item
    // would be blocked, penalize proportionally.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0;
            if post_residual == next_item_size {
                score -= 18.0;
            }
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.8;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well or bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins are roomy (fragmentation low)
        // and few bins are open; reward when mean residual is large but unusable.
        score += 20.0 - fragmentation * 25.0 + open_bins_count as f64 * 1.5;
        if fitting_bins_count > 0 {
            score += 15.0 * (1.0 - progress);
        }
        // Late in stream, prefer consolidating into open bins.
        score += progress * 10.0;
    }

    // Mild preference for filling bins that are already mostly full.
    let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * used_frac;

    // Coupling with global mean residual: prefer bins below mean residual
    // (fill the tighter bins first, keep roomy bins flexible).
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 3.0;
    }

    score
}

