    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strong non-linear preference for small post_residual
    let tightness = (post / cap) * (post / cap);
    score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact / near-exact fit bonus, smoothly amplified by stream progress
    let exactness = 1.0 - (post / cap);
    score -= 40.0 * exactness * exactness * exactness * (0.5 + progress);

    // Penalize leaving dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 0.35 * gap * gap / cap;
        // Reward leaving room exactly for the next item
        let match_bonus = 1.0 - ((post - next_item_size as f64).abs() / cap);
        score -= 15.0 * match_bonus * match_bonus * match_bonus;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 + 40.0 * progress;
    }

    // Penalize fragmenting bins with large residuals when many alternatives exist
    if fitting_bins_count > 2 {
        score += 8.0 * (fitting_bins_count as f64 - 2.0).sqrt() * (post / cap);
    }

    // New-bin candidate: smooth penalty that decays with progress and grows
    // when the item is large (poor fit anywhere) or few bins fit it
