pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of bin left empty

    // Dead-space penalty: residuals that are too small to hold typical items
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 200.0;
    } else if post_residual < 30 {
        score += 80.0;
    }

    // Reward near-perfect fits (harmonic completion)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Modulo-class logic: residual divisible by common item sizes is reusable
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { harmony += 40.0; }
        }
        score -= harmony;
    }

    // Next-item lookahead: does the leftover fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus scaled by how snugly the next item fits afterward
        let after = post_residual - next_item_size;
        score -= 60.0 + (after as f64).min(50.0);
    } else if next_item_size > 0 {
        // Leftover cannot host next item: mild penalty, worse near stream end
        score += 30.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity
    if bin_residual == bin_capacity {
        // Prefer an open bin that can host the next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 250.0;
        }
        // Early stream: keep bins open; late stream: fresh bins less costly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 * (1.0 - progress);
        // Penalize opening bins when many are already open
        score += (open_bins_count as f64) * 10.0;
    } else {
        // Prefer bins whose residual is close to item (tight fit)
        let tight = (bin_residual - item_size) as f64;
        score -= 20.0 * (1.0 - tight / cap).max(0.0);
        // Prefer bins below mean residual (consolidate emptier space usage)
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.4 * t * t + 1.3 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // deeper lookahead: can next item fit again after placing next?
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // multiplicity fit: pr holds k copies of next item
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0) ;
            }
        }
        // residual matching current item's multiples: anticipate future copies
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // crowd penalty consolidates late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    // residual deviation from mean
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual < bin_capacity && pr > 0.0 {
        let ratio = pr / mean_residual . max (1.0) ;
        if ratio < 0.35 { score -= 0.15 * (0.35 - ratio) ; }
        if ratio > 2.5 { score += 0.1 * (ratio - 2.5) . min (1.0) ; }
    }
    if bin_residual == bin_capacity {
        // new-bin candidate scoring
        let it = item_size as f64 ;
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * it / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if it > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if it >= 0.9 * cap { score -= 0.55 ; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
            // two-chain: room for next item twice
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
        }
        if next_item_size as f64 > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
            if next_item_size as f64 - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (next_item_size as f64 - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && it > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
        // avoid stranding a tiny residual
        let stranded = new_pr ;
        if next_item_size > 0 && stranded > next_item_size as f64 {
            let w = stranded - next_item_size as f64 ;
            if w > 0.0 && w < 8.0 { score += 0.7 * (1.0 - w / 8.0) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    // small waste penalty after placing next item
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    // large residual bins late in the stream are less attractive
    if t > 0.6 && bin_residual as f64 > 0.5 * cap && bin_residual != bin_capacity {
        score += 0.15 * (t - 0.6) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual > 0 && post_residual < item_size as f64 * 0.25 {
        score += 25.0; // gap too small relative to future items
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when residual is large and item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin leaves room for lookahead item
        }
    }

    // Lookahead coupling: prefer bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0; // blocks lookahead too
    }

    // Mean-residual context: penalize bins far below mean residual (already tight).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

