pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 500.0;
        }
        // Penalize if the next item cannot follow into the leftover.
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Penalize tiny dead space (unusable slivers) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64;
    }

    // Relative-to-mean coupling: prefer bins that absorb more than average.
    score -= (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when it enables a perfect 2-item chain
    // with the lookahead, or when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 120.0; // base penalty for opening a new bin
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 130.0; // fresh bin can host a full chain
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight early-stream bias to keep bins open and flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

