        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // refined dead-space avoidance: penalize new bins whose residual is
        // unlikely to absorb any future item given the mean residual scale,
        // sharpened near the end of the stream where leftovers are pure waste
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        // dead-space avoidance v2: also compare new_pr against the next item
        // directly; a new bin that can't even hold the next item is a liability
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                score += 0.25 * (1.0 - new_pr / nx) * (0.6 + 0.4 * progress);
            }
        }
        // reward opening a new bin when existing bins would leave tiny,
        // unusable slivers relative to the next item (tightened threshold)
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64;
            let best_sliver = ((bin_capacity - item_size) as f64 - nx).max(0.0);
            if best_sliver > 0.0 && best_sliver < 0.03 * cap {
                score -= 0.3 * (1.0 - best_sliver / (0.03 * cap));
            }
        }
