        // since open-bin leftovers are unlikely to be filled afterwards
        if progress > 0.75 && item_size as f64 > 0.4 * cap && fitting_bins_count >= 2 {
            score -= 0.2 * (progress - 0.75) / 0.25;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

