        // unusable slivers relative to the next item
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64;
            let best_sliver = ((bin_capacity - item_size) as f64 - nx).max(0.0);
            if best_sliver > 0.0 && best_sliver < 0.04 * cap {
                score -= 0.2;
            }
        }
        // NEW: penalize new bins whose post-residual cannot hold the mean
        // residual-sized item even once, scaled by how much slack would be lost
        if new_pr > 0.0 && mean_residual > 0.0 && new_pr < mean_residual {
            let deficit = (mean_residual - new_pr) / cap;
            score += 0.45 * deficit.min(0.25) * (0.6 + 0.4 * progress);
        }
