        // over opening another bin unless the new bin's residual fits the next item
        if open_bins_count >= 4 && next_item_size > 0 && new_pr < next_item_size as f64 {
            score += 0.15 * ((open_bins_count - 3) as f64).min(4.0) * 0.25;
        }
