        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // NEW: extra penalty when this placement creates a residual that is
        // far below the next item but close to mean residual scale — a trap
        let gap = (next_item_size - post_residual) as f64;
        if gap > 4.0 && pr < mean_residual * 0.8 {
            score += 0.12 * (pr / mean_residual.max(1.0));
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
