            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        // reward opening a new bin when existing bins would leave tiny unusable slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            let best_sliver = (new_pr - nx) . max (0.0) ;
            if best_sliver > 0.0 && best_sliver < 0.04 * cap {
