            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            // two-step lookahead: reward residuals that fit the next item twice
            let cr = chain_residual as f64 ;
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
