pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / cap;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // dead space relative to next item
            let waste = post_residual as f64 / next_item_size as f64;
            score += waste * 10.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // penalize opening new bin generally, more when many bins open
        let mut nb = 15.0 + open_bins_count as f64 * 1.5;
        // if the item is large relative to capacity, a fresh bin is more useful
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            nb -= 12.0 * (frac - 0.5);
        }
        // if mean residual across open bins is small, poor fits exist -> new bin more attractive
        if mean_residual < item_size as f64 {
            nb -= 10.0;
        }
        // early in stream, keep bins open to allow combination
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += (1.0 - progress) * 8.0;
        score += nb;
    }

    // Slight preference for bins with lower residual among equals
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            // two-step lookahead: reward residuals that fit the next item twice
            let cr = chain_residual as f64 ;
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // multiplicity fit: residual packs next item an integer number of times
            if nx > 0.0 {
                let k = (cr / nx).round() ;
                if k >= 2.0 {
                    let mult_err = (cr - k * nx).abs() ;
                    if mult_err <= 2.0 { score -= 40.0 * (1.0 - mult_err / 2.0) ; }
                }
            }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            // small gap to next item: poor fit, penalize proportionally
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
        }
        // residual that exactly fits a multiple of the current item: strong compaction
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz).round() ;
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz).abs() <= 1.5 {
                score -= 30.0 * (1.0 - 0.3 * progress) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance: penalize new bins whose residual is unlikely
        // to absorb future items given the mean residual scale
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // encourage fresh bins for big items when many bins are open (load spreading)
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 40.0 ; }
        // double-fit lookahead for the new bin residual
        if next_item_size > 0 && new_pr >= 2.0 * next_item_size as f64 {
            let r = new_pr - 2.0 * next_item_size as f64 ;
            if r <= 6.0 { score -= 50.0 * (1.0 - r / 6.0) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
        // deviation from mean residual: prefer typical residuals, punish outliers
        let dev = (bin_residual as f64 - mean_residual) / cap ;
        score += 30.0 * dev * dev ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on dead space
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth coupling: dead space matters more as stream progresses
    score += 12.0 * norm_post * norm_post * progress;

    // Reward filling a large fraction of the bin (smooth polynomial in fit_ratio)
    score -= 8.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits in the post residual, reward; else penalize
    if next_item_size > 0 {
        let next_fits = if (next_item_size as f64) <= post { 1.0 } else { 0.0 };
        let gap = ((next_item_size as f64) - post).abs() / cap;
        score -= 6.0 * next_fits * (1.0 - gap);
        score += 4.0 * (1.0 - next_fits) * gap * (0.5 + progress);
    }

    // Mild pressure against proliferating bins late in the stream
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Deviation from mean residual: prefer bins near the average load state
    score += 0.05 * (post - mean_residual).abs();

    // New empty bin candidate: penalize unless post residual is very usable
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    score
}

