        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // --- Harmonic classes of post_residual (modulo / threshold bands) ---
    // Perfect closure is gold; tiny residues (<10) are near-dead space; mid residues are reusable.
    let harmonic_penalty: f64 = if pr == 0 {
        -60.0
    } else if pr <= 5 {
        30.0
    } else if pr <= 10 {
        18.0
    } else if pr <= 20 {
        6.0
    } else if pr <= 30 {
        0.0
    } else if pr <= 50 {
        -4.0
    } else {
        -8.0
    };
    score += harmonic_penalty;

    // Modulo coupling: residues that are multiples of common item sizes (10/20/25/50)
    // are more likely to be filled by future arrivals.
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 6.0;
    }

    // --- Lookahead: does the residue accommodate the next item? ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0;
            // Exact chain: residue equals next item exactly -> perfect follow-up
            if pr == next_item_size {
                score -= 12.0;
            }
        } else {
            // Dead space relative to lookahead
            score += (next_item_size - pr) as f64 * 0.35;
        }
    }

    // --- Last-chance bin: avoid opening a new bin unnecessarily ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate ---
    if bin_residual == bin_capacity {
        score += 30.0; // default: prefer existing bins
        if fitting_bins_count <= 1 {
            score -= 35.0; // no real alternative -> open the bin
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= bin_capacity / 2 {
            score -= 10.0; // big item now, big item next: fresh bin is attractive
        }
    }

    // Tie-break: prefer more-filled bins (smaller residual) among equals
    score -= bin_residual as f64 * 0.04;

    // Mild stream-progression pressure: late in the stream, consolidation matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0;

    score
}

