        if post_residual < next_item_size {
            // Unusable for the lookahead: heavy penalty scaled by how close it is to useless.
            let waste = (next_item_size - post_residual) as f64;
            score += 25.0 + 0.5 * waste;
        } else {
            // Usable slack: mild reward proportional to how well it fits the next item.
