            score -= 0.3 * (1.0 - slack_fit / bin_capacity as f64).max(0.0);
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize creating very small dead gaps even without lookahead knowledge.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate and loose fits).
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins are already open,
        // unless this bin is the last chance for the item.
        score += 5.0 + 0.8 * pressure;
    } else {
        score -= 0.4 * pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
