        if next_item_size > 0 && new_pr > next_item_size as f64 {
            let rem = (new_pr - (new_pr / next_item_size as f64).floor() * next_item_size as f64) / cap;
            if rem > 0.0 && rem < 0.03 { score -= 40.0 * (1.0 - rem / 0.03); }
