    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress);
        }
    }
    // slight pressure to keep the open-bin count in check early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
