            if next_item_size as f64 - new_pr <= 8.0 {
                score += 60.0 * (1.0 - (next_item_size as f64 - new_pr) / 8.0);
            }
        }
        score -= 8.0 * (1.0 - progress);
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0; }
        // moderate items into fresh bins when few fitting bins exist mid-stream
        if item_size as f64 > 0.4 * cap && progress < 0.5 && fitting_bins_count >= 2 {
