    let fit_norm = (item_size as f64) / cap;
    let pr_norm = pr / cap;

    // Base: penalize post residual, but with a smooth non-linear (quartic-ish) coupling
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Smooth polynomial coupling of residual with stream progress:
    // early on, prefer leaving medium residuals; later, prefer tight fits
    let progress_coupling = (1.0 - progress) * (1.0 - progress) * 0.4 - progress * progress * 0.6;
    score += pr_norm * progress_coupling * 30.0;

    // Reward large fill fraction (low post_residual relative to capacity) non-linearly
    score -= fit_norm * fit_norm * 12.0;

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Penalty for leaving a residual that is too small to be useful later
    // smooth dead-space term: residuals in (0, ~10) are dead; approximate smoothly
    let dead = (-pr / 6.0).exp() * 8.0;
    score += dead;

