    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize residuals that block the next item smoothly
        let gap = (next_item_size as f64 - pr) / cap;
        score += gap * gap * 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: make it moderately attractive only when it truly beats poor fits
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

