        }
        let new_pr = stranded ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 { score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ; }
            if new_pr < nx && nx - new_pr <= 8.0 { score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ; }
        }
        if open_bins_count >= 6 && it > 0.6 * cap { score -= 0.3 ; }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 { score += 0.65 * (1.0 - t * 0.3) ; }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    // large residual bins late in the stream are less attractive
    if t > 0.6 && bin_residual as f64 > 0.5 * cap && bin_residual != bin_capacity {
        score += 0.15 * (t - 0.6) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: classify dead space by divisibility / magnitude bands
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // residual as fraction of capacity

    // Penalize residuals that are "unusable" — too small for typical items (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space trap
    }

    // Modulo arithmetic: residuals divisible by small harmonic divisors are more reusable
    let mut harmony: f64 = 0.0;
    for &d in &[10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            harmony += 8.0;
        }
    }
    // Harmonic pairing: can next item exactly fill this bin?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // next item completes this bin perfectly
        } else if next_item_size < post_residual {
            // combined leftover class
            let combo = post_residual - next_item_size;
            if combo == 0 { score -= 150.0; }
            if combo % 10 == 0 { harmony += 4.0; }
            if combo < 10 && combo > 0 { harmony -= 10.0; }
        } else {
            // next item cannot use this bin's leftover: leftover class must serve future items
            harmony -= 3.0;
        }
    }
    score -= harmony;

    // Integer-division thresholds on post_residual: band-based reusability
    let band = post_residual / 10; // which decade band the leftover falls in
    match band {
        0 => { if post_residual > 0 { score += 25.0; } }   // 1-9: nearly dead
        1 => { score += 5.0; }                              // 10-19: marginal
        2 | 3 => { score -= 6.0; }                          // 20-39: decent
        4 | 5 => { score -= 10.0; }                         // 40-59: good
        _ => { score -= 4.0; }                              // large leftover: flexible but wasteful now
    }

    // Capacity-fraction coupling: prefer filling bins past half full
    let fill = (bin_residual as f64) / cap_f;
    if fill < 0.5 {
        score += 12.0 * (0.5 - fill); // discourage using a mostly-empty bin when others are fuller
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_options = if next_item_size > 0 && next_item_size <= bin_residual { 0.0 } else { 0.0 };
        let _ = poor_options;
        // base penalty so open bins usually win
        score += 90.0;
        // relax penalty when open bins are fragmented (mean residual low) or late stream
        score -= (mean_residual / cap_f) * 40.0;
        score -= progress * 30.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits: must open
        }
    }

    // Lookahead: if next item is large, keep large residuals intact
    if next_item_size > 60 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
        score += 30.0; // this leftover would barely fit next item; better to save a bigger bin
    }

    // Slight tie-break toward fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.5 * t * t + 1.2 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 5.0 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // two-step lookahead: can the chain still host another item?
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                else if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            // wasted dead-space beyond the next item
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // multiplier alignment: residual that divides cleanly by next item is valuable
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // small gap: leaving too little room for next item wastes space
        let gap = (nx - pr) / cap ;
        if gap > 0.0 && gap < 0.25 {
            score += 1.6 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
        }
        // near-perfect divisibility of current residual by item size
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // congestion: penalize spreading across many bins early, relax late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual == bin_capacity {
        // new-bin candidate: open when item is large or few fitting bins
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count == 2 { score += 0.7 * (1.0 - t) ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // avoid opening a bin when an existing bin fits nearly perfectly
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // late stream: opening fresh bins is cheaper, dead space matters less
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // lookahead on the fresh bin's residual
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            let best_sliver = (new_pr - nx) . max (0.0) ;
            if best_sliver > 0.0 && best_sliver < 0.04 * cap { score -= 0.2 ; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap ;
                if rem > 0.0 && rem < 0.03 { score -= 0.3 * (1.0 - rem / 0.03) ; }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && t < 0.5 {
            score -= 0.15 * (1.0 - t / 0.5) ;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let pair_left = new_pr - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        // extra penalty when the existing bin would be left with a useless sliver
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 8.0 * fill_ratio;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // (especially tight fits) rather than spreading residual space around.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item could use the post-residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            // dead space relative to lookahead item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: an empty bin is attractive early when few
    // bins are open, but penalized when open bins already fit the item well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let reuse_quality = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        score += 5.0 + 20.0 * (1.0 - progress) - 0.5 * fitting_bins_count as f64
            - if fitting_bins_count > 0 { 2.0 * reuse_quality } else { 0.0 };
        // Opening a new bin is fine if mean residuals are large (poor reuse).
        score -= 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = pr / cap ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10 { score -= 0.9 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 0.25 ; }
            // two-step lookahead: reward residuals that fit the next item twice
            let cr = chain_residual as f64 ;
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.45 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // reward near-multiple chain residuals (k * next item)
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 {
                score -= 0.35 * (1.0 - mult_err / 2.0) ;
            }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * progress ;
            // small gap to next item: poor fit, penalize proportionally
            let gap = (nx - pr) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            if (nx - pr) <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0) ;
            }
        }
        // exact item-multiple residual fit
        if item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3) ;
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) ;
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        score -= 0.05 * mean_residual / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // sliver avoidance in existing bins pushes toward fresh bin
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance: penalize new bins whose residual is unlikely
        // to absorb future items given the mean residual scale
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            let sliver = (new_pr - nx) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 0.2 ; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // next-item multiple fit in fresh bin
        if next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
