            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        // modular remainder fit: fresh bin residual divisible by next item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap ;
                if rem > 0.0 && rem < 0.03 * cap {
                    score -= 0.3 * (1.0 - rem / (0.03 * cap)) ;
                }
            }
        }
        // after placing next item, residual should stay usable
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) {
                    score -= 0.18 * (1.0 - progress * 0.4) ;
                }
                if after > 0.0 && after < nx * 0.25 {
                    score -= 0.12 * (1.0 - after / (nx * 0.25)) ;
                }
            }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5) ;
        }
        if progress > 0.85 && fitting_bins_count <= 2 {
            score += 0.6 * (progress - 0.85) / 0.15 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead fit: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item could still fit here: mild reward scaled by closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            score += 10.0 * (diff / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual of open bins.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mr = mean_residual.max(0.0);
    // Penalize leaving residual far above the mean (fragmenting space).
    if pr > mr {
        score += 0.5 * (pr - mr);
    } else {
        score -= 0.3 * (mr - pr);
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 15.0 * (1.0 - pr / cap);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        // Penalize opening new bins mildly; escalate as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * progress - 0.1 * open_pressure;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residual (non-linear).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill
    }
    if post_residual >= 10 && post_residual < item_size.min(80) {
        score += 6.0; // awkward gap smaller than typical items
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // leftover useless for next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (fill emptier bins first) unless it's the new-bin candidate.
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate handling: attractive early or when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) as f64 > mean_residual);
        if poor_fit || open_bins_count == 0 {
            score -= 25.0 + 20.0 * progress;
        } else {
            score += 35.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

