pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small leftover space (tight fits).
    let mut score = pr;

    // Smooth non-linear penalty for residuals that are too small to be useful
    // (dead space) vs. residuals large enough to host a future item.
    let dead_zone = 10.0 / cap; // min item size fraction
    let pr_norm = pr / cap;
    let dead_penalty = (-((pr_norm / dead_zone).ln().max(0.0))).exp(); // ~1 when pr tiny, decays as pr grows
    score += 12.0 * dead_penalty * (1.0 + progress);

    // Reward near-perfect fits with a smooth Gaussian-like bump around pr == 0.
    let tightness = (-pr_norm * pr_norm / 0.02).exp();
    score -= 8.0 * tightness;

    // Non-linear coupling with stream progress: late in the stream, be greedier
    // about filling bins (favor tight fits more, tolerate open-bin sprawl less).
    let late = progress * progress;
    score -= 6.0 * late * tightness;
    score += 4.0 * late * (pr_norm - 0.5).abs();

    // Lookahead: if the next item fits exactly in post_residual, reward strongly;
    // if it cannot fit, penalize leaving a residual just below it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let match_bonus = (-(gap / cap).powi(2) / 0.01).exp();
        score -= 10.0 * match_bonus;
        if pr < ni && pr > 0.0 {
            score += 6.0 * (1.0 - pr / ni) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin should only win when no open bin offers
    // a decent fit; make the empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.9 {
            score -= 15.0; // large upcoming item: fresh bin is fine
        }
    }

    // Slight preference to spread load when many bins are open and mean
    // residual is high (balance), smoothed via tanh.
    score += 2.0 * ((open_bins_count as f64 / 8.0).tanh()) * (mean_residual / cap - pr_norm).max(0.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.2 * t * t + 1.3 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // two-step lookahead: does the residual chain continue after next item?
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // near-multiple fit: residual almost exactly k * next_size
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // small gap: leaving too little room for next item wastes space
        let gap = (nx - pr) / cap ;
        if gap > 0.0 && gap < 0.25 {
            score += 1.5 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ;
        }
        // sliver waste: tiny leftover just above zero
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    // congestion: penalize spreading across many bins early, relax late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    // exact divisibility bonus: item fits residual leaving k*next or near-zero
    if pr > 0.0 && item_size > 0 {
        let isz = item_size as f64 ;
        let k = (pr / isz) . round () ;
        if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
            score -= 0.2 * (1.0 - t * 0.3) ;
        }
    }
    if bin_residual == bin_capacity {
        // new-bin candidate: open when item is large or few fitting bins
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count == 2 { score += 0.7 * (1.0 - t) ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // late stream: opening fresh bins is cheaper, dead space matters less
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && t < 0.5 {
            score -= 0.15 * (1.0 - t / 0.5) ;
        }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
            // divisibility of new residual by next item
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap ;
                if rem > 0.0 && rem < 0.03 { score -= 0.3 * (1.0 - rem / 0.03) ; }
            }
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
            if next_item_size == item_size && new_pr >= next_item_size as f64 { score -= 0.15 ; }
        }
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            let best_sliver = ((bin_capacity - item_size) as f64 - nx) . max (0.0) ;
            if best_sliver > 0.0 && best_sliver < 0.04 * cap { score -= 0.2 ; }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Dead-space penalty grows super-linearly for awkward residual classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best outcome
    } else if post_residual < 10 {
        score -= 35.0; // near-perfect, unusable sliver -> effectively full
    } else if post_residual <= quarter {
        score -= 15.0; // small residual, still useful for tiny items
    } else if post_residual <= half {
        score += 5.0; // medium residual, moderate utility
    } else if post_residual <= three_quarter {
        score += 12.0;
    } else {
        score += 20.0; // huge leftover: wasted a nearly-empty bin
    }

    // Modulo-style coupling: how well does post_residual align with common item classes?
    // Residuals that are multiples of common block sizes (10, 20, 25) are more reusable.
    let pr_u = post_residual;
    if pr_u % 10 == 0 {
        score -= 6.0;
    }
    if pr_u % 25 == 0 {
        score -= 4.0;
    }

    // Lookahead: reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 {
        let gap = pr_u as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // next item will close this bin perfectly
        } else if gap > 0 && gap < 10 {
            score -= 12.0; // next item fits snugly
        } else if gap < 0 {
            // next item won't fit here; residual becomes dead space until then
            score += (-gap) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless all open residuals are poor relative to the item.
    if bin_residual == bin_capacity {
        let openness = step_index as f64 / total_items.max(1) as f64;
        // Early in stream: new bins are cheap; later: consolidation matters more.
        score += 8.0 + 25.0 * openness;
        // If many bins fit the item, opening a new one is wasteful.
        score += 10.0 * fitting_bins_count as f64;
    } else {
        // Favor bins whose residual is already committed (low residual = high density).
        score -= (c - bin_residual as f64) * 0.05;
    }

    // Prefer filling bins below mean residual (denser than average bins).
    if bin_residual < bin_capacity {
        let density_gap = mean_residual - bin_residual as f64;
        score -= density_gap * 0.3;
    }

    // Mild pressure to reduce open bin count as stream progresses.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.0;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.4 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // two-step lookahead: residual fits next item twice
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.5 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiplicity fit: residual nearly k*next
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
        }
        // item-multiplicity check on current residual
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        // near-perfect post-fit for next item
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        // reward new bins whose remainder after next item is reusable
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // sliver avoidance: reject new bins leaving unusable slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64;
            let best_sliver = (new_pr - nx) . max (0.0);
            if best_sliver > 0.0 && best_sliver < 0.04 * cap { score -= 0.2; }
        }
        // exact multiple packing of next item into fresh bin
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 { score -= 0.3 * (1.0 - rem / 0.03); }
            }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 { score -= 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1) is impossible; treat gaps that
    // can host nothing likely (very small post_residual) as dead space.
    if post_residual > 0 {
        // Non-linear penalty on small residuals: quadratic blow-up near zero.
        let r = post_residual as f64;
        score += 40.0 * (1.0 - r / bin_capacity as f64).powi(6) * (bin_capacity as f64 / (r + 1.0));
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; a new empty bin gets penalized via count.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, scaled by pressure.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If only this new bin fits, we must open it regardless.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin usage relieves pressure slightly.
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the single bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the resulting residual,
    // reward this placement; otherwise penalize leaving a tempting-but-wrong gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (future items
    // unknown); late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mean-residual coupling: if this bin's post placement is far below the mean
    // residual, it is creating an outlier gap; penalize mildly.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

