pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        // Perfect match => strong bonus (item fits exactly next step).
        if diff < 0.5 {
            score -= 40.0;
        } else if nxt <= post {
            // Next item could fit here later; scale reward by closeness.
            score -= 15.0 * (1.0 - diff / cap);
        } else {
            // Next item cannot fit: post_residual is dead space relative to lookahead.
            score += 8.0 + 0.1 * diff;
        }
    } else {
        // Last item: simply minimize leftover, prefer tightest bin.
        score -= 5.0;
    }

    // Penalize post_residual far below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins whose residual is already below average (tight bins) when they still fit.
    if post < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild pressure against opening new bins early in the stream.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless lookahead suggests a fresh bin is useful
