        score += 10.0;
        if next_item_size > 0 && post_residual == bin_capacity && next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Slight phase term: later in stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post / cap);

    score
}

