pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used to modulate lookahead strength.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual: fraction of the bin wasted after placement.
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space super-linearly: small leftovers are hard to fill later.
    if post_frac > 0.0 {
        score += 40.0 * post_frac * post_frac;
    }

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily;
    // if the next item cannot fit in post-residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover is usable, reduce waste penalty.
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: leftover likely dead.
            score += 8.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if nothing fits well elsewhere (many bins already open, poor fit),
        // relax the penalty slightly so a fresh bin can win.
        if post_frac > 0.5 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Global state: prefer filling bins whose residual is close to the mean
    // (keeps residuals homogeneous, improving future packing options).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins that are already fuller (smaller residual).
    score += 0.02 * bin_residual as f64;

    // Time horizon: early in the stream, be conservative (favor tight fits);
    // late in the stream, accept looser fits to close out bins.
    score -= 10.0 * progress * (1.0 - post_frac);

    score
}

