        if progress > 0.6 && fitting_bins_count >= 3 {
            let best_gap = ((next_item_size as f64 - pr) . max (0.0)) / cap;
            if best_gap < 0.15 { score += 0.5 * (1.0 - best_gap / 0.15); }
