        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // mutation: extra penalty for residuals that are just barely too small
        // for the next item (wasted space that cannot be recovered)
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 0.4 * (1.0 - miss / 10.0) * (0.5 + 0.5 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0.0 (perfect fill) .. 1.0 (empty bin)

    // Dead-space penalty: strongly penalize residuals in "useless" harmonic bands.
    // Residuals that cannot hold typical items (>=10) are pure waste.
    if post_residual < 10 {
        score += 60.0 * (1.0 - frac);
    }

    // Integer-division thresholds on post_residual: buckets of 10.
    let bucket = post_residual / 10;
    score += 3.0 * (bucket as f64);

    // Modulo-10 class: residuals congruent to small remainders are harder to fill.
    let rem10 = (post_residual % 10) as f64;
    score += 0.8 * rem10;

    // Reward tight fits (post_residual small but usable).
    if post_residual >= 10 && post_residual <= 20 {
        score -= 25.0;
    }

    // Next-item lookahead: harmonic class of next_item_size via integer division.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus if this bin can also host the next item (chain packing).
        score -= 12.0;
        // Extra chain bonus when post_residual % next_item_size leaves a clean class.
        let chain_rem = (post_residual % next_item_size) as f64;
        score -= 6.0 * (1.0 - chain_rem / cap_f);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Leftover too small for lookahead item: penalize if it blocks next item.
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is not chosen unless existing bins are bad.
        score += 15.0;
        // As stream progresses and bins accumulate, discourage new bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if mean residual across open bins is too small to fit item,
        // opening a new bin is right: relax the penalty.
        if mean_residual < item_size as f64 {
            score -= 45.0;
        }
        // If many open bins but few fit, new bin may be preferable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    // (keeps residual distribution balanced, avoids fragmentation).
    let dev = (post_f - mean_residual).abs();
    score += 0.15 * dev;

    // Modulo arithmetic on capacity fractions: items dividing capacity evenly
    // (harmonic classes 50, 25, 20, 10) pair well with matching residuals.
    if item_size == 50 || item_size == 25 || item_size == 20 || item_size == 10 {
        if post_residual % item_size == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
