        score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize spreading across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Time horizon: early in stream, prefer keeping bins compact; late, prefer closing gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.2;

    // New-bin candidate: make it attractive only when fits are poor elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * item_size as f64 - progress * 20.0;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open a new bin when we have a last-chance fit
        }
    }

    score
}

