    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalize post-residual to [0,1]
    let r = post / capacity;

    // Non-linear polynomial coupling: penalize large residual quadratically,
    // but reward small residuals super-linearly (tight fits).
    let mut score = r * r * 40.0 + r * 10.0 - (1.0 - r) * (1.0 - r) * 25.0;

    // Stream-progress coupling: early on, tolerate looser fits (leave room for big items);
    // later, tighten packing aggressively.
    score += progress * r * r * 30.0 - (1.0 - progress) * r * 8.0;

    // Interaction: dead space is worse when many bins are open (fragmentation).
    let frag = (open_bins_count as f64).ln().max(0.0);
    score += frag * r * r * 6.0;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 18.0 + (1.0 - r) * 12.0;
    }

    // Lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / capacity;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 4.0 * (nx - post) / capacity;
        }
    }

