        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.38 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.32 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        // large items into fresh bins early
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        // after-fit headroom checks
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.2 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.24 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // new-bin dead-space ratio: fresh residual far above mean residual wastes space
        if mean_residual > 0.0 && new_pr > 0.0 && new_pr > mean_residual * 2.0 {
            score += 0.12 * ((new_pr / mean_residual - 2.0) . min (2.0)) * (0.4 + 0.6 * progress);
        }
        // prefer opening fresh bins when current item nearly fills them (waste < 5%)
        if new_pr > 0.0 && new_pr < 0.05 * cap { score -= 0.5 * (1.0 - new_pr / (0.05 * cap)); }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // sliver penalty: leaving an unusable remainder relative to mean residual
        if mean_residual > 0.0 && pr < mean_residual * 0.35 {
            score += 0.28 * (1.0 - pr / (mean_residual * 0.35)) * (0.6 + 0.4 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize wasted space quadratically.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Aggressive 2-step lookahead: if the next item fits exactly in post_residual,
    // strongly reward this bin (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let next_leftover = post_residual - next_item_size;
            let next_eff = next_leftover as f64 / bin_capacity as f64;
            score -= 30.0 * (1.0 - next_eff);
            score += 10.0 * next_eff * next_eff;
        } else {
            // Next item cannot follow here: penalize proportionally to mismatch.
            let mismatch = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 15.0 * mismatch;
        }
    }

    // Compare against mean residual: prefer bins whose residual is tighter than average.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 8.0 * rel;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open
    // bins; penalize new bins more when many bins are open with usable space.
    if bin_residual == bin_capacity {
        let open_f64 = open_bins_count as f64;
        score += 15.0 + 3.0 * open_f64 + mean_residual * 0.3;
        // Allow opening a new bin when item is large and nothing fits well anyway.
        if item_size >= 70 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild bonus for filling tight bins completely.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    score
}

