pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild bonus scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does not fit here: penalize large residuals that tempt bad packing
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins whose residual is already small relative to mean (tight packing)
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (res - mean_residual).max(0.0);
        score -= 0.1 * (mean_residual - res).max(0.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let mut penalty = 120.0;
        if next_item_size > 0 && next_item_size <= item_size {
            penalty += 40.0;
        }
        if fitting_bins_count > 0 {
            penalty += 60.0 * (fitting_bins_count as f64).min(3.0);
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 80.0 * progress;
        score += penalty;
    }

    // Mild penalty for leaving residuals in the awkward 1..=10 dead-space band
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Fragmentation pressure: penalize residual relative to smallest useful item size
    score += 0.2 * (res / (100.0 - item_size as f64).max(1.0));

    // Slight preference for bins with larger original residual (fill fuller bins first)
    score -= 0.05 * bin_residual as f64 / bin_capacity as f64;

    // Scale with number of open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

