        // the item is tiny, discourage fragmentation
        if open_bins_count >= 5 && new_pr > 0.0 && new_pr < 0.08 * cap {
            score += 0.5 * (1.0 - new_pr / (0.08 * cap)) * (0.4 + 0.6 * progress);
