            score += 0.25 * (1.0 - pr / (mean_residual * 0.3)) * (0.5 + 0.5 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (1.0 - norm_pr) * progress;

    let mut score = pr;

    // Penalize large residuals early, penalize small residuals late (smooth coupling)
    score += 12.0 * poly;

    // Reward tight fits, amplified as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 6.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 4.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty when many bins are open, encouraging consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    score
}

