pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "waste bands" of capacity/8
    let band = cap / 8.0;
    let post = post_residual as f64;
    let band_index = (post / band).floor();
    // Penalize residual just above a band boundary (awkward slivers)
    let frac = (post / band) - band_index;
    score += frac * 6.0;

    // Perfect-fit reward: post_residual exactly in harmonic classes {0, 25, 50, 75, 100}
    let pr = post_residual;
    if pr == 0 || pr == 25 || pr == 50 || pr == 75 || pr == 100 {
        score -= 12.0;
    }

    // Class-match: does next item fit into post_residual? Reward tight pairing
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= pr {
            // reward proportional to how well next item fills the leftover
            score -= 8.0 * (1.0 - (pr as f64 - nxt) / cap);
        } else {
            // next item won't fit: penalize if leftover is small dead space
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, slight penalty unless current bin is crowded
    if bin_residual == bin_capacity {
        score = cap - post; // = 100, competes only when no open bin is good
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 4.0; // open a fresh bin when open bins are fragmented
        }
    }

    // Progression-aware slack: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - post / cap);

    // Fragmentation penalty relative to mean residual
    if post < mean_residual * 0.4 {
        score += 4.0;
    }

    score
}

