    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            // gap too small for the lookahead item: heavy penalty scaled by tightness
            let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
            score += 25.0 + 40.0 * tightness;
        }
    }
    if post_residual == 0 {
        // perfect fill: strong reward
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into a fresh bin
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if bin_residual == bin_capacity {
