        score -= 2.0 * open_pressure;
    }

    // Slight preference for filling bins with larger residual as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64);

    score
}

