    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 700.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            // next item fits, but reward tighter residual afterwards
            let post2 = post_residual - next_item_size;
            score -= 150.0 - post2 as f64 * 0.5;
        } else {
            // next item does NOT fit: penalize dead space it creates
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

