pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into residue classes mod 10
    let post_mod = post_residual % 10;
    // Dead space penalty: residuals in awkward classes are harder to fill
    let dead_penalty: f64 = match post_mod {
        0 => 0.0,
        1 | 2 => 8.0,
        3 | 4 => 4.0,
        5 => 1.0,
        6 | 7 => 3.0,
        8 | 9 => 6.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small residual that next item can fill: reward coupling
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic decay of usefulness with leftover slack
            score -= 30.0 * (1.0 - slack / 20.0).max(0.0);
        } else {
            // next item cannot use this residual: mild penalty proportional to overshoot
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Integer-division thresholds on post_residual: unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver likely dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing residuals are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // if mean residual is small, opening new bin is reasonable
        score = 35.0 + 50.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can hold current + next comfortably
            if item_size + next_item_size <= bin_capacity {
                score -= 12.0;
            }
        }
    }

    // Tightness bonus: prefer bins where item fills a large fraction of residual
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // Progress modulation: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_frac;

    // Prefer denser packing across open bins
    if (bin_residual as f64) > mean_residual {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let t = progress;
    let fit_ratio = item_size as f64 / cap;
    let mut score = pr / cap;

    // Exact fill is always best
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead-space polynomial weight
    let dead_weight = 1.0 + 2.0 * t * t + 1.5 * t * (1.0 - t);
    score += 0.6 * dead_weight * (pr / cap).powi(2);

    // Tightness reward
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus for the only fitting open bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Consolidation pressure early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean-residual alignment (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Lookahead on next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 4.8;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.35 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
