}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit anything are pure waste.
    // Treat residuals below the minimum plausible item size as "dead" and punish hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Non-linear dead-space curve: small usable gaps are also risky.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness bonus: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage proliferating bins when few exist,
    // but allow spreading when many bins are open (avoid fragmentation).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // elsewhere would be terrible. Make the empty bin moderately unattractive,
    // but let it win if the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let large_item_relief = (item_size as f64 / bin_capacity as f64) * 40.0;
        score += base_penalty - large_item_relief;
        // Extra penalty early in the stream when keeping bins tight matters most.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead: if the next item could exactly fill this bin's post_residual,
    // reward keeping that gap; if post_residual can't fit the next item anywhere
    // useful, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean in a
    // usable direction (larger-than-mean residuals absorb awkward items).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

