        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // stranded residual: post-fit gap exceeds mean residual — mild extra penalty late
        if mean_residual > 0.0 && (next_item_size - post_residual) as f64 > mean_residual {
            score += 0.15 * ((next_item_size - post_residual) as f64 - mean_residual) / cap * (0.5 + progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0;
        }
        // Perfect pair: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin before opening a new bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 25.0 * progress - 5.0 * crowd;
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer fuller bins relative to global mean residual
    score -= 3.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.5 * t * t + 1.2 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 4.8 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // multi-step lookahead: reward residuals fitting next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // divisibility bonus: residual close to a multiple of next item
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // exact item-fill bonus: residual is a small multiple of current item size
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // congestion: penalize spreading across many bins early, relax late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual == bin_capacity {
        // new-bin candidate: reset scoring baseline
        let new_pr = (bin_capacity - item_size) as f64 ;
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // penalize new bin when open bins would leave tiny slivers
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        // near-perfect post-fit for next item
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        // two-step fit for next item from a fresh bin
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let pair_left = new_pr - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        // extra penalty when the existing bin would be left with a useless sliver
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / c;

    // Base: prefer small post_residual (tight fits), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fit_norm * (1.0 - fit_norm)) * (1.0 + 0.5 * progress);

    // Penalize large unusable residuals quadratically
    score += 0.35 * pr * pr / c;

    // Reward near-perfect fits strongly (smooth non-linear coupling)
    score -= 40.0 * (1.0 - fit_norm).powi(6) * (1.0 + progress);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * (1.0 - fit_norm));
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let g = gap / c;
            score -= 18.0 * (1.0 - g) * (1.0 - g);
        } else {
            // residual too small for next item: mild penalty scaled by waste
            score += 6.0 * (-gap / c);
        }
    }

    // Encourage consolidation when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * fit_norm;

    // Pull toward mean residual: prefer bins whose post residual matches stream average
    score += 0.25 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * progress - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.12;
