pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions. Residuals in small classes (<= cap/4) are "dead"
    // space and should be penalized heavily; large residuals are reusable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 45.0; // perfect fit is ideal
    } else if post_residual <= quarter / 2 {
        score += 18.0; // tiny sliver, nearly dead
    } else if post_residual <= quarter {
        score += 9.0;
    } else if post_residual <= half {
        score -= 3.0; // sweet spot: fits mid-size future items
    } else {
        score -= 6.0; // large residual left, bin still very usable
    }

    // Modulo coupling: reward residuals that are multiples of common item
    // granularity (items 1..100 often cluster on multiples of 5/10).
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Integer-division threshold on next_item_size: does the lookahead item
    // fit into the post residual? Strongly reward / penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
            // exact pairing bonus via harmonic class
            if post_residual - next_item_size <= quarter / 4 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.85;
        // if this bin is the only fitting option, opening is necessary
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (1.0 - progress);
        // many open bins with high mean residual -> discourage new bins
        score += open_bins_count as f64 * 1.5;
        if mean_residual > cap * 0.3 {
            score += 10.0;
        }
    }

    // Mild preference for tighter bins overall (waste minimization).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
