}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Medium dead space (10..=25) is often unusable for items >=10; mild penalty.
    if post_residual >= 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit post_residual but post_residual is large, penalize waste.
    if next_item_size > post_residual as u32 && post_residual > 30 {
        score += 10.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a tight fit — favor.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
