                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // gen-71 mutation: reward fresh bins whose residual packs the next item
        // into a still-usable leftover scaled by mean residual (dead-space coupling)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let leftover = new_pr - nx;
                let usable_scale = mean_residual . max (1.0);
                if leftover >= usable_scale * 0.8 {
                    score -= 0.28 * (1.0 - progress * 0.5);
                }
            }
        }
        // gen-71 mutation: prefer fresh bins for items that exactly halve capacity
        if item_size * 2 == bin_capacity { score -= 0.35; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

