pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space: residual too small for any plausible item (1..=100).
        if post_residual < 10 {
            score += 40.0; // tiny sliver is wasted space
        }
        // Dead-space penalty grows when residual is small but nonzero.
        score += (10.0_f64.min(post_residual as f64)) * 0.5;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0; // perfect chain: this bin will be exactly filled next step
        } else if post_residual as u32 >= next_item_size {
            // Bin can also host the next item: reward closeness of that second fit.
            let second_residual = post_residual as f64 - next;
            score -= 120.0 - 2.0 * second_residual.min(100.0);
        } else {
            // Next item cannot fit here; mildly penalize if we leave a gap smaller than next item.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next {
                score += 0.4 * (next - gap);
            }
        }
    }

    // Compare post_residual relative to mean residual: prefer bins that end tighter than average.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: prefer existing bins unless they fit badly.
        score += 60.0;
        // If lookahead chains perfectly into a fresh bin, allow opening it.
        if next_item_size > 0 && (bin_capacity - item_size) as f64 == next_item_size as f64 {
            score -= 400.0;
        }
    }

    // Slight preference early in the stream to keep bins open and consolidated later;
    // late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating bins when many are already open.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

