pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward high fill ratio (low post_residual relative to capacity)
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill * fill;

    // Penalize post-residual that is small but unusable for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host next item: mild reward scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space for the lookahead item: penalize proportionally
            let dead = post_residual as f64;
            score += 0.5 * dead + 10.0 * (dead / next_item_size as f64);
        }
    } else {
        // last item: maximize packing tightness aggressively
        score -= 20.0 * fill;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let time = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(3.0);
        // base cost of a fresh bin; reduced when forced or crowded with small residuals
        score = 70.0 - 40.0 * pressure - 6.0 * crowding - 10.0 * time;
        // if the next item is large, a fresh bin is more flexible
        if next_item_size >= item_size {
            score -= 12.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (perfect fit shaping)
        let gap = (bin_residual - item_size) as f64;
        score += 0.3 * gap;
