        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Slight global consolidation: with many open bins, favor filling existing ones
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

