        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // penalize new bin when open bins would leave tiny slivers
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        // near-perfect post-fit for next item
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        // two-step fit for next item from a fresh bin
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large chunks
    // are more "reusable" by future items (items often come in coarse sizes).
    let pr = post_residual;
    let class_penalty = match pr % 20 {
        0 => -6.0,
        10 => -3.0,
        5 | 15 => -1.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: small post-residuals are dead space.
    let dead = (pr / 10) as f64; // coarse dead-space measure
    score += (dead * dead) * 0.35; // quadratic penalty on wasted space

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // nearly, strongly favor this bin (pairing bonus via modulo classes).
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap <= 5 {
            score -= 10.0;
        } else if gap % 10 == 0 {
            score -= 6.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > pr {
        // next item cannot use the leftover: penalize proportionally
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when many bins are already open with usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 8.0; // an open bin could have absorbed this item
        }
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Prefer bins whose residual is close to the mean (balance), mildly.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Harmonic coupling between item size class and post residual class:
    // items in "big" classes (>=50) should go into bins leaving round residuals.
    if item_size >= 50 && pr % 10 == 0 {
        score -= 4.0;
    }
    if item_size < 30 && pr >= 70 {
        score += 4.0; // don't waste big residual on tiny item if avoidable
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
