            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // NEW: dead-space pressure — residual far above mean wastes space
            if mean_residual > 0.0 && chain_residual > mean_residual * 1.5 {
