    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits: reward proportional to match quality
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 40.0; // perfect two-item packing
            }
        } else {
            // post_residual leaves unusable dead space relative to next item
            score += 15.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins: prefer bins with residual
    // close to item size (tight relative to fleet state).
    let resid = bin_residual as f64;
    score += 0.3 * (resid - mean_residual).abs();
    if (resid - item_size as f64).abs() < 5.0 {
        score -= 10.0; // near-perfect fit relative to current bin state
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and lookahead doesn't benefit.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            score -= 20.0; // fresh bin is fine if it also serves the next item
        }
    }

    // Early in stream: consolidate into few bins; late: keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
