            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        // extra penalty when the existing bin would be left with a useless sliver
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    // small-waste guard after next item placement
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to capacity, with a steep curve.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: slight penalty proportional to waste.
        score += 3.0 * (next_item_size as f64 - post_residual as f64).abs() / 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins,
    // penalize opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are many open bins or slack is plentiful.
        score += 10.0 + 0.8 * open_bins_count as f64 + 0.15 * mean_residual;
        // Early in the stream, new bins are cheaper; late in the stream, expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If item is large and no bin fits well, opening a fresh bin is reasonable.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 18.0;
        }
    } else {
        // Reusing an open bin reduces fragmentation; reward more when bins are plentiful.
        score -= 0.3 * open_bins_count as f64;
        // Reward keeping residuals near multiples of common item sizes.
        let r = post_residual as f64;
        if r <= 10.0 {
            score -= 5.0; // near-perfect closure of the bin
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good
    // candidate to consume (it's the most fragmented).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.1 * dev;

    score
}

