        // two-step fit for next item from a fresh bin
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        // large items into fresh bins early
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        // after-fit headroom checks
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // fragmentation sweep: penalize fresh-bin residuals that are unusable slivers vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 && new_pr < mean_residual * 0.35 {
            score += 0.4 * (1.0 - new_pr / (mean_residual * 0.35));
        }
        // reward fresh-bin residuals that can host two next-size items
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && new_pr - 2.0 * nx <= mean_residual . max (4.0) {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a convex quadratic penalty
    // that grows super-linearly for large leftover dead space.
    let mut score = norm_pr + 1.8 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: late in the stream, dead space
    // becomes more costly (fewer chances to fill it), so amplify the
    // quadratic term with a smooth polynomial in progress.
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 2.5 * late * norm_pr * norm_pr;

    // Reward tight fits: subtract a smooth bump centered at zero post-residual.
    let tightness = (-norm_pr * 4.0).exp();
    score -= 3.0 * tightness;

    // Penalize medium-range residuals (awkward gaps) with a smooth bump
    // centered around ~40% of capacity.
    let mid_gap = ((norm_pr - 0.4) * 5.0) * ((norm_pr - 0.4) * 5.0);
    score += 0.9 * (-mid_gap).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * late;
    }

    // Lookahead coupling: if the next item fits into the resulting post
    // residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 1.5 * (-slack * 6.0).exp();
        } else {
            // next item won't fit: mild penalty scaled by wasted potential
            score += 0.4 * (nxt - pr) / cap;
        }
    }

    // Mild preference for bins whose residual is below the open-bin mean
    // (consolidate space into fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64) / cap;

    // Slight pressure against accumulating too many open bins late.
    score += 0.02 * open_bins_count as f64 * (0.5 + late);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
