    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 dead-space classes
    let pr_class = post_residual % 10;
    // Penalize residuals that fall in "awkward" small classes (1..9 dead space unlikely to be reused)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin is fine actually; but tiny residual is dead space
        // actually tiny residual is GOOD (bin almost full): reward instead
        score -= 60.0;
    }
    // Mid-range awkward residuals (11..25) are classic dead zones
    if post_residual >= 11 && post_residual <= 25 {
        score += 18.0;
    }
    // Harmonic reward: post_residual divisible by 10 is a clean class, easily refilled
    if pr_class == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Divisibility by 5 secondary harmonic
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit the post residual exactly or well?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0; // perfect lookahead fit
        } else if slack <= 5 {
            score -= 22.0;
        } else {
            score -= (slack as f64).ln().max(0.0) * 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: residual becomes dead space
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly unless current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // open a new bin when open bins have little room or many awkward residuals
        let pressure = if mean_residual < item_size as f64 + 5.0 { 0.0 } else { 15.0 };
        score = 55.0 + pressure - fragmentation * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
