    }

    // Late-stream tightening: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Prefer bins whose residual is closest to item size (tight fit)
    score -= (bin_residual - item_size) as f64 * 0.15;

    score
}

