        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // NEW: fresh-bin dead-space ratio — discourage fresh bins whose post
        // residual sits in the "unusable sliver" band relative to mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let sliver_band = mean_residual * 0.35;
            if new_pr < sliver_band {
                score += 0.45 * (1.0 - new_pr / sliver_band) * (0.4 + 0.6 * progress);
            }
            // reward fresh bins whose residual can absorb the mean residual
            // together with the next item (triple-fit lookahead)
            if next_item_size > 0 {
                let nx = next_item_size as f64;
                let triple_left = new_pr - nx - mean_residual;
                if triple_left >= 0.0 && triple_left <= 4.0 {
                    score -= 0.28 * (1.0 - triple_left / 4.0);
                }
            }
        }
        // NEW: when only one open bin fits and the fresh residual after placing
        // the item cannot host the next item, strongly prefer the open bin
        if fitting_bins_count == 1 && next_item_size > 0 && new_pr < next_item_size as f64 {
            score += 0.8 * (1.0 - (next_item_size as f64 - new_pr) / cap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (near-perfect packing).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post-residual, dead space for the lookahead: penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins with below-mean residual (tighter bins keep big gaps available elsewhere).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New empty bin: only attractive late in the stream or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - progress * 25.0 + open_bins_count as f64 * 0.3;
    }

    score
}

