pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: residual exactly consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits, leaving a chainable residual
            let chain = post_residual - next_item_size;
            score -= 300.0 - (chain as f64).min(300.0);
        } else {
            // next item cannot fit here: dead space for lookahead, penalize
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if only this bin can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a new bin when open bins give a good fit.
    if bin_residual == bin_capacity {
        // new bin: baseline penalty unless current fits are terrible
        score += 50.0;
        if post_residual == 0 {
            score -= 200.0; // item exactly fills a fresh bin
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild preference for fewer open bins (consolidation).
    score += open_bins_count as f64 * 0.1;

    // Squared residual: convex penalty on wasted space.
    score += (post_residual as f64).powi(2) * 0.01;

    score
}

