    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item could use this bin's post-residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or
    // the fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let bad_fit = 1.0 - fit_ratio;
        score = 15.0 + 20.0 * pressure * bad_fit - 10.0 * (1.0 - pressure);
        if fitting_bins_count <= 1 {
            score += 30.0; // never open new bin if an open bin is the only fit
        }
    }

    // Global state coupling: when mean residual is low, conserve open-bin capacity.
    let mr = mean_residual / bin_capacity as f64;
    score += 8.0 * (0.5 - mr);

    // Time horizon: early in stream, be more liberal with new bins (future unknown);
    // late in stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
