    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, dead space is heavily penalized.
    let progress_coupling = 1.0 + 4.0 * progress * progress * (1.0 + progress);
    score *= progress_coupling;

    // Non-linear interaction: post_residual squared vs mean residual.
    // Penalize bins whose post-residual deviates above the fleet mean (creates outliers).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving space that the next item can use.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 15.0;
    } else if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild penalty for opening new bins when many are already open.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Small preference for fuller bins overall (waste minimization pressure).
    score -= 0.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    score
}

