            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        // large items into fresh bins early
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        // after-fit headroom checks
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // endgame: prefer fresh bins whose residual exceeds mean residual (keeps space usable)
        if mean_residual > 0.0 && progress > 0.6 && new_pr >= mean_residual * 0.9 {
            score -= 0.1 * (1.0 - progress) . min (0.5);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose residual falls into
    // "reusable" classes (multiples of common item granularities) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Class 1: residual exactly matches a plausible next-item size band -> great
        if next_item_size > 0 && pr >= next_item_size {
            // residual can host the lookahead item exactly or nearly
            let slack = pr - next_item_size;
            score -= (10.0 + slack as f64 * 0.3).min(20.0);
        }
        // Class 2: residual in low-dead-space zones (small leftovers are often reusable)
        let frac = pr as f64 / cap;
        if frac < 0.10 {
            score -= 6.0; // tiny residual = bin "closed" cleanly, little waste left stranded
        } else if frac < 0.25 {
            score += 2.0; // awkward mid-low zone
        } else if frac < 0.5 {
            score += 4.0;
        }
        // Integer-division harmonic classes on residual modulo common sizes
        let m = pr % 10;
        if m == 0 {
            score -= 3.0; // aligned residuals pack well with 10-multiple streams
        } else if m > 7 {
            score += 2.0;
        }
    } else {
        // Perfect fill: strongly reward
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate bias: only attractive when current bin leaves bad residue
    if bin_residual == bin_capacity {
        // base cost of opening a bin; discount late in stream when mean residual is high
        score += 8.0 - (mean_residual / cap) * 4.0;
        // early in stream, opening bins is cheaper (more future to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0; // big lookahead item: fresh bin useful
        }
    }

    // Mild lookahead: avoid burning a bin that the next item would fit better
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size <= bin_residual {
        score += 3.0;
    }

    // Prefer tighter fits generally (residual proximity to item size)
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

