pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for the smallest item are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer compacting
    // (favor bins with small residual); when few bins are open, opening fresh is cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * post_residual as f64 * 0.15;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit and post-residual is small, slight penalty (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Prefer bins whose residual is already below average (compaction tendency).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let early = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        score += 25.0 - 20.0 * early;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
