            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let pair_left = new_pr - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    // small-waste penalty: leftover after next item barely wasted
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward bins where the NEXT item also fits
    // into the post_residual (perfect 2-item chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or well: strong reward proportional to tightness
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize leaving dead space that blocks it
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual is tiny
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins are badly fragmented
        score += 10.0 + mean_residual * 0.2 - (post_residual as f64 * 0.1);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open new bin
        }
    }

    // Late in stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.4 * t * t + 1.3 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 5.0 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // multi-step lookahead: reward residuals fitting next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // divisibility bonus: residual close to a multiple of next item
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // exact item-fill bonus: residual is a small multiple of current item size
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // crowd penalty grows slightly with progress to consolidate late
    score += 0.05 * open_bins_count as f64 * (1.0 - 0.5 * t) ;
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual == bin_capacity {
        // NEW BIN candidate: reset scoring baseline
        let it = item_size as f64 ;
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * it / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if it > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if it >= 0.9 * cap { score -= 0.55 ; }
        // penalize new bin when open bins would leave tiny slivers
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // near-perfect post-fit for next item
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        // two-step fit for next item from a fresh bin
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && it > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap ;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)) ; }
            }
        }
        // after-fit headroom checks
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let pair_left = new_pr - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
        // avoid opening a bin that will strand a tiny residual
        let stranded = cap - it ;
        if next_item_size > 0 && stranded > next_item_size as f64 && (stranded - next_item_size as f64) < 8.0 {
            score += 0.7 ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    // large residual bins late in the stream are less attractive
    if t > 0.6 && bin_residual as f64 > 0.5 * cap && bin_residual != bin_capacity {
        score += 0.15 * (t - 0.6) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but punish near-zero residuals (dead space waste).
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 8.0; // tiny unusable sliver is worse than a moderate gap
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can also fit in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // extra reward if next item fills the bin exactly afterward
        if next_item_size == post_residual {
            score -= 10.0;
        }
    }
    // Penalize leaving a gap that nothing of typical size can use
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // New-bin candidate handling: brand-new empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current fits are poor.
        // Estimate quality of the best alternative via mean residual spread.
        let tightness = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        // Default penalty for opening a new bin (wasteful unless necessary)
        let mut new_bin_penalty = 30.0;
        // If many bins are open and mean residual is large, opening a new bin is bad.
        new_bin_penalty += (open_bins_count as f64).sqrt() * 3.0;
        new_bin_penalty += (mean_residual / bin_capacity as f64) * 20.0;
        // If item is huge, a fresh bin gives a clean fit; reduce penalty.
        new_bin_penalty -= tightness * 15.0;
        // Early in the stream, allow more bins (spread risk); late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += progress * 20.0;
        score += new_bin_penalty.max(0.0);
    } else {
        // Existing bin: mild reward for using fuller bins (best-fit-like).
        let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Global state coupling: with many open bins, prefer consolidating into existing ones.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Mean residual coupling: if this bin is far from the mean residual, slight penalty
    // (prefer bins whose residual is representative; keeps residual distribution compact).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (dev / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // multi-step lookahead: reward residuals that fit the next item repeatedly
            if cr > 2.0 * nx {
                let r2 = cr - 2.0 * nx;
                if r2 <= 8.0 { score -= 30.0 * (1.0 - r2 / 8.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 20.0 * (1.0 - r3 / 8.0); }
                }
            }
            // divisibility bonus: residual near a multiple of next item
            let k = (post_residual as f64 / nx) . round ();
            let mult_err = (post_residual as f64 - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 35.0 * (1.0 - mult_err / 2.0); }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            // tiny-gap penalty: nearly fitting next item is dead space
            if (nx - post_residual) <= 3 { score += 60.0 * (1.0 - (nx - post_residual) as f64 / 3.0); }
        }
        // exact item-fill bonus: residual is a small multiple of current item size
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (post_residual as f64 / isz) . round ();
            if k >= 1.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 20.0 * (1.0 - progress * 0.3);
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if fitting_bins_count >= 4 { score -= 40.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance vs mean residual
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        // two-step fit from a fresh bin
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 40.0 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            // modulo-fit: fresh residual leaves near-zero remainder vs next item
            if new_pr > nx {
                let rem = new_pr - (new_pr / nx) . floor () * nx;
                if rem > 0.0 && rem < 0.03 * cap { score -= 30.0 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && next_item_size > 0 && new_pr >= next_item_size as f64 {
            let nx = next_item_size as f64;
            let pair_left = new_pr - nx;
            if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                score += 22.0 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
            }
        }
        // discourage new bins late when few fitting alternatives exist
        if progress > 0.85 && fitting_bins_count <= 2 { score += 60.0 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: post residual (lower waste preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger residuals; later: penalize them super-linearly.
    let progress_coupling = progress * norm_pr * norm_pr * cap;
    score += progress_coupling * 40.0;

    // Smooth convex penalty on residual itself (quartic-ish shaping)
    score += (norm_pr * norm_pr) * (norm_pr * cap) * 6.0;

    // Reward tight fits: item filling most of the bin
    score -= item * item * 25.0;

    // Lookahead: bonus if next item fits the post residual (smooth coupling)
    let fits_next = (nxt - norm_pr).max(0.0);
    score -= (1.0 - fits_next.min(1.0)) * 18.0 * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.3);
    }

    // Many fitting bins: this bin is less critical; slight penalty toward best-fit alternatives
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Mean residual interaction: prefer bins whose residual deviates from the mean
    // (consolidating waste into few bins), smooth via squared deviation.
    let dev = pr - mean_residual;
    score -= (dev * dev) / (cap * cap) * 10.0;

    // New-bin candidate: penalize opening a new bin, more so as stream progresses.
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
