            }
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap ;
                if rem > 0.0 && rem < 0.03 { score -= 30.0 * (1.0 - rem / 0.03) ; }
            }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 15.0 * (1.0 - progress / 0.5) ;
        }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && next_item_size > 0 && new_pr >= next_item_size as f64 {
            let nx = next_item_size as f64 ;
            let pair_left = new_pr - nx ;
            if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                score += 22.0 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress) ;
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 60.0 * (progress - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (multiples of 10 are classic friendly slots).
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 14.0,
        5 => 7.0,
        1 | 9 => 2.0,
        3 | 7 => 1.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual bucketed by what item
    // classes (10..80) could still fit. Fewer fitting classes = dead space.
    let usable_classes = post_residual / 10; // items of size <= usable_classes*10 fit
    score -= (usable_classes as f64) * 2.5;

    // Tight fit reward: relative fill of the bin.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * 20.0;

    // Last-chance bin: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize crowding when many bins already fit the item (choose best fit anyway via post_residual).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is perfect (harmonic pairing via modulo).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let pair_left = post_residual - next_item_size;
            score -= 8.0 - (pair_left as f64) * 0.15;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // New-bin candidate handling: empty bin starts neutral; make it
    // attractive only when no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 35.0 + pressure * 20.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += (open_bins_count as f64).ln() * 0.8;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
