            nb -= 0.15 * (1.0 - t / 0.5) ;
        }
        // after-fit headroom checks
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { nb -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { nb -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
