        let new_pr = (bin_capacity - item_size) as f64;
        // near-perfect post-fit for next item
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        // two-step fit for next item from a fresh bin
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // dead-space avoidance vs mean residual
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        // large items into fresh bins early
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        // after-fit headroom checks
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // mutation: prefer fresh bins whose residual stays usable for the mean item
        if new_pr > 0.0 && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.3 * (1.0 - new_pr / mean_residual);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // mutation: penalize bins that would strand a sub-mean sliver after this item
        if mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.6 {
            score += 0.35 * (1.0 - pr / (mean_residual * 0.6)) * (0.5 + 0.5 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        } else {
            // Reward bins whose leftover can still host the lookahead item.
            score -= 8.0;
        }
        // Perfect chaining: leftover exactly fits the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer filling existing bins as fully as possible.
        score -= 30.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well, or the stream is early and bins are scarce.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open bins early in the stream (more future items to fill it).
        score -= 30.0 * (1.0 - progress);
        // Expensive when many bins are already open and mean residual is large.
        score += 0.6 * open_bins_count as f64 + 0.3 * mean_residual;
        // Very expensive if an existing bin is a last chance.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // If lookahead item is large, a fresh bin is more valuable.
        score -= (next_item_size as f64) * 0.15;
    } else {
        // Prefer bins whose residual is closest to item (minimal waste) among many options.
        if fitting_bins_count > 1 {
            score += 5.0 * tightness;
        }
        // Slight preference for bins below mean residual (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild global pressure: when many bins are open, favor placements that
    // reduce average residual spread (fill fuller bins first).
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
