        // two-step fit for next item from a fresh bin
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr as f64 >= 2.0 * nx && 2.0 * nx - new_pr as f64 <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr as f64) / 6.0) ;
            }
            if (new_pr as f64) < nx && nx - new_pr as f64 <= 8.0 {
