            score -= 0.15 ;
        }
        // modulo-fit: fresh residual leaves near-zero remainder vs next item
        if new_pr > 0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr as f64 > nx {
