        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
        // pair-fragmentation risk: leftover after next item is sub-mean
        if mean_residual > 0.0 && new_pr > 0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr as f64 >= nx {
                let pair_left = new_pr as f64 - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    // late-stream waste guard: penalize residuals too small for any plausible future item
    if t > 0.6 && pr > 0.0 && pr < 6.0 {
        score += 0.3 * (1.0 - pr / 6.0) * (t - 0.6) / 0.4 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: minimize post residual, with non-linear squashing
    let mut score = post * (1.0 + 0.8 * pr * pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, demand tightness
    let progress_coupling = 1.0 - 0.9 * progress * (1.0 - progress) * 4.0 * 0.5; // smooth bump peaking mid-stream
    score += 12.0 * pr * pr * progress_coupling;

    // Reward using nearly-full bins (small post residual) increasingly over time
    score -= 15.0 * progress * (1.0 - pr);

    // Penalize dead space: post residual that no typical item can use
    let dead = if post_residual < next_item_size && post_residual > 0 { 1.0 } else { 0.0 };
    score += dead * (8.0 + 20.0 * progress);

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * snug * (1.0 - progress);
