    // are pure waste. Penalize the "dead zone" super-linearly.
    let dead_threshold = 9.0; // nothing useful fits in gaps < ~10 on typical streams
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Penalize gaps that cannot fit the known next item (creates forced fragmentation).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
