    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (which would strand this residual forever).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        // Using an existing bin keeps bin count down; slight bonus scaled by pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean residual (i.e., fuller bins),
    // keeping large residuals available in other bins for future big items.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Late in the stream, consolidation matters more: amplify existing-bin preference.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

