        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect chain: next item fills this bin exactly
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: penalize proportional to leftover slack after chain
            let chain_leftover = post_residual as f64 - next;
            score -= 25.0 * (1.0 - chain_leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space creation
            score += 15.0 + 0.3 * (next - post_residual as f64);
        }
        // proximity shaping
        score += 0.25 * diff;
    } else {
        // last item: minimize residual directly
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep neutral-ish baseline, slightly penalized so good fits win
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if item is huge relative to capacity, opening fresh bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Slight stream-progression pressure to consolidate early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

