pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic coupling of post-residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Dead-space penalty: small post-residuals are wasted space; penalize smoothly.
    let dead = (1.0 - norm_pr).powi(6);
    score += 60.0 * dead * (0.5 + 0.5 * progress);

    // Sweet spot: reward post-residuals near a fraction of capacity that shrink with progress.
    let target = 0.25 - 0.12 * progress;
    score -= 25.0 * (-(norm_pr - target).powi(2) / 0.02).exp();

    // Lookahead: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress) * (norm_next / (norm_pr + 0.1));
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress) * (1.0 - norm_next / (norm_pr + norm_next + 0.1));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Penalize opening a new bin when open bins have large mean residual and item fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 30.0 * (1.0 - norm_item) * (1.0 - progress);
        score += 0.5 * open_bins_count as f64 * (mean_residual / cap);
        // Allow new bin when mean residual is low (open bins nearly full).
        score -= 25.0 * (1.0 - (mean_residual / cap)).powi(2) * progress;
    } else {
        // Reward tight fits relative to bin residual.
        score -= 10.0 * norm_item * (norm_item / (bin_residual as f64 / cap + 0.1));
    }

    score
}

