        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // fresh-bin sliver guard: penalize opening a new bin whose residual can
        // never hold the mean residual (permanent dead space)
        if mean_residual > 0.0 && new_pr > 0.0 && new_pr < mean_residual * 0.4 {
            score += 0.5 * (1.0 - new_pr / (mean_residual * 0.4));
        }
        // reward fresh bins whose residual is a near-exact multiple of next item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let q = (new_pr / nx) . floor ();
            if q >= 1.0 {
                let rem = new_pr - q * nx;
                if rem <= 1.0 { score -= 0.25 * (1.0 - progress * 0.4); }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // penalize leaving this bin stranded: residual too small for mean item
        if mean_residual > 0.0 && pr < mean_residual * 0.3 {
            score += 0.15 * (1.0 - pr / (mean_residual * 0.3)) * (0.5 + 0.5 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions and modulo structure.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftovers that are too small to be useful
    // (below the smallest plausible item, 1..=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // "Sweet spot" residuals that many item sizes can still use.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;
    }

    // Harmonic divisibility bonus: if post_residual is a multiple of a
    // common size class, future items of that class fit exactly.
    for class in [10u32, 20, 25, 40, 50] {
        if class > 0 && post_residual % class == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Exact fit: perfect closure.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly discourage opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Favor opening a new bin when the current item is large (leaves a
    // small, clean post_residual) and many bins are already open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score -= 12.0 * frac;
        if open_bins_count > 4 {
            score -= 2.0;
        }
        // Keep new-bin attractive when post_residual falls on a harmonic
        // class boundary (e.g. 50, 25, 20) that future items can reuse.
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 4.0;
        }
    }

    // Mild pressure to prefer bins below the mean residual (tighter bins
    // get filled first, keeping looser bins flexible).
    score += (mean_residual - post) * 0.05;

    // Late-stream consolidation: near the end, prefer compacting into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

