    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..100 unknown,
    // but historically small) can use are costly. Penalize residual in (0, 20) heavily.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fills: fraction of bin used by this placement.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: discourage spreading across many bins unless it closes waste.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    // else, i.e., current bin residual leaves a big awkward gap or doesn't fit well.
    if bin_residual == bin_capacity {
        // Base neutrality: raw post_residual = capacity - item_size.
        // Penalize opening a new bin while good open capacity exists.
        if fitting_bins_count > 0 {
            let best_possible_gap = mean_residual - item_size as f64;
            if best_possible_gap >= 0.0 && best_possible_gap < 20.0 {
                // Another bin gives a tight fit -> new bin is bad.
                score += 40.0;
            }
        }
        // Reward a fresh bin when item is large relative to mean residual.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Lookahead: if next item exactly matches post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this leftover anyway; slightly less pressure to be tight.
        score += 3.0;
    }

    // Mild stream-progress coupling: later in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0 as u32) as i32 as f64;

    score
}

