        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let pair_left = new_pr - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
        // sliver penalty vs open bins: avoid opening fresh bins when open bins leave tiny slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1) ; }
        }
        if t > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (t - 0.85) / 0.15 ; }
        score = nb ;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when open bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0;
        // But allow new bin if this is the only fitting bin AND lookahead is large
        if fitting_bins_count <= 1 && (next_item_size as f64) > post_residual as f64 + 5.0 {
            score -= 45.0;
        }
