        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Reward tight fits (small post_residual) with non-linear bonus
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use this bin's post_residual,
    // reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            // next item can still use leftover space
            score -= 10.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // leftover becomes dead space for the next item
            score += 8.0 * tightness;
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late in stream, avoid creating tiny unusable residuals (< 10)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += 12.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * tightness;

    score
}

