pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    score += 40.0 * poly;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: penalize leaving residual that can't fit next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 15.0 * fits_next * (1.0 - (pr - next_item_size as f64).abs() / cap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure toward consolidation as bins accumulate
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // Penalize residuals far from mean (dead-space dispersion)
    score += 5.0 * (pr - mean_residual).abs() / cap;

    score
}

