pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of the post-residual: residual mod 10 classes.
    // Residuals that are multiples of 10 (harmonic with item sizes 10..80)
    // are reusable; odd/prime-ish residuals are dead space.
    let pr = post_residual as i64;
    let class = pr % 10;
    let class_bonus: f64 = match class {
        0 => 14.0,
        5 => 6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => -5.0, // odd residual -> poor future fit
    };
    score -= class_bonus;

    // Small post-residuals are near-perfect fits; reward strongly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 12.0;
    } else if post_residual > 50 {
        score += 8.0; // wasteful large leftover
    }

    // Lookahead coupling: does next_item_size divide/fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic: next item fits exactly or leaves harmonic remainder
            let rem = (post_residual % next_item_size.max(1)) as f64;
            score -= 10.0 + 8.0 * (1.0 - rem / bin_capacity as f64);
        } else {
            score += 6.0; // lookahead blocked by this placement
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless current bins would leave bad residuals.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).min(1.0)
        } else {
            0.5
        };
        score += 10.0 - 20.0 * pressure * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: be greedy with tight fits; late stream: consolidate.
    score -= (1.0 - progress) * (mean_residual - post_residual as f64) * 0.05;

    score
}

