        if mean_residual > 1.0 && new_pr > 0.0 {
            let ratio = new_pr / mean_residual;
            let frac_err = (ratio - ratio . round ()) . abs ();
            if ratio . round () >= 1.0 && frac_err <= 0.1 {
                score -= 0.2 * (1.0 - frac_err / 0.1) * (1.0 - progress * 0.5);
