    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            // Perfect two-item packing: strong reward.
            score -= 100.0;
        } else {
            // Penalize leftover gap after the lookahead item.
            score += diff as f64 * 1.5;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here; penalize dead space creation.
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Reward tight fits relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize bins far from the mean residual (favor typical bins unless perfect lookahead).
    let dev = post_residual as f64 - mean_residual;
    score += dev * dev * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead-space penalties for unusable slivers.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0 * (item_size as f64 - post_residual as f64) / cap;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 3.0 * (20.0 - post_residual as f64) / cap;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 4.8;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.35 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            // divisibility bonus: residual close to a multiple of next item
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // wasted-space penalty grows with progress
            let wasted = chain / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
        } else {
            // next item won't fit here: residue becomes dead space
            let gap = (nx - pr) / cap;
            score += 0.25 + 0.003 * pr + 0.55 * progress;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
        }
        // exact item-fill bonus: residual is a small multiple of current item size
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness reward.
    let tightness = 1.0 - pr / cap;
    score -= 2.0 * tightness * tightness;

    // Last-chance bonus: only bin that fits — keep it open.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins below mean residual (keep large gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // ---- NEW-BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // penalize new bin when open bins would leave tiny slivers
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
