pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into usable buckets.
    // Residuals that are "harmonically nice" (divisible into common item sizes) are penalized less.
    let pr = post_residual;
    let mut harmony_bonus = 0.0f64;
    if pr == 0 {
        harmony_bonus = 40.0; // perfect fit, best possible outcome
    } else {
        // Check divisibility of residual by common harmonic sizes
        for &h in &[10u32, 20, 25, 50] {
            if pr % h == 0 {
                harmony_bonus += 6.0;
            }
        }
        // Small residuals are dead space; penalize proportionally via quadratic term
        if pr <= 10 {
            score += 15.0 + (10 - pr) as f64 * 2.0;
        } else if pr <= 20 {
            score += 5.0;
        }
    }
    score -= harmony_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // next item fits: reward tightness of that future fit
            let future_waste = pr - next_item_size;
            score -= 12.0 - (future_waste as f64).min(12.0);
            // harmonic check: does post_residual - next_item leave a nice class?
            let fr = pr - next_item_size;
            if fr == 0 || fr % 10 == 0 || fr % 25 == 0 {
                score -= 8.0;
            }
        } else {
            // next item does NOT fit here: residual becomes truly dead unless huge
            if pr < next_item_size {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all bad.
    if bin_residual == bin_capacity {
        score += 20.0;
