        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Early in stream, opening bins is fine (need spread); late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Mild penalty for spreading across too many open bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    // Prefer bins whose residual is close to item size (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    score
}

