    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when existing bins could fit.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).sqrt() * 8.0
            + fitting_bins_count as f64 * 25.0
            + t * 15.0;
        score += 60.0 + pressure;
        // Allow new bin only if the item barely fits anywhere and future item is big.
        if fitting_bins_count <= 1 && next_item_size >= bin_residual {
            score -= 55.0;
        }
        return score;
    }

    // Reward tight fits: minimize post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Penalize large dead space that no small item can use later.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // nearly perfect fill
    }
    if post_residual > 50 {
        score += 8.0; // wasteful large gap
    }

    // Lookahead: bonus if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Global state coupling: prefer filling bins when many are open.
    score -= (open_bins_count as f64).ln() * 3.0;

    // Deviation from mean residual: prefer bins below mean (fill the fullest).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Time horizon: early stream, be flexible; late stream, pack tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 4.0 - t * 6.0;

    score
}

