pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 class determines dead-space quality.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in "harmonic" classes (0, 5, divisible by small numbers) are more reusable.
    let harmonic_bonus = match class {
        0 => 6.0,
        5 => 3.0,
        2 | 4 | 6 | 8 => 1.5,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: post_residual bucketed by /10.
    let bucket = pr / 10;
    // Buckets that can host common item sizes (>=10) are valuable; below 10 is dead space.
    if pr < 10 {
        score += 12.0; // dead space penalty
    } else {
        score -= (bucket.min(9) as f64) * 0.8;
    }

    // Capacity fraction: how full the bin becomes.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 8.0; // reward high fill non-linearly

    // Perfect fit coupling with lookahead: if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += 2.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + 10.0 * (1.0 - progress) - (item_size as f64 / 10.0);
        // Opening early is fine for large items that would waste an existing bin.
        if item_size > 60 && fitting_bins_count > 0 && post_residual > 25 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: if this bin is far below mean residual, deprioritize.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Many open bins: encourage consolidating into existing bins.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Non-linear penalty for mid-size wasted gaps (hard to fill later).
    let pr = post_residual as f64;
    score += 0.15 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-fit reward: post_residual close to but below next item size is valuable.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 12.0;
        } else if post_residual < next_item_size {
            // gap too small for the lookahead item: penalize mildly.
            score += 6.0;
        } else {
            // gap can host the next item: reward proportionally.
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (pr / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced use).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: penalize opening a new bin unless current bins are mostly full
    // and the item is large relative to remaining space.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let base = 45.0 + 25.0 * avg_fill;
        score += if large_item && avg_fill > 0.7 { 10.0 } else { base };
        // Late in the stream, opening fresh bins is less costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // dead-space penalty: leftover after chain is a sub-mean sliver
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            // NEW: deeper 3-item chain lookahead — reward residuals that survive two more items
            if chain_residual >= 2.0 * nx {
                let r2c = chain_residual - 2.0 * nx;
                if r2c <= 6.0 { score -= 0.3 * (1.0 - r2c / 6.0) * (1.0 - progress * 0.4); }
            }
            // NEW: penalize chain remainders that are awkwardly just below the mean residual
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let frac = chain_residual / mean_residual;
                if frac > 0.6 && frac < 1.0 {
                    score += 0.18 * (1.0 - (frac - 0.6) / 0.4) * progress;
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            // NEW: if next item can pair with this residual using a future mean-sized item
            if mean_residual > 0.0 && pr > 0.0 && mean_residual <= pr {
                score -= 0.15 * (1.0 - progress * 0.5);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // refined: fresh-bin residual should stay usable across several future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        // refined: avoid opening a bin that strands a large current-item remainder
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        // NEW: fresh-bin residual that exactly tiles by next item size is highly attractive
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 && (new_pr - k * nx) . abs () <= 1.0 {
                score -= 0.28 * (1.0 - progress * 0.3);
            }
        }
        // NEW: penalize opening a fresh bin whose residual sits in the dead zone just below mean_residual
        if mean_residual > 1.0 && new_pr > 0.0 && new_pr < mean_residual {
            score += 0.25 * (1.0 - new_pr / mean_residual) * (0.4 + 0.6 * progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

