pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;                       // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 25.0;                         // perfect 2-step fit bonus
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 12.0;                         // near-perfect follow-up fit
        }
        // Penalize leaving a residual that is too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.9;
        }
    } else {
        // Last item: just minimize leftover
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean-residual adjustment: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 10;
        if tight_fit_exists {
            score += 40.0;   // an open bin offers a great 2-step chain, keep it closed
        }
        score += 15.0;       // baseline cost of opening a new bin
        if fitting_bins_count > 0 {
            score += 10.0;   // extra penalty when some open bin already fits
        }
    }

    // Small penalty for dead space that is unusable for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild late-stream consolidation: fewer bins preferred as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Exact-fill reward.
    if post_residual == 0 { score -= 8.0; }

    // Dead-space avoidance: unusable slivers penalized.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0 * (item_size as f64 - post_residual as f64) / cap;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 3.0 * (20.0 - post_residual as f64) / cap;
    }

    // Lookahead chain: does the next item (and beyond) fit in the residue?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.35 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            // multiple copies of next item exactly filling residue
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain > 0.0 && chain < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else if pr > 0.0 {
            // next item won't fit -> residue likely dead
            let gap = nx - pr;
            score += 0.25 + 0.003 * (pr - mean_residual).max(0.0) + 0.55 * progress;
            if gap as f64 / cap < 0.25 { score += 1.8 * (1.0 - gap as f64 / (0.25 * cap)) * (1.0 - 0.5 * progress); }
            if gap <= 3 { score += 1.0 * (1.0 - gap as f64 / 3.0); }
        }
        // exact-fit bonus for current item too
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - 0.3 * progress);
            }
        }
    }

    // Last-chance: only fitting bin -> keep it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual preference.
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // New-bin candidate evaluation.
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if pr >= nx {
                let after = pr - nx;
                if after >= mean_residual.max(1.0) { score -= 0.18 * (1.0 - 0.4 * progress); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            } else {
                let miss = (nx - pr) / cap;
                score += 0.5 * miss.min(0.3);
            }
        }
        if mean_residual > 0.0 && pr > 0.0 {
            let usable = if pr >= mean_residual { 1.0 } else { pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let fits_ahead = (pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - 0.5 * progress).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.2 * pr / cap;
        if gap <= 4.0 { score += 0.65 * (1.0 - 0.3 * progress); }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (-tightness * 12.0).exp();

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 {
        let usable = post_residual >= 10;
        if !usable {
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        }
    }

    // Lookahead: reward bins whose residual can also host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.05 * post_residual as f64;
        } else {
            // Penalize leaving a residual just barely below the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 25.0 {
                score += 0.4 * gap;
            }
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins with large mean residual: discourage fragmenting, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 30.0 && open_bins_count > 3 {
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: only attractive when no good fit exists,
    // i.e., current bin fit is poor and mean residual across open bins is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = post_residual as f64 > 55.0;
        let desperate = fitting_bins_count == 0 || mean_residual < 15.0;
        if poor_fit && desperate {
            score -= 20.0; // opening a fresh bin is fine
        } else {
            score += 45.0 + 10.0 * progress; // prefer existing bins
        }
    }

    // Mild time-horizon coupling: early on, keep bins flexible (larger residuals ok);
    // late in the stream, favor compacting tightly.
    score += 5.0 * progress * (post_residual as f64 / 100.0);

    // Small deterministic tie-breaker favoring bins with residual close to item+next size.
    if next_item_size > 0 {
        let target = (item_size + next_item_size) as f64;
        score += 0.03 * (bin_residual as f64 - target).abs();
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
