        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is punished more aggressively.
    let waste_penalty = x * x * (1.0 + 2.0 * progress) + x * x * x * (0.5 + 3.0 * progress);
    score += waste_penalty * cap * 0.5;

    // Reward near-perfect fits smoothly (residual close to 0).
    let perfect_fit = (1.0 - x).powi(6);
    score -= perfect_fit * cap * 0.6;

    // Dead-space term: residuals too small for typical future items are bad.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            // unusable for the lookahead item: penalize proportionally to how close it is
            let gap = (ni - pr) / cap;
            score += gap * cap * (0.3 + progress);
        } else {
            // reward leaving space exactly usable for the next item
            let usable = 1.0 - ((pr - ni) / cap).abs();
            score -= usable * usable * 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        // spread mild penalty across many fitting bins to prefer tightest choice
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate: penalize opening a new bin, but relax when open bins
    // have large mean residual spread (poor fits) or late in the stream.
    if bin_residual == bin_capacity {
        let mean_x = mean_residual / cap;
        let desperation = mean_x * mean_x * (1.0 + progress);
        score += 15.0 - desperation * 10.0 - progress * 4.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        }
    } else {
        // reward reusing bins mildly, scaled by number of open bins
        score -= (open_bins_count as f64).ln() * 0.3;
    }

    // Smooth global tilt: as stream progresses, prefer consolidation into fewer bins.
    score += progress * mean_residual * 0.05;

    score
}

