pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 define "waste classes".
    let class = post_residual % 10;
    // Penalize awkward residual classes (1..9 are less reusable than multiples of 10/20).
    let class_penalty: f64 = match class {
        0 => -6.0,
        5 => -2.0,
        2 | 4 | 6 | 8 => -1.0,
        _ => 2.0, // odd residues 1,3,7,9 are hard to reuse
    };
    score += class_penalty;

    // Integer-division threshold: residual buckets of 25.
    let bucket = post_residual / 25;
    score += match bucket {
        0 => -8.0,      // near-perfect fill
        1 => -3.0,
        2 => 0.0,
        _ => 5.0,       // large leftover waste
    };

    // Lookahead coupling: reward when next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tight_exists = post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10);
        score += if tight_exists { 0.0 } else { 15.0 + 0.1 * open_bins_count as f64 };
        // early stream: opening bins is cheap
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Mean residual alignment: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
