        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect-fill reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead-space avoidance: unusable residue penalized.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0 * (item_size as f64 - post_residual as f64) / cap;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 0.5 * (20.0 - post_residual as f64) / cap;
    }

    // Lookahead chain: if next item fits, how good is the chain leftover?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.0;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.3 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.8; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            // second-order lookahead: room for another next-item
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.4 * (1.0 - r2 / 15.0); }
            }
            // multiplicative fit: residual divisible by next item
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // sliver leftover after chain is future dead space
            if mean_residual > 0.0 && chain > 0.0 && chain < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            // next item won't fit: near-miss penalty
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.6 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress); }
            if (nx - pr) as f64 <= 3.0 { score += 0.9 * (1.0 - (nx - pr) as f64 / 3.0); }
            score += 0.2 + 0.5 * progress;
        }
    }

    // Tight-fit reward.
    let tightness = 1.0 - pr / cap;
    score -= 3.0 * tightness * tightness;

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure: fill existing bins, stronger late.
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (keep large gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // NEW-BIN CANDIDATE logic (borrowed from best, adapted).
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // fresh-bin residual usable across many future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - 0.5 * progress); }
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
            } else if nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.45 * (next_item_size - post_residual) as f64;
    }

    // Reward residual that can still host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.35 * (post_residual as f64).min(30.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // When many bins fit the item, prefer the one with the smallest residual
    // (best-fit coupling via mean_residual context).
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - mean_residual) * 0.12;
    }

    // Late in the stream, pack tightly into existing bins; early on, allow
    // spreading to keep flexibility (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or open-bin fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 0 && post_residual < item_size / 2);
        if poor_fits {
            score -= 5.0;
        } else {
            score += 10.0 + 0.05 * open_bins_count as f64;
        }
    }

    // Mild penalty for very fragmented residual (small unusable leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let t = progress;
    let mut score = pr / cap;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead-space polynomial coupling
    let dead_weight = 1.0 + 2.0 * t * t;
    score += dead_weight * (pr / cap).powi(2);

    // Tightness reward
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus for the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Consolidation pressure early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean residual alignment
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            // Lookahead chain: residual can host next item
            let chain = pr - nx;
            score -= 1.35 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            // Two-step chain
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
            }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // Dead-space sliver penalty
            if mean_residual > 0.0 && chain > 0.0 && chain < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain / (mean_residual * 0.4)) * (0.5 + 0.5 * t);
            }
        } else {
            // Residual misses next item: penalize near-misses
            let gap = (nx - pr) / cap;
            score += 0.25 + 0.55 * t;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5);
            }
            if nx - pr <= 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / 3.0);
            }
        }
        // Multiplicity fit of residual against current item
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3);
            }
        }
    }

    // ---- NEW-BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        let nx = next_item_size as f64;
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64;
        score -= 0.45 * fit_ratio;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if nx > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // Big item into fresh bin: avoid stranding remainder
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 {
                score += 1.3 * (1.0 - slack / 0.1);
            } else if slack > 0.3 && slack < 0.5 && nx > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3; }
        // Fresh-bin residual should accommodate next item
        if nx > 0.0 && new_pr >= nx {
            let r = new_pr - nx;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
        }
        if nx > 0.0 && new_pr < nx && nx - new_pr <= 8.0 {
            score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
        }
        // Residual usable across several mean-sized future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - t * 0.5).min(1.0); }
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t);
        }
        // Late stream: prefer opening bins when few fit options
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15; }
        if open_bins_count >= 6 && fit_ratio > 0.6 { score -= 0.3; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Near-miss residual penalty
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: raw post residual, normalized.
    let mut score = pr / cap;

    // Non-linear coupling: squared residual penalty scaled by stream progress
    // (late in the stream, waste is costlier).
    let waste_term = (pr / cap).powi(2) * (1.0 + 2.0 * progress);
    score += waste_term;

    // Perfect-fit reward: smooth polynomial trough near zero residual.
    score -= 0.8 * (1.0 - (pr / cap)).powi(3);

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residual that wastes potential for it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 0.5 * (1.0 - slack.powi(2));
        } else {
            let gap = (nx - pr) / cap;
            score += 0.6 * gap * gap;
        }
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // existing fits are terrible (small fitting set) or progress is early.
    if is_new_bin {
        let scarcity = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        score += 0.9 - 0.5 * scarcity - 0.3 * progress;
        // Encourage a fresh bin when it can absorb the next item too.
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 0.4;
        }
    } else {
        // Last-chance bonus: strongly favor the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 1.2;
        }
        // Crowd control: prefer bins whose residual deviates favorably from mean.
        let dev = pr - mean_residual;
        score += 0.05 * dev / cap;
        // Prefer filling already-open bins as open count grows.
        score -= 0.02 * (open_bins_count as f64).ln().max(0.0);
    }

    // Smooth global regularization.
    score += 0.001 * (pr / cap).powi(3) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect-fill bonus.
    if post_residual == 0 { score -= 8.0; }

    // Dead-space avoidance: gaps that can't fit even a small item are wasted.
    if post_residual > 0 && post_residual < 20 {
        score += 0.12 * (20.0 - post_residual as f64);
    }

    // ---- Lookahead chain logic (borrowed from best, tightened) ----
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // second-level lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            // multiplicative fit: k copies of next item
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // sub-mean sliver after chain becomes dead space
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            // next item won't fit here: residue becomes orphaned
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
        }
        // divisibility hint: post_residual divisible by current item size
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins below mean residual (keep big gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // fresh-bin residual should stay usable across several future items
        let new_pr = cap - item_size as f64;
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5); }
        }
        // avoid stranding a large remainder when other bins could take it
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = ((next_item_size as f64 - new_pr) / cap).min(0.3);
            score += 0.5 * miss;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // near-miss: next item almost fits in the residue
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // Dead-space penalty grows for residuals in awkward class gaps.
        // Residuals <= 9 are "dead" (smallest item is 1, but large items 10..80 waste them).
        if post_residual < 10 {
            score += 30.0;
        }
        // Harmonic class: residual mod 10 — small remainders are more reusable.
        let cls = post_residual % 10;
        score -= cls as f64 * 1.5;
        // Integer division thresholds: residual in [10,20) is a good slot for small items.
        if post_residual < 20 {
            score -= 10.0;
        } else if post_residual < 30 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = (post_residual - next_item_size) as f64;
        score -= 25.0 + tight * 0.5;
        // Extra reward if next item then fills bin completely (chain of perfect fits).
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving large stranded residual.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer bins with below-mean residual (tighter bins first) — best-fit flavor.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: penalize opening a new bin unless current options are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keeps it behind decent existing fits.
        score = 45.0 + post_residual as f64;
        // Early in the stream, opening bins is cheaper (build a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins are open already, discourage proliferation.
        score += open_bins_count as f64 * 1.0;
        // If next item is large, a fresh bin is attractive (room for it later).
        if next_item_size >= 60 {
            score -= 15.0;
        }
        // If only one bin fits and its fit is loose, new bin becomes competitive:
        // handled implicitly since existing-bin score already got penalties.
    }

    // Mild tie-break noise-free ordering: prefer filling larger residual bins.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Exact-fill reward
    if post_residual == 0 { score -= 8.0; }

    // Strict dead-space avoidance: penalize unusable residue quadratically.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0 * (item_size as f64 - post_residual as f64) / cap;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 3.0 * (20.0 - post_residual as f64) / 100.0;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - pr / cap;
    score -= 4.0 * tightness * tightness;

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // ---- Lookahead chain logic (borrowed & adapted) ----
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.0;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // two-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            // multiple of next item fits almost exactly
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // dead-space penalty: leftover after chain is a sub-mean sliver
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else if pr > 0.0 {
            // next item won't fit here -> residue becomes dead space
            let gap = (nx - pr) / cap;
            score += 1.0;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) as f64 <= 3.0 { score += 1.0 * (1.0 - (nx - pr) as f64 / 3.0); }
        }
        // residue divisible by current item size
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    // Slightly prefer bins below mean residual (keep big gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = ((next_item_size as f64 - new_pr) / cap).min(0.3);
            score += 0.5 * miss;
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            // fresh-bin residual should stay usable across several future items
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
