            if tile_err < 0.02 { score -= 0.22 * (1.0 - tile_err / 0.02) * (0.6 + 0.4 * progress); }
        }
        // refined: avoid opening a bin that strands a large current-item remainder
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        // refined: penalize opening a new bin when its dead space exceeds the mean residual badly
        if mean_residual > 0.0 && new_pr > 0.0 && new_pr < mean_residual * 0.7 {
            score += 0.45 * (1.0 - new_pr / (mean_residual * 0.7)) * (0.5 + 0.5 * progress);
        }
        // refined: late-stream, prefer bins whose leftover can absorb the next two items exactly
        if progress > 0.6 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && (new_pr - 2.0 * nx) <= 4.0 {
