    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Strict dead-space avoidance ----
    // Gaps too small to ever hold a real item are pure waste: hard penalty.
    let min_useful_gap = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < min_useful_gap {
        score += 25.0 + (min_useful_gap - post_residual as f64) * 2.0;
    }

    // ---- Lookahead coupling (k=2) ----
    // Reward bins whose leftover can still host the next item;
    // mildly penalize bins that strand space the next item could have used.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    // ---- Open-bins pressure ----
    // The more bins are open, the more we punish leaving large residuals
    // scattered around (fragmentation), pushing consolidation into tight fits.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 0.15 * open_bins_count as f64 * residual_frac;

    // Bins with residual close to the mean are "typical" candidates;
    // slight tie-break toward bins tighter than average.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // ---- Last-chance bonus ----
    // If this is the only open bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // ---- New-bin candidate penalty ----
    // Brand-new empty bin: only attractive if existing fits are bad.
    // Penalty grows with the number of already-open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 8.0;
    }

    // Chain lookahead: simulate placing next item, then the one after
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let chain_residual = pr - nx;
            score -= 1.4 * (1.0 - chain_residual / cap);
            if chain_residual == 0.0 { score -= 3.0; }
            // second-level lookahead: chain_residual divisible by next item
            if chain_residual > 0.0 && chain_residual >= nx {
                let r2 = chain_residual - nx;
                if r2 <= 8.0 { score -= 0.4 * (1.0 - r2 / 8.0); }
            }
            // near-multiple reward
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // dead-space sliver after chain
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else if pr > 0.0 {
            // next item won't fit here: penalize near-misses (dead space)
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            score += 0.25 + 0.55 * progress;
        }
    }

    // Tightness reward for current placement
    let tightness = 1.0 - pr / cap;
    score -= 4.0 * tightness * tightness * 0.15;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Open-bin pressure
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins below mean residual (keep big gaps alive)
    if (bin_residual as f64) < mean_residual {
        score -= 0.3;
    }

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        // fresh-bin residual usable across several future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5); }
        }
        // avoid stranding remainder when good fits exist
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        // next item fits fresh bin residue nicely
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        // fresh bin would strand a near-miss for next item
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
        // late stream: prefer closing out open bins
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // near-miss on open bin: residue likely dead
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        } else {
            score += 0.2 * pr / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // closely matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // Next item can follow in this bin.
            score -= 250.0 - 4.0 * gap;
            if gap == 0.0 {
                score -= 400.0;
            }
        } else {
            // Post residual too small for next item: penalize wasted space,
            // worse when close to next_item_size (just barely unusable).
            score += 0.8 * gap;
        }
        // If next item fits exactly in current residual (pre-placement),
        // slightly penalize consuming that bin unless post fit is tight.
        if bin_residual == next_item_size && post_residual != 0 {
            score += 60.0;
        }
    }

    // Relative-to-mean-residual shaping: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // Penalize opening new bins when existing bins fit decently.
    if bin_residual == bin_capacity {
        score += 120.0;
        if open_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Early in stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 80.0 * (1.0 - progress);
    }

    // Large items: prefer bins with large residuals.
    if item_size > 60 {
        score += 0.2 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

