            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.4 * (1.0 - mult_err / 2.0); }
            // dead-space penalty: leftover after chain is a sub-mean sliver
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            // next item won't fit: residue becomes dead space unless reusable
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if nx - pr <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
        }
    }

    // dead-space avoidance: tiny unusable gaps penalized quadratically
    if post_residual > 0 && post_residual < 20 {
        score += 0.05 * (20.0 - post_residual as f64) * (20.0 - post_residual as f64) / 20.0;
    }

    // last-chance bonus: only fitting bin -> keep item out of a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // open-bin pressure: many open bins -> prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        let nx = next_item_size as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if nx > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // fresh-bin residual should stay usable across several future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.2 * (1.0 - 0.5 * progress); }
        }
        // avoid opening a bin that strands a large remainder
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && nx > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if nx > 0.0 && new_pr >= nx {
            let r = new_pr - nx;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
            if r >= mean_residual.max(1.0) { score -= 0.18; }
        }
        if nx > 0.0 && new_pr > 0.0 && new_pr < nx {
            let miss = ((nx - new_pr) / cap).min(0.3);
            score += 0.5 * miss;
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // near-miss: next item almost fits, residue nearly dead
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        score += 0.2 * pr / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: fraction of bin filled by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let waste_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how much of the bin is consumed.
    score -= 2.0 * fill_ratio;

    // Penalize dead space non-linearly: small post-residuals that can't fit
    // typical future items (>= 10) are wasted; quantic penalty on waste.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 3.0 * waste_ratio * waste_ratio * waste_ratio * waste_ratio * waste_ratio;
    score += 6.0 * dead;

    // Lookahead: if the next item fits exactly into the post-residual, strongly
    // favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // Reward residual that still accommodates the next item,
            // scaled by how snugly the next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * snug;
        } else {
            // Post-residual too small for next item: mild penalty for
            // leaving unusable-looking space.
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless the
    // current fit is poor. Penalize new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 12.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 10.0 * fill_ratio * fill_ratio;
        // If other fitting bins exist and mean residual is high, opening new
        // bins is wasteful.
        if fitting_bins_count > 0 {
            score += 8.0 * (mean_residual / bin_capacity as f64);
        }
        // Late in the stream, prefer closing out existing bins.
        score += 6.0 * progress;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidating items into existing space (penalize new bins
    // implicitly via above; here reward bins below mean residual, i.e. fuller
    // bins, to balance load toward closing bins).
    let residual_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * residual_gap;

    // Encourage bin consolidation when the number of open bins is large.
    score += 0.05 * open_bins_count as f64 * waste_ratio;

    // Slight time-varying exploration pressure: early on, allow looser fits
    // to learn structure; later, tighten.
    score -= 2.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
        // new: penalize leaving a residual sliver that no plausible item can fill
        if pr > 0.0 && pr < nx && mean_residual > 0.0 {
            let sliver = pr / mean_residual . max (1.0);
            if sliver < 0.35 { score += 0.28 * (1.0 - sliver / 0.35) * (0.4 + 0.6 * progress); }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        // refined: prefer fresh bins whose residual decomposes cleanly into mean-sized chunks
        if mean_residual > 0.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual . max (1.0)) . round ();
            let err = (new_pr - k * mean_residual . max (1.0)) . abs ();
            if k >= 2.0 && err <= 2.0 { score -= 0.22 * (1.0 - err / 2.0) * (1.0 - progress * 0.4); }
        }
        // refined: discourage opening a bin that leaves exactly a small unfillable gap
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let gap = next_item_size as f64 - new_pr;
            if gap <= 3.0 { score += 0.4 * (1.0 - gap / 3.0); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.2 * t * t + 1.3 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 5.2 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            // reward chains that still leave room for a follow-up small item
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // two-step lookahead: chain leaves room for next item plus another
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
            // multiplicative fit: residual ~ k * next item
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
            // dead-space penalty: leftover after chain is a sub-mean sliver
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * t) ;
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // small gap: leaving too little room for next item wastes space
        // residual ~ k * current item fit bonus
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // congestion: penalize spreading across many bins early, relax late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual == bin_capacity {
        // new-bin candidate: open when item is large or few fitting bins
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // very tight slack after placing: fresh bin is good
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // late stream: opening fresh bins is cheaper, dead space matters less
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && t > 0.3 && t < 0.8 {
            let slack = new_pr / cap ;
            if slack > 0.15 && slack < 0.45 { score -= 0.25 ; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap ;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)) ; }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && t < 0.5 {
            score -= 0.15 * (1.0 - t / 0.5) ;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let pair_left = new_pr - nx ;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * t) ;
                }
            }
        }
        // refined: fresh-bin residual should stay usable across several future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor () ;
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - t * 0.5).min (1.0) ; }
        }
        // refined: avoid opening a bin that strands a large current-item remainder
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2) ;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear penalty on wasted residual: cubic in normalized residual
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * norm_post;

    // Reward tight fits (small post_residual), stronger late in the stream
    let tightness = 1.0 - norm_post;
    score -= (6.0 + 14.0 * progress) * tightness * tightness;

    // Smooth coupling: residual waste relative to mean residual across open bins
    score += 0.35 * (post - mean_residual) * (1.0 + progress);

    // Lookahead: penalize post_residual that cannot host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 8.0 * (1.0 - (post - nx) / cap);
        } else {
            let gap = (nx - post) / cap;
            score += 22.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize slightly so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
        // But if the item is large relative to capacity, opening a fresh bin is fine
        score -= 0.25 * item_size as f64;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.6 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // dead-space penalty: leftover after chain is a sub-mean sliver
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            // NEW: dead-space ratio coupling — residual that cannot absorb even a
            // small fraction of mean future demand is stranded; penalize more as
            // the stream approaches its end where fewer re-fills remain.
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let usable_frac = (chain_residual / mean_residual) . min (1.0);
                let end_weight = 0.35 + 0.65 * progress;
                if usable_frac < 0.5 {
                    score += 0.28 * (1.0 - usable_frac / 0.5) * end_weight;
                }
                // reward residuals that exactly tile the near-term demand
                let tiles = (chain_residual / mean_residual) . floor ();
                if tiles >= 2.0 && chain_residual - tiles * mean_residual <= 1.0 {
                    score -= 0.22 * (1.0 - progress * 0.4);
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            // NEW: near-miss gap that a *mean-sized* residual could still close
            // signals a bin whose leftover is systematically unusable
            if mean_residual > 0.0 && pr > 0.0 && pr < mean_residual * 0.5 {
                score += 0.18 * (1.0 - pr / (mean_residual * 0.5)) * (0.4 + 0.6 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // refined: fresh-bin residual should stay usable across several future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
            // NEW: prefer fresh bins whose remainder tiles mean-sized demand
            // with minimal slack — sharpens the multi-fit criterion
            let slack_tiled = new_pr - fits_ahead * mean_residual . max (1.0);
            if fits_ahead >= 2.0 && slack_tiled <= 3.0 {
                score -= 0.14 * (1.0 - slack_tiled / 3.0) * (0.5 + 0.5 * progress);
            }
            // NEW: penalize fresh bins leaving a stranded sliver below half-mean
            if new_pr < mean_residual * 0.5 {
                score += 0.26 * (1.0 - new_pr / (mean_residual * 0.5)) * (0.4 + 0.6 * progress);
            }
        }
        // refined: avoid opening a bin that strands a large current-item remainder
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bucket by integer division of capacity.
    let class = post_residual / (bin_capacity / 4).max(1); // 4 harmonic classes: 0..=3
    let class_penalty = match class {
        0 => -30.0, // post_residual < 25: nearly full bin, excellent placement
        1 => -8.0,  // 25..50: decent
        2 => 6.0,   // 50..75: mediocre, leaves awkward gap
        _ => 18.0,  // >= 75: wasteful placement
    };
    score += class_penalty;

    // Dead-space penalty: gap too small for any plausible future item (sizes >= 1, but
    // typical items are large). Penalize gaps below a modulo-style threshold.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Exact-fit harmonic bonus: post_residual divisible by small divisors => reusable gap.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Lookahead coupling: reward if next item fits the post-residual (chain placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap unusable by the known next item: mild penalty scaled by gap size.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
        if class == 3 {
            score += 10.0; // but not if it would leave a huge gap
        }
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a good fit. Make the empty-bin score moderately high by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheap-ish; later, discourage it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // If many bins are already open, discourage spreading further.
        score += 2.0 * open_bins_count as f64;
        // But if the next item is large and current bins are tight, new bin is fine.
        if next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to mean (balance residual mass) — mild.
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    // Small tie-break favoring tighter current residuals.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let t = progress;
    let fit_ratio = item_size as f64 / cap;

    // Base: post residual, normalized
    let mut score = pr / cap;

    // Perfect fill bonus
    if post_residual == 0 { score -= 8.0; }

    // Dead-space penalty grows with progress
    let dead_weight = 1.0 + 2.0 * t * t + 1.5 * t * (1.0 - t);
    score += dead_weight * (pr / cap).powi(2);

    // Reward tight fits
    let tightness = 1.0 - (pr / cap);
    score -= 0.8 * tightness * tightness * fit_ratio;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * t;
    }

    // Penalize spreading when many bins open
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Mean residual alignment
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Lookahead: chain reasoning on post_residual vs next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.35 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            // second-order chain
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
            }
            let wasted = chain / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // dead-space sliver below mean
            if mean_residual > 0.0 && chain > 0.0 && chain < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain / (mean_residual * 0.4)) * (0.5 + 0.5 * t);
            }
        } else {
            // residual barely misses next item
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5); }
            if nx - pr <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            score += 0.2 * pr / cap + 0.3 * t;
        }
        // reward residual that exactly accommodates next item
        if pr >= nx && (pr - nx) / cap < 0.1 {
            score -= 1.0 * (1.0 - t * 0.5);
        }
        // residual divisible by item size suggests future fits
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3);
            }
        }
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64;
        score -= 0.45 * fit_ratio;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if fit_ratio >= 0.9 * cap / cap { score -= 0.55; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { score -= 0.18 * (1.0 - t * 0.4); }
            } else {
                let miss = (nx - new_pr) / cap;
                score += 0.5 * miss.min(0.3);
            }
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t);
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - t * 0.5).min(1.0); }
        }
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold any
    // item (min size 1, but practically small gaps < 12) are wasted space.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild dead-space penalty.
        score += 8.0;
    }

    // Tight fit bonus: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading out; penalize less when few bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    // (i.e., many fitting bins means we should reuse one).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            score += 70.0; // last-chance bin exists, avoid new bin
        } else {
            score += 20.0 + fitting_bins_count as f64 * 5.0;
        }
        // Slight preference for new bins late in the stream when open bins
        // have low mean residual (poor reuse prospects).
        if mean_residual < item_size as f64 && fitting_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Alignment bonus: post_residual that is a "nice" size (>= 12) is reusable.
    if post_residual >= 12 {
        score -= 5.0;
    }

    score
}

