        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if nx > 0.7 * cap { score -= 0.6 ; }
        if isz > 0.5 * cap && nx <= pr { score -= 0.3 ; }
        if isz >= 0.9 * cap { score -= 0.55 ; }
        if t > 0.75 { score -= 0.25 * (t - 0.75) / 0.25 ; }
