                if r3 <= 4.0 { score -= 0.2 * (1.0 - r3 / 4.0) * (1.0 - progress * 0.4); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            // refined: near-miss gap that equals a small known stream size wastes less
            if mean_residual > 0.0 && (nx - pr) > 0.0 && (nx - pr) <= mean_residual {
                score -= 0.15 * (1.0 - (nx - pr) / mean_residual . max (1.0));
            }
