    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual close to next item size (within small window)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + diff * 0.35);
    }

    // Penalize dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual + 1.0 {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when good fits exist in open bins
    if bin_residual == bin_capacity {
        let tight_fit_bonus = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 0.0 };
        score += 12.0 + 0.25 * open_bins_count as f64 + tight_fit_bonus;
        // New bin is attractive only if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early in the stream, new bins are cheap
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Discourage leaving residuals that are too small to be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

