pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let t = progress ;
    let mut score = pr / cap ;
    // dead-space penalty: quadratic in normalized residual, growing with stream progress
    let dead_weight = 1.0 + 2.5 * t * t + 1.2 * t * (1.0 - t) ;
    score += dead_weight * (pr / cap) . powi (2) ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if pr == nx {
            score -= 5.2 ;
        } else if pr > nx {
            let chain_residual = pr - nx ;
            score -= 1.35 * (1.0 - chain_residual / cap) ;
            if chain_residual <= 10.0 { score -= 0.9 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25 ; }
            // multi-step lookahead: chain hosting a sequence of next items
            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            // multiplicative fit: chain holds an integer number of next items
            let k = (pr / nx) . round () ;
            let mult_err = (pr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0) ; }
            // dead-space penalty: leftover after chain is a sub-mean sliver
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * t) ;
            }
            let wasted = chain_residual / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * t) ; }
        } else {
            let orphan = (pr - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * t ;
            let gap = (nx - pr) / cap ;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - t * 0.5) ; }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0) ; }
        }
        // current item nearly fills bin to a multiple of next item
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
        }
    }
    // congestion: penalize spreading across many bins early, relax late
    score += 0.05 * open_bins_count as f64 * (1.0 - t) ;
    if fitting_bins_count > 3 {
        score += 0.08 * (fitting_bins_count as f64 - 3.0) * (1.0 - t) ;
    }
    // residual deviation from mean: prefer bins whose residual matches the pack structure
    let dev = (bin_residual as f64 - mean_residual) / cap ;
    score += 0.3 * dev * dev ;
    if bin_residual == bin_capacity {
        // new-bin candidate: open when item is large or few fitting bins
        score = 0.9 - 0.4 * t + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count == 2 { score += 0.7 * (1.0 - t) ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        // avoid opening a bin when an existing bin fits nearly perfectly
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // late stream: opening fresh bins is cheaper, dead space matters less
        if t > 0.7 { score -= 0.25 * (t - 0.7) / 0.3 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // fresh-bin residual should chain the next item tightly
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ;
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
        // fresh-bin residual stays usable across several future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor () ;
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - t * 0.5) . min (1.0) ; }
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * t) ;
        }
        // avoid stranding a large remainder when an open bin could host it
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2) ;
            }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15 ;
        }
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - t * 0.4) ; }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
            }
        }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        // extra penalty when the existing bin would be left with a useless sliver
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64 ;
        let waste = pr - nx ;
        if waste > 0.0 && waste < 5.0 {
            score += 1.0 * (1.0 - waste / 5.0) * (0.5 + 0.5 * t) ;
        }
    }
    score
}

