    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..20) are also risky given min item size 1..100 unknown.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would NOT fit the post residual, penalize wasted potential.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins with below-mean residual (consolidate space).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when few bins open.
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * open_bins_count as f64;
    }

    // Early stream: mild preference for keeping items together.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    score
}

