pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect match for the next item is highly desirable.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= next {
            // Next item still fits: mild reward proportional to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space creation.
            score += 15.0 * (diff / bin_capacity as f64);
        }
        // If post_residual would strand a large gap unusable by next item, penalize more.
        if (post_residual as f64) < next * 0.5 && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // Last item: simply minimize waste.
        score += 5.0;
    }

    // Relative to mean residual: prefer bins that are already "loose" (above-average residual)
    // to be filled, keep tight bins tight.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty-bin option unattractive unless it's genuinely needed
    // (i.e., no good fit exists). Penalize proportional to how well existing bins could work.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, opening bins is cheaper; late, consolidation matters.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins already open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // If next item is large and would need a fresh bin anyway, allow new bin sometimes.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Prefer tight fits overall (small post_residual relative to item size).
    if item_size > 0 {
        score += 10.0 * (post_residual as f64 / item_size as f64);
    }

    // Small tie-breaker against fragmentation.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).recip().min(1.0);

    score
}

