                score += 0.1 * (1.0 - (2.0 * nx - post_residual as f64) / (2.0 * nx)) ;
            }
        }
        // residual exactly tiles with item_size multiples
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (post_residual as f64 / isz) . round ();
            if k >= 1.0 && k <= 4.0 && ((post_residual as f64) - k * isz) . abs () <= 1.5 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) ;
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        let mut new_score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64 ;
        new_score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { new_score += 2.5 ; }
        if fitting_bins_count >= 4 { new_score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { new_score -= 0.6 ; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= post_residual as f64 { new_score -= 0.3 ; }
        if item_size as f64 >= 0.9 * cap { new_score -= 0.55 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance: penalize new bins whose residual can't absorb future items
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            new_score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { new_score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        // two-step tile from a fresh bin
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                new_score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                new_score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        // fresh bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            new_score += 0.5 * miss . min (0.3) ;
        }
        // fresh bin residual that tiles exactly with next item multiples
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { new_score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { new_score -= 0.2 * (0.5 + 0.5 * progress); }
        }
