        if fitting_bins_count >= 2 && next_item_size > 0 {
            let slack = new_pr / cap;
            if slack < 0.1 { new_score += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 && slack < 0.5 && (next_item_size as f64) > new_pr {
                new_score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        // fresh bin residual close to mean residual is likely reusable
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev <= 0.1 { new_score -= 0.15 * (1.0 - dev / 0.1) ; }
        }
        // residual after placing next item still above mean residual: good
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { new_score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { new_score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.7 { new_score -= 0.25 * (progress - 0.7) / 0.3 ; }
        if progress > 0.85 && fitting_bins_count <= 2 { new_score += 0.6 * (progress - 0.85) / 0.15 ; }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { new_score -= 0.3 ; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            new_score -= 0.15 * (1.0 - progress / 0.5);
        }
        score = new_score ;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

