        if fitting_bins_count >= 2 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > 0.0 && new_pr < nx && (nx - new_pr) > 10.0 {
                score += 0.3 * (1.0 - progress * 0.4);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
