            score += 0.65 * (1.0 - progress * 0.3);
        }
        // refined: a nearly-missed pairing wastes space; penalize proportionally to the shortfall
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 12.0 { score += 0.12 * (1.0 - miss / 12.0); }
    }
    score
}

