            let kf = (cr / nx . max (1.0)) . floor () ;
            if kf >= 2.0 {
                let rem = cr - kf * nx ;
                if rem <= 2.0 { score -= 25.0 * (1.0 - rem / 2.0) * (0.6 + 0.4 * progress) ; }
                if kf >= 3.0 && rem <= 3.0 { score -= 18.0 * (1.0 - rem / 3.0) ; }
