            }
            // refined: deeper exact tiling — residual tiles into >=4 copies of next item
            if kf >= 4.0 {
                let rem4 = chain_residual - kf * nx;
                if rem4 <= 2.0 { score -= 0.15 * (1.0 - rem4 / 2.0); }
            }
            // refined: reward residual that still accommodates mean-sized items afterward
            if mean_residual > 0.0 && chain_residual >= mean_residual {
                let tail = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if tail <= 4.0 { score -= 0.12 * (1.0 - tail / 4.0) * (0.5 + 0.5 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6). min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // refined: penalize dead space pr that no item of plausible size can ever use
            if pr > 0.0 && pr < 0.05 * cap {
                score += 0.3 * (1.0 - pr / (0.05 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx. max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // refined: fresh bin residual that cannot tile even once with mean residual is dead weight
        if new_pr > 0.0 && mean_residual > 1.0 && new_pr < mean_residual {
            score += 0.2 * (1.0 - new_pr / mean_residual) * (0.5 + 0.5 * progress);
        }
        // refined: fresh bin is attractive when it exactly fits a multiple of next item (tight tiling)
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . round ();
            if k >= 1.0 && (new_pr - k * nx) . abs () <= 1.0 && k <= 5.0 {
                score -= 0.3 * (1.0 - progress * 0.4);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the smallest plausible item (1..100 unknown, so use graded penalty).
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead-space penalty grows super-linearly for unusable slivers
        score += (pr / bin_capacity as f64).powf(1.7) * 40.0;
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Classic best-fit flavor: prefer bins whose residual was already tight
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // well, reward this placement; if next item is larger than post-residual
    // and this bin is the only fitting one, penalize slightly (last-chance).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let waste = pr - ni;
            score -= (1.0 - waste / bin_capacity as f64) * 12.0;
        } else {
            score += (ni - pr).min(bin_capacity as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post-residual is a dead sliver).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        // but if it leaves a tiny useless remainder, soften the reward
        if pr > 0.0 && pr < 10.0 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is attractive when no open bin fits well; make the
    // empty-bin score depend on global state so it loses when a good fit exists.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 35.0;
        // early in the stream, opening bins is cheap (build a portfolio)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if many open bins already, discourage proliferation
        score += (open_bins_count as f64).powf(0.9) * 1.5;
        // if mean residual across open bins is high, better to reuse them
        score += (mean_residual / bin_capacity as f64).max(0.0) * 25.0;
    } else {
        // reusing an existing bin: reward proportional to how much of the
        // bin's current residual we consume (encourages compact packing)
        let consumed = item_size as f64 / bin_residual.max(1) as f64;
        score -= consumed * 10.0;
        // mildly prefer bins with residual below the mean (tighten stragglers)
        score -= ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 6.0;
    }

    // Slight preference for keeping the number of open bins low when the
    // stream is nearly done: avoid orphan bins at the tail.
    if total_items > 0 && step_index + 1 >= total_items.saturating_sub(2) {
        if bin_residual != bin_capacity {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nx = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Exact fill is perfect.
    if post_residual == 0 { score -= 8.0; }

    // Dead-space avoidance: unusable residue penalized.
    if post_residual > 0 && post_residual < item_size {
        score += 1.5 * (item_size as f64 - post_residual as f64) / cap;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 0.5 * (20.0 - post_residual as f64) / cap;
    }

    // Lookahead chain: reward residuals that tile with the next item.
    if next_item_size > 0 {
        if pr == nx {
            score -= 4.0;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.2 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.7; }
            // multi-step tiling: residual divisible by next item
            let k = (chain / nx.max(1.0)).floor();
            let rem = chain - k * nx;
            if k >= 2.0 && rem <= 2.0 {
                score -= 0.5 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress);
            }
            if k >= 3.0 && rem <= 3.0 { score -= 0.2; }
            // leftover chain residual too small to be useful later
            if chain > 0.0 && chain < nx && chain < 0.08 * cap {
                score += 0.6 * (1.0 - chain / (0.08 * cap));
            }
        } else {
            // next item won't fit here: near-miss dead space
            let miss = nx - pr;
            score += 0.3 + 0.5 * progress;
            if miss <= 5.0 { score += 1.2 * (1.0 - miss / 5.0); }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.15 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
        }
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Open-bin pressure: prefer filling existing bins as they accumulate.
    score += 0.06 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins below mean residual (keep large gaps alive).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 0.3;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.4 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if item_size as f64 >= 0.9 * cap { score -= 0.6; }
        // fresh bin that exactly tiles with next item
        if next_item_size > 0 && new_pr >= nx {
            let r = new_pr - nx;
            if r == 0.0 { score -= 3.0; }
            else if r <= 5.0 { score -= 0.6 * (1.0 - r / 5.0); }
            let k = (new_pr / nx.max(1.0)).floor();
            if k >= 2.0 && new_pr - k * nx <= 2.0 { score -= 0.4; }
        } else if next_item_size > 0 && new_pr > 0.0 && new_pr < nx {
            let miss = nx - new_pr;
            if miss <= 8.0 { score += 0.5 * (1.0 - miss / 8.0); }
            if new_pr < 0.08 * cap { score += 0.6 * (1.0 - new_pr / (0.08 * cap)); }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.5 * (progress - 0.85) / 0.15; }
    } else if next_item_size > post_residual && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 { score += 0.6 * (1.0 - miss / 4.0); }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post-residual, non-linearly shaped by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Polynomial coupling: penalize small-but-nonzero dead space more as stream advances.
    let dead = pr_norm * (1.0 - pr_norm); // peaks at half-full residual
    score += 40.0 * dead * (1.0 - progress);

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 25.0 * (-pr_norm * 6.0).exp();

    // Penalize opening new bins late in the stream when alternatives exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress * (1.0 - item_norm);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mild dispersion penalty: prefer bins near the mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for fuller bins overall (non-linear in fill ratio).
    let fill = 1.0 - pr_norm;
    score -= 10.0 * fill * fill * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // combined: prefer fresh bin when every fitting bin would strand a near-miss gap
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nx = next_item_size as f64;
            let all_bad = fitting_bins_count as f64;
            let _ = all_bad;
            if new_pr >= nx && (new_pr - nx) <= 2.0 {
                score -= 0.35 * (1.0 - progress * 0.3);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover is a "useful" size
    // class (multiples of 10 up to 50) are favored; dead space penalized super-linearly.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => -30.0,                      // perfect fit
        1 | 2 | 3 | 4 | 5 => -2.0 * (6.0 - class as f64), // reusable classes
        _ => (post - 50.0) * 0.6,        // large waste penalty
    };
    score += class_bonus;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or near-exactly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 35.0; // chain perfect fit
            } else if (post_residual - next_item_size) % 10 == 0 && post_residual - next_item_size <= 50 {
                score -= 12.0; // leaves another harmonic class
            } else {
                score -= 6.0 * (1.0 - slack / cap);
            }
        } else {
            // next item won't fit here; penalize large leftovers mildly
            score += 0.05 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves dead space
    // and mean residual shows open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).max(0.0) / cap;
        score += 55.0 - 40.0 * fragmentation - 15.0 * progress;
        // never open a new bin if this item would leave a harmonic-class leftover
        if class <= 5 && post_residual > 0 {
            score += 60.0;
        }
    }

    // Prefer filling fuller bins (tight packing) as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
