            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - t * 0.5). min (1.0) ; }
        }
        if open_bins_count >= 6 && it > 0.6 * cap { score -= 0.3 ; }
        if t > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (t - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - t * 0.3) ;
        }
    }
    // large residual bins late in the stream are less attractive
    if t > 0.6 && bin_residual as f64 > 0.5 * cap && bin_residual != bin_capacity {
        score += 0.15 * (t - 0.6) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        // Gap that cannot fit even the smallest plausible item is pure dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
        // Dead space relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits, mild penalty (dead space trap for lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bin pressure: discourage scattering across many open bins;
    // encourage filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Encourage closing bins that are nearly full (post_residual small but usable).
    if post_residual > 0 && post_residual <= 15 && post_residual >= 10 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (emptier bins get filled
    // when mean is high, tightening overall spread).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in stream or when
        // existing bins would leave large dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0 - progress * 10.0;
        if post_residual > 40 {
            // Opening a new bin for a big item may be better than wrecking a small bin
            new_bin_score -= 15.0;
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            // New bin can host both current and next item: attractive
            new_bin_score -= 20.0;
        }
        score = score.max(new_bin_score.min(score)) + new_bin_score - score; // blend
        score = new_bin_score;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
