            // refined: three-step exact tiling lookahead — residual that fits next item exactly k>=3 times
            let kf = (chain_residual / nx. max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // mutation: penalize chain residuals that are unusable dead space — smaller than
            // the next item and below any plausible future item (well under mean residual)
            if chain_residual > 0.0 && chain_residual < nx {
                if chain_residual < 0.06 * cap {
                    score += 0.5 * (1.0 - chain_residual / (0.06 * cap)) * (0.6 + 0.4 * progress);
                }
                if mean_residual > 0.0 && chain_residual < mean_residual * 0.25 {
                    score += 0.18 * (1.0 - chain_residual / (mean_residual * 0.25));
                }
            }
            // mutation: reward residuals that still tile exactly with next item at depth 2
            if chain_residual >= nx {
                let rem2 = (chain_residual - ((chain_residual / nx. max (1.0)) . floor ()) * nx. max (1.0));
                if rem2 < 1.0 { score -= 0.15 * (0.5 + 0.5 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6). min (1.0); }
            }
            // refined: penalize bins whose residual cannot pair with the following item twice
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            // refined: extra penalty when gap is tiny but nonzero (near-miss dead space)
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // mutation: near-miss bands just beyond 8 also carry dead-space risk, taper off
            if miss > 8.0 && miss <= 16.0 {
                score += 0.08 * (1.0 - (miss - 8.0) / 8.0) * (0.5 + 0.5 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
