            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        // refined: fresh bin that exactly tiles with the next item size (zero final dead space)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx. max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        // refined: dead-space ratio penalty — fresh bin leaving residual that no plausible item can use
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // mutation: fresh-bin two-step exact tiling — residual that fits next item exactly twice
        // with near-zero remainder is a strong open (avoids one extra bin later)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem2 = new_pr - 2.0 * nx;
                if rem2 <= 1.0 { score -= 0.32 * (1.0 - rem2) * (0.5 + 0.5 * progress); }
            }
        }
        // mutation: fresh-bin dead-space guard scaled by stream progress — late-stream tiny
        // residuals are almost certainly wasted, so push harder against opening such bins
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < mean_residual . max (1.0) * 0.5 {
                score += 0.25 * (1.0 - new_pr / (mean_residual . max (1.0) * 0.5)) * progress;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // mutation: dead-space penalty when the leftover after this placement is tiny
        // relative to capacity and cannot host the next item
        if pr < 0.05 * cap && pr > 0.0 {
            score += 0.35 * (1.0 - pr / (0.05 * cap)) * (0.6 + 0.4 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base fit quality: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this one: mild bonus scaled by leftover slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.25 * slack;
        } else {
            // Next item cannot follow: penalize dead space proportional to post_residual.
            score += 0.6 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins: prefer tighter-than-average bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // Spread items when many bins fit: slight penalty to avoid hoarding one bin.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of opening a new bin, discounted late in the stream.
        let mut nb = 35.0 - 10.0 * progress;
        // If next item is large and this item leaves a big residual, a fresh bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 8.0;
        }
        // Discourage opening new bins when an existing bin would be nearly full.
        if post_residual <= 10 {
            nb += 25.0;
        }
        score += nb;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

