            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

#[inline]
fn rem3_of (chain_residual : f64 , nx : f64) -> f64 {
    let kf = (chain_residual / nx. max (1.0)) . floor ();
    chain_residual - kf * nx. max (1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post-residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that leave room for the next item.
            score -= 0.15 * (post_residual as f64).min(next_item_size as f64 * 2.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fit_quality;
    }

    // New-bin candidate: penalize opening a new bin, but less when the item
    // is large (a fresh bin gives it a full horizon) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score += 8.0 - 6.0 * size_pressure - 4.0 * progress;
        // If many bins are open but none fit well, opening may be fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate fullness).
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild preference for bins that remain useful after placement.
    if post_residual > 0 && post_residual <= 10 {
        score -= 5.0; // near-perfect fill
    } else if post_residual > 50 {
        score += 1.0; // large leftover wastes capacity
    }

    score
}

