        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        // refined: fresh bin that exactly tiles with the next item size (zero final dead space)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx. max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        // refined: dead-space ratio penalty — fresh bin leaving residual that no plausible item can use
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // refined: two-step exact tiling of fresh bin (item + 2×next fills perfectly)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let two_rem = (new_pr - 2.0 * nx) . abs ();
            if new_pr >= 2.0 * nx && two_rem <= 2.0 {
                score -= 0.24 * (1.0 - two_rem / 2.0) * (0.5 + 0.5 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (1..=100, min item 1) are dead space.
    // Penalize unusable gaps super-linearly.
    if post_residual > 0 {
        // smallest item is 1, so any post_residual >= 1 is technically usable,
        // but small gaps (< 10) are practically dead.
        if post_residual < 10 {
            score += 60.0 + (10 - post_residual) as f64 * 6.0;
        } else if post_residual < 20 {
            score += 18.0;
        }
    }

    // Reward tight fits (small post_residual) relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: only one bin can fit the item; strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += pressure * 0.8;

    // New-bin candidate handling: an empty bin should only win when the item
    // fits poorly everywhere else. Give it a moderate baseline penalty that
    // grows with open bin count.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 4.0;
        // But if the item is large and would leave a big residual in any bin anyway,
        // a fresh bin can be attractive; soften the penalty for large items.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0; // next placement would create dead space here
        }
    }

    // Prefer bins whose residual is already below the mean (consolidate
    // fullness into the emptier bins being drained).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

