        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        // refined: fresh bin that exactly tiles with the next item size (zero final dead space)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx. max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        // refined: dead-space ratio penalty — fresh bin leaving residual that no plausible item can use
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // refined: open bins with poor fits should prefer a fresh bin — scale new-bin bonus with worst-fit pressure
        if fitting_bins_count >= 2 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && (new_pr - nx) <= 0.12 * cap {
                score -= 0.15 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins partitioned by capacity fraction bands.
    let q = post_residual / (bin_capacity / 5); // classes 0..5 (0 = tightest fit)
    let class_bonus = match q {
        0 => 60.0,               // near-perfect fit: heavily reward
        1 => 35.0,               // residual <= 20% of capacity
        2 => 15.0,               // moderate
        3 => -5.0,               // large residual: penalize slightly
        4 => -15.0,
        _ => -25.0,              // bin left nearly untouched
    };
    score -= class_bonus;

    // Modulo arithmetic on post_residual: residuals divisible into small chunks
    // are more reusable by future small items.
    let pr = post_residual as i64;
    let mut mod_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { mod_bonus += 8.0; }
        if pr % 5 == 0 { mod_bonus += 4.0; }
        if pr % 4 == 0 { mod_bonus += 2.0; }
        if pr % 7 == 0 { mod_bonus += 1.5; }
        if pr % 3 == 0 { mod_bonus += 1.0; }
    }
    score -= mod_bonus;

    // Integer-division threshold coupling: can the next item fit exactly into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // Reward lookahead fit, scaled by how tight the follow-up fit is.
        let tight = 1.0 - (slack as f64) / cap;
        score -= 20.0 + 15.0 * tight;
        if slack == 0 {
            score -= 30.0; // perfect two-item chain
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: mild penalty proportional to overshoot class.
        let over = (next_item_size - post_residual) / (bin_capacity / 4);
        score += 5.0 * over as f64;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // (mean residual low relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let fragmentation = (item_size as f64) / mean_residual.max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap; late stream: penalize new bins.
        score = 45.0 + 30.0 * progress - 20.0 * fragmentation.min(2.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Slight preference to fill bins with larger residual when many bins are open
    // (consolidation pressure), scaled by capacity fraction.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05 * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Strict dead-space avoidance: any leftover gap too small for the
    // smallest possible item (size 1..=10 margin) is unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps below the known minimum item size of the classic regime are dead.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Reward gaps that can still host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 20.0;
        } else if gap < 10.0 {
            score += 8.0; // would create fresh dead space for the next item
        } else {
            score -= 5.0;
        }
    }
    // Penalize if the next item cannot fit here at all.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new bin is comparatively cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure;

    // Early in the stream, new bins are cheap; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // Prefer bins whose residual is above the mean (keeps a healthy spread),
    // mildly penalize bins already nearly full unless the fit is exact.
    if (bin_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 4.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0; // room to pair with the next item
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            // refined: near-exact two-step chain (residual divisible by next item) is gold
            if chain_residual >= nx && (chain_residual % nx. max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            // refined: three-step exact tiling lookahead — residual that fits next item exactly k>=3 times
            let kf = (chain_residual / nx. max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // refined: dead-space ratio — penalize chain residuals too small for any plausible item
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap)) * (0.6 + 0.4 * progress);
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6). min (1.0); }
            }
            // refined: penalize bins whose residual cannot pair with the following item twice
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            // refined: extra penalty when gap is tiny but nonzero (near-miss dead space)
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // refined: tiny orphan residual — dead space no future item can use
            if pr > 0.0 && pr < 0.05 * cap {
                score += 0.4 * (1.0 - pr / (0.05 * cap)) * (0.5 + 0.5 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        // refined: fresh bin that exactly tiles with the next item size (zero final dead space)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx. max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        // refined: dead-space ratio penalty — fresh bin leaving residual that no plausible item can use
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // refined: penalize fresh bins whose residual is a near-miss multiple of next item (dead space after tiling)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 {
                let rem = new_pr - k * nx;
                if rem > 2.0 && rem < 0.06 * cap {
                    score += 0.25 * (1.0 - rem / (0.06 * cap)) * (0.5 + 0.5 * progress);
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item would NOT fit: penalize leaving medium dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Penalize small dead space (unusable gap) more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins with residual below mean (tighter bins get filled first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_tightness = 1.0 - mean_residual / bin_capacity as f64;
        score += 35.0 - 25.0 * avg_tightness - 5.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = post_residual as f64 / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 5.0;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size;
            score -= 1.3 * (1.0 - chain_residual as f64 / cap);
            if chain_residual <= 10 { score -= 0.9; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 0.25; }
            // two-step lookahead: reward residuals that fit the next item twice
            let cr = chain_residual as f64;
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.45 * (1.0 - (cr - 2.0 * nx) / 8.0);
            }
            // multi-step exact tiling: residual divisible by next item
            let kf = (cr / nx . max (1.0)) . floor ();
            if kf >= 2.0 {
                let rem = cr - kf * nx;
                if rem <= 2.0 { score -= 0.3 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap;
            if wasted > 0.05 { score += 0.5 * wasted * (0.4 + 0.6 * progress); }
            // sliver chain space below mean residual is likely dead
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 0.3 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            // small gap to next item: poor fit, penalize proportionally
            let gap = (nx - post_residual as f64) / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress);
            }
            let miss = nx - post_residual as f64;
            if miss > 3.0 && miss <= 8.0 { score += 0.2 * (1.0 - (miss - 3.0) / 5.0); }
        }
        // item tiles residual exactly: strong reward
        if item_size > 0 {
            let isz = item_size as f64;
            let k = (post_residual as f64 / isz) . round ();
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let isz = item_size as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * isz / cap;
        score -= 0.05 * mean_residual;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        // dead-space avoidance: penalize new bins whose residual is unlikely
        // to absorb future items given the mean residual scale
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.4 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0);
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 0.6; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        // large items pack better into fresh bins early
        if isz >= 0.9 * cap { score -= 0.55; }
        // fresh bin that exactly tiles with the next item size
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        // fresh bin residual that no plausible item can use
        if new_pr > 0.0 && next_item_size > 0 && new_pr < next_item_size as f64 && new_pr < 0.08 * cap {
            score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
        }
        // fresh bin residual can absorb the next item k>=2 times with tiny remainder
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        // fresh bin residual close to mean residual: likely reusable
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        // late stream: prefer reusing open bins, discourage new bins
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // many open bins with a large item: fresh bin is fine
        if open_bins_count >= 4 && isz > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - 0.3 * progress);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
