            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // mutation: discourage opening a fresh bin when an existing bin already
        // achieves a near-perfect fit (post_residual tiny) — prefer compacting
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 3.0 {
            score += 0.8 * (1.0 - pr / 3.0);
        }
        // mutation: fresh bins are more attractive when the mean residual is large
        // (open bins are fragmented) — combine dead-space ratio with fragmentation
        if mean_residual > 0.0 && new_pr > 0.0 {
            let frag = mean_residual / cap;
            if frag > 0.25 && new_pr >= next_item_size as f64 {
                score -= 0.25 * ((frag - 0.25) / 0.25) . min (1.0);
            }
        }
        // mutation: late-stream, strongly prefer closing bins with tight fits
        if progress > 0.75 && pr > 0.0 {
            score += 0.3 * (progress - 0.75) / 0.25 * (pr / cap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin wastefully.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residual below the mean (compact usage) mildly.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in the stream, favor opening bins (keep flexibility);
    // later, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
        score += 6.0 * progress;
    }

    // Many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap ;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size as u32 {
            score -= 5.2 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            let cr = chain_residual as f64 ;
            score -= 1.35 * (1.0 - cr / cap) ;
            if chain_residual <= 10 { score -= 0.9 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 0.25 ; }
            // multi-step lookahead: reward residuals that tile with next item repeatedly
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0) ; }
                }
            }
            // exact k-fold tiling of chain residual by next item is gold
            let kf = (cr / nx . max (1.0)) . floor () ;
            if kf >= 2.0 {
                let rem = cr - kf * nx ;
                if rem <= 2.0 { score -= 0.35 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress) ; }
            }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress) ; }
            // dead sliver relative to mean residual scale
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 0.3 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress) ;
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * progress ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0) ; }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0) ; }
            // penalize bins that cannot pair residual with next item twice
            if post_residual > 0 && 2.0 * nx > post_residual as f64 && post_residual as f64 + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - post_residual as f64) / (2.0 * nx)) ;
            }
        }
        // residual exactly tiles current item too
        if item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz) . round () ;
            if k >= 1.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3) ;
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) ;
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        score -= 0.05 * mean_residual / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        let nx = next_item_size as f64 ;
        // dead-space avoidance: residual unlikely to absorb future items
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // sliver check against open bins
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let slack = new_pr / cap ;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
            if slack > 0.3 && slack < 0.5 && nx > new_pr { score += 0.2 * (1.0 - (0.5 - slack) / 0.2) ; }
        }
        // near-perfect post-fit for next item
        if nx > 0.0 && new_pr >= nx {
            let r = new_pr - nx ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 { score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0) ; }
            // exact tiling with next item
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress) ; }
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = new_pr - k * nx ;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress) ; }
            }
            let after = new_pr - nx ;
            if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)) ; }
        }
        // opening a new bin that cannot fit the next item: penalize
        if nx > 0.0 && new_pr < nx {
            let miss = (nx - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
            if nx - new_pr <= 8.0 { score += 0.35 * (1.0 - (nx - new_pr) / 8.0) ; }
            // tiny unusable sliver
            if new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress) ;
            }
        }
        // residual close to mean residual scale is reusable
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1) ; }
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor () ;
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0) ; }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15 ; }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping.
    // Slightly convex so mid-size residuals are preferred over extreme ones.
    let mut score = pr + 12.0 * pr_norm * pr_norm - 6.0 * pr_norm * pr_norm * pr_norm;

    // Reward tight fits (low post_residual) with a smooth quadratic bonus.
    score -= 18.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * item_norm;

    // Stream-progress coupling: as the stream advances, tighten tolerance for waste.
    let tightness = 1.0 + 2.0 * progress * (1.0 - progress).abs();
    score *= 0.8 + 0.4 * tightness;

    // Last-chance bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can fit into the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_after = (nxt / cap) * (1.0 - pr_norm);
            score -= 10.0 * fill_after;
        } else {
            // Penalize residuals that are too small for the next item (dead space).
            score += 8.0 * (1.0 - nxt / cap);
        }
    }

    // Mild penalty when this bin's residual deviates far from the mean residual
    // (encourages homogeneous residual pools), scaled smoothly by open bins.
    let open_f = open_bins_count as f64;
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * (open_f / (open_f + 4.0));

    // New-bin candidate: penalize opening a new bin unless current residual is badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 20.0 - 15.0 * (1.0 - fragmentation) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes (0..=10, exact halves, etc.) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Modulo-class rewards on post_residual (harmonic classes of 25 = C/4).
    match post_residual % 25 {
        0 => score -= 120.0,           // quarter-aligned residual: reusable
        1..=10 => score -= 60.0,       // small dead space, low value lost
        11..=20 => score += 25.0,      // awkward mid-class gap
        _ => score += 10.0,            // large-but-usable class
    }

    // Integer-division thresholds: residual usable by typical next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also serve the lookahead item: strong reward,
            // scaled by how tightly the pair packs.
            let slack = (post_residual - next_item_size) as f64;
            score -= 90.0 - slack * 0.8;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0; // exact harmonic subdivision
            }
        } else {
            // Lookahead won't fit here; penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest packing overall.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Brand-new bin candidate: keep it attractive only when current bins
    // would leave bad residues (mid-class gaps) or are crowded.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        let bad_fit_elsewhere = (mean_residual - post).abs();
        score = 60.0 + open_pressure * 30.0 - bad_fit_elsewhere * 0.3;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 25.0; // fresh bin good for upcoming large item
        }
    }

    // Mild bias toward fuller bins relative to fleet mean residual.
    score -= (mean_residual - post) * 0.4;

    // Late-stream consolidation: favor using existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

