            score -= 30.0;
        } else if next_item_size > post_residual {
            // residual too small for next item -> dead space penalty
            score += 8.0;
        }
    }

    // New-bin candidate: make it moderately expensive so it is chosen only
    // when no open bin offers a decent fit; scale with how many bins are open.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
    }

    // Slight tie-break: prefer bins with below-average residual (more filled).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
