    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual relative to capacity).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can host the next item; penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain placement possible: subtract bonus proportional to
            // how "snugly" the next item fits into the post-residual.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 25.0 + 20.0 * snug;
        } else {
            // Dead space for the next item: penalize proportionally to waste.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste;
        }
    } else {
        // Last item: simply minimize post_residual.
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with residual below mean
    // (they are "nearly full", close them out), penalize bins above mean.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (resid_f - mean_residual) / (bin_capacity as f64);
        score += 30.0 * rel;
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive late in the stream or
    // when no open bin is a good fit; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_open_bins = if open_bins_count > 0 {
            (mean_residual / (bin_capacity as f64)) > 0.5
        } else {
            true
        };
        if bad_open_bins || progress > 0.8 {
            // Competitive with a mediocre fit: neutral-ish score.
            score = (bin_capacity as f64) * 0.45;
        } else {
            score += 60.0; // discourage opening new bins early
        }
    }

    // Mild reward for closing out bins as the stream progresses.
    score -= 5.0 * (step_index as f64 / (total_items.max(1) as f64)) * (1.0 - tightness);

    score
}

