    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if leftover fits the next item, penalty otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 0.4 * next_item_size as f64;
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Time horizon: late in the stream, be more aggressive about using existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild default penalty so it's chosen only when clearly better.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

