    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: reward tight fits via non-linear polynomial in post_residual.
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Smooth stream-progress coupling: later in the stream, tolerate larger residuals less.
    score += 8.0 * pr_norm * (0.25 + progress) * (1.0 - progress);

    // Penalize residual that cannot fit the lookahead item (smooth quadratic mismatch).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 6.0 * gap * gap * (1.0 - progress);
