    // Mild penalty relative to mean residual across open bins (avoid fragmenting).
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * pr_norm;

    score
}

