            if (new_pr % nx. max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // new: fresh bin that tiles exactly with next item twice (zero dead space chain)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . round ();
            if k >= 2.0 && (new_pr - k * nx) . abs () < 1.0 {
                score -= 0.25 * (0.6 + 0.4 * progress);
            }
        }
        // new: discourage opening fresh bins when many open bins already fit well
        if fitting_bins_count >= 3 && new_pr < mean_residual {
            score += 0.3;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo arithmetic on residual space.
    // Residuals divisible by 10 are "harmonic" — easier for future items to fill.
    let post_mod = post_residual % 10;
    let harm_bonus = match post_mod {
        0 => 14.0,
        5 => 7.0,
        _ => 0.0,
    };
    score -= harm_bonus;

    // Integer-division thresholds on post_residual: classify leftover into slots.
    let slot = post_residual / 10; // 0..=10
    let slot_penalty = match slot {
        0 => 30.0,          // dead space: nothing fits (min item size 1..=10 range)
        1..=2 => 16.0,      // nearly dead
        3..=5 => 6.0,       // medium slot
        6..=8 => -4.0,      // roomy slot, attractive
        _ => -8.0,          // near-empty leftover, very attractive
    };
    score += slot_penalty;

    // Capacity-fraction coupling: does post_residual align with next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or leaves a harmonic remainder
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 18.0;
            } else if nr < 10 {
                score += 12.0; // would create dead space after next item
            }
        } else {
            score += 10.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins are poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins early is cheap; late in the stream consolidate.
        let fresh_bias = 26.0 - 30.0 * progress - pressure * 0.6;
        score += fresh_bias.max(2.0);
    }

    // Mild penalty proportional to residual variance vs mean (prefer balanced bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Tight-fit reward: filling most of the bin in one shot.
    let fill = item_size as f64 / cap;
    if fill > 0.75 {
        score -= 10.0 * (fill - 0.75) / 0.25;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
