        // residual is an exact multiple of the mean residual is a strong opener
        if mean_residual > 1.0 && new_pr > 0.0 {
            let km = (new_pr / mean_residual) . round ();
            if km >= 2.0 && (new_pr - km * mean_residual) . abs () < 2.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
        // mutation: avoid opening fresh bins when an open bin would end with a
        // chain residual that itself fits the next item (keep tight chains alive)
        if next_item_size > 0 && pr > next_item_size as f64 {
            let cr = pr - next_item_size as f64;
            if cr <= 0.05 * cap && cr > 0.0 { score += 0.35 * (1.0 - cr / (0.05 * cap)); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // mutation: residual just below next item and below mean residual scale is
        // likely dead space — discourage such placements
        if mean_residual > 0.0 && pr < mean_residual * 0.5 {
            score += 0.15 * (1.0 - pr / (mean_residual * 0.5)) * (0.5 + 0.5 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are essentially unusable
    // for items of size >= 10, so penalize them heavily beyond their raw size.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 19 {
        score += 12.0;
    } else if post_residual >= 20 && post_residual <= 30 {
        score += 4.0;
    }

    // Perfect fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // mean residual is low (bins nearly full already).
    score += 0.05 * open_bins_count as f64;

    // Prefer bins with residual below the mean (denser bins) to consolidate.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (gap <= 5), mild penalty for near-miss dead space.
    if next_item_size > 0 && post_residual >= 1 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // New-bin candidate: baseline attractiveness that decays as the stream
    // progresses (late in the stream, prefer filling existing bins).
    if bin_residual == bin_capacity {
        score = 30.0 + 25.0 * (step_index as f64 / total_items.max(1) as f64);
        // If no other bin can fit, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the only alternative is a very poor fit (large dead space),
        // opening fresh is reasonable.
        if post_residual >= 1 && post_residual <= 9 && fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

