pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Perfect chain: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to tightness of the 2-step fit.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize leftover dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let cap = bin_capacity as f64;
    if post_residual as f64 > mean_residual {
        // Creating a larger-than-average residual wastes capacity relative to peers.
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        // Tighter than average residual is good.
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins can fit reasonably well.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible = mean_residual.max(0.0);
        if best_possible >= item_size as f64 {
            score += 25.0 + 0.1 * mean_residual;
        }
    }

    // Late in the stream, tighten up: avoid leaving many small open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / cap);

    // Mild preference for filling fuller bins.
    score -= 0.1 * (bin_residual - post_residual) as f64;

    score
}

