pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness: reward small post_residual non-linearly.
    let tight = (post / cap).powi(3);
    score -= 12.0 * (1.0 - tight) * (post / cap);

    // Smooth stream-progress coupling: later in stream, penalize wasted space more.
    score += post * (0.5 + 1.5 * progress * progress);

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (10.0 - post);
    }

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward leaving that space.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * ((next_item_size as f64) - post).max(0.0) / cap;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean.
    let dev = (post - mean_residual).abs();
    score += 2.0 * (dev / cap) * (dev / cap) * cap;

    // New-bin candidate: prefer it only when post_residual is large (item tiny relative to bin)
    // or no good fit exists; otherwise bias toward reusing open bins.
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * (fitting_bins_count as f64).powf(0.5);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
