        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        // fresh bin exactly tiles with next item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        // dead-space penalty: fresh bin residual too small for any plausible item
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // mutation: prefer fresh bins when item is large and open bins would leave slivers
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        // mutation: late-stream fresh bins are cheap only if they tile tightly
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // mutation: fresh bin whose post-residual supports two more items is very cheap
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && new_pr - 2.0 * nx <= 10.0 {
                score -= 0.32 * (1.0 - (new_pr - 2.0 * nx) / 10.0) * (0.6 + 0.4 * progress);
            }
        }
        // mutation: avoid opening fresh bins that strand the immediately following large item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if nx > new_pr && nx > 0.6 * cap {
                score += 0.3 * ((nx - 0.6 * cap) / (0.4 * cap)) . min (1.0);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // mutation: near-miss bins whose gap matches mean residual are less wasteful
        if mean_residual > 0.0 {
            let miss = (next_item_size - post_residual) as f64;
            if (miss - mean_residual) . abs () <= 2.0 {
                score -= 0.2 * (1.0 - (miss - mean_residual) . abs () / 2.0);
            }
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // multi-step exact tiling lookahead (combined with parent's two-step)
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            if cr > nx {
                let r2 = cr - nx;
                if r2 <= 15.0 { score -= 40.0 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 25.0 * (1.0 - r3 / 8.0); }
                }
            }
            // exact divisibility with next item is gold
            if cr >= nx && (cr % nx . max (1.0)) < 1.5 {
                score -= 25.0 * (1.0 - progress * 0.3);
            }
            let k = (cr / nx . max (1.0)) . floor ();
            if k >= 2.0 {
                let rem = cr - k * nx;
                if rem <= 2.0 { score -= 22.0 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // penalize chain residual far below mean residual scale (dead sliver)
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 30.0 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64;
            if miss <= 3.0 { score += 90.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 20.0 * (1.0 - (miss - 3.0) / 5.0); }
            if mean_residual > 0.0 && post_residual as f64 > 0.0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 12.0 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if fitting_bins_count >= 4 { score -= 40.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance: penalize new bins whose residual is unlikely
        // to absorb future items given the mean residual scale
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
            let slack = new_pr / cap;
            if slack < 0.1 { score += 130.0 * (1.0 - slack / 0.1); }
            if slack > 0.15 && slack < 0.45 && progress > 0.3 && progress < 0.8 { score -= 25.0; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        // fresh bin that tiles multiple copies of next item
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 40.0 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 35.0 * (1.0 - (nx - new_pr) / 8.0);
            }
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 28.0 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
            // fresh bin exactly tiles with next item
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 20.0 * (0.5 + 0.5 * progress); }
            // dead-space penalty: fresh bin residual too small for any plausible item
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 45.0 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // prefer fresh bins when item is large and open bins would leave slivers
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 20.0 * (item_size as f64 / cap - 0.55);
        }
        // late-stream fresh bins are cheap only if they tile tightly
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 30.0 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 60.0 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 15.0 * (1.0 - dev / 0.1); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score += 5.0 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
