            }
            let kf = (chain / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
