            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // mutation: reward chain residuals that tile with the mean residual,
            // reducing future dead space across many bins
            if mean_residual > 0.5 && chain_residual > 0.0 {
                let km = (chain_residual / mean_residual) . round ();
                if km >= 1.0 {
                    let errm = (chain_residual - km * mean_residual) . abs ();
                    if errm <= 2.0 { score -= 0.28 * (1.0 - errm / 2.0) * (0.6 + 0.4 * progress); }
                }
            }
            // mutation: penalize chain residuals slightly above a typical item size
            // (nearly-wasted space that no known item can fill)
