        }
        // mutation: fresh bins whose residual exactly fits next item twice are
        // excellent two-item containers; strengthen the pull toward them
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr - 2.0 * nx) . abs () <= 2.0 {
                score -= 0.32 * (1.0 - (new_pr - 2.0 * nx) . abs () / 2.0) * (0.6 + 0.4 * progress);
