                if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5); }
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        // mutation: prefer fresh bins early for large items with small mean residual
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        // mutation: endgame — discourage new bins when few items remain
        let remaining = total_items.saturating_sub(step_index) as f64;
        if remaining < 5.0 {
            score += 0.8 * (5.0 - remaining) / 5.0;
        }
        // mutation: discourage new bins when many open bins already have room
        if fitting_bins_count >= 3 && new_pr > 0.35 * cap {
            score += 0.2;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

