            if new_pr < 0.08 * cap {
                score += 45.0 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress) ;
            }
        }
        score -= 8.0 * (1.0 - progress) ;
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // fresh bin residual tiles with mean_residual: strong long-term reuse
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 22.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // fresh residual that leaves a sub-mean sliver after next item: penalize
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let pair_left = new_pr - next_item_size as f64 ;
            if pair_left > 0.0 && mean_residual > 0.0 && pair_left < mean_residual * 0.5 {
                score += 22.0 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress) ;
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.3 { score -= 12.0 * ((slack - 0.3) / 0.7) . min (1.0) ; }
        }
        // late stream: avoid opening bins unless really needed
        if progress > 0.85 && fitting_bins_count <= 2 { score += 60.0 * (progress - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
