            if chain_residual > nx {
                let r2 = chain_residual - nx ;
                if r2 <= 15.0 { score -= 0.5 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.28 * (1.0 - r3 / 8.0) ; }
