pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Non-linear post-residual shaping: penalize large dead space quadratically
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += 30.0 * pr_norm * pr_norm * (0.5 + p2);

    // Smooth coupling of post_residual with progress: later in stream, demand tighter fits
    score -= (1.0 - pr_norm) * 20.0 * (p2 + p3);

    // Mean residual interaction: prefer bins below mean residual (tighter packing)
    let mr_norm = mean_residual / cap;
    score += 10.0 * (pr_norm - mr_norm) * (1.0 + progress);

    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr >= nx) as i32 as f64;
        let slack = ((pr - nx) / cap).max(-1.0);
        score -= fit_next * (15.0 - 10.0 * slack.abs()) * (0.5 + 0.5 * progress);
        score += (1.0 - fit_next) * 12.0 * (1.0 - progress);
    }

    // Last-chance bin bonus (smooth via inverse of fitting bins)
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 18.0 * scarcity * scarcity * (0.4 + 0.6 * progress);
    }

    // Penalize crowding of open bins mildly
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    // Slight reward for filling bin fully (smooth saturation)
    let fill = 1.0 - pr_norm;
    score -= 8.0 * fill * fill * fill;

    score
}

