                score += 0.1 * (0.5 + 0.5 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes penalize "dead" residuals
    let class = post_residual % 10;
    if class != 0 {
        score += class as f64 * 0.8;
    }

    // Reward near-perfect fits (small post_residual) strongly
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Integer division threshold: large residual chunks are valuable
    let chunk = post_residual / 25;
    score += chunk as f64 * 2.0;

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // extra reward if next item exactly fills the class
        if post_residual - next_item_size <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize leaving mid-range dead space
        if post_residual > 20 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer denser bins when many bins are open
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: penalize so it is only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Late-stream pressure: consolidate more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

