    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // fresh bins whose residual tiles with mean_residual are strong (dead-space avoidance)
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        // prefer fresh bins early when the item is large and mean residual is small
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        // mutation: a fresh bin is especially valuable when its residual matches the
        // next item almost exactly AND open-bin alternatives would strand more space
        if next_item_size > 0 && fitting_bins_count >= 2 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let fresh_waste = new_pr - nx;
                if fresh_waste <= 2.0 { score -= 0.3 * (1.0 - fresh_waste / 2.0); }
            }
        }
        // mutation: late-stream fresh bins should only open if they tile cleanly
        if progress > 0.6 && mean_residual > 0.0 && new_pr > 0.0 {
            let rem = (new_pr / mean_residual . max (1.0) - (new_pr / mean_residual . max (1.0)) . floor ()) * mean_residual . max (1.0);
            if rem > 1.0 && rem < mean_residual * 0.5 {
                score += 0.2 * (1.0 - rem / (mean_residual * 0.5)) * ((progress - 0.6) / 0.4);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    // mutation: global fragmentation guard — when many bins are open and this fit
    // would strand a residual just under the next item, push the item elsewhere
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        if stranded > 2.0 && stranded < 0.05 * cap && open_bins_count > 2 {
            score += 0.25 * (1.0 - stranded / (0.05 * cap)) * (0.6 + 0.4 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, non-linearly warped by stream progress.
    // Late in the stream, tight fills (small post_residual) matter more.
    let warp = 1.0 + 2.0 * progress * progress;
    let mut score = pr * warp + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits with smooth polynomial in (1 - norm_pr).
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * (0.3 + progress);

    // Penalize dead space relative to the next item: smooth quadratic coupling.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward post-residual that exactly accommodates the lookahead item.
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 15.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement wastes space.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * open_pressure * norm_pr;

    // Coupling with mean residual: prefer bins deviating below mean residual
    // (i.e., tighter bins) via smooth interaction.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    // 2-step lookahead: reward when leftover space exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 5.0;
    }
    // Near-match lookahead with multi-step tiling bonuses.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx = next_item_size as f64;
        let chain = pr - nx;
        score -= 1.3 * (1.0 - chain / cap);
        if chain <= 10.0 {
            score -= 0.9;
        }
        if chain >= 20.0 && chain <= 60.0 {
            score -= 0.25;
        }
        // two-step lookahead: residual fits next item twice
        if chain > nx {
            let r2 = chain - nx;
            if r2 <= 15.0 {
                score -= 0.45 * (1.0 - r2 / 15.0);
            }
            if r2 > nx {
                let r3 = r2 - nx;
                if r3 <= 8.0 {
                    score -= 0.25 * (1.0 - r3 / 8.0);
                }
            }
        }
        // multiple-of-next-item tiling bonus
        let k = (pr / nx).round();
        let mult_err = (pr - k * nx).abs();
        if k >= 2.0 && mult_err <= 2.0 {
            score -= 0.35 * (1.0 - mult_err / 2.0);
        }
        // wasted dead-space penalty scaled by progress
        let wasted = chain / cap;
        if wasted > 0.05 {
            score += 0.4 * wasted * (0.4 + 0.6 * progress);
        }
        if chain > 0.0 && chain < mean_residual * 0.4 {
            score += 0.3 * (1.0 - chain / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
        }
        if chain >= nx && (chain % nx.max(1.0)) < 1.5 {
            score -= 0.3 * (1.0 - progress * 0.3);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // cannot hold next item: penalize near-misses
        let miss = (next_item_size - post_residual) as f64;
        score += 0.2 * pr / cap;
        if miss <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        } else if miss <= 8.0 {
            score += 0.18 * (1.0 - (miss - 4.0) / 5.0);
        }
    }

    // Dead-space penalty: slivers below plausible item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 0.35 * (1.0 - pr / 10.0) + 0.3;
    } else if post_residual > 0 && post_residual < 25 {
        score += 0.25;
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.08 * (mean_residual - bin_residual as f64) / mean_residual;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Mild stream-progress pressure: later in the stream, consolidate more.
    score -= 0.3 * progress * (pr / cap);

    // Open-bin count pressure early in stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // NEW-BIN candidate logic.
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 {
            score += 2.5;
        }
        if fitting_bins_count >= 4 {
            score -= 0.4;
        }
        if next_item_size as f64 > 0.7 * cap {
            score -= 0.6;
        }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= new_pr {
            score -= 0.3;
        }
        if item_size as f64 >= 0.9 * cap {
            score -= 0.55;
        }
        // tight fit into a fresh bin is bad if open bins could do better
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 {
                score += 1.3 * (1.0 - slack / 0.1);
            }
            if slack > 0.3 {
                score -= 0.12 * ((slack - 0.3) / 0.7).min(1.0);
            }
        }
        if progress > 0.7 {
            score -= 0.25 * (progress - 0.7) / 0.3;
        }
        if progress > 0.85 && fitting_bins_count <= 2 {
            score += 0.6 * (progress - 0.85) / 0.15;
        }
        // lookahead on fresh-bin residual
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 {
                    score -= 0.55 * (1.0 - r / 5.0);
                }
                if r >= mean_residual.max(1.0) {
                    score -= 0.18 * (1.0 - progress * 0.4);
                }
            } else {
                let miss = (nx - new_pr) / cap;
                score += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            let k = (new_pr / nx).floor();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 {
                    score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress);
                }
            }
        }
        // fresh bins whose residual tiles with mean_residual are strong
        if mean_residual > 0.5 {
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 {
                score -= 0.18;
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap {
            score -= 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 0..7 harmonic class

    // Reward small post residuals non-linearly (best-fit bias with curvature).
    score -= (cap - pr) / cap * 12.0;

    // Dead-space penalty: residuals that no plausible item (1..100) can fill well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0; // sweet spot: many item sizes fit
    }
    // Modulo arithmetic: residuals divisible by common item sizes are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += (open_bins_count as f64) * 0.3 * (pr / cap);

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Default: penalize opening a new bin.
        let mut new_bin_penalty = 18.0;
        // But allow a new bin when all open bins would leave bad dead space,
        // i.e., the item would fit poorly everywhere (post_residual here is cap - item).
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && pr < 15.0 && item_size >= 50);
        if poor_fit_elsewhere {
            new_bin_penalty = -5.0; // fresh bin becomes attractive
        }
        // Late in the stream, be more reluctant to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
        // Harmonic class alignment for the fresh bin: exact-fill potential.
        if class < 1.0 {
            score -= 8.0;
        }
    }

    // Mild tie-breaking noise via harmonic function of step (deterministic).
    score += ((step_index as f64 * 0.37).sin()) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // two-step lookahead: residual fits next item twice
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                // mutation: escalate dead-space penalty when many bins compete (poor fits deserve rejection)
                let crowd = 1.0 + 0.06 * (fitting_bins_count . min (8) as f64);
                score += 0.35 * crowd * (1.0 - chain_residual / (0.06 * cap));
            }
            // mutation: reward chain residuals that still tile with mean_residual (future reuse)
            if mean_residual > 0.5 && chain_residual > 0.0 {
                let km = (chain_residual / mean_residual) . floor ();
                if km >= 1.0 {
                    let remm = chain_residual - km * mean_residual;
                    if remm <= 4.0 { score -= 0.2 * (1.0 - remm / 4.0) * (0.5 + 0.5 * progress); }
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // mutation: nearly-miss bins are worse when the stream still has many items left
            if miss > 0.0 && miss <= 2.0 && progress < 0.5 {
                score += 0.25 * (1.0 - miss / 2.0) * (1.0 - progress / 0.5);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // fresh bins whose residual tiles with mean_residual are strong (dead-space avoidance)
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        // prefer fresh bins early when the item is large and mean residual is small
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        // mutation: fresh bin is extra attractive when its residual exactly equals the mean residual
        // (maximizes future reuse of the leftover space)
        if mean_residual > 0.5 && new_pr > 0.0 && ((new_pr - mean_residual) . abs () as u32) <= 2 {
            score -= 0.28 * (1.0 - (new_pr - mean_residual) . abs () / 2.0) * (0.6 + 0.4 * progress);
        }
        // mutation: discourage fresh bins whose residual leaves an awkward sliver vs next item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = new_pr - nx;
                if rem > 0.0 && rem < 5.0 { score += 0.2 * (1.0 - rem / 5.0); }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (small post_residual relative to item)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + fit_ratio * 3.0);

    // Open-bin pressure: when many bins are open, favor filling existing ones
    score -= (open_bins_count as f64).sqrt() * 4.0;

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item can use the post_residual, this placement is great
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Slight preference to keep mean residual balanced
    score += (post_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: baseline so it's chosen only when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // two-step lookahead: residual fits next item twice
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
