                if rem > 0.0 && rem < 0.04 * cap && rem < mean_residual . max (1.0) {
                    score += 0.3 * (1.0 - rem / (0.04 * cap)) * (0.5 + 0.5 * progress);
                }
            }
        }
        // mutation: fresh bin is more attractive when it can absorb the next
        // item AND the resulting leftover still exceeds the mean residual
        // (guarantees future usefulness), refined in mid-stream
        if next_item_size > 0 && new_pr > 0.0 && progress > 0.2 && progress < 0.85 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) * 1.2 {
                    score -= 0.14 * ((after / mean_residual . max (1.0) - 1.2) . min (2.0) / 2.0);
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
