}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly or nearly exactly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny unusable slivers (post_residual < 10 likely dead).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (concentrate waste into already-loose bins).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it unattractive unless current bin is very tight
    // relative to the next item (handled implicitly by lookahead terms).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Allow new bin if no open bin can chain the next item well.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

