            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // fresh bins whose residual tiles with mean_residual are strong (dead-space avoidance)
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        // prefer fresh bins early when the item is large and mean residual is small
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        // mutation: strengthen dead-space avoidance — reject fresh bins whose leftover
        // residual is a tiny sliver no plausible item (mean or next) can use
        if new_pr > 0.0 && new_pr < 0.05 * cap {
            let usable_floor = mean_residual . max (next_item_size as f64) . max (1.0);
            if new_pr < usable_floor * 0.35 {
                score += 0.3 * (1.0 - new_pr / (usable_floor * 0.35)) * (0.6 + 0.4 * progress);
            }
        }
        // mutation: reward fresh bins that leave room for the current item AND the next two
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let r2 = new_pr - nx;
            if r2 >= nx {
                let r3 = r2 - nx;
                if r3 <= 6.0 { score -= 0.2 * (1.0 - r3 / 6.0); }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer near-perfect fits: reward small post_residual nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for typical future items is waste.
    let min_item = 1.0;
    if (post_residual as f64) < min_item * 10.0 {
        score += 0.0; // already near zero, no extra penalty
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.8; // small awkward gap
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - gap as f64 / 100.0);
            }
        } else {
            // Next item cannot follow into this bin; mild penalty, worse if gap small.
            let overshoot = next_item_size - post_residual;
            if overshoot <= 15 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin. Prefer reusing open bins unless
    // they are all fragmented (high mean residual spread) or many bins already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream horizon.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 - 8.0 * progress;
        // If existing bins are highly fragmented, opening fresh is more attractive.
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        if fragmentation > 25.0 {
            new_bin_cost -= 10.0;
        }
        // With many open bins, consolidation is preferable to adding more.
        if open_bins_count > 8 {
            new_bin_cost += 0.5 * (open_bins_count as f64 - 8.0);
        }
        // If the next item is large and current bins are tight, new bin helps.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost.max(0.0);
        // Empty bin has post_residual == capacity - item; normalize so its
        // intrinsic residual doesn't dominate the decision.
        score -= post_residual as f64 * 0.5;
    }

    // Mild global pressure: when many bins are open, favor tighter packing
    // (smaller post_residual) more aggressively.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.02;

    // Early stream: slightly favor filling existing bins to build good structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr / cap;

    // Tight-fit reward: favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 0.35 * fit_ratio * fit_ratio;

    // Perfect fills.
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead-space penalty: slivers below plausible item sizes.
    if pr > 0.0 && pr < 0.06 * cap {
        score += 0.35 * (1.0 - pr / (0.06 * cap));
    }

    // Global mean residual pressure: consolidate into fuller bins early.
    score += 0.05 * mean_residual * (1.0 - progress) / cap;

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 {
            if pr == nx {
                score -= 4.0;
            } else if pr > nx {
                let chain = pr - nx;
                score -= 1.2 * (1.0 - chain / cap);
                // two-step lookahead
                if chain > nx {
                    let r2 = chain - nx;
                    if r2 <= 12.0 {
                        score -= 0.4 * (1.0 - r2 / 12.0);
                    }
                }
                // tiling bonus: residual is a near-multiple of next item
                let k = (pr / nx.max(1.0)).round();
                if k >= 2.0 && (pr - k * nx).abs() <= 2.0 {
                    score -= 0.3 * (1.0 - (pr - k * nx).abs() / 2.0);
                }
                // large unusable leftover, worse late in the stream
                if chain > 0.12 * cap {
                    score += 0.4 * (chain / cap) * (0.4 + 0.6 * progress);
                }
            } else {
                // next item can't use the leftover; penalize near-misses
                let miss = nx - pr;
                if miss <= 5.0 {
                    score += 1.2 * (1.0 - miss / 5.0) * (1.0 - 0.5 * progress);
                } else {
                    score += 0.25 + 0.5 * progress;
                }
                // leftover still large enough to be useful later
                if pr >= 0.5 * nx {
                    score -= 0.08 * (pr / nx) * (1.0 - progress);
                }
            }
        }
    }

    if bin_residual == bin_capacity {
        // NEW BIN candidate: baseline score so it only wins when open bins are poor.
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        let new_pr = (bin_capacity - item_size) as f64;
        score -= 0.45 * item_size as f64 / cap;

        if fitting_bins_count == 1 {
            score += 2.5; // nothing else fits, new bin is fine
        }
        if fitting_bins_count >= 4 {
            score -= 0.4;
        }
        // very large item: fresh bin is natural
        if item_size as f64 >= 0.9 * cap {
            score -= 0.55;
        }
        // penalize fresh bins whose leftover is a near-miss for the next item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after <= 5.0 {
                    score -= 0.5 * (1.0 - after / 5.0);
                }
                // two-step tiling in fresh bin
                if after > nx && after - nx <= 8.0 {
                    score -= 0.25 * (1.0 - (after - nx) / 8.0);
                }
            } else {
                let miss = nx - new_pr;
                if miss <= 8.0 {
                    score += 0.35 * (1.0 - miss / 8.0);
                }
                if new_pr < 0.08 * cap {
                    score += 0.4 * (1.0 - new_pr / (0.08 * cap));
                }
            }
        }
        // fresh bin residual aligned with mean residual tiles well
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 {
                score -= 0.12 * ((slack - 0.3) / 0.7).min(1.0);
            }
        }
        // late-stream: keep consolidating, avoid fresh bins
        if progress > 0.85 && fitting_bins_count <= 2 {
            score += 0.6 * (progress - 0.85) / 0.15;
        }
        // early large-item opening when open bins are tight
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap {
            score -= 0.3;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        } else {
            score += 0.2 * pr / cap;
        }
    }

    // Mild pressure against scattering across many open bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Late-stream urgency: consolidate harder as the stream ends.
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly discounted at late stream stages (pack tighter)
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear penalty on residual: tiny residuals are dead space, huge residuals waste capacity
    let dead = (1.0 - norm_pr).powi(3) * 30.0 * (1.0 - progress);
    let waste = norm_pr * norm_pr * 20.0 * progress;
    score += dead + waste;

    // Reward good fit (small post residual relative to item)
    score -= norm_item * (1.0 - norm_pr) * 25.0;

    // Lookahead coupling: if next item fits exactly into post residual, strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 35.0 * fit_quality * fit_quality * (1.0 - 0.5 * progress);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.3 * progress);
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mean residual interaction: prefer bins below mean residual (tighter bins first)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress) - 6.0 * norm_item;
    }

    // Smooth open-bin pressure: many open bins -> discourage spreading
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // two-step lookahead: residual fits next item twice
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // mutation: penalize residuals that cannot hold even the mean-sized future piece
            if mean_residual > 1.0 && chain_residual > 0.0 && chain_residual < mean_residual {
                score += 0.18 * (1.0 - chain_residual / mean_residual) * (0.3 + 0.7 * progress);
            }
            // mutation: reward chain residuals close to a whole multiple of mean residual
            if mean_residual > 1.0 {
                let km = (chain_residual / mean_residual) . round ();
                if km >= 1.0 {
                    let err = (chain_residual - km * mean_residual) . abs ();
                    if err <= 2.0 { score -= 0.16 * (1.0 - err / 2.0); }
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // mutation: extra dead-space penalty for tiny unfillable residuals late in stream
            if pr > 0.0 && mean_residual > 1.0 && pr < 0.35 * mean_residual {
                score += 0.22 * (1.0 - pr / (0.35 * mean_residual)) * (0.4 + 0.6 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
