pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common
    // item sizes (multiples of 5, 10, 20) are "harmonic" and get rewarded.
    let h = post_residual % 20;
    let harmonic = match h {
        0 => 1.0,
        5 | 15 => 0.6,
        10 => 0.8,
        _ => 0.0,
    };
    score -= 6.0 * harmonic;

    // Non-harmonic small dead space is penalized super-linearly.
    if post_residual > 0 && post_residual < 10 && h != 5 {
        score += 12.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Can the lookahead item fit exactly into post_residual? Reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            // Harmonic pairing: (post_residual - next) stays on a good class.
            let h2 = (post_residual - next_item_size) % 10;
            if h2 == 0 {
                score -= 10.0;
            }
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead: penalize by the gap's class.
        let gap = next_item_size - post_residual;
        if gap <= 10 {
            score += 4.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: opening a new bin is costly, so favor using it
    // unless the fit is terrible (large post_residual waste).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 40 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit into any open bin would be very loose.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded || fitting_bins_count == 0 {
            score -= 8.0 + 10.0 * progress;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 20.0 + 5.0 * mean_residual / bin_capacity as f64;
        }
    }

    // Mild preference for tighter bins as stream progresses.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * (step_index as f64 / total_items.max(1) as f64);

    score
}

