        // once AND is small enough to be dead space — this is where dead space accumulates
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 && new_pr < 0.12 * cap {
            score += 0.55 * (1.0 - new_pr / (0.12 * cap)) * (0.6 + 0.4 * progress);
        }
        // mutation: reward fresh bins whose residual supports a two-item chain
        // (next item + any plausible small item) with minimal leftover
        if next_item_size > 0 && new_pr > next_item_size as f64 {
            let nx = next_item_size as f64;
            let after = new_pr - nx;
            if after >= 1.0 && after <= 0.15 * cap {
                // leftover small but usable: good tiling
                score -= 0.2 * (1.0 - after / (0.15 * cap)) * (0.5 + 0.5 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
