        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // reject fresh bins whose residual falls in the dead gap just
        // below the next item (waste now) unless the residual is a clean tile of
        // the mean residual; strengthened mid-stream where compaction matters
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // prefer fresh bins whose residual can host the next item twice
        // (pair-packing lookahead) with a tight remainder
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // mutation: extend pair-packing lookahead to triple fits — a fresh bin
        // that can absorb the next item three times with a tight remainder is an
        // excellent compaction target, especially early/mid stream
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem3 = new_pr - 3.0 * nx;
                if rem3 <= 5.0 {
                    score -= 0.22 * (1.0 - rem3 / 5.0) * (1.0 - progress * 0.4);
                }
            }
        }
        // mutation: penalize fresh bins whose residual is a sliver of dead space
        // relative to the stream's mean leftover scale, but only when other open
        // bins actually fit the item (competition-aware)
        if mean_residual > 0.5 && new_pr > 0.0 && fitting_bins_count >= 2 {
            if new_pr < 0.5 * mean_residual {
                score += 0.2 * (1.0 - new_pr / (0.5 * mean_residual)) * (0.5 + 0.5 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

