        // residual is genuinely better-shaped than the mean residual scale —
        // otherwise the open bins should absorb the item (dead-space discipline)
        if fitting_bins_count >= 3 && mean_residual > 0.5 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev > 0.75 { score += 0.3 * ((dev - 0.75) / 0.75) . min (1.0); }
        }
        // mutation: fresh bins whose residual leaves zero waste after the next
        // two items are prime compaction candidates
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.3 * (1.0 - rem / 3.0) * (0.6 + 0.4 * progress); }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

