                }
            }
        }
        // prefer fresh bins whose residual can host the next item twice
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // mutation: prefer fresh bins whose residual can host the next item a full
        // number of times with a remainder that matches the mean residual scale —
        // extends the pair-packing lookahead to k>=3 tilings
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 3.0 {
                let rem = new_pr - k * nx;
                if rem <= mean_residual * 0.4 {
                    score -= 0.2 * (1.0 - rem / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
                }
            }
        }
        // mutation: when the new bin's residual is a near-exact multiple of the
        // mean residual, it can absorb the stream's typical leftovers cleanly —
        // reward more strongly late where dead space accumulates
        if mean_residual > 0.5 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 2.0 {
                score -= 0.25 * (1.0 - rem / 2.0) * (0.4 + 0.6 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
