        // mutation: fresh bins that leave a residual exactly equal to the mean
        // residual are ideal "chain starters" — the next item likely closes them
        if mean_residual > 0.5 && new_pr > 0.0 && (new_pr - mean_residual) . abs () <= 2.0 {
            score -= 0.25 * (1.0 - (new_pr - mean_residual) . abs () / 2.0) * (0.5 + 0.5 * progress);
        }
        // mutation: when few open bins fit and the stream is late, opening a
        // fresh bin with a large residual is cheap insurance against stranding
        if fitting_bins_count >= 2 && progress > 0.6 && new_pr >= next_item_size as f64 {
            score -= 0.1 * progress;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap ;
    if post_residual == 0 { score -= 6.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 4.5 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            let cr = chain_residual as f64 ;
            score -= 1.2 * (1.0 - cr / cap) ;
            if chain_residual <= 10 { score -= 0.8 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 0.2 ; }
            // two-step lookahead: reward residuals that fit the next item twice
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.35 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // multi-step tiling: residual hosts nx repeatedly with tight remainder
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 0.4 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 0.22 * (1.0 - r3 / 8.0) ; }
                }
            }
            // multiple-of-next tiling bonus
            let k = (post_residual as f64 / nx) . round () ;
            let mult_err = (post_residual as f64 - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.3 * (1.0 - mult_err / 2.0) ; }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap ;
            if wasted > 0.06 { score += 0.5 * wasted * (0.4 + 0.6 * progress) ; }
            // dead-space sliver penalty
            if cr > 0.0 && cr < 0.06 * cap {
                score += 0.35 * (1.0 - cr / (0.06 * cap)) ;
            }
            // gap band: chain residual just below nx can't absorb a future item
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ;
                }
            }
            // residual near mean_residual scale is reusable
            if mean_residual > 0.0 && cr > 0.0 {
                let ratio = cr / mean_residual ;
                if ratio < 0.15 { score += 0.2 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.4 * progress ;
            // small gap to next item: poor fit, penalize proportionally
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 1.6 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss >= 1.0 && miss <= 2.0 { score += 0.4 * (2.0 - miss) ; }
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0) ; }
            if mean_residual > 0.0 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0) ; }
            }
        }
        // item-size tiling of the post residual
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz) . round () ;
            if k >= 1.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3) ;
            }
