            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // fresh bins whose residual tiles with mean_residual are strong (dead-space avoidance)
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // mutation: reject fresh bins whose residual falls in the dead gap just
        // below the next item (waste now) unless the residual is a clean tile of
        // the mean residual; strengthened mid-stream where compaction matters
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // mutation: prefer fresh bins whose residual can host the next item twice
        // (pair-packing lookahead) with a tight remainder
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // mutation (gen 130): fresh-bin residual that tiles with mean_residual with a
        // wider tolerance window — mid-stream, matching the stream's leftover scale
        // predicts low dead-space over the bin's whole lifetime
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 1.0 {
                let dev = (new_pr - k * mean_residual) . abs ();
                if dev > 3.0 && dev <= 7.0 {
                    score -= 0.1 * (1.0 - (dev - 3.0) / 4.0) * (0.5 + 0.5 * progress);
                }
            }
        }
        // mutation (gen 130): penalize fresh bins whose residual sits in the dead
        // band just above the next item — it will absorb nx but strand a sliver
        // smaller than typical items, wasting compaction potential
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let after = new_pr - nx;
                if after > 0.0 && after < 0.35 * nx && mean_residual > 0.0 && after < mean_residual * 0.6 {
                    score += 0.18 * (1.0 - after / (0.35 * nx)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // mutation (gen 130): when many bins fit and the stream is deep, opening a
        // fresh bin with a residual close to the mean residual is a strong long-run
        // play — the residual will likely be reused by future typical items
        if fitting_bins_count >= 3 && progress > 0.35 && mean_residual > 2.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.2 { score -= 0.2 * (1.0 - dev / 0.2); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when it enables large future packing.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin.
        score += 60.0;
        // Lookahead: if next item fits nicely into leftover of this item, discount opening.
        let leftover = bin_capacity - item_size;
        if next_item_size > 0 && (leftover as i64 - next_item_size as i64) >= 0 {
            let next_fit = next_item_size as f64 / leftover as f64;
            score -= 55.0 * next_fit;
        }
        // Early in stream: more willing to open bins (exploration).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If open bins are fragmented (high mean residual but many bins), opening is fine.
        if open_bins_count > 4 && mean_residual > 40.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: prefer bins whose residual is close to item (best-fit shaping).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.15 * tightness;
        // Prefer bins with residual below mean (consolidate fragmentation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Lookahead synergy: if next item exactly fits the post-residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here; mild penalty for wasting the slot.
            score += 3.0;
        }
        // Late in stream: avoid opening bins, squeeze existing ones harder.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
