            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: dead-space ratio term — penalize chain residuals that are
            // too small to ever match the stream's typical leftover scale, scaled
            // by how much of the bin is left empty relative to the mean
            if mean_residual > 0.5 && chain_residual > 0.0 && chain_residual < 0.5 * mean_residual {
                score += 0.3 * (1.0 - chain_residual / (0.5 * mean_residual)) * (0.3 + 0.7 * progress);
            }
