        }
        // prefer fresh bins whose residual can host the next item twice
        // (pair-packing lookahead) with a tight remainder
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // mutation: fresh-bin residual whose leftover after absorbing the next
        // item lands within a sliver of the mean residual scale keeps the
        // stream's dead-space rhythm tight — reinforce this compaction signal
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let after = new_pr - nx;
                let rem = after - (after / mean_residual) . floor () * mean_residual;
                if rem <= 2.0 { score -= 0.2 * (1.0 - rem / 2.0) * (0.6 + 0.4 * progress); }
            }
        }
        // mutation: late-stream, prefer closing fresh bins that leave almost
        // nothing — a tiny residual is near-zero future dead space
        if progress > 0.8 && new_pr > 0.0 && new_pr <= 4.0 {
            score -= 0.25 * (1.0 - new_pr / 4.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions and residue classes (mod arithmetic).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post residual relative to capacity.
    let frac = pr / cap; // in [0, 1]
    // Integer division thresholds on post_residual.
    let q = post_residual / 10; // which "decade" of leftover space we land in
    let r = post_residual % 10; // residue within the decade

    // Reward large post residuals less strongly when they fall into
    // "dead space" classes (very small leftovers that few items can use).
    let dead_zone = pr > 0.0 && pr < 10.0;
    if dead_zone {
        score += 15.0; // penalize leaving nearly-unusable slivers
    }

    // Harmonic coupling: post residual residue class vs next item size class.
    if next_item_size > 0 {
        let nxt = next_item_size;
        // Does the next item fit exactly into the post residual?
        if nxt == post_residual {
            score -= 40.0; // perfect harmonic match: reserve this slot
        } else if nxt <= post_residual {
            // Next item fits; reward based on how tightly it nests.
            let nest = (post_residual - nxt) as f64;
            score -= 20.0 * (1.0 - nest / cap);
            // Modulo harmony: next item and post residual share residue class mod 10
            if (nxt % 10) == (post_residual % 10) {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover; slight penalty scaled
            // by how much dead space we would strand relative to next need.
            score += 5.0 * (nxt as f64 - pr) / cap;
        }
        // Integer-division threshold coupling: if post residual is in the
        // same decade class as next item size, encourage compatibility.
        if (nxt / 10) == q && nxt <= post_residual {
            score -= 6.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 10.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins
    // are nearly full or the fit is poor.
    if bin_residual == bin_capacity {
        // Opening fresh: neutral baseline plus pressure from stream progress
        // and number of open bins.
        score = cap * 0.9 + (open_bins_count as f64) * 2.0;
        // Early in stream, opening new bins is cheap (spreads load).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If item leaves a good harmonic class in a fresh bin (e.g. lands on
        // a decade boundary), slightly favor opening.
        if (item_size % 10) == 0 {
            score -= 5.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    score -= 30.0 * (item_size as f64) / (bin_residual as f64).max(1.0);

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // an outlier; using it harmonizes the residual distribution.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.min(20.0) * 0.5;
    } else {
        score += (-dev).min(20.0) * 0.3;
    }

    // Residue-class bonus: post residuals that are multiples of 10 pair well
    // with the item size grid (sizes 10..80 historically).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Penalize odd residues that create awkward leftovers.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize residuals in the "gap band" between the next item and the
            // smallest plausible reusable remainder — dead space no single future
            // item can absorb without splitting
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals that tile with the mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: scarcity-aware tightening — when few bins can host the item,
            // committing to the best chain fit is worth more (avoids leaving a lone
            // fitting bin stranded with an awkward residual)
            if fitting_bins_count <= 2 && chain_residual <= 0.2 * cap {
                score -= 0.3 * (1.0 - chain_residual / (0.2 * cap)) * (1.0 - progress * 0.4);
            }
            // mutation: chain residual that exactly equals mean_residual scale is a
            // low-variance leftover; prefer it to shrink residual dispersion
            if mean_residual > 0.5 && (chain_residual - mean_residual) . abs () <= 2.0 {
                score -= 0.2 * (1.0 - (chain_residual - mean_residual) . abs () / 2.0);
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // when the miss is exactly 1-2 units, the bin is nearly saturated —
            // a strong signal to fill it now rather than strand it
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            // mutation: a near-miss bin whose residual is far below the stream's
            // mean residual is likely to stay stranded; amplify the penalty
            if mean_residual > 0.5 && pr > 0.0 && pr < 0.5 * mean_residual {
                score += 0.25 * (1.0 - pr / (0.5 * mean_residual));
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // fresh bins whose residual tiles with mean_residual are strong
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // reject fresh bins whose residual falls in the dead gap just below the
        // next item unless the residual is a clean tile of the mean residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // prefer fresh bins whose residual can host the next item twice tightly
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // mutation: tighten the "best chain fit leaves a sliver" case — when every
        // open fit would strand a residual below the mean-residual scale, a fresh
        // bin with a clean-tile residual is preferred
        if mean_residual > 0.5 && fitting_bins_count >= 1 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . floor ();
            let rem = new_pr - k * mean_residual;
            if k >= 1.0 && rem < 0.35 * mean_residual {
                score -= 0.2 * (1.0 - rem / (0.35 * mean_residual)) * (0.5 + 0.5 * progress);
            }
        }
        // mutation: late-stream fresh bins should only open when the residual can
        // still absorb at least one more item of the stream's typical scale
        if progress > 0.6 && mean_residual > 0.5 && new_pr > 0.0 && new_pr < mean_residual * 0.6 {
            score += 0.3 * (1.0 - new_pr / (mean_residual * 0.6));
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // mutation: near-miss open bins whose residual is a small orphan relative
        // to mean residual should be deprioritized further mid-stream
        if mean_residual > 0.5 && pr < 0.4 * mean_residual {
            score += 0.15 * (1.0 - pr / (0.4 * mean_residual)) * (0.4 + 0.6 * progress);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste. Penalize them
    // heavily; residuals in the "usable" band get a mild reward instead.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // Reward tight fits that leave a usable remainder.
        let tightness = (post_residual as f64) / bin_capacity as f64;
        score -= (1.0 - tightness) * 12.0;
    }

    // Penalize residuals that cannot fit the known next item (lookahead k=2):
    // the leftover is dead space at least until the item after next.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Conversely, reward bins whose post_residual exactly accommodates the
    // next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // compact fit exists; scale with stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Prefer bins whose residual is below the mean (denser bins first),
    // keeping the residual ordering primary.
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., the current fit leaves a large dead gap).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 40.0 - 0.4 * waste; // empty bin baseline; big items make it attractive
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // gap-band penalty just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: exact-fill chain (residual absorbs next item with zero waste)
            if chain_residual < 1.0 {
                score -= 0.5 * (1.0 - progress * 0.4);
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // near-saturated bins (miss 1-2) — fill them now
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // mutation: bins that will fit the item after next (2-step lookahead)
            if pr >= nx && mean_residual > 0.0 && mean_residual > nx {
                score -= 0.1;
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            // fresh bin residual exactly absorbs next item plus mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            // pair-packing lookahead — fresh residual hosts next item twice
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            // reject fresh bins whose residual falls just below next item
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // mutation: fresh residual that tiles cleanly with the next item size
            let kf = (new_pr / nx).floor();
            if kf >= 3.0 {
                let rem = new_pr - kf * nx;
                if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            // mutation: penalize fresh bins whose leftover after the current item is
            // a dead sliver no future item can use (below mean residual scale)
            if next_item_size > 0 && new_pr >= next_item_size as f64 {
                let after = new_pr - next_item_size as f64;
                if after > 0.0 && after < mean_residual * 0.3 {
                    nb += 0.2 * (1.0 - after / (mean_residual * 0.3)) * (0.5 + 0.5 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits into the post_residual,
    // reward this bin heavily (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual as f64 - next_item_size as f64);
            score -= 40.0 - slack * 0.5;
        } else {
            // Next item won't fit here; penalize leaving a gap that is
            // too small to be useful for typical items.
            if post_residual < 10 {
                score += 15.0;
            }
            // Small penalty proportional to unusable gap relative to next item.
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean
    // (better fits), penalize bins far looser than the mean.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the
    // current fit is poor. An empty bin has large post_residual (= capacity),
    // which naturally scores high; subtract a modest bonus so it wins only
    // when open bins have very poor fits, but discourage it early on.
    if bin_residual == bin_capacity {
        score -= 25.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Mild preference to close out nearly-full bins when many bins are open.
    if open_bins_count > 5 && post_residual <= 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize residuals that sit in the "gap band" between the next
            // item and the smallest plausible reusable remainder — dead space no
            // single future item can absorb without splitting
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals that tile with the mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: chain residual that is a clean multiple of the next item
            // with remainder near zero is a perfect tiling — reward progressively
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // mutation: penalize chain residuals in the "unreachable band" between
            // the mean residual and 2x the next item when they are not tiles of
            // either — high dead-space risk mid-stream
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // when the miss is exactly 1-2 units, the bin is nearly
            // saturated — a strong signal to fill it now rather than strand it
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            // mutation: bins whose residual nearly matches the mean residual are
            // the stream's natural leftover scale — mild bonus to keep rhythm
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        // fresh bins whose residual tiles with mean_residual are strong (dead-space avoidance)
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // pull toward fresh bins when all open fits leave >30% slack
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // reject fresh bins whose residual falls in the dead gap just
        // below the next item (waste now) unless the residual is a clean tile of
        // the mean residual; strengthened mid-stream where compaction matters
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // prefer fresh bins whose residual can host the next item twice
        // (pair-packing lookahead) with a tight remainder
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // mutation: fresh bins that can host next item three times with near-zero
        // remainder are ideal triple-tilers — extend the pair-packing lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        // mutation: late-stream, prefer fresh bins when the best open fit would
        // strand more than 25% of capacity (endgame compaction push)
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // gap band just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: clean multiple of next item with near-zero remainder
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // mutation: unreachable band between mean residual and 2x next item
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // near-saturated bins (miss 1-2) — fill them now
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                // mutation: residual matching the stream's natural leftover scale
                if mean_residual > 0.5 {
                    let dev2 = ((pr - mean_residual) / mean_residual).abs();
                    if dev2 <= 0.05 { score -= 0.1 * (1.0 - dev2 / 0.05); }
                }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                // mutation: triple-tiler lookahead
                if new_pr >= 3.0 * nx {
                    let rem3 = new_pr - 3.0 * nx;
                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            // fresh bin residual exactly absorbs next item plus mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            // pair-packing lookahead — fresh residual hosts next item twice
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            // reject fresh bins whose residual falls just below next item
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        // mutation: endgame compaction push — prefer fresh bins when all open
        // fits would strand more than 25% of capacity
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                nb -= 0.3 * ((best_open_slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        // mutation: fresh bins whose residual pairs next item tightly with mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

