                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-136 mutation: near-miss fits whose leftover would be a tiny
            // sliver barely below the mean residual are salvageable — soften
            if mean_residual > 0.5 && pr > 0.0 && pr < mean_residual {
                let near = mean_residual - pr;
                if near <= 3.0 { score -= 0.12 * (1.0 - near / 3.0); }
