        // sliver between the next item and 2x next item (dead zone)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-136 mutation: fresh-bin dead-zone refinement — when the leftover
        // after placing the item cannot fit the next item but is within a
        // mean-residual-sized reach of doing so, penalize proportionally to
        // how close it came (avoids stranding just-below-threshold space)
        if next_item_size > 0 && new_pr > 0.0 && mean_residual > 0.5 {
            let nx = next_item_size as f64;
            if new_pr < nx && nx - new_pr <= mean_residual * 0.5 {
                score += 0.18 * (1.0 - (nx - new_pr) / (mean_residual * 0.5)) * (0.5 + 0.5 * progress);
            }
        }
