        if progress > 0.3 && progress < 0.85 && open_bins_count >= 5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let mut tiled = false;
            if nx > 0.0 {
                let rem_n = new_pr - (new_pr / nx) . floor () * nx;
                if rem_n <= 3.0 { tiled = true; }
            }
            if !tiled && mean_residual > 1.0 {
                let rem_m = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
                if rem_m <= 3.0 { tiled = true; }
            }
            if !tiled && new_pr > 0.12 * cap && new_pr < 0.55 * cap {
                score += 0.22 * (1.0 - progress * 0.3);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
