        }
        // exact item-to-residual tiling
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let kk = (pr / isz) . round () ;
            if kk >= 1.0 && (pr - kk * isz) . abs () <= 1.5 && kk <= 4.0 {
                score -= 0.2 * (1.0 - t * 0.3) ;
            }
