                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-138 mutation: fresh-bin residual that exactly absorbs the next
        // TWO items with near-zero remainder — deep lookahead tiling
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target2 = 2.0 * nx;
            if new_pr >= target2 && new_pr - target2 <= 1.0 {
                score -= 0.3 * (1.0 - (new_pr - target2)) * (0.6 + 0.4 * progress);
            }
        }
        // gen-138 mutation: fresh-bin residual that absorbs next item plus the
        // current item size (perfect pair closure of this placement)
        if next_item_size > 0 && item_size > 0 && new_pr > 0.0 {
            let target = next_item_size as f64 + item_size as f64;
            if (new_pr - target) . abs () <= 1.0 {
                score -= 0.22 * (1.0 - (new_pr - target) . abs ()) * (0.5 + 0.5 * progress);
            }
        }
