            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-139 mutation: dead-space ratio refinement — sharpen the dead-zone
        // band (2x next item) using a tighter threshold scaled by mean residual,
        // and add a mid-band penalty for residuals just above 2x next item that
        // cannot absorb the mean residual either.
        if next_item_size > 0 && new_pr > 0.0 && mean_residual > 0.5 {
            let nx = next_item_size as f64;
            let dead_zone = (0.05 * cap) . min (mean_residual * 0.6) . max (6.0);
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < dead_zone {
                    score += 0.38 * (1.0 - dead / dead_zone) * (0.4 + 0.6 * progress);
                }
            }
            if new_pr > 2.0 * nx {
                let rem2 = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
                if rem2 > 1.5 && rem2 < mean_residual * 0.35 {
                    score += 0.16 * (1.0 - rem2 / (mean_residual * 0.35)) * (0.5 + 0.5 * progress);
                }
            }
        }
        // gen-139 mutation: waste-rate coupling — when many bins can fit the
        // item, prefer fresh bins whose residual exactly matches the mean
        // residual scale (clean tiling), discouraging heterogeneous leftovers.
        if fitting_bins_count >= 3 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr / mean_residual) . round () * mean_residual - new_pr) . abs ();
            if dev <= 2.0 { score -= 0.18 * (1.0 - dev / 2.0) * (0.6 + 0.4 * progress); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // gen-139 mutation: penalize open-bin fits that strand a sliver the
        // next item cannot use and that sits far from the mean residual scale.
        if mean_residual > 0.5 {
            let miss = (next_item_size - post_residual) as f64;
            if miss > 4.0 && miss <= 12.0 {
                score += 0.12 * (1.0 - (miss - 4.0) / 8.0) * (0.5 + 0.5 * progress);
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fit reward: minimize post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item can fit into post_residual (chained placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving dead space that next item can't use.
            let waste = post_residual as f64 - if next_item_size as f64 > post_residual as f64 { 0.0 } else { 0.0 };
            score += 0.15 * waste;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins can fit the item.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is worse.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the item would leave a large residual elsewhere anyway, new bin is less bad.
        let spread = (post_residual as f64 - mean_residual).abs();
        score -= 0.1 * spread;
    } else {
        // Reward using bins whose residual is close to the item (good matching).
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += 0.2 * diff;
        // Slight penalty for spreading across too many open bins with big residuals.
        if mean_residual > 40.0 {
            score += 0.05 * (mean_residual - 40.0);
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr) + 0.5 * norm_pr * norm_pr;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (0.5 + 1.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 1.5 * (1.0 - slack / cap);
        } else {
            score += 1.0 * (nxt - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (prefer balanced residuals), smoothed by progress
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * (0.5 + progress);

    // Mild penalty for many open bins to discourage sprawl
    score += 0.01 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline with slight decay over time
    if bin_residual == bin_capacity {
        score = 1.2 + 0.8 * (1.0 - progress) + 0.02 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 0.1;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
