        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let rem = new_pr - (new_pr / nx) . floor () * nx;
            if new_pr >= nx && rem >= mean_residual * 0.8 && rem <= mean_residual * 1.2 {
