            if k >= 1.0 && pr - k * nx <= 2.0 && item_size as f64 <= 0.4 * cap {
                score += 0.35;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: quarter/half-capacity leftovers are
    // reusable "sweet spots"; tiny slivers (< 10) are dead space.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let frac = pr / cap;
        if frac < 0.10 {
            score += 8.0; // unusable sliver penalty
        } else if (post_residual % 25 == 0) || (post_residual % 20 == 0) {
            score -= 6.0; // harmonic class: divisible into common item sizes
        } else if frac >= 0.25 && frac <= 0.75 {
            score -= 3.0; // mid-range residual stays usable
        }
    }

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 10.0 * (nx / cap); // leaves room for the known next item
        } else if (post_residual as u32) < 10 {
            score += 4.0; // stranded capacity, next item cannot use it
        }
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // New-bin candidate (brand-new empty bin): default is a mediocre choice.
    // Open a new bin only when the item is large and would leave a useful
    // round residual, or when existing fits are very poor.
    if bin_residual == bin_capacity {
        let base = 40.0;
        let frac = item_size as f64 / cap;
        // Large items (>= 3/4 of capacity) benefit from a fresh bin.
        let bonus = if frac >= 0.75 { -10.0 } else if frac >= 0.5 { 0.0 } else { 8.0 };
        // If many bins are open and mean residual is high, spreading is worse.
        let spread_penalty = (open_bins_count as f64).ln().max(0.0) * 2.0 + (mean_residual / cap) * 5.0;
        score = base + bonus + spread_penalty;
        // Late in the stream, avoid opening new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 6.0;
        }
        // Never open a new bin for a perfect fit elsewhere is handled by
        // comparing scores; give a floor so perfect fits always win.
        if score < 15.0 {
            score = 15.0;
        }
    }

    score
}

