                }
            }
            // gen-140 mutation: dead-space pressure — penalize open-bin fits whose
            // chain residual lands in the "almost tileable but not" zone, where
            // leftover space is likely stranded for the rest of the stream
            if mean_residual > 0.5 && chain_residual > 0.0 {
                let rem_t2 = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_t2 > 5.0 && rem_t2 < mean_residual * 0.45 {
