        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // reject fresh bins with small gap below next item unless near-mean tile
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // pair-packing lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // triple-tiler lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        // late-stream: prefer fresh bins when best open fit would strand >25%
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        // endgame compaction — strong push toward fresh bins when
        // nearly all capacity would be wasted by an open-bin fit
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        // mean-residual tiling lookahead for fresh bins
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        // penalize fresh bins whose leftover is a stranded
        // sliver between the next item and 2x next item (dead zone)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-140 mutation: fresh-bin residual that tiles with BOTH the next
        // item and the mean residual — strong compaction signal, deeper bonus
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let after = new_pr - nx;
            if after > 0.0 {
                let rem_m = after - (after / mean_residual) . floor () * mean_residual;
                if rem_m <= 2.0 {
                    score -= 0.32 * (1.0 - rem_m / 2.0) * (0.5 + 0.5 * progress);
                }
            }
        }
        // gen-140 mutation: when many bins fit the item, only open a fresh bin
        // if its residual is strictly better than the typical open-bin leftover;
        // otherwise discourage fragmentation of the bin pool
        if fitting_bins_count >= 3 && mean_residual > 0.0 && new_pr > 0.0 {
            let excess = (new_pr - mean_residual . max (1.0)) / cap;
            if excess > 0.0 { score += 0.25 * excess . min (1.0) * (0.4 + 0.6 * progress); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;

    // Perfect-fit bonus: exact fill of the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 15.0;
        // Exact 2-step match bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer minimizing final residual waste.
        score += post_residual as f64 * 0.5;
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great
    // 2-step lookahead match (post_residual == next_item_size) or this is a last-chance situation.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Mild penalty for too many open bins relative to stream progress.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize residuals in the "gap band" just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals that tile with the mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // unreachable band beyond 2x mean residual, not tiles of either
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // clean multiple of next item with near-zero remainder
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // gen-140: quad-tiler lookahead — residual fits next item four times
            if chain_residual >= 4.0 * nx {
                let rem4 = chain_residual - 4.0 * nx;
                if rem4 <= 4.0 { score -= 0.3 * (1.0 - rem4 / 4.0) * (0.5 + 0.5 * progress); }
            }
            // gen-140: reward chain residuals that exactly absorb next item + mean residual
            if mean_residual > 0.5 && chain_residual >= nx + mean_residual && chain_residual - (nx + mean_residual) <= 2.0 {
                score -= 0.28 * (1.0 - (chain_residual - nx - mean_residual) / 2.0);
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // near-saturated bin: fill it now rather than strand it
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            // reward bins whose residual matches mean residual scale
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-140: extra pressure to close bins that will strand a tiny gap
            if miss <= 1.0 { score += 0.25 * (1.0 - miss) * (0.5 + 0.5 * progress); }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        // NEW BIN candidate: decide when a fresh bin beats a poor fit.
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                // triple-tiler lookahead
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            // mean-residual tiling with near-zero remainder
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        // penalize fresh bins whose leftover is a stranded sliver
        // between the next item and 2x next item (dead zone)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // endgame compaction — push toward fresh bins when an
        // open-bin fit would strand a large share of capacity
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-140: fresh-bin residual that exactly absorbs next item + mean residual
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // gen-140: quad-tiler lookahead for fresh bins
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 4.0 * nx {
                let rem = new_pr - 4.0 * nx;
                if rem <= 4.0 { nb -= 0.3 * (1.0 - rem / 4.0) * (0.5 + 0.5 * progress); }
            }
        }
        // gen-140: reject fresh bins with a stranded sliver leftover (< smallest plausible item)
        if new_pr > 0.0 && new_pr < 1.0 * (mean_residual.max(1.0)).min(10.0) && progress > 0.5 {
            nb += 0.4 * (1.0 - new_pr / (mean_residual.max(1.0)).min(10.0));
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty scaled down.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize creating residual that is too small to be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly needed.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with residual far below mean (they are "leftovers" to consolidate).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // Many open bins: encourage filling existing ones to close them out.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mild preference for larger residual bins early (spread), tighter bins later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;
    score -= (bin_residual as f64 / bin_capacity as f64) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize residuals in the "gap band" just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals that tile with the mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // gen-139: unreachable band beyond 2x mean residual, not tiles of either
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-139: clean multiple of next item with near-zero remainder
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // gen-140: quad-tiler lookahead — residual fits next item four times
            if chain_residual >= 4.0 * nx {
                let rem4 = chain_residual - 4.0 * nx;
                if rem4 <= 4.0 { score -= 0.2 * (1.0 - rem4 / 4.0) * (0.6 + 0.4 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // near-saturated bin: fill it now rather than strand it
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            // gen-139: reward bins whose residual matches mean residual scale
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-140: mid-stream tighter squeeze on residual just under next item
            if pr > 0.0 && miss > 2.0 && miss <= 5.0 && progress > 0.5 {
                score += 0.12 * (1.0 - (miss - 2.0) / 3.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        // NEW BIN candidate: decide when a fresh bin beats a poor fit.
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                // gen-139: triple-tiler lookahead
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                // gen-140: quad-tiler lookahead for fresh bins
                if new_pr >= 4.0 * nx {
                    let rem = new_pr - 4.0 * nx;
                    if rem <= 4.0 { nb -= 0.18 * (1.0 - rem / 4.0) * (0.6 + 0.4 * progress); }
                }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            // gen-139: mean-residual tiling with near-zero remainder
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        // gen-139: penalize fresh bins whose leftover is a stranded sliver
        // between the next item and 2x next item (dead zone)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-139: endgame compaction — push toward fresh bins when an
        // open-bin fit would strand a large share of capacity
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-140: combine — favor fresh bins whose leftover exactly matches
        // the mean residual scale mid-stream (reusable space coupling)
        if progress > 0.3 && progress < 0.85 && mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem < 0.5 && new_pr >= mean_residual { nb -= 0.12 * (1.0 - progress * 0.4); }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // mutation: penalize chain residuals in the gap band just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // mutation: reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: clean multiple of next item with near-zero remainder
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // mutation: unreachable band beyond 2x mean residual, not tiles of either
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // near-saturated bins (miss 1-2) — fill them now
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // mutation: near-mean residual match — bin tracks population average well
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            // fresh bin residual exactly absorbs next item plus mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            // pair-packing lookahead — fresh residual hosts next item twice
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            // mutation: triple-tiler lookahead
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
            // reject fresh bins whose residual falls just below next item
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // mutation: stranded sliver between next item and 2x next item (dead zone)
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        // mutation: mean-residual tiling lookahead for fresh bins
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        // mutation: endgame compaction — fresh bins when open fit would strand >40%
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // mutation: late-stream fresh-bin preference for large stranded slack
        if progress > 0.6 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.25 {
                nb -= 0.3 * ((slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer low post-residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste matters more.
    let coupling = 1.0 + 1.5 * progress * progress + 0.5 * progress;
    score *= coupling;

    // Reward near-perfect fits with a smooth term.
    let fit_frac = item_size as f64 / cap;
    score -= 12.0 * fit_frac * fit_frac * (1.0 - progress);

    // Penalize large dead space relative to mean residual across bins.
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * (pr / cap);
    }

    // Mild penalty for spreading across many open bins early.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-slightly-high unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * progress * (1.0 - mean_residual / cap);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // gen-141: sharpen sliver penalty for residuals near multiples of mean
            if chain_residual > 0.0 && mean_residual > 1.0 {
                let km = (chain_residual / mean_residual) . floor ();
                if km >= 1.0 {
                    let remm = chain_residual - km * mean_residual;
                    if remm <= 2.0 { score -= 0.28 * (1.0 - remm / 2.0) * (0.5 + 0.5 * progress); }
                }
            }
            // gap band between next item and smallest reusable remainder
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // tile with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // clean multiple of next item with near-zero remainder
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // unreachable band beyond 2x mean residual, not tiles of either
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // reject fresh bins with small gap below next item unless near-mean tile
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // pair-packing lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // triple-tiler lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        // late-stream: prefer fresh bins when best open fit would strand >25%
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        // mutation: endgame compaction — strong push toward fresh bins when
        // nearly all capacity would be wasted by an open-bin fit
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        // gen-135 mutation: mean-residual tiling lookahead for fresh bins —
        // reward residuals that tile cleanly with the mean residual scale
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        // gen-135 mutation: penalize fresh bins whose leftover is a stranded
        // sliver between the next item and 2x next item (dead zone)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-141 mutation: dead-space coupling — penalize fresh bins whose
        // leftover cannot tile with the observed mean residual scale
        if mean_residual > 1.0 && new_pr > 0.0 {
            let km = (new_pr / mean_residual) . floor ();
            if km >= 1.0 {
                let remm = new_pr - km * mean_residual;
                if remm > 3.0 && remm < mean_residual * 0.6 {
                    score += 0.2 * (1.0 - remm / (mean_residual * 0.6)) * (0.5 + 0.5 * progress);
                }
            }
        }
        // gen-141 mutation: endgame exact-fit bias — when near the end of the
        // stream, reward fresh bins whose residual matches the mean residual
        if progress > 0.7 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = (new_pr - mean_residual) . abs ();
            if dev <= 2.0 { score -= 0.3 * (1.0 - dev / 2.0) * (progress - 0.7) / 0.3; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes heavily rewarded
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr <= 10 {
        score -= 300.0;
    } else if pr <= 20 {
        score -= 150.0;
    } else if pr <= 40 {
        score -= 50.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item classes
    // (10, 20, 25, 50) leave re-usable slots.
    let harmonic_bonus = if pr % 50 == 0 {
        120.0
    } else if pr % 25 == 0 {
        80.0
    } else if pr % 20 == 0 {
        60.0
    } else if pr % 10 == 0 {
        40.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residual too small for the smallest item (1)
    // but awkward — penalize tiny non-zero leftovers in mid-stream.
    if pr > 0 && pr < 5 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly-ish, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            let fit_gap = pr as f64 - nxt;
            if fit_gap <= 10.0 {
                score -= 200.0; // next item slots in almost perfectly
            } else {
                score -= 40.0 / (1.0 + fit_gap / 20.0);
            }
        } else {
            // next item cannot fit here: mild penalty proportional to waste
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only prefer when no open bin is a good fit
    if bin_residual == bin_capacity {
        // baseline new-bin score ~ capacity minus a discount that grows
        // with stream progress and crowdedness
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - 30.0 - 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if fitting_bins_count == 1 {
            score += 300.0; // existing last-chance bin should win
        }
    }

    // Prefer filling bins with low mean residual (consolidating)
    score -= 0.3 * (cap - mean_residual);

    // Slight preference for tighter bins overall
    score += 0.2 * (bin_residual as f64 - post_residual as f64).signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // mutation: exact tiling of chain residual with next item
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // mutation: unreachable band beyond 2x mean residual
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                if mean_residual > 0.5 && dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                // triple-tiler lookahead
                if new_pr >= 3.0 * nx {
                    let rem3 = new_pr - 3.0 * nx;
                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // dead zone between nx and 2x nx
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            // gen-141: mean-residual tiling lookahead
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        // gen-141: endgame compaction — push toward fresh bins when open fit strands much capacity
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that no item can use are costly.
    let min_item = 1u32;
    if post_residual < min_item * 10 {
        score += 500.0; // essentially perfect fit, strongly reward below
    }
    // Penalize "unusable" gaps: leftover too small for plausible items (<= 10 or < next_item_size)
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap cannot host the next item: dead space penalty scaled by tightness
        score += 60.0 + 3.0 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can host next item: reward chain placements
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    }

    // Reward tight fits: fraction of bin consumed
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 100.0 * fill * fill;

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is near the mean (balanced packing), penalize outliers
    score += 0.8 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // base cost of opening a new bin, reduced if item is large or few fitting bins
        score += 350.0 - 1.5 * item_size as f64 - 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 20.0; // next item similar size: fresh bin useful
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
