        // residual tiles cleanly with BOTH next item and mean residual scale,
        // and penalize fresh bins that leave a residual smaller than any
        // plausible item (unreachable dead space)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let rem = new_pr - (new_pr / nx) . floor () * nx;
            if rem < 1.0 && new_pr >= 2.0 * nx { score -= 0.2 * (0.5 + 0.5 * progress); }
            if new_pr > 0.0 && new_pr < 0.03 * cap && new_pr < mean_residual {
