    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer tight fits via smooth non-linear polynomial of post_residual
    let mut score = 2.0 * x - 1.6 * x * x + 0.6 * x * x * x;

    // Stream-progress coupling: later in stream, penalize larger residuals more strongly
    let progress_coupling = progress * (x * x) * 1.2;
    score += progress_coupling;

    // Dead-space penalty: residual too small to fit typical future items
    let dead_zone = (0.35 - x).max(0.0) * (0.35 - x).max(0.0) * 3.0;
    score += dead_zone;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 0.5;
    } else if next_item_size > 0 {
        score += 0.3;
    }

    // Mean-residual divergence: penalize bins far from fleet mean
    score += ((mean_residual - post).abs() / cap) * 0.4;

    // Slight preference for reusing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * (1.0 - progress);
    }

    score
}

