            }
            // gen-147 mutation: dead-zone detector — chain residual stranded in the
            // narrow band just below the next item size can never absorb it again
            if chain_residual > 0.0 && chain_residual < nx {
                let gap = nx - chain_residual;
                if gap > 0.0 && gap <= 6.0 && mean_residual > 0.5 && chain_residual < 0.7 * mean_residual {
                    score += 0.32 * (1.0 - gap / 6.0) * (0.5 + 0.5 * progress);
                }
            }
            // gen-147 mutation: reward residuals that tile with BOTH next item and
            // mean residual simultaneously — high reuse probability
            if mean_residual > 1.0 && chain_residual >= nx + mean_residual {
                let rem_b = (chain_residual - nx) - ((chain_residual - nx) / mean_residual) . floor () * mean_residual;
                if rem_b <= 2.0 { score -= 0.3 * (1.0 - rem_b / 2.0) * (0.5 + 0.5 * progress); }
            }
        } else {
