                if rem_m <= 3.0 { score -= 15.0 * (1.0 - rem_m / 3.0) ; }
            }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // dead-space: slivers below plausible item sizes
            if cr > 0.0 && cr < 0.06 * cap {
                score += 25.0 * (1.0 - cr / (0.06 * cap)) ;
            }
            // gap band: residual just below next item is stranded
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 {
                    score += 20.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ;
                }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            // small gap to next item: poor fit, penalize proportionally
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            // near-miss bands: tiny misses are the worst dead space
            let miss = nx - post_residual as f64 ;
            if miss >= 1.0 && miss <= 2.0 { score += 40.0 ; }
            if miss > 3.0 && miss <= 8.0 { score += 18.0 * (1.0 - (miss - 3.0) / 5.0) ; }
            // residual near mean residual is likely reusable later
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 12.0 * (1.0 - dev / 0.05) ; }
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if fitting_bins_count >= 4 { score -= 30.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance: penalize new bins whose residual is unlikely
        // to absorb future items given the mean residual scale
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        // two-item lookahead on fresh bin
        if next_item_size > 0 && new_pr >= 2.0 * next_item_size as f64 {
            let r2 = new_pr - 2.0 * next_item_size as f64 ;
            if r2 <= 4.0 { score -= 45.0 * (1.0 - r2 / 4.0) ; }
        }
        // mean-residual tiling lookahead for fresh bins
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual ;
            if rem <= 1.5 { score -= 30.0 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress) ; }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
            // stranded sliver far below any plausible item
            if new_pr < 0.08 * cap {
                score += 45.0 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress) ;
            }
        }
        // dead zone: fresh residual between next item and 2x next item
        if next_item_size > 0 && new_pr > next_item_size as f64 && new_pr < 2.0 * next_item_size as f64 {
            let dead = 2.0 * next_item_size as f64 - new_pr ;
            if dead < 0.05 * cap {
                score += 30.0 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress) ;
            }
        }
        score -= 8.0 * (1.0 - progress) ;
        // large items pack better into fresh bins early
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // endgame compaction: prefer fresh bins when open-bin fit strands much space
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap ;
            if slack > 0.4 { score -= 40.0 * ((slack - 0.4) / 0.6) . min (1.0) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // multiple-of-next-item tiling bonus
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space penalty: slivers below plausible item sizes
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // gap band between next item and smallest reusable remainder
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // tile with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // clean multiple of next item with near-zero remainder
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // unreachable band beyond 2x mean residual, not tiles of either
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-148: reward open bins whose post-fit residual exactly equals
            // the mean residual scale (perfectly reusable remainder)
            if mean_residual > 1.0 {
                let rem_exact = (chain_residual - mean_residual) . abs ();
                if rem_exact <= 2.0 { score -= 0.2 * (1.0 - rem_exact / 2.0); }
            }
            // gen-148: penalize chain residuals that are dead zones — larger
            // than next item but leaving a sliver under half the next item
            if chain_residual > nx && chain_residual < nx * 1.5 {
                let sliver = chain_residual - nx;
                score += 0.18 * (1.0 - sliver / (nx * 0.5)) * (0.5 + 0.5 * progress);
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-148: if the miss is small relative to mean residual, the bin
            // is one mean-sized item away from fitting — mild penalty relief
            if miss > 2.0 && mean_residual > 0.5 && miss <= mean_residual {
                score -= 0.12 * (1.0 - miss / mean_residual . max (1.0)) * (1.0 - progress * 0.4);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // reject fresh bins with small gap below next item unless near-mean tile
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        // pair-packing lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        // triple-tiler lookahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        // late-stream: prefer fresh bins when best open fit would strand >25%
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        // endgame compaction — strong push toward fresh bins when
        // nearly all capacity would be wasted by an open-bin fit
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        // mean-residual tiling lookahead for fresh bins —
        // reward residuals that tile cleanly with the mean residual scale
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        // penalize fresh bins whose leftover is a stranded
        // sliver between the next item and 2x next item (dead zone)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: fresh-bin residual that equals a clean multiple of
        // the item just placed (self-tiling) — the bin can absorb clones of it
        if item_size > 0 {
            let isz = item_size as f64;
            let k = (new_pr / isz) . round ();
            if k >= 2.0 {
                let rem = (new_pr - k * isz) . abs ();
                if rem <= 1.5 { score -= 0.22 * (1.0 - rem / 1.5) * (0.6 + 0.4 * progress); }
            }
        }
        // gen-148 mutation: when few bins fit and the fresh-bin residual is a
        // near-perfect tile of the mean residual, strongly favor opening it
        if mean_residual > 1.0 && fitting_bins_count >= 2 && fitting_bins_count <= 5 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 1.0 {
                let rem = (new_pr - k * mean_residual) . abs ();
                if rem <= 2.0 { score -= 0.18 * (1.0 - rem / 2.0); }
            }
        }
        // gen-148 mutation: penalize fresh bins whose residual sits in the
        // "orphan band" — too small for the mean residual but not tiny either
        if mean_residual > 2.0 && new_pr > 0.0 && new_pr < mean_residual * 0.7 && new_pr > 0.05 * cap {
            score += 0.2 * (1.0 - new_pr / (mean_residual * 0.7)) * (0.5 + 0.5 * progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 6.0,
            5 => 3.0,
            _ => 0.0,
        };
        // Perfect fits get the strongest reward.
        if pr == 0 {
            score -= 25.0;
        } else {
            score -= class_bonus;
        }
        // Penalize dead space: leftover that is too small for the smallest item (1..=10).
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
        // Integer-division thresholds: leftover big enough for half-capacity
        // chunks is valuable; small-but-usable leftovers are penalized less.
        let half_chunk = pr / (bin_capacity / 2);
        if half_chunk == 0 && pr >= 10 {
            score += 4.0; // leftover < 50 but >= 10: moderately awkward
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 - slack * 0.15;
        } else {
            // next item won't fit here; slightly penalize tight fills that
            // strand the next item.
            score += 2.0;
        }
    }

    // Fraction-of-capacity coupling: prefer filling bins that are already
    // substantially full (low residual fraction), keeping large residuals
    // available for large future items.
    let residual_frac = bin_residual as f64 / cap;
    score += residual_frac * 10.0;

    // Mean residual context: when open bins are generally empty-ish, mildly
    // discourage spreading into many bins.
    if mean_residual > 60.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    // Stream progression: late in the stream, tighten packing (favor exact fits
    // more, tolerate new bins less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.05;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: slightly worse than a decent existing fit.
        score += 5.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / cap) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Moderate gap: mild quadratic penalty scaled by fraction of capacity.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * frac * frac;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0; // dead-ends the bin before the next arrival
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins with residual below mean (tighter bins get priority).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        score = base + 0.8 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // avoid stealing the single last-chance fit
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // pairing potential in a fresh bin
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-148: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-148: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-148: near-miss gap scaled by progress — later in the stream,
            // a small gap below the next item is more costly (less time to fill)
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: subtract reward proportional to how snugly next item fits
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // next item cannot chain here: penalize dead space, worse when close to full
            score += 8.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        }
    }

    // Relative to mean residual: prefer bins more filled than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * progress;
        // still allow new bin if item is huge and would leave tiny post_residual elsewhere
        if item_size >= 80 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Slight preference to fill older/dense bins when many bins open
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap;
    if post_residual == 0 { score -= 8.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 == nx {
            score -= 5.2 ;
        } else if post_residual as f64 > nx {
            let chain_residual = post_residual - next_item_size ;
            let cr = chain_residual as f64 ;
            score -= 1.35 * (1.0 - cr / cap) ;
            if chain_residual <= 10 { score -= 0.9 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 0.25 ; }
            // two-step lookahead: reward residuals that fit the next item twice
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.35 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // multi-step tiling: reward residuals that tile exactly with next item
            let tile_rem = cr % nx . max (1.0);
            if tile_rem < 1.5 { score -= 0.3 * (0.5 + 0.5 * progress) ; }
            let k = (cr / nx . max (1.0)) . floor ();
            if k >= 3.0 {
                let rem3 = cr - k * nx . max (1.0);
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress) ; }
            }
            // penalize large wasted chain space late in the stream
            let wasted = cr / cap ;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress) ; }
            // dead-space control: chain residual well below mean residual scale
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 0.3 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress) ;
            }
            if cr == 0.0 { score -= 0.6 ; }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.55 * progress ;
            // small gap to next item: poor fit, penalize proportionally
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0) ; }
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0) ; }
            // late-stream near-miss gap is more costly
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress ;
            }
        }
        // exact-fill of current residual by current item
        if item_size > 0 {
            let isz = item_size as f64;
            let k = (post_residual as f64 / isz) . round ();
            if k >= 1.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3) ;
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) ;
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        score -= 0.05 * mean_residual / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        // dead-space avoidance: penalize new bins whose residual is unlikely
        // to absorb future items given the mean residual scale
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        // reward opening a new bin when all fitting bins would leave tiny slivers
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 0.6 ; }
            let slack = new_pr / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1) ; }
        }
        // near-perfect post-fit for next item
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0) ; }
        }
        // opening a new bin that cannot fit the next item: penalize
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // exact multiple of next item: zero future dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress) ;
            }
        }
        // residual variance control: fresh bin near mean residual scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25) ; }
        }
        // stranded sliver residual below smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // large residual fresh bin with room for many future items
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor () ;
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) ; }
        }
        // late stream: fresh bins with generous slack for remaining items
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0) ; }
        }
        // two-step lookahead from fresh bin: residual fits next item twice
        if next_item_size > 0 && new_pr >= 2.0 * next_item_size as f64 {
            let rem = new_pr - 2.0 * next_item_size as f64;
            if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3) ;
        }
    }
    score
}

