            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-151 mutation: dead-space compaction gate — when the fresh bin's
        // post-fit residual is an exact multiple of the mean residual scale,
        // strongly favor it (future items tile without stranded slivers)
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr % mean_residual;
            if rem < 0.5 { score -= 0.22 * (0.5 + 0.5 * progress); }
        }
        // gen-151 mutation: late-stream compaction — prefer fresh bins late
        // when they leave a residual that can absorb two more next-sized items
        if progress > 0.6 && next_item_size > 0 && new_pr >= 2.0 * next_item_size as f64 {
            score -= 0.25 * (progress - 0.6) / 0.4;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
