        // with the next TWO items (nx then mean_residual), it promises zero
        // dead space over a longer horizon; reward more as the stream matures
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx + mean_residual {
                let after = new_pr - nx - mean_residual;
                if after == 0.0 { score -= 0.28 * (0.4 + 0.6 * progress); }
                else if after <= 2.0 { score -= 0.16 * (1.0 - after / 2.0); }
            }
        }
