        // and the fresh residual is large, opening a new bin preserves open
        // capacity for future mid-size items; slightly strengthen the gate
        if progress > 0.65 && fitting_bins_count >= 3 && new_pr > 0.55 * cap {
            score -= 0.18 * ((new_pr - 0.55 * cap) / (0.45 * cap)) * ((progress - 0.65) / 0.35);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
