                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-152: fresh-bin residual near next-item multiples — a fresh bin
        // whose residual tiles cleanly with the next item avoids future
        // dead space in a brand-new bin
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let rem = (new_pr % nx . max (1.0)) . min (nx . max (1.0) - new_pr % nx . max (1.0));
                if rem <= 2.0 { score -= 0.22 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        // gen-152: late-stream consolidation — prefer fresh bins late only
        // when they leave residuals close to the observed mean residual
        if progress > 0.75 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev > 0.5 { score += 0.25 * ((dev - 0.5) / 0.5) . min (1.0) * (progress - 0.75) / 0.25; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear penalty on dead space: small post_residuals are risky
    let pr = post_residual as f64;
    let dead = (1.0 - pr / bin_capacity as f64).powi(3);
    score += 12.0 * dead * (0.4 + progress);

    // Exact-fit reward (smooth via tightness factor)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: prefer leaving room for next item
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 {
            score -= 4.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        } else {
            score += 0.05 * (-gap) as f64;
        }
    }

    // Mild preference for fuller bins relative to mean residual
    score -= 0.3 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Late-stream consolidation: favor existing bins over opening new ones
    score += progress * 6.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

