        if fitting_bins_count >= 2 && mean_residual > 0.5 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let open_worst = (item_size as f64 % 1.0) * 0.0 + (nx - item_size as f64 % nx . max (1.0));
            let _ = open_worst;
            if new_pr >= nx && (new_pr - nx) >= mean_residual * 0.6 {
                score -= 0.14 * (1.0 - progress * 0.5);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize "dead space": post_residual too small for any item (min size 1,
    // but practically items >= 10 in classic streams; use graded waste penalty).
    let waste_threshold = 12u32;
    if post_residual < waste_threshold {
        score += 25.0 * (waste_threshold - post_residual) as f64;
    }

    // Harmonic class logic: classify post_residual by integer division into
    // capacity fractions. Residuals in the lowest class (near full) are great;
    // residuals in awkward middle classes (leaving a sliver) are penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual > 0 {
        if post_residual <= eighth {
            score -= 20.0; // near-perfect fill class
        } else if post_residual > quarter && post_residual < item_size.min(bin_capacity / 2) {
            score += 12.0; // awkward middle class: hard to reuse
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0; // perfect chain fit
        } else if gap <= eighth {
            score -= 15.0; // near-perfect chain fit
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < waste_threshold {
        score += 10.0; // next item can't use this sliver anyway
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere. Make the empty-bin baseline moderate.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; reduce it when bins are scarce relative
        // to stream progress or when mean residual is high (fragmentation).
        score = 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress); // early on, new bins are cheap-ish
        if mean_residual > (bin_capacity as f64) * 0.5 {
            score -= 8.0; // existing bins are fragmented; prefer fresh capacity
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 4 {
            score += 5.0; // small next item pairs well with existing bins instead
        }
    }

    // Mild penalty for spreading across many open bins when this bin is loose.
    if open_bins_count > 4 && post_residual > bin_capacity / 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
