                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
                // gen-153: exact multiple of next item — zero future dead space
                if new_pr - (new_pr / nx).floor() * nx == 0.0 {
