        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when open bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, prefer filling existing bins even more strongly.
        let new_bin_penalty = 40.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // If the next item is large and this fresh bin could take it comfortably,
        // slightly soften the penalty (strategic reservation).
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0;
        }
        return score;
    }

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward small post residuals nonlinearly.
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * 20.0;
        // Dead-space penalty: residuals too small for typical items are wasted.
        if pr < 10 {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving moderate gaps.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // encouraging consolidation into fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Mild bonus for using bins early in the stream (keep flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score -= 3.0;
    }

    score
}

