        // risk), favor the fresh bin whose residual lands near that scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev_fresh < 0.25 { score -= 20.0 * (1.0 - dev_fresh / 0.25) ; }
        }
