        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let kf = (new_pr / nx) . floor () ;
            if kf >= 1.0 && new_pr - kf * nx == 0.0 {
                score -= 30.0 * (0.5 + 0.5 * progress) ;
            }
        }
        // gen-154: stranded sliver fresh residual below smallest plausible item
