        // item unplaceable (stranded residual), a fresh bin whose residual
        // can absorb the next item avoids compounding dead space
        if next_item_size > 0 && fitting_bins_count >= 2 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let best_open = if pr > 0.0 { pr } else { 0.0 };
