                if r2 <= 15.0 { score -= 35.0 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 20.0 * (1.0 - r3 / 8.0); }
                }
            }
            // gen-156: multiple-of-next-item alignment reward
            let kf = (cr / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
