        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-157: multi-fill fresh-bin lookahead — reward fresh bins whose
        // residual can absorb the next item plus one mean-scale item with
        // near-zero remainder, i.e. a bin that will close almost perfectly
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target {
                let r = new_pr - target;
                if r <= 4.0 {
                    score -= 0.32 * (1.0 - r / 4.0) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-157: sliver guard refinement — fresh-bin residuals just below
        // the next item strand space permanently; penalize the near-miss band
        // proportionally to how close it is, weighted by remaining stream
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let gap = next_item_size as f64 - new_pr;
            if gap <= 4.0 {
                score += 0.28 * (1.0 - gap / 4.0) * (0.3 + 0.7 * progress);
            }
        }
        // gen-157: dense-stream fresh-bin economy — early in the stream with
        // many open bins, avoid opening fresh bins whose residual exceeds
        // twice the mean scale (they will sit half-empty for a long time)
        if progress < 0.35 && open_bins_count >= 5 && mean_residual > 0.5 && new_pr > 2.0 * mean_residual {
            score += 0.18 * ((new_pr / mean_residual - 2.0) . min (2.0)) * (1.0 - progress / 0.35);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
