            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-158 combine: dead-space pressure on tiny strandable residuals
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-158: chain residual that still fits the mean-residual scale
            // keeps the bin reusable — reward near-exact mean tiling
