            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-158: two-step exact fill — a fresh bin residual that exactly
        // accommodates two copies of the next item leaves zero dead space
        // after two placements; reward scaled by remaining stream length
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr == 2.0 * nx {
                score -= 0.45 * (0.4 + 0.6 * progress);
            } else if new_pr > 2.0 * nx && new_pr - 2.0 * nx <= 1.0 {
                score -= 0.2 * (1.0 - (new_pr - 2.0 * nx)) * (0.4 + 0.6 * progress);
            }
        }
        // gen-158: when the fresh residual is a stranded sliver that no
        // plausible item can use, but an open bin could take the item
        // exactly, penalize the fresh-bin route harder
        if new_pr > 0.0 && next_item_size > 0 && new_pr < next_item_size as f64 {
            let nx = next_item_size as f64;
            if nx - new_pr <= 4.0 {
                score += 0.3 * (1.0 - (nx - new_pr) / 4.0) * (0.6 + 0.4 * progress);
            }
        }
        // gen-158: residual-variance control — prefer fresh bins whose
        // residual is an exact multiple of the mean residual scale so future
        // average items tile it with no dead space
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem == 0.0 && new_pr >= 2.0 * mean_residual {
                score -= 0.18 * (0.5 + 0.5 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
