            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // gen-159: multi-tile lookahead — reward chain residuals that
            // accommodate 3+ copies of the next item with tiny remainder
            let kf = (cr / nx . max (1.0)) . floor () ;
            if kf >= 3.0 {
                let rem3 = cr - kf * nx ;
                if rem3 <= 4.0 { score -= 35.0 * (1.0 - rem3 / 4.0) * (0.5 + 0.5 * progress) ; }
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // gen-159: mean-scale tiling — chain residual that tiles with the
            // mean residual leaves predictable fillable space
            if mean_residual > 1.0 && cr >= mean_residual {
                let rem_m = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem_m <= 3.0 { score -= 20.0 * (1.0 - rem_m / 3.0) * (0.4 + 0.6 * progress) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            // gen-159: residual near mean scale is likely to be filled by the
            // observed item distribution — reward such fits
            if mean_residual > 1.0 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.1 { score -= 25.0 * (1.0 - dev / 0.1) ; }
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
            // gen-159: k-fold exact tiling of fresh residual for k >= 4
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 4.0 {
                let remk = new_pr - k * nx ;
                if remk <= 2.0 { score -= 45.0 * (1.0 - remk / 2.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // gen-159: fresh residual that tiles with the mean residual scale
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 40.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // gen-159: when many open bins remain, discourage opening yet another
        // bin unless the fresh residual is near the mean scale
        if open_bins_count >= 5 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev > 0.5 { score += 30.0 * ((dev - 0.5) / 0.5) . min (1.0) * (1.0 - progress) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of capacity it falls in.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4

    // Penalize dead space in higher harmonic classes non-linearly.
    score += match class {
        0 => -6.0,                    // near-perfect fit: strongly reward
        1 => 0.0,
        2 => 2.0,
        3 => 5.0,
        _ => 8.0,                     // almost untouched bin used: wasteful
    };

    // Exact fit (or tiny residue) is ideal.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
            // Harmonic match: next item's class equals post-residual class -> great pairing
            let next_class = next_item_size / quarter;
            if next_class == class {
                score -= 3.0;
            }
        } else {
            // post residual too small for next item: dead space unless item is last
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 3.0 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Early in stream: be conservative about opening new bins; late: allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current bins are fragmented or late stream.
        score = bin_capacity as f64 * 0.5
            - 4.0 * progress
            - if open_bins_count == 0 { 20.0 } else { 0.0 }
            + if mean_residual > bin_capacity as f64 * 0.4 { 6.0 } else { 0.0 };
    }

    // Modulo tie-breaker on post_residual to break ties toward smoother residues.
    score += (post_residual % 7) as f64 * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
