        }
        // dead-space-aware fresh-bin gate: fresh residual an exact multiple of
        // the next item leaves zero future dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // residual variance control: fresh residual near mean scale reduces
        // dead-space risk when open-bin fits are far off
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // cap total dead space: penalize stranded slivers below item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // exact-fill fresh bin: residual equal to next item guarantees a
        // perfect follow-up fill
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // late-stream consolidation: prefer fresh bin for large items over
        // fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-159: pair-fit lookahead — fresh residual that exactly fits the
        // next item plus the mean residual leaves a tight future slot
        if next_item_size > 0 && mean_residual > 1.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if (new_pr - target) . abs () <= 1.0 {
                score -= 0.2 * (0.5 + 0.5 * progress);
            }
        }
        // gen-159: two-item lookahead against open bins — when the next item
        // is large relative to open residuals, opening fresh is safer
        if next_item_size > 0 && fitting_bins_count >= 2 && progress > 0.5 {
            let nx = next_item_size as f64;
            if nx > pr && nx - pr <= 0.15 * cap && new_pr >= nx {
                score -= 0.15 * (1.0 - (nx - pr) / (0.15 * cap));
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals next item size -> ideal 2-step chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 25.0 - 1.5 * slack;
        } else {
            score += 0.3 * slack; // leftover beyond next item is potential dead space
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; the residual is likely stranded.
        score += 8.0;
    }

    // Reward bins whose residual is below mean (tight bins get filled first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin early in the stream unless nothing fits well.
    if bin_residual == bin_capacity {
        let good_chain = next_item_size > 0 && post_residual == next_item_size;
        if !good_chain {
            score += 35.0;
        }
        // Late in the stream, a fresh bin is less costly.
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Small absolute residual is valuable (tight packing).
    if post_residual > 0 && post_residual <= 10 {
        score -= 10.0;
    }

    score
}

