                score += 0.14 * ((chain_residual - 8.0) / 6.0) * (1.0 - ((chain_residual - 8.0) / 6.0)) * (0.5 + 0.5 * progress);
            }
            // gen-160: two-step lookahead — if the chain residual can absorb
            // the next item twice with a tiny leftover, this bin is a strong
            // multi-fill candidate; reward scaled by remaining stream
            if chain_residual >= 2.0 * nx {
