            }
            // gen-160: stranded-residual guard — a residual that misses the
            // next item by more than half its size but sits far below the
            // mean item scale is likely dead space; penalize late in stream
            if miss > 6.0 && pr > 0.0 && mean_residual > 1.0 && pr < mean_residual * 0.6 {
                score += 0.2 * (1.0 - pr / (mean_residual * 0.6)) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
