pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual by capacity/4 classes
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1); // 0..4
    match class {
        0 => score -= 40.0, // near-perfect fit: strongly reward
        1 => score -= 15.0, // residual 0..25: still good
        2 => score += 5.0,  // 25..50: mediocre dead space
        3 => score += 20.0, // 50..75: wasteful
        _ => score += 30.0, // barely used bin
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: post_residual too small for any plausible item (1..100 unknown, min 1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post residual exactly / closely
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item won't fit here; this bin becomes dead
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral-ish baseline, prefer new bin only when
    // open bins are crowded (mean residual low) and this placement is bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 - mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Mild penalty per open bin to encourage filling existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
