                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-148: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-148: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-155: dead-space pressure — chain residuals slightly above a
            // small-item scale strand space; penalize when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-160: stranded-sliver pressure — a chain residual below the
            // mean item scale is likely to never be filled; penalize in
            // proportion to how stranded it is, more so late in the stream
            if chain_residual > 0.0 && mean_residual > 1.0 && chain_residual < mean_residual * 0.5 {
                let stranded = 1.0 - chain_residual / (mean_residual * 0.5);
                score += 0.18 * stranded * stranded * (0.5 + 0.5 * progress);
            }
            // gen-160: dead-space budget — large chain residuals waste space
            // that could serve later mid-size items; scale penalty by the
            // number of competing fits
            if chain_residual > 0.35 * cap && fitting_bins_count >= 3 {
                score += 0.2 * ((chain_residual / cap - 0.35) / 0.65) . min (1.0);
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-148: near-miss gap scaled by progress — later in the stream,
            // a small gap below the next item is more costly (less time to fill)
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-160: fresh-bin residual tiling with the mean scale — a fresh
        // bin whose post-residual holds a near-integer count of mean-sized
        // items promises high future fill; reward mildly, stronger early
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . floor ();
            if k >= 1.0 {
                let rem = new_pr - k * mean_residual;
                if rem < 0.05 * mean_residual {
                    score -= 0.16 * (1.0 - rem / (0.05 * mean_residual)) * (1.0 - progress * 0.5);
                }
            }
        }
        // gen-160: fresh-bin vs. open-bin residual comparison — when the
        // fresh bin's residual is a clean multiple of the next item while
        // every open fit would strand more than a quarter of the next item's
        // worth of dead space, prefer the fresh bin
        if fitting_bins_count >= 2 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 && new_pr - k * nx <= 1.0 && progress > 0.5 {
                score -= 0.2 * (0.5 + 0.5 * progress);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
        // gen-160: stranded open-bin residual — an open bin whose residual is
        // far below the next item and below the mean item scale will likely
        // never fill; penalize proportionally, stronger when other bins can
        // take this item instead
        if mean_residual > 1.0 {
            let stranded = 1.0 - pr / mean_residual . max (1.0);
            if stranded > 0.0 {
                let comp = ((fitting_bins_count as f64 - 1.0) / 3.0) . min (1.0);
                score += 0.22 * stranded * (0.4 + 0.6 * comp) * (0.5 + 0.5 * progress);
            }
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead: tile chain residual with repeated next items
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-161 mutation: pair-tiling lookahead — fresh residual that exactly
        // accommodates next item plus a second follow-up item of mean scale
        // leaves zero cumulative dead space over a two-step horizon
        if next_item_size > 0 && new_pr > 0.0 && mean_residual > 1.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if (new_pr - target) . abs () <= 1.0 {
                score -= 0.32 * (0.6 + 0.4 * progress);
            }
            // dead-space pressure on open fits: when the best open fit would
            // strand more than a quarter of the mean residual, tilt toward
            // the fresh bin whose residual lands near a mean-scale tile
            if fitting_bins_count >= 2 {
                let open_strand = (pr - nx) . max (0.0);
                if open_strand > mean_residual * 1.25 && new_pr >= nx {
                    score -= 0.15 * ((open_strand / mean_residual) - 1.25) . min (1.5);
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (low post_residual relative to item)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: penalize opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late stream: prefer consolidation into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // multi-step tiling: residual that fits two more next-items nearly exactly
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 35.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 20.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            // multiple-of-next-item tiling reward
            let k = (post_residual as f64 / nx) . round () ;
            let mult_err = (post_residual as f64 - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 30.0 * (1.0 - mult_err / 2.0) ; }
            // mean-residual tiling: residual tiles with typical item scale
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem <= 4.0 { score -= 18.0 * (1.0 - rem / 4.0) ; }
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // small sliver residuals below plausible item scale are dead space
            if cr > 0.0 && cr < 0.06 * cap {
                score += 35.0 * (1.0 - cr / (0.06 * cap)) ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            if miss >= 1.0 && miss <= 2.0 { score += 25.0 * (1.0 - (miss - 1.0)) ; }
            // residual near mean scale is likely reusable later
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 10.0 * (1.0 - dev / 0.05) ; }
                if dev > 0.6 { score += 12.0 * ((dev - 0.6) / 0.6) . min (1.0) ; }
            }
        }
        // item-sized exact fill of the post residual
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 {
                score -= 20.0 * (1.0 - progress * 0.3) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
            // two- and three-step exact tiling of the fresh residual
            if r >= next_item_size as f64 {
                let r2 = r - next_item_size as f64 ;
                if r2 <= 4.0 { score -= 60.0 * (1.0 - r2 / 4.0) ; }
                if r2 >= next_item_size as f64 {
                    let r3 = r2 - next_item_size as f64 ;
                    if r3 <= 3.0 { score -= 40.0 * (1.0 - r3 / 3.0) * (0.5 + 0.5 * progress) ; }
                }
            }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // residual variance control: fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        // mean-residual multiple tiling of the fresh residual
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 22.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // late-stream with large open slack: fresh bin avoids fragmenting
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.4 { score -= 35.0 * ((slack - 0.4) / 0.6) . min (1.0) ; }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual that is a near-miss just above 2x next item strands space
        if next_item_size > 0 && new_pr > next_item_size as f64 && new_pr < 2.0 * next_item_size as f64 {
            let dead = 2.0 * next_item_size as f64 - new_pr ;
            if dead < 0.05 * cap {
                score += 30.0 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress) ;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item can also fit here: bonus scaled by tightness
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item cannot follow into residual: penalize leftover dead space
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Reward tight fits now (small post_residual relative to capacity)
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 + 30.0 - 40.0 * congestion - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Mild preference to spread load when many bins open
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            // multi-step tiling: residual that tiles over two or three next items
            if cr >= 2.0 * nx {
                let rem2 = cr - 2.0 * nx ;
                if rem2 <= 4.0 { score -= 55.0 * (1.0 - rem2 / 4.0) ; }
                if cr >= 3.0 * nx {
                    let rem3 = cr - 3.0 * nx ;
                    if rem3 <= 3.0 { score -= 35.0 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress) ; }
                }
            }
            // tiling against the mean residual scale as a second lookahead target
            if mean_residual > 1.0 && cr >= mean_residual {
                let rem_m = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem_m <= 2.0 { score -= 30.0 * (1.0 - rem_m / 2.0) * (0.4 + 0.6 * progress) ; }
            }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // near-mean residuals keep future fill options alive
            if mean_residual > 0.5 && cr > 0.0 {
                let dev = ((cr - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.1 { score -= 25.0 * (1.0 - dev / 0.1) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            // tiny near-miss: residual within 2 of the next item is one item away
            // from a perfect fill — strong reward, especially late in the stream
            if miss >= 1.0 && miss <= 2.0 {
                score += 45.0 * (1.0 - (miss - 1.0)) * (0.5 + 0.5 * progress) ;
            }
            // residual close to the mean scale blends with future items
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 20.0 * (1.0 - dev / 0.05) ; }
            }
        }
        // exact-fill lookahead on the current item: residual that the just-placed
        // item tiles perfectly is a zero-waste placement
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64 ;
            let pr = post_residual as f64 ;
            let k = (pr / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (pr - k * isz) . abs () <= 1.5 {
                score -= 35.0 * (1.0 - progress * 0.3) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // fresh residual that tiles exactly with the next item leaves zero dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let k = (new_pr / nx) . floor () ;
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 45.0 * (0.5 + 0.5 * progress) ;
            }
        }
        // fresh residual tiling with the mean scale: predictable future fills
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual ;
            if rem <= 1.5 { score -= 35.0 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress) ; }
        }
        // late-stream fresh bin whose residual comfortably holds the next item
        if progress > 0.75 && next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r <= 0.12 * cap { score -= 40.0 * (1.0 - r / (0.12 * cap)) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into this bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize large dead space that nothing reasonable can use.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * dead * dead * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual,
    // penalize if the next item would not fit (wasting capacity for it).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_tight = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * pair_tight;
        } else {
            // Next item won't fit here anyway; slight penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(50.0);
        }
    } else {
        // Last item: prefer perfect closure.
        score -= 20.0 * fill;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for a poor-fit item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: empty bin should only win when current bin
    // would leave bad dead space relative to the next item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // and mean residual is high (existing bins are fragmented).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut open_cost = 18.0 + 10.0 * (1.0 - progress);
        if fragmentation > 0.5 {
            open_cost -= 8.0 * (fragmentation - 0.5);
        }
        if next_item_size > 0 && next_item_size <= item_size {
            // A fresh bin can hold both current and next item comfortably.
            open_cost -= 12.0;
        }
        score += open_cost;
    }

    // Mild penalty for spreading across too many bins when residuals are large.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 {
                score -= 0.9 * (1.0 - chain_residual / 10.0);
            }
            if chain_residual >= 20.0 && chain_residual <= 60.0 {
                score -= 0.25;
            }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 {
                    score -= 0.45 * (1.0 - r2 / 15.0);
                }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 {
                        score -= 0.25 * (1.0 - r3 / 8.0);
                    }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 {
                score += 0.4 * wasted * (0.4 + 0.6 * progress);
            }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 {
                score -= 0.35 * (1.0 - mult_err / 2.0);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 {
                    score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress);
                }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 {
                    score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress);
                }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 {
                    score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 {
                    score -= 0.18 * (1.0 - rem / 4.0);
                }
            }
            // gen-161: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 {
                score -= 0.6;
            }
            // gen-161: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 {
                score -= 0.2 * (0.5 + 0.5 * progress);
            }
            // gen-161: dead-space pressure — small stranded chain residuals
            // penalized more when few bins can host the item
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let miss = nx - pr;
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            if miss <= 3.0 {
                score += 1.0 * (1.0 - miss / 3.0);
            } else if miss <= 8.0 {
                score += 0.18 * (1.0 - (miss - 3.0) / 5.0);
            }
            let gap = miss / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if miss >= 1.0 && miss <= 2.0 {
                score += 0.35 * (1.0 - (miss - 1.0));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 {
                    score += 0.12 * ((dev - 0.6) / 0.6).min(1.0);
                } else if dev <= 0.05 {
                    score -= 0.1 * (1.0 - dev / 0.05);
                }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            // gen-161: near-miss gap scaled by progress — late near-misses
            // are costlier since there is less time to fill the gap
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate: decide when a fresh bin beats a poor fit.
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 {
                    nb -= 0.5;
                } else if r <= 5.0 {
                    nb -= 0.55 * (1.0 - r / 5.0);
                } else if r <= 2.0 {
                    nb -= 0.25 * (1.0 - r / 2.0);
                }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem2 = new_pr - 2.0 * nx;
                    if rem2 <= 4.0 { nb -= 0.35 * (1.0 - rem2 / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem3 = new_pr - 3.0 * nx;
                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
                // gen-161: exact-multiple fresh bin — zero future dead space
                if k >= 1.0 && new_pr - k * nx == 0.0 {
                    nb -= 0.3 * (0.5 + 0.5 * progress);
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
            if mean_residual > 1.0 && new_pr > 0.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5); }
            // gen-161: variance control — prefer fresh bins whose residual
            // lands near the stream's mean residual scale
            if fitting_bins_count >= 2 && mean_residual > 1.0 && dev < 0.25 {
                nb -= 0.2 * (1.0 - dev / 0.25);
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.25 {
                nb -= 0.3 * ((slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-161: late-stream consolidation — for large items late in the
        // stream, a fresh bin beats fragmenting an open residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-161: stranded sliver gate for fresh bins
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (waste minimization)
    let mut score = pr;

    // Non-linear polynomial coupling: dead-space penalty grows super-linearly
    // for small residuals, since tiny residuals are hard to fill.
    let prn = pr / cap; // normalized post residual
    score += 40.0 * (1.0 - prn) * (1.0 - prn) * prn;

    // Stream progress coupling: early in the stream, prefer keeping residuals
    // flexible (large post_residual); late in the stream, allow tight packing.
    let tight_bias = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 25.0 * tight_bias * (item_size as f64 / cap);

    // Lookahead: reward if next item fits into the resulting residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // residual too small for next item: penalize proportionally
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-to-slightly-high baseline so it is
    // chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * progress;
        // If no open bin could fit at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward smaller values when the mean is already low (consolidation).
    let dev = pr - mean_residual;
    score += 0.15 * dev * (1.0 - prn);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap ;
    if post_residual == 0 { score -= 6.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size as f64 {
            score -= 4.0 ;
        } else if post_residual as f64 > nx {
            let chain_residual = post_residual as f64 - nx ;
            score -= 1.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10.0 { score -= 0.7 ; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.2 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 0.35 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.3 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            let wasted = cr / cap ;
            if wasted > 0.05 { score += 0.45 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 0.2 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 0.3 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // multi-step tiling: chain residual fits next item twice nearly exactly
            if cr >= 2.0 * nx {
                let rem2 = cr - 2.0 * nx ;
                if rem2 <= 4.0 { score -= 0.3 * (1.0 - rem2 / 4.0) ; }
            }
            // near-multiple of next item leaves minimal dead space
            let k = (cr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0) ;
                if rem <= 2.0 { score -= 0.25 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan + 0.5 * progress ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 1.5 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 0.2 * (1.0 - miss / 6.0) * progress ;
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.3 * (1.0 - (miss - 1.0)) ; }
            // residual close to mean scale is more likely to be filled later
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05) ; }
            }
        }
        // exact-fill lookahead: item placed so residual matches next item exactly
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 {
                score -= 0.2 * (1.0 - progress * 0.3) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64 ;
        score -= 0.45 * item_size as f64 / cap ;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if fitting_bins_count >= 4 { score -= 0.4 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 0.4 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 0.5 ; }
            else if r <= 5.0 { score -= 0.45 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 0.2 * (1.0 - dev / 0.25) ; }
        }
        // fresh residual exact multiple of next item: zero dead space ahead
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let k = (new_pr / nx) . floor () ;
            if k >= 1.0 && new_pr - k * nx == 0.0 { score -= 0.3 * (0.5 + 0.5 * progress) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.25 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // fresh residual that can absorb the next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let target = nx + mean_residual ;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.25 * (1.0 - (new_pr - target) / 2.0) ;
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.5 * (progress - 0.85) / 0.15 ; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.8 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (10,20,25,50) are valuable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill — best possible outcome
    } else if pr % 50 == 0 {
        -35.0
    } else if pr % 25 == 0 {
        -22.0
    } else if pr % 20 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -12.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: leftover below the smallest plausible item is pure waste.
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr < 20 {
        score += 10.0 * (1.0 - pr as f64 / 20.0);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 12.0;
        } else {
            // next item won't fit here; leftover is likely dead
            score += (pr as f64) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should win only when no open bin
    // offers a decent fit. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.25 * (open_bins_count as f64);
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
    }

    // Prefer filling nearly-full bins (tight fits) as stream progresses.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 20.0 * tightness * (step_index as f64 / (total_items.max(1) as f64));

    // Prefer bins whose residual is already below mean (consolidate fullness).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Integer-division threshold: classify residual into fifths of capacity,
    // reward lower fifths (less waste).
    let fifth = pr / 20;
    score -= match fifth {
        0 => 15.0,
        1 => 8.0,
        2 => 3.0,
        3 => 0.0,
        4 => -4.0,
        _ => -6.0,
    };

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-162: mid-chain dead-space guard — residuals in the awkward
            // band just above the next item size strand space that only very
            // small future items can reclaim; penalize when open bins are few
            if chain_residual > nx && chain_residual < nx + 5.0 && open_bins_count <= 4 {
                score += 0.14 * (1.0 - (chain_residual - nx) / 5.0) * (0.5 + 0.5 * progress);
            }
            // gen-162: long-stream consolidation — late in the stream, prefer
            // leaving residuals that still tile with the item after next
            if chain_residual >= 2.0 * nx {
                let r4 = chain_residual - 2.0 * nx;
                if r4 <= 2.0 { score -= 0.2 * (1.0 - r4 / 2.0) * progress; }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-162: near-miss with large pr — when the bin is already half
            // full and the next item barely misses, the stranded residual is
            // proportionally smaller; soften the penalty slightly
            if miss > 0.0 && miss <= 4.0 && pr > 0.5 * cap {
                score -= 0.1 * (1.0 - miss / 4.0) * (0.6 + 0.4 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
