                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 {
                    score -= 0.18 * (1.0 - rem / 4.0);
                }
            }
            // exact-fill lookahead: chain residual exactly zero leaves no dead space
            if chain_residual == 0.0 {
                score -= 0.6;
            }
            // perfect tiling with next item: zero future dead space
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 {
                score -= 0.2 * (0.5 + 0.5 * progress);
            }
            // dead-space pressure: small stranded chain residuals when bins are scarce
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let miss = nx - pr;
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            if miss <= 3.0 {
                score += 1.0 * (1.0 - miss / 3.0);
            } else if miss <= 8.0 {
                score += 0.18 * (1.0 - (miss - 3.0) / 5.0);
            }
            let gap = miss / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if miss >= 1.0 && miss <= 2.0 {
                score += 0.35 * (1.0 - (miss - 1.0));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 {
                    score += 0.12 * ((dev - 0.6) / 0.6).min(1.0);
                } else if dev <= 0.05 {
                    score -= 0.1 * (1.0 - dev / 0.05);
                }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            // near-miss scaled by progress: late small gaps are costlier
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);

    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 {
                    nb -= 0.5;
                } else if r <= 5.0 {
                    nb -= 0.55 * (1.0 - r / 5.0);
                } else if r <= 2.0 + 5.0 {
                    // near-exact follow-up fill
                    nb -= 0.1 * (1.0 - (r - 5.0) / 2.0);
                }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem2 = new_pr - 2.0 * nx;
                    if rem2 <= 4.0 { nb -= 0.35 * (1.0 - rem2 / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem3 = new_pr - 3.0 * nx;
                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
            if mean_residual > 1.0 && new_pr > 0.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5); }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.25 {
                nb -= 0.3 * ((slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        // fresh-bin residual that exactly tiles with the next item: zero dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx).floor();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                nb -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // variance control: fresh residual near the mean residual scale is safer
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // sliver gate: fresh bin residual below smallest plausible item is wasted
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // late-stream: large items that open bins cannot hold tightly go fresh
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            // partial match: reward proportionally, penalize leftover dead space after next
            let leftover = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.25 * leftover;
        } else {
            // next item can't fit here; post_residual likely becomes dead space
            score += 0.15 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more precious;
    // wasting them is costly, using them well is rewarded.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.10 * dev; // post_residual below mean: penalize slightly (tight bin)
    } else {
        score += 0.05 * dev; // post_residual above mean: mild reward for using loose bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a great fit.
    if bin_residual == bin_capacity {
        score += 12.0; // discourage opening new bins by default
        // allow new bin when lookahead shows no good match anywhere (post_residual large)
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() > 20 {
            score -= 8.0;
        }
    }

    // Late in stream: consolidate harder, avoid scattering residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize chain residuals in the gap band just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // gen-164: exact-fill lookahead — a chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-164: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-164: tiling remainder within 1 unit of next item
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // gen-164: dead-space control vs mean residual scale
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-164: dead-space pressure — small chain residuals strand space
            // when few bins remain open to absorb them
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // near-saturated bins (miss 1-2) — fill them now
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // gen-164: near-miss gap scaled by progress — later in the stream,
            // a small gap below the next item is more costly
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                // gen-164: exact-fill fresh bin — residual exactly equals the
                // next item guarantees a perfect follow-up fill
                if r == 0.0 { nb -= 0.5; }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            // fresh bin residual exactly absorbs next item plus mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            // pair-packing lookahead — fresh residual hosts next item twice
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            // triple-packing lookahead
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
            // reject fresh bins whose residual falls just below next item
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // gen-164: dead-space-aware fresh-bin gate — exact multiple of
            // next item means zero future dead space in a brand-new bin
            let kx = (new_pr / nx).floor();
            if kx >= 1.0 && new_pr - kx * nx == 0.0 {
                nb -= 0.3 * (0.5 + 0.5 * progress);
            }
            // gen-164: dead space between one and two next items
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            let rem_m = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem_m <= 1.5 { nb -= 0.25 * (1.0 - rem_m / 1.5) * (0.5 + 0.5 * progress); }
        }
        // gen-164: residual variance control — favor fresh bins whose
        // residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-164: cap total dead space — penalize stranded slivers
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        // gen-164: pair-left control — fresh bin that leaves a residual just
        // below half the mean residual risks dead space
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // gen-164: late-stream fresh-bin gate — avoid opening a bin with lots
        // of slack when open bins could host it
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                nb -= 0.3 * ((best_open_slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-164: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= 4.0 * nx {
                let rem4 = chain_residual - 4.0 * nx;
                if rem4 <= 4.0 { score -= 0.2 * (1.0 - rem4 / 4.0) * (0.6 + 0.4 * progress); }
            }
            // mutation gen-165: exact-fill lookahead — zero leftover after the
            // next item is a guaranteed perfect fill
            if chain_residual == 0.0 { score -= 0.6; }
            // mutation gen-165: exact tiling of chain residual with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // mutation gen-165: dead-space pressure on tiny chain residuals
            // when few bins can fit the item
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && miss > 2.0 && miss <= 5.0 && progress > 0.5 {
                score += 0.12 * (1.0 - (miss - 2.0) / 3.0) * progress;
            }
            // mutation gen-165: near-miss gap scaled by progress — late-stream
            // small gaps below the next item are more costly
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 4.0 * nx {
                    let rem = new_pr - 4.0 * nx;
                    if rem <= 4.0 { nb -= 0.18 * (1.0 - rem / 4.0) * (0.6 + 0.4 * progress); }
                }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
                // mutation gen-165: exact multiple of next item — zero future
                // dead space in a brand-new bin
                if new_pr - (new_pr / nx).floor() * nx == 0.0 {
                    nb -= 0.3 * (0.5 + 0.5 * progress);
                }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // mutation gen-165: residual variance control — favor fresh bins whose
        // residual lands near the mean residual scale (reusable space)
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // mutation gen-165: cap stranded slivers in fresh bins
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // mutation gen-165: late-stream consolidation — prefer fresh bins for
        // large items that open bins fit poorly
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        if progress > 0.3 && progress < 0.85 && mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem < 0.5 && new_pr >= mean_residual { nb -= 0.12 * (1.0 - progress * 0.4); }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize post residuals that are too small to hold any plausible item
    // (dead space) but reward residuals that can still fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 * (post_residual as f64 - next_item_size as f64).min(50.0) / 50.0;
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual) or are scarce.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 60.0;
        // cheaper to open new bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // if many open bins with slack, discourage new bin
        score += (open_bins_count as f64).ln().max(0.0) * 8.0;
        // if mean residual is large, open bins are roomy; discourage new bin
        score += mean_residual * 0.5;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 25.0;
        }
    }

    // Prefer denser bins when many bins are open (bin consolidation pressure)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: later in the stream, be greedier (minimize waste now)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
