            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-165: second-order dead-space audit — after the next item,
            // check whether the remaining chain residual can still absorb a
            // third copy of the next item; a residual that is a sliver above
            // one nx but below 2 nx strands space if items repeat
            if chain_residual >= nx && chain_residual < 2.0 * nx {
