            // small-item scale strand space; penalize when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-167: stranded-sliver penalty — residuals too small for the
            // mean item scale are dead space; escalate when many bins compete
            if chain_residual > 0.0 && mean_residual > 1.0 && chain_residual < mean_residual * 0.25 && fitting_bins_count >= 3 {
                score += 0.2 * (1.0 - chain_residual / (mean_residual * 0.25)) * (0.6 + 0.4 * progress);
            }
