            }
            // gen-167: near-miss sliver — residual that misses the next item by
            // only 1-2 units strands nearly the whole residual; penalize harder
            // late in the stream when there is no time to recover it
            if miss > 0.0 && miss <= 2.0 && progress > 0.5 {
                score += 0.18 * (1.0 - miss / 2.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
