        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-167: multi-step tiling gate — fresh-bin residual that tiles
        // exactly with the next item for 2+ placements eliminates all future
        // dead space in this bin; reward grows with the tile count
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let kt = (new_pr / nx) . floor ();
            if kt >= 2.0 && new_pr - kt * nx == 0.0 {
                score -= 0.22 * (kt / 4.0) . min (1.0) * (0.5 + 0.5 * progress);
            }
        }
        // gen-167: dead-space ratio control — fresh bins whose residual
        // exceeds twice the mean residual carry long-horizon dead space;
        // penalize mildly when few fitting bins exist (competition is low)
        if fitting_bins_count <= 2 && mean_residual > 1.0 && new_pr > 2.5 * mean_residual {
            score += 0.14 * ((new_pr / mean_residual - 2.5) / 2.5) . min (1.0) * (0.5 + 0.5 * progress);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let cls = post_residual % 10;
    // Penalize awkward residuals (dead space classes)
    match cls {
        0 => score -= 12.0,           // perfect fill class
        1..=2 => score -= 4.0,
        3..=6 => score += 2.0,
        7..=9 => score += 5.0,
        _ => {}
    }

    // Integer-division threshold: large residual chunks are reusable
    if post_residual >= bin_capacity / 2 {
        score -= 8.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 4.0; // small sliver
    }

    // Perfect fit detection via modulo of item size against capacity fractions
    if post_residual == 0 {
        score -= 25.0;
    }
    if bin_residual % item_size == 0 && item_size > 0 {
        // bin divides evenly into this item's size
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            score += 7.0; // next item won't fit here
        }
        // harmonic match: next_item_size % 10 == post_residual % 10
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else {
        // last item: prefer tight fill
        score -= 10.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive early or when residual is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 - 30.0 * (1.0 - progress) + 0.5 * mean_residual;
        if post_residual >= bin_capacity / 2 { score -= 10.0; }
    }

    // Mild normalization by mean residual state
    score -= 0.05 * mean_residual;
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
