            }
            // gen-167: near-miss relief via other open bins — when several
            // bins can fit the current item, a small gap here is less costly
            // because the stream has alternatives to drain this residual
            if miss > 0.0 && miss <= 6.0 && fitting_bins_count >= 3 {
