        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
