            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-169: dead-space budget gate — a fresh bin is only worth opening
        // mid-stream if its residual can plausibly absorb the next item or the
        // mean-scale item; otherwise the residual becomes permanent dead space
        if fitting_bins_count >= 2 && progress > 0.35 && progress < 0.9 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let scale = mean_residual . max (1.0);
            let usable = new_pr >= nx * 0.95 || new_pr >= scale * 0.9;
            if !usable && new_pr < 0.12 * cap {
                score += 0.3 * (1.0 - new_pr / (0.12 * cap)) * (0.5 + 0.5 * progress);
            }
        }
        // gen-169: two-item lookahead tiling — fresh bins whose residual
        // accommodates the next item plus a near-mean leftover tile cleanly
        // with future items; reward near-exact nx+mean_residual compositions
        if next_item_size > 0 && mean_residual > 1.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target2 = nx + mean_residual;
            if new_pr >= target2 {
                let r = new_pr - target2;
                if r <= 4.0 { score -= 0.2 * (1.0 - r / 4.0) * (0.5 + 0.5 * progress); }
            }
        }
        // gen-169: fragment-avoidance for large items — when the item is large
        // and any open bin would be left with a sliver residual, prefer the
        // fresh bin whose own residual is at least item-scale usable
        if fitting_bins_count >= 2 && item_size as f64 > 0.35 * cap && next_item_size > 0 {
            let open_slack = (bin_capacity - item_size) as f64;
            let nx = next_item_size as f64;
            if open_slack > 0.0 && open_slack < nx * 0.5 && new_pr >= nx {
                score -= 0.18 * (1.0 - open_slack / (nx * 0.5)) . max (0.0);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item (size 1) are never dead, but gaps below a usable threshold are waste.
    let min_item = 1.0f64;
    let usable_threshold = 20.0f64; // gaps smaller than this rarely get filled
    if post_residual > 0 && (post_residual as f64) < usable_threshold {
        // penalize unusable dead space super-linearly
        score += (usable_threshold - post_residual as f64).powi(2) * 0.6;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= min_item as u32 {
        score -= 25.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if the leftover gap can't hold the next item but is close
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // open-bin pressure: with many open bins, prefer reusing them
        score += open_bins_count as f64 * 4.0;
        // if no existing bin fits well, opening is more attractive
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    } else {
        // reuse pressure: fewer open bins is better, reward reuse
        score -= 5.0;
        // prefer bins with tighter residuals (best-fit flavor) beyond raw post_residual
        score += (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Global open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Slight preference to fill bins that are already more full than average
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
