        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste (post_residual) small relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize proportionally to leftover after next
            let second_leftover = post_residual - next_item_size;
            score += 0.25 * second_leftover as f64;
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.4 * post_residual as f64;
        }
    }

    // Penalize creating dead space smaller than the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual below mean are more precious.
    if (bin_residual as f64) < mean_residual {
        score += 3.0 * (mean_residual - bin_residual as f64);
    } else {
        score -= 1.0 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate: prefer it only when no open bin gives a good fit.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Base penalty so open bins win when reasonably tight.
        score += 30.0;
        // If many open bins are fragmented (high mean residual spread), new bin OK.
        if mean_residual < 25.0 {
            score -= 20.0;
        }
        // Late in stream, prefer compacting into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is large, fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild pressure to reduce number of open bins.
    score -= 0.5 * open_bins_count as f64;

    score
}

