            // gen-178: stranded-tail penalty — chain residuals that sit just
            // below the mean residual scale are hard to fill later; penalize
            // proportionally to how close they are to that scale
            if mean_residual > 1.0 && chain_residual > 0.0 && chain_residual < mean_residual {
