            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        // NEW BIN candidate: decide when a fresh bin beats a poor fit.
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                if r == 0.0 { nb -= 0.5; }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 4.0 * nx {
                    let rem = new_pr - 4.0 * nx;
                    if rem <= 4.0 { nb -= 0.18 * (1.0 - rem / 4.0) * (0.6 + 0.4 * progress); }
                }
                // gen-180: exact multiple of next item — zero future dead space
                if (new_pr % nx.max(1.0)) == 0.0 { nb -= 0.28 * (0.5 + 0.5 * progress); }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
                if new_pr < 0.04 * cap {
                    nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        if progress > 0.3 && progress < 0.85 && mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem < 0.5 && new_pr >= mean_residual { nb -= 0.12 * (1.0 - progress * 0.4); }
        }
        // gen-180: residual variance control — fresh bins landing near the
        // mean residual scale are more reusable; favor them over open bins
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-180: late-stream consolidation — prefer fresh bins for large
        // items rather than fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space nonlinearly (fragmentation).
    let dead = post_residual as f64;
    score += 0.02 * dead * dead / bin_capacity as f64;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if post_residual is awkwardly small
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins that are already fairly full (below mean residual).
    if open_bins_count > 2 {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff; // bins with less residual than average get favored
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (score for new bin candidate relative); late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus discount early in stream.
        score = 40.0 - 20.0 * (1.0 - progress);
        // If no open bin can fit, new bin is necessary: make it cheap.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Don't open a new bin when the item would leave a very large residual
        // that could instead go into an existing bin's gap.
        if post_residual as f64 > mean_residual && open_bins_count > 3 {
            score += 10.0;
        }
    }

    // Mild penalty for opening bins when many are already open late in stream.
    if bin_residual == bin_capacity && open_bins_count > 0 && progress > 0.7 {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize chain residuals in the gap band just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // exact-fill lookahead
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-180: dead-space pressure — small stranded chain residuals
            // are worse when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-180: combine residual-scale coupling — chain residuals close
            // to the mean residual scale are reusable by future items
            if mean_residual > 1.0 && chain_residual > 0.0 {
                let dev_c = ((chain_residual - mean_residual) / mean_residual).abs();
                if dev_c <= 0.2 { score -= 0.14 * (1.0 - dev_c / 0.2) * (0.5 + 0.5 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-180: near-miss lookahead — a bin whose residual is exactly
            // one next-item short of perfect closure should be filled now
            if miss >= 1.0 && miss <= 4.0 && fitting_bins_count >= 2 {
                score += 0.2 * (1.0 - miss / 4.0) * (0.5 + 0.5 * progress);
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            let kx = (new_pr / nx).floor();
            if kx >= 1.0 && new_pr - kx * nx == 0.0 {
                nb -= 0.3 * (0.5 + 0.5 * progress);
            }
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
            // gen-180: fresh-bin residual should tile with the item scale so
            // future items pack without stranding space
            if mean_residual > 1.0 && new_pr > 0.0 {
                let rem_m = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem_m <= 1.5 { nb -= 0.25 * (1.0 - rem_m / 1.5) * (0.5 + 0.5 * progress); }
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    nb += 0.15 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // gen-180: late-stream fresh-bin gate — avoid opening a bin with lots
        // of slack when open bins could host it
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                nb -= 0.3 * ((best_open_slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        // gen-180: late-stream consolidation — large items late in the stream
        // favor fresh bins over fragmenting open residuals
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr as f64;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, penalize dead space super-linearly
    let dead_weight = 1.0 + 2.5 * progress * progress + 1.5 * progress * norm_pr;
    score += norm_pr * norm_pr * cap * 0.6 * dead_weight;

    // Reward filling a bin nearly completely (smooth quadratic reward)
    let fill = 1.0 - norm_pr;
    score -= fill * fill * cap * 0.8;

    // Lookahead coupling: penalize post_residual that neither fits nor is far from next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = pr - nx;
            // small gap => good chaining; smooth quadratic bonus
            score -= (1.0 - gap / cap) * 4.0;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (nx - pr) / cap * 12.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but allow it early when few bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64 - 6.0 * progress;
    }

    // Mean residual context: penalize bins deviating from mean (fragmentation control)
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize chain residuals in the gap band just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // gen-154: exact-fill lookahead — a chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-154: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-154: tiling remainder within 1 unit of next item
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // gen-154: dead-space control vs mean residual scale
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-180: dead-space pressure — small stranded chain residuals are
            // costly when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // near-saturated bins (miss 1-2) — fill them now
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // gen-154: near-miss gap scaled by progress
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            // fresh bin residual exactly absorbs next item plus mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            // pair-packing lookahead — fresh residual hosts next item twice
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            // triple-packing lookahead
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
            // reject fresh bins whose residual falls just below next item
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // gen-154: dead-space-aware fresh-bin gate — exact multiple of
            // next item means zero future dead space in a brand-new bin
            let kx = (new_pr / nx).floor();
            if kx >= 1.0 && new_pr - kx * nx == 0.0 {
                nb -= 0.3 * (0.5 + 0.5 * progress);
            }
            // gen-154: dead space between one and two next items
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            let rem_m = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem_m <= 1.5 { nb -= 0.25 * (1.0 - rem_m / 1.5) * (0.5 + 0.5 * progress); }
        }
        // gen-154: residual variance control
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-154: cap total dead space — penalize stranded slivers
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        // gen-154: pair-left control
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // gen-154: late-stream fresh-bin gate
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                nb -= 0.3 * ((best_open_slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-180: late-stream consolidation — near the end, opening a fresh
        // bin for large items open bins cannot hold tightly is preferable to
        // fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-180: mid-stream fresh-bin slack guard — when the fresh residual
        // cannot host the next item, penalize moderately to avoid premature
        // bin openings that strand dead space
        if next_item_size > 0 && fitting_bins_count >= 2 && progress < 0.5 {
            let nx = next_item_size as f64;
            if new_pr < nx && nx - new_pr > 0.1 * cap {
                nb += 0.15 * (1.0 - progress / 0.5);
            }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction band does post_residual fall in?
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;
    let band = (pr / eighth).floor(); // 0..8 harmonic band of leftover

    // Reward leftovers that align with common item sizes (integer division classes)
    // Leftovers divisible by 10 are "harmonic" and reusable by typical items.
    let harmonic_bonus = if post_residual % 10 == 0 && post_residual > 0 {
        6.0
    } else if post_residual % 5 == 0 && post_residual > 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space: leftover too small for the smallest plausible item (1..100 unknown, assume >=10-ish risk)
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // nearly-unusable sliver
    } else if pr == 0.0 {
        score -= 20.0; // perfect closure
    }

    // Band-based penalty: mid bands (quarter to half) are awkward; low bands good, high bands fine.
    score += match band as u32 {
        0 => -8.0,
        1 => -4.0,
        2 => 2.0,
        3 => 5.0,
        4 => 4.0,
        _ => 0.0,
    };

    // Lookahead coupling: does the leftover fit the next item's harmonic class?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits here: reward, more if fit is tight (small slack)
            let slack = pr - nx;
            score -= 10.0 + 8.0 * (1.0 - slack / cap);
            // modulo harmony between leftover and next item
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize leaving a bin that strands the lookahead
            score += 4.0 + 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, discourage unless open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // Opening a new bin costs ~1 bin; only attractive if existing residuals are fragmented
        let fragmentation = (mean_residual - pr).abs();
        score = cap * 0.55 + fragmentation * 0.3 - crowd * 0.8 - progress * 5.0;
        // If the item exactly halves a fresh bin, that's a decent open
        if post_residual * 2 == bin_capacity {
            score -= 12.0;
        }
    }

    // Mild tie-break toward fuller bins overall
    score -= (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            // multi-step lookahead
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            // tiling bonus
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            // dead-space slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // penalize chain residuals in the gap band just below the next item
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals tiling with mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            // exact-fill lookahead — a chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // tiling remainder within 1 unit of next item
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            // dead-space control vs mean residual scale
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-180: dead-space pressure — chain residuals slightly above a
            // small-item scale strand space; penalize when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            let miss = nx - pr;
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            else if miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            // near-saturated bins (miss 1-2) — fill them now
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // near-miss gap scaled by progress — later in the stream,
            // a small gap below the next item is more costly
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
            // fresh bin residual exactly absorbs next item plus mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual;
                if new_pr >= target && new_pr - target <= 2.0 {
                    nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
                }
            }
            // pair-packing lookahead — fresh residual hosts next item twice
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
            }
            // triple-packing lookahead
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
            // reject fresh bins whose residual falls just below next item
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // dead-space-aware fresh-bin gate — exact multiple of
            // next item means zero future dead space in a brand-new bin
            let kx = (new_pr / nx).floor();
            if kx >= 1.0 && new_pr - kx * nx == 0.0 {
                nb -= 0.3 * (0.5 + 0.5 * progress);
            }
            // dead space between one and two next items
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            let rem_m = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem_m <= 1.5 { nb -= 0.25 * (1.0 - rem_m / 1.5) * (0.5 + 0.5 * progress); }
        }
        // residual variance control — favor fresh bins whose
        // residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // cap total dead space — penalize stranded slivers
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap {
                nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
            }
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { nb -= 0.25; }
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        // pair-left control — fresh bin that leaves a residual just
        // below half the mean residual risks dead space
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        // late-stream fresh-bin gate — avoid opening a bin with lots
        // of slack when open bins could host it
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                nb -= 0.3 * ((best_open_slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-180: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-180: fresh-bin mean-tiling gate — a fresh residual that tiles
        // the mean residual exactly promises reusable space; prefer it
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem == 0.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // multi-step tiling lookahead (borrowed from best): r2/r3 layers
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 45.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 25.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            // near-multiple-of-next tiling
            let k = (cr / nx . max (1.0)) . round () ;
            let mult_err = (cr - k * nx) . abs () ;
            if k >= 2.0 && mult_err <= 2.0 { score -= 35.0 * (1.0 - mult_err / 2.0) ; }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // chain residual below small-item scale is dead space
            if cr > 0.0 && cr < 0.06 * cap {
                score += 35.0 * (1.0 - cr / (0.06 * cap)) ;
            }
            // chain residual below mean scale strands space
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 30.0 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress) ;
            }
            // tiles with mean residual scale
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem <= 4.0 { score -= 18.0 * (1.0 - rem / 4.0) ; }
            }
            if cr == 0.0 { score -= 60.0 ; }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            if miss >= 1.0 && miss <= 2.0 { score += 35.0 * (1.0 - (miss - 1.0)) ; }
            // residual near mean scale keeps future fits tight
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 10.0 * (1.0 - dev / 0.05) ; }
                if dev > 0.6 { score += 12.0 * ((dev - 0.6) / 0.6) . min (1.0) ; }
            }
        }
        // item exactly tiles current residual
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 {
                score -= 20.0 * (1.0 - progress * 0.3) ;
            }
        }
    }
    score += 5.0 * open_bins_count as f64 * (1.0 - progress) ;
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if fitting_bins_count >= 4 { score -= 40.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
            let gap = next_item_size as f64 - new_pr ;
            if gap <= 10.0 {
                let mut pen = 40.0 * (1.0 - gap / 10.0) ;
                if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5 ; }
                score += pen * (0.6 + 0.4 * progress) ;
            }
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
            // exact multiple of next item: zero future dead space
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 30.0 * (0.5 + 0.5 * progress) ;
            }
            // residual just above 2x next item is a near-perfect pair
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr ;
                if dead < 0.05 * cap {
                    score += 30.0 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress) ;
                }
            }
            // pair with mean residual
            if mean_residual > 0.0 {
                let target = nx + mean_residual ;
                if new_pr >= target && new_pr - target <= 2.0 {
                    score -= 30.0 * (1.0 - (new_pr - target) / 2.0) ;
                }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
            if dev <= 0.1 { score -= 15.0 * (1.0 - dev / 0.1) ; }
        }
        // tiles with mean residual
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual ;
            if rem <= 1.5 { score -= 25.0 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // late-stream: fresh bin with big slack is worse than tight open fit
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.4 { score += 35.0 * ((slack - 0.4) / 0.6) . min (1.0) ; }
        }
        // end-of-stream: avoid opening bins that cannot be refilled
        if progress > 0.85 && fitting_bins_count <= 2 { score += 60.0 * (progress - 0.85) / 0.15 ; }
        if progress > 0.7 { score -= 25.0 * (progress - 0.7) / 0.3 ; }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 80.0 ; }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 20.0 * (item_size as f64 / cap - 0.55) ;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (below the minimum item size) are pure waste.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0; // heavy penalty for creating unusable slivers
    }

    // Non-linear penalty on small-but-nonzero gaps that likely can't fit the
    // lookahead item either: double dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using bins that fit well relative to the mean residual state.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Open-bin pressure: discourage scattering across many bins; encourage
    // filling existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive for large items or when no
    // open bin offers a decent fit; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 1.1;
        if decent_fit_exists && post_residual > 0 {
            score += 18.0; // penalize new bin when an open bin fits decently
        }
        if item_size >= 70 {
            score -= 10.0; // big items are fine in a fresh bin
        }
        // A fresh bin has perfect residual; don't let the base term dominate.
        score -= 5.0;
    }

    // Early-stream exploration: slight preference for tight fits early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap;
    if post_residual == 0 { score -= 6.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual == next_item_size as u32 {
            score -= 4.5 ;
        } else if post_residual as f64 > nx {
            let chain_residual = post_residual - next_item_size ;
            let cr = chain_residual as f64 ;
            score -= 1.2 * (1.0 - cr / cap) ;
            if chain_residual <= 10 { score -= 0.8 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 0.25 ; }
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 0.35 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.3 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            // multi-step tiling: chain residual that fits next item twice
            if cr >= nx {
                let r2 = cr - nx;
                if r2 <= 15.0 { score -= 0.4 * (1.0 - r2 / 15.0); }
                if r2 >= nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.22 * (1.0 - r3 / 8.0); }
                }
            }
            // near-multiple of next item leaves minimal dead space
            let k = (cr / nx . max (1.0)) . floor ();
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0);
                if rem <= 2.0 { score -= 0.25 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 0.5 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 0.2 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 0.3 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // chain residual far below mean residual scale is stranded
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 0.28 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 0.25 + 0.003 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 1.6 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 0.2 * (1.0 - miss / 6.0) * progress ;
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            // residual close to mean scale is likely to be reused later
            if mean_residual > 0.5 && post_residual > 0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.12 * (1.0 - dev / 0.05); }
                if dev > 0.6 { score += 0.1 * ((dev - 0.6) / 0.6).min(1.0); }
            }
        }
        // current item exactly tiles the residual for the next item
        if post_residual > 0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (post_residual as f64 / isz) . round ();
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.04 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate — rebased score so open-bin logic dominates
        score = 0.9 - 0.35 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.55 ; }
        if item_size as f64 >= 0.9 * cap { score -= 0.6 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 0.4 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 0.5 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 1.8 ; }
            else if r <= 5.0 { score -= 0.6 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 0.5 * miss . min (0.3) ;
        }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 0.4 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.6 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 0.25 * (1.0 - dev / 0.25) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.3 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // fresh residual tiles with mean residual repeatedly
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.2 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        // after placing next item, residual still above mean scale is reusable
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.15 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { score -= 0.3 * ((slack - 0.4) / 0.6).min(1.0); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 / cap ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.9 * (1.0 - 0.3 * progress) ;
        }
    }
    score
}

