                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-183: dead-space budget gate — compare the fresh bin's residual
        // against the best achievable open-bin residual; when open bins would
        // strand more space than the fresh bin's remainder after tiling the
        // next item, prefer opening the fresh bin
        if fitting_bins_count >= 2 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let open_strand = (mean_residual - nx . min (mean_residual)) . max (0.0);
            let fresh_after = if new_pr >= nx { new_pr - nx } else { new_pr };
            if fresh_after < open_strand * 0.5 {
                score -= 0.18 * (1.0 - fresh_after / (open_strand * 0.5).max (1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // gen-183: two-step tiling — fresh bins whose residual tiles the next
        // item twice with a tiny remainder are near-perfect containers
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem2 = new_pr - 2.0 * nx;
                if rem2 <= 1.0 { score -= 0.2 * (1.0 - rem2) * (0.6 + 0.4 * progress); }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with a smooth polynomial shaping.
    let mut score = pr * pr * (3.0 - 2.0 * pr) * 60.0 + post * 0.5;

    // Non-linear coupling: waste penalty grows quadratically as stream progresses
    // (later waste is more costly since fewer items remain to fill gaps).
    let waste_coupling = pr * pr * (0.5 + progress * 1.5);
    score += waste_coupling * 40.0;

    // Dead-space term: residuals too small for typical items are penalized smoothly.
    let deadness = ((cap - post) / cap) * ((cap - post) / cap); // fill fraction squared
    let unusable = 1.0 - (post / 80.0).min(1.0).max(0.0);
    score += deadness * unusable * 30.0 * (0.6 + progress);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let snug = 1.0 - ((post - nx) / cap).abs();
            score -= 18.0 * snug * (1.0 - progress * 0.3);
        } else {
            score += 8.0 * ((nx - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr);
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation.
    let crowd = (open_bins_count as f64).ln() * (mean_residual / cap);
    score += crowd * 6.0 * (0.5 + progress);

    // Mild preference for filling existing bins over opening new ones,
    // decaying as stream progresses (early on, fresh bins are cheaper).
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress * 0.5) + (open_bins_count as f64) * 2.0;
    } else {
        score -= 5.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
