            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-148: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-155: dead-space pressure — chain residuals slightly above a
            // small-item scale strand space; penalize when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-184: two-step exact tiling — reward chain residuals that
            // tile exactly with the next item twice over, guaranteeing two
            // future perfect fills with zero dead space
            if chain_residual >= 2.0 * nx && chain_residual % nx . max (1.0) == 0.0 {
                score -= 0.15 * ((chain_residual / nx) . min (4.0) - 1.0) * (0.5 + 0.5 * progress);
            }
            // gen-184: mean-scale tiling — chain residual close to a whole
            // number of mean residuals predicts reusable leftover space
            if mean_residual > 1.0 && chain_residual > mean_residual {
                let rem_mean = chain_residual - (chain_residual / mean_residual) . round () * mean_residual;
                if rem_mean . abs () <= 1.5 {
