            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-184: multi-fill fresh bin — a fresh bin whose residual tiles
        // exactly with several copies of the next item promises multiple
        // perfect fills; deepen the reward with the fill count
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 && new_pr - k * nx == 0.0 {
                score -= 0.18 * (k - 1.0) . min (3.0) * (0.5 + 0.5 * progress);
            }
        }
        // gen-184: waste-floor guard — when the current waste (bins used minus
        // lower bound implied by mean fill) is small, be conservative about
        // opening new bins; when waste is already large, allow consolidation
        if mean_residual > 0.0 && open_bins_count > 3 {
            let avg_fill = cap - mean_residual;
            if avg_fill > 0.0 {
                let slack_ratio = mean_residual / cap;
                if slack_ratio < 0.08 && new_pr / cap > slack_ratio * 3.0 {
                    score += 0.2 * (new_pr / cap - slack_ratio * 3.0) . min (0.3);
                }
            }
        }
        // gen-184: sliver-tolerant late gate — a tiny fresh-bin residual late
        // in the stream is nearly always dead space unless the next item
        // exactly matches it
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 && progress > 0.7 {
            score += 0.25 * (1.0 - new_pr / next_item_size as f64) . min (1.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: small residuals are hard to fill (items >= 10... but sizes 1..100 allowed).
    let small_item_floor = 1u32;
    if post_residual > 0 && post_residual < small_item_floor + 9 {
        score += 25.0; // tiny unusable sliver
    }

    // Aggressive 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(150.0);
        } else {
            // next item does NOT fit in this bin's remainder: penalize
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow.min(120.0);
        }
    }

    // Compare post_residual against mean residual: keep bins balanced-ish but
    // prefer bins tighter than average being filled.
    if post_residual as f64 > mean_residual {
        score += 8.0; // leaving more than average residual -> mild penalty
    } else {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // Late in the stream: consolidate into existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Many open bins: discourage new-bin opening, encourage filling existing ones.
    if open_bins_count > 4 {
        score -= 5.0;
    }

    // New-bin candidate: empty bin gets a large residual by construction.
    if bin_residual == bin_capacity {
        // Only attractive for big items or when no good existing option exists.
        score += 40.0 + (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 60.0; // fresh bin can host item + next item together
        }
    }

    // Reward tighter fits overall (smaller post_residual relative to item size).
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 10.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            let wasted = cr / cap ;
            if wasted > 0.05 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // deeper multi-tile lookahead with next item
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 25.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 15.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            // near-multiple tiling of chain residual
            let k = (cr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0) ;
                if rem <= 3.0 { score -= 18.0 * (1.0 - rem / 3.0) * (0.6 + 0.4 * progress) ; }
            }
            // chain residual well below mean item scale strands space
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 22.0 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress) ;
            }
            // gen-184: mean-residual ratio penalty on very small chain residuals
            if mean_residual > 0.0 && cr > 0.0 {
                let ratio = cr / mean_residual ;
                if ratio < 0.15 { score += 20.0 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress) ; }
            }
            // gen-184: mean-residual tiling reward
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem <= 4.0 { score -= 15.0 * (1.0 - rem / 4.0) ; }
            }
            // gen-184: exact zero chain residual is a perfect fill
            if cr == 0.0 { score -= 60.0 ; }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            if miss > 3.0 && miss <= 8.0 {
                score += 12.0 * (1.0 - (miss - 3.0) / 5.0) ;
            }
            if miss >= 1.0 && miss <= 2.0 {
                score += 30.0 * (1.0 - (miss - 1.0)) ;
            }
            // residual close to mean scale is reusable later
            if mean_residual > 0.5 && post_residual as f64 > 0.0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 8.0 * (1.0 - dev / 0.05) ; }
                if dev > 0.6 { score += 10.0 * ((dev - 0.6) / 0.6) . min (1.0) ; }
            }
            // gen-184: residual that pairs well with next item at half scale
            if post_residual as f64 > 0.0 && 2.0 * nx > post_residual as f64 && post_residual as f64 + nx <= cap {
                score += 10.0 * (1.0 - (2.0 * nx - post_residual as f64) / (2.0 * nx)) ;
            }
        }
        // gen-184: residual tiles with the placed item itself
        if post_residual as f64 > 0.0 && item_size > 0 {
            let isz = item_size as f64 ;
            let k = (post_residual as f64 / isz) . round () ;
            if k >= 1.0 && k <= 4.0 && (post_residual as f64 - k * isz) . abs () <= 1.5 {
                score -= 15.0 * (1.0 - progress * 0.3) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // many open bins with a big item -> fresh bin is cheap
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 30.0 ; }
        // fresh residual that tiles exactly with the next item leaves zero dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 1.0 && new_pr - k * nx . max (1.0) == 0.0 {
                score -= 25.0 * (0.5 + 0.5 * progress) ;
            }
        }
        // fresh residual near-mean multiple tiling
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 18.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // very late stream with few fitting bins: fresh bin is safe consolidation
        if progress > 0.85 && fitting_bins_count <= 2 { score += 40.0 * (progress - 0.85) / 0.15 ; }
        // gen-184: fresh residual that leaves a near-multiple of next item
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr ;
                if dead < 0.05 * cap {
                    score += 25.0 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress) ;
                }
            }
        }
        // gen-184: fresh residual below next item and tiny -> stranded
        if next_item_size > 0 && new_pr > 0.0 && new_pr < next_item_size as f64 && new_pr < 0.08 * cap {
            score += 40.0 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress) ;
        }
        // gen-184: fresh residual fits several mean-scale items ahead
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor () ;
            if fits_ahead >= 3.0 { score -= 15.0 * ((1.0 - progress * 0.5) . min (1.0)) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    // gentle open-bin pressure early in the stream to avoid bin sprawl
    score += 3.0 * open_bins_count as f64 * (1.0 - progress) / (total_items . max (1) as f64).sqrt () ;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-148: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-148: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-155: dead-space pressure — chain residuals slightly above a
            // small-item scale strand space; penalize when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-185: stranded-sliver gate — a chain residual that is a tiny
            // sliver below the next item can never be filled; penalize it
            // proportionally to how little time remains in the stream
            if chain_residual > 0.0 && chain_residual < nx {
                let strand = nx - chain_residual;
                if strand <= 4.0 {
                    score += 0.3 * (1.0 - strand / 4.0) * (0.6 + 0.4 * progress);
                }
            }
            // gen-185: multi-fit competition — when many bins can take this
            // item, prefer the one whose chain residual is closest to the
            // mean residual scale (keeps residual variance low)
            if fitting_bins_count >= 3 && mean_residual > 0.5 && chain_residual > 0.0 {
                let dev = ((chain_residual - mean_residual) / mean_residual) . abs ();
                if dev < 0.2 { score -= 0.18 * (1.0 - dev / 0.2) * (0.5 + 0.5 * progress); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-148: near-miss gap scaled by progress — later in the stream,
            // a small gap below the next item is more costly (less time to fill)
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-185: near-miss rescue via item itself — if the *current*
            // item nearly exhausts the residual (pr - item_size close to a
            // useful scale), soften the near-miss penalty since this bin
            // will be reusable right after
            if pr > 0.0 && (item_size as f64) > 0.0 && pr >= item_size as f64 {
                let after = pr - item_size as f64;
                if after > 0.0 && after < mean_residual . max (1.0) {
                    score -= 0.15 * (1.0 - after / mean_residual . max (1.0));
                }
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-185: two-step tiling lookahead — reward fresh bins whose
        // residual tiles with the next item for two steps (nx + mean scale),
        // leaving near-zero dead space after two placements
        if next_item_size > 0 && mean_residual > 0.5 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let two_step = nx + nx . max (mean_residual);
            if new_pr >= two_step {
                let rem2 = new_pr - two_step;
                if rem2 <= 3.0 { score -= 0.26 * (1.0 - rem2 / 3.0) * (0.4 + 0.6 * progress); }
            }
        }
        // gen-185: open-bin fragmentation guard — when the best open-bin fit
        // would strand a residual below the next item (unfillable gap), and
        // the fresh bin's residual instead accommodates the next item,
        // prefer the fresh bin more strongly in the late stream
        if progress > 0.5 && fitting_bins_count >= 2 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let open_slack = (bin_capacity - item_size) as f64;
            if open_slack > 0.0 && open_slack < nx && new_pr >= nx {
                score -= 0.35 * (1.0 - open_slack / nx) * ((progress - 0.5) / 0.5) . min (1.0);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize large dead space relative to smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect fit
    }
    if post_residual >= 10 && post_residual < item_size.min(100) {
        score += (post_residual as f64).powf(0.8) * 0.3;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // prefer leaving space exactly for next item
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * progress - 5.0 * pressure;
        // allow new bin late in stream when open bins are fragmented
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins
    if bin_residual < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Mild time-horizon coupling: early stream, be conservative with new bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - t);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 / cap ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // deeper multi-tile lookahead with next item
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 25.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 15.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            // near-multiple tiling of chain residual
            let k = (cr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0) ;
                if rem <= 3.0 { score -= 18.0 * (1.0 - rem / 3.0) * (0.6 + 0.4 * progress) ; }
            }
            // chain residual well below mean item scale strands space
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 22.0 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress) ;
            }
            // gen-185: chain residual below smallest plausible item scale is
            // dead space; penalize more strongly as stream progresses
            if cr > 0.0 && cr < 0.06 * cap {
                score += 35.0 * (1.0 - cr / (0.06 * cap)) * (0.4 + 0.6 * progress) ;
            }
            // gen-185: reward chain residuals that tile with the mean residual
            // scale, since future items cluster near the mean
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem_m = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem_m <= 4.0 { score -= 20.0 * (1.0 - rem_m / 4.0) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            if miss > 3.0 && miss <= 8.0 {
                score += 12.0 * (1.0 - (miss - 3.0) / 5.0) ;
            }
            // residual close to mean scale is reusable later
            if mean_residual > 0.5 && post_residual as f64 > 0.0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 8.0 * (1.0 - dev / 0.05) ; }
            }
            // gen-185: residuals far from the mean scale are dead-space risks
            if mean_residual > 0.5 && post_residual as f64 > 0.0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev > 0.6 { score += 12.0 * ((dev - 0.6) / 0.6) . min (1.0) ; }
            }
            // gen-185: residual that pairs with next item to near-capacity fill
            if post_residual as f64 > 0.0 && 2.0 * nx > post_residual as f64 && post_residual + next_item_size <= bin_capacity {
                score += 10.0 * (1.0 - (2.0 * nx - post_residual as f64) / (2.0 * nx)) ;
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // many open bins with a big item -> fresh bin is cheap
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 30.0 ; }
        // fresh residual that tiles exactly with the next item leaves zero dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 1.0 && new_pr - k * nx . max (1.0) == 0.0 {
                score -= 25.0 * (0.5 + 0.5 * progress) ;
            }
        }
        // fresh residual near-mean multiple tiling
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 18.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // very late stream with few fitting bins: fresh bin is safe consolidation
        if progress > 0.85 && fitting_bins_count <= 2 { score += 40.0 * (progress - 0.85) / 0.15 ; }
        // gen-185: fresh residual that can host next item AND leave a
        // mean-scale remainder is a strong two-step plan
        if next_item_size > 0 && new_pr > 0.0 && mean_residual > 1.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= nx {
                let after = new_pr - nx ;
                if after >= mean_residual && after - mean_residual <= 3.0 {
                    score -= 30.0 * (1.0 - (after - mean_residual) / 3.0) * (0.5 + 0.5 * progress) ;
                }
                if after > 0.0 && after < mean_residual * 0.5 {
                    score += 25.0 * (1.0 - after / (mean_residual * 0.5)) * (0.6 + 0.4 * progress) ;
                }
            }
        }
        // gen-185: fresh bin whose residual fits several mean-scale items is
        // a long-lived bin; reward when few bins are open
        if mean_residual > 1.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual) . floor () ;
            if fits_ahead >= 3.0 { score -= 18.0 * ((1.0 - progress * 0.5) . min (1.0)) ; }
        }
        // gen-185: dead-space gate — fresh residual just above next item
        // (small dead remainder) is worse than just below a tiling point
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr ;
                if dead > 0.0 && dead < 0.05 * cap {
                    score += 30.0 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress) ;
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    // gentle open-bin pressure early in the stream to avoid bin sprawl
    score += 3.0 * open_bins_count as f64 * (1.0 - progress) / (total_items . max (1) as f64).sqrt () ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: dead space grows superlinearly.
    let prn = pr / cap;
    score += 30.0 * prn * prn * prn * cap;

    // Reward tight fits (small post-residual) with a smooth saturating term.
    let tight = (-prn * 6.0).exp();
    score -= 25.0 * tight * it / cap;

    // Stream-progress coupling: later in the stream, be more tolerant of
    // residual space (consolidate into open bins rather than opening new ones),
    // but early on prefer near-perfect packing.
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress);
    score -= 18.0 * progress_coupling * prn * cap;
    score += 10.0 * (1.0 - progress_coupling) * prn * cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.3 * pr;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gapn = gap / cap;
        score -= 22.0 * (-gapn * 8.0).exp();
        // If next item cannot fit in residual, penalize slightly (fragmentation risk).
        if nxt > pr {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (making residual small) or no open bin is comparable.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - it / cap) + 8.0 * (open_bins_count as f64).sqrt();
        // Allow new bin late in stream if item would leave tiny residual anyway.
        score -= 35.0 * (-prn * 10.0).exp();
    }

    // Mild preference for bins below mean residual (use emptier bins first,
    // keeping tight bins for small future items) — smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common
    // item-size classes (multiples of 10/20/25) are more reusable.
    let pr = post_residual;
    let reusability = if pr == 0 {
        -40.0 // perfect fill: strongly reward
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 {
        0.0
    } else {
        25.0 // dead space < 10: heavy penalty (min item size assumed small)
    };
    score += reusability;

    // Integer-division threshold: post_residual bucketed in quarters of capacity
    let quarter = bin_capacity / 4;
    if pr > 3 * quarter {
        score -= 8.0; // bin still mostly empty: fine to keep filling
    } else if pr > 2 * quarter {
        score -= 3.0;
    } else if pr > quarter {
        score += 4.0; // getting tight: mild penalty unless exact class match
        if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if next_item_size > pr {
            score += 6.0; // next item won't fit here; slight penalty for tightness
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 45.0 + 25.0 * (1.0 - progress); // early stream: more willing to open
        score = base
            + if fitting_bins_count == 0 { -50.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size + item_size <= bin_capacity { -8.0 } else { 0.0 };
    }

    // Tie-breaking via mean residual: prefer bins below mean (filling laggards)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-185: two-step lookahead proxy — chain residual that can
            // still absorb mean_residual after the next item leaves room for
            // one more typical item; reward near-exact double chains
            if mean_residual > 1.0 && chain_residual > nx {
                let double_left = chain_residual - nx - mean_residual;
                if double_left >= 0.0 && double_left <= 2.0 {
                    score -= 0.3 * (1.0 - double_left / 2.0) * (0.5 + 0.5 * progress);
                }
                if double_left > 0.0 && double_left < 0.05 * cap {
                    score += 0.2 * (1.0 - double_left / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
            // gen-185: late-stream tightness — residual dead space after the
            // chain matters more when few items remain to fill it
            if chain_residual > 0.0 && progress > 0.75 {
                let tight = chain_residual / cap;
                if tight > 0.02 { score += 0.5 * ((tight - 0.02) / 0.1) . min (1.0) * ((progress - 0.75) / 0.25); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
