            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-185: stranded-sliver penalty — a residual just below the
            // next item and far below the mean residual is unlikely to ever
            // be filled; penalize proportionally to how stranded it is
            if pr > 0.0 && mean_residual > 1.0 && pr < mean_residual * 0.5 && miss > 2.0 {
                score += 0.18 * (1.0 - pr / (mean_residual * 0.5)) * (0.5 + 0.5 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-185: fresh-bin double-chain gate — a fresh bin whose residual
        // fits next item plus the mean residual almost exactly promises two
        // more zero-waste fills; strengthen preference for that geometry
        if next_item_size > 0 && mean_residual > 1.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target {
                let over = new_pr - target;
                if over <= 4.0 { score -= 0.32 * (1.0 - over / 4.0) * (0.6 + 0.4 * progress); }
            }
        }
        // gen-185: avoid opening a fresh bin that strands a residual just
        // below the next item when open bins could still absorb the item —
        // such a fresh bin creates immediate dead space
        if next_item_size > 0 && new_pr > 0.0 && fitting_bins_count >= 2 {
            let nx = next_item_size as f64;
            if new_pr < nx && nx - new_pr > 2.0 && nx - new_pr <= 12.0 {
                score += 0.28 * (1.0 - (nx - new_pr - 2.0) / 10.0) * (0.5 + 0.5 * progress);
            }
        }
        // gen-185: mean-residual tiling bonus — fresh bin residual that is a
        // near-exact multiple of the mean residual is likely to be consumed
        // by subsequent typical items with minimal waste
        if mean_residual > 1.5 && new_pr > mean_residual {
            let km = (new_pr / mean_residual) . floor ();
            let remm = new_pr - km * mean_residual;
            if remm <= 1.0 { score -= 0.24 * (1.0 - remm) * (0.5 + 0.5 * progress); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 { score -= 8.0; }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= 4.0 * nx {
                let rem4 = chain_residual - 4.0 * nx;
                if rem4 <= 4.0 { score -= 0.2 * (1.0 - rem4 / 4.0) * (0.6 + 0.4 * progress); }
            }
            // gen-186: exact zero dead space after chain
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if pr > 0.0 && miss > 2.0 && miss <= 5.0 && progress > 0.5 {
                score += 0.12 * (1.0 - (miss - 2.0) / 3.0) * progress;
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 4.0 * nx {
                    let rem = new_pr - 4.0 * nx;
                    if rem <= 4.0 { nb -= 0.18 * (1.0 - rem / 4.0) * (0.6 + 0.4 * progress); }
                }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        if progress > 0.3 && progress < 0.85 && mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem < 0.5 && new_pr >= mean_residual { nb -= 0.12 * (1.0 - progress * 0.4); }
        }
        // gen-186: residual-variance control — prefer fresh bins whose leftover
        // lands near the mean-residual scale, reducing dead-space spread
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-186: exact-tiling fresh bin — zero future dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx).floor();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                nb -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-186: strand sliver below smallest plausible scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-186: late-stream consolidation for large items
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: smaller post_residual relative to capacity is better,
    // with a non-linear (quadratic) tightness bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // If the next item fits exactly in the post residual, reward strongly
    // (chaining placements).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot fit in post_residual but would fit a fresh bin.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and this is a new empty bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But allow opening a new bin if mean residual across open bins is small
        // (fragmented bins) and item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 && item_size > 50 {
            score -= 30.0 * (0.5 + progress);
        }
    }

    // Mild preference for bins below mean residual (consolidate slack).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            // gen-148: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            // gen-148: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-155: dead-space pressure — chain residuals slightly above a
            // small-item scale strand space; penalize when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-186: dead-space pressure coupling — when many bins are open
            // and the chain residual is a mid-band sliver (too small for most
            // items but too large to ignore), penalize proportionally to how
            // far it sits from the mean residual scale; this steers selection
            // toward bins whose leftovers remain reusable by the stream
            if chain_residual > 4.0 && chain_residual <= 0.12 * cap && open_bins_count >= 3 {
                let band = chain_residual / (0.12 * cap);
                score += 0.10 * band * (1.0 - (chain_residual / mean_residual . max (1.0)) . min (1.0)) * (0.5 + 0.5 * progress);
            }
            // gen-186: multi-item tiling depth — reward residuals that can
            // absorb several more next-sized items with a tiny tail; deeper
            // tiling means the bin stays productive longer
            if chain_residual > 0.0 && mean_residual > 0.5 {
                let depth = (chain_residual / nx . max (1.0)) . floor ();
                if depth >= 2.0 {
                    let tail = chain_residual - depth * nx;
                    if tail <= 5.0 {
                        score -= 0.10 * (1.0 - tail / 5.0) * ((depth - 1.0) / 3.0) . min (1.0) * (0.5 + 0.5 * progress);
                    }
                }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-148: near-miss gap scaled by progress — later in the stream,
            // a small gap below the next item is more costly (less time to fill)
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-186: stranded-residual gate — a residual that cannot take the
            // next item and is far below the mean residual scale is likely
            // stranded; penalize harder when the stream is long and many bins
            // are competing (their residuals are more likely to be reused)
            if miss > 0.0 && mean_residual > 1.0 && pr < 0.5 * mean_residual && open_bins_count >= 4 {
                score += 0.10 * (1.0 - pr / (0.5 * mean_residual)) * (0.4 + 0.6 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-148 mutation: dead-space-aware fresh-bin gate — when the fresh
        // bin's residual is an exact multiple of the next item, strongly
        // prefer it (zero future dead space in a brand-new bin)
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // gen-148 mutation: residual variance control — when open-bin fits
        // leave residuals far from the mean residual (dead-space risk), favor
        // the fresh bin whose residual lands near the mean scale
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // gen-148 mutation: cap total dead space — penalize fresh bins whose
        // residual is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // gen-155: exact-fill fresh bin — placing the item so the fresh bin's
        // residual exactly equals the next item guarantees a perfect follow-up
        // fill; strengthen the reward and extend it to near-exact residuals
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        // gen-155: late-stream consolidation — near the end of the stream,
        // opening a fresh bin for large items that open bins cannot hold
        // tightly is preferable to fragmenting an open bin's residual
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-186: fresh-bin tiling depth — a fresh residual that can absorb
        // several next-sized items with a small tail is a productive bin;
        // deepen the reward beyond the exact-fill case so multi-item fresh
        // bins are preferred over fragmenting open bins
        if next_item_size > 0 && new_pr > 0.0 && mean_residual > 0.5 {
            let nx = next_item_size as f64;
            let depth = (new_pr / nx) . floor ();
            if depth >= 2.0 {
                let tail = new_pr - depth * nx;
                if tail > 0.0 && tail <= 6.0 {
                    score -= 0.14 * (1.0 - tail / 6.0) * ((depth - 1.0) / 4.0) . min (1.0) * (0.5 + 0.5 * progress);
                }
            }
        }
        // gen-186: open-bin competition gate — when several open bins can fit
        // the item and their combined slack already exceeds what a fresh bin
        // would strand, tilt against opening a new bin (reduces bin count by
        // reusing fragmented capacity instead of spawning bins)
        if fitting_bins_count >= 3 && new_pr > 0.0 && mean_residual > 0.0 {
            let fresh_slack = new_pr / cap;
            if fresh_slack > mean_residual / cap * 1.5 {
                score += 0.18 * (1.0 - (fresh_slack - mean_residual / cap) . min (1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // gen-186: mid-stream fresh-bin residual reuse — favor fresh bins
        // whose residual sits within one mean-residual of a reusable scale
        // (i.e. can still take at least one typical future item), penalize
        // fresh bins stranding less than that
        if progress > 0.35 && progress < 0.9 && new_pr > 0.0 && mean_residual > 1.0 {
            if new_pr < mean_residual * 0.8 {
                score += 0.20 * (1.0 - new_pr / (mean_residual * 0.8)) * (1.0 - (progress - 0.35) . abs ());
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact 2-step chain
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 150.0; // next item leaves near-perfect fit
            } else {
                score -= 50.0 / (1.0 + gap as f64 / 20.0);
            }
        } else {
            // next item won't fit here after placement; penalize slightly by mismatch
            let miss = next_item_size - post_residual;
            score += 30.0 * (miss as f64 / 100.0);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize large dead space relative to item scale
    if post_residual > 0 && post_residual < item_size {
        score += 0.3 * post_residual as f64;
    }

    // New-bin candidate: only attractive when open bins are quite full or item fits poorly
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64;
        let lookahead_bad = next_item_size > 0 && (bin_capacity - item_size) < next_item_size;
        let bias = 400.0 - 350.0 * pressure
            + if poor_fit < 15.0 { 100.0 } else { 0.0 }
            + if lookahead_bad { 50.0 } else { 0.0 }
            + if fitting_bins_count == 0 { 2000.0 } else { 0.0 };
        score += bias;
    }

    // Slight late-stream consolidation: prefer reusing bins as stream progresses
    score += 20.0 * (step_index as f64 / (total_items as f64).max(1.0));

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-186: dead-space pressure on mid-size chain residuals with
            // few fitting bins — strand risk grows late in the stream
            if chain_residual > 6.0 && chain_residual < 0.12 * cap && fitting_bins_count <= 2 {
                score += 0.12 * (1.0 - chain_residual / (0.12 * cap)) * progress;
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-186: residual reusable by mean-scale item later — mild reward
            if mean_residual > 0.5 && pr > 0.0 && (pr - mean_residual) . abs () <= 2.0 {
                score -= 0.08 * (1.0 - (pr - mean_residual) . abs () / 2.0) * (0.5 + 0.5 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-186: fresh-bin lookahead pair — residual that exactly fits the
        // next two items of the same scale is a zero-dead-space commitment
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && (new_pr - 2.0 * nx) == 0.0 {
                score -= 0.35 * (0.5 + 0.5 * progress);
            }
        }
        // gen-186: avoid opening a fresh bin whose residual is a near-miss of
        // the mean scale when many bins are already open (bin sprawl control)
        if open_bins_count >= 5 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev > 0.5 && new_pr < 0.15 * cap { score += 0.2 * ((dev - 0.5) / 0.5) . min (1.0); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good, but dead space
    // below the minimum item size is pure waste — penalize it extra.
    if post_residual > 0 {
        let waste_weight = 1.0 + (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;
        score += waste_weight * 0.5;
    } else {
        score -= 40.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well it fits
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual: leftover likely becomes dead space
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (favor keeping
    // residuals flexible); late in the stream, squeeze bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual across open bins is high,
    // we have slack — prefer bins that reduce dispersion (post close to mean).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Many open bins: discourage spreading items thinly; prefer fuller bins.
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64).ln() * post_residual as f64 / bin_capacity as f64;
    }

    // New-bin candidate: opening a new bin wastes (capacity - item) immediately.
    // Only attractive when no open bin fits well and item is large.
    if bin_residual == bin_capacity {
        let escape_pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score = bin_capacity as f64 - item_size as f64 * 0.6 - escape_pressure
            + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;
    let mut score = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        if pr == nx {
            score -= 5.5;
        } else if pr > nx {
            let chain = pr - nx;
            score -= 1.4 * (1.0 - chain / cap);
            if chain <= 10.0 { score -= 0.9; }
            if chain >= 20.0 && chain <= 60.0 { score -= 0.25; }
            // multi-step tiling lookahead
            if chain > nx {
                let r2 = chain - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            // small stranded chain residuals
            if chain > 0.0 && chain < 0.06 * cap {
                score += 0.35 * (1.0 - chain / (0.06 * cap));
            }
            if chain > 0.0 && chain < nx {
                let band = nx - chain;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // exact tiling with next item
            if (chain % nx.max(1.0)) == 0.0 { score -= 0.25 * (0.5 + 0.5 * progress); }
            if chain == 0.0 { score -= 0.6; }
            // dead-space pressure when few fitting bins
            if chain > 0.0 && chain <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain / 6.0) * progress;
            }
        } else {
            // next item does NOT fit: near-miss penalty
            let miss = nx - pr;
            score += 0.25 + 0.55 * progress;
            if miss < 0.25 * cap {
                score += 1.8 * (1.0 - miss / (0.25 * cap)) * (1.0 - progress * 0.5);
            }
            if miss <= 3.0 { score += 1.0 * (1.0 - miss / 3.0); }
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
        }
        // item_size tiling check on post residual
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual.
    if mean_residual > 0.0 {
        score -= 0.15 * (mean_residual - bin_residual as f64) / cap;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // ---------- NEW BIN CANDIDATE ----------
    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if nx > 0.7 * cap { score -= 0.6; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        // exact-fill lookahead for fresh bin
        if nx > 0.0 && new_pr >= nx {
            let r = new_pr - nx;
            if r == 0.0 { score -= 0.6; }
            else if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
            if r >= mean_residual.max(1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
            if r > 0.0 && r < nx * 0.25 { score -= 0.12 * (1.0 - r / (nx * 0.25)); }
        }
        if nx > 0.0 {
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        // mean-residual alignment of fresh residual
        if mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev < 0.25 { score -= 0.2 * (1.0 - dev / 0.25); }
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        // stranded sliver fresh residual
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // late-stream: prefer fresh bin for large items over fragmenting
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.25 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if nx > 0.0 && new_pr > 0.0 && new_pr < nx {
            let miss = (nx - new_pr) / cap;
            score += 0.5 * miss.min(0.3);
        }
    } else if nx > pr && post_residual > 0 {
        score += 0.2 * pr / cap;
        if nx - pr <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 6.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 3.5;
        } else if pr > nx {
            let cr = pr - nx;
            score -= 1.2 * (1.0 - cr / cap);
            if cr <= 10.0 { score -= 0.7; }
            if cr >= 20.0 && cr <= 60.0 { score -= 0.2; }
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 0.35 * (0.5 + 0.5 * progress); }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 0.3 * (1.0 - (cr - 2.0 * nx) / 8.0);
            }
            let wasted = cr / cap;
            if wasted > 0.06 { score += 0.5 * wasted * (0.4 + 0.6 * progress); }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 0.2 * (1.0 - cr / 6.0) * progress;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr;
                if band <= 12.0 { score += 0.3 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress); }
            }
            // deeper multi-tile lookahead
            if cr > nx {
                let r2 = cr - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            // near-multiple tiling of chain residual
            let k = (cr / nx . max (1.0)) . floor ();
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0);
                if rem <= 3.0 { score -= 0.22 * (1.0 - rem / 3.0) * (0.6 + 0.4 * progress); }
            }
            // chain residual well below mean item scale strands space
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 0.25 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            // borrowed: exact zero chain residual is a perfect fill
            if cr == 0.0 { score -= 0.6; }
            // borrowed: mean-scale tiling of chain residual
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem = cr - (cr / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.5 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 {
                score += 1.6 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress);
            }
            let miss = nx - pr;
            if miss > 0.0 && miss <= 6.0 {
                score += 0.15 * (1.0 - miss / 6.0) * progress;
            }
            if miss > 3.0 && miss <= 8.0 {
                score += 0.18 * (1.0 - (miss - 3.0) / 5.0);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.3 * (1.0 - (miss - 1.0)); }
            // residual close to mean scale is reusable later
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.12 * (1.0 - dev / 0.05); }
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        score -= 0.05 * mean_residual / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        let new_pr = (bin_capacity - item_size) as f64;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.8 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0);
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 0.4; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r == 0.0 { score -= 1.0; }
            else if r <= 5.0 { score -= 0.6 * (1.0 - r / 5.0); }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 1.0 * miss . min (0.3);
        }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.4 * (1.0 - rem / 4.0); }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev < 0.25 { score -= 0.25 * (1.0 - dev / 0.25); }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.3 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // many open bins with a big item -> fresh bin is cheap
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        // fresh residual that tiles exactly with the next item leaves zero dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx . max (1.0)) . floor ();
            if k >= 1.0 && new_pr - k * nx . max (1.0) == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        // fresh residual near-mean multiple tiling
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        // very late stream with few fitting bins: fresh bin is safe consolidation
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        // borrowed: fresh residual leaving a generous usable remainder for the future
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
            }
        }
        // borrowed: fresh residual that fits next item plus a mean-scale remainder
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        // borrowed: fresh residual near a multiple of the mean residual
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.7 * (1.0 - 0.3 * progress);
        }
    }
    // gentle open-bin pressure early in the stream to avoid bin sprawl
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Normalized post residual
    let x = (pr / cap).clamp(0.0, 1.0);
    // Base: prefer small post residual (tight fits)
    let mut score = pr as f64;
    // Non-linear polynomial coupling: dead space penalty grows super-linearly
    // with residual, modulated by stream progress (late stream => harsher on waste)
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += 30.0 * poly * (0.5 + progress);
    // Interaction: residual^2 / capacity scaled by progress
    score += (pr * pr / cap) * (0.2 + 0.6 * progress);
    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            // smooth reward: how snugly next item fits into post residual
            let fit_ratio = (nx / pr).clamp(0.0, 1.0);
            score -= 15.0 * fit_ratio * (1.0 - fit_ratio) * 4.0 * (0.5 + 0.5 * (1.0 - progress));
        } else {
            // post residual cannot host next item => mild penalty, smoothed
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * (1.0 + progress);
        }
    }
    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - poly) * (0.5 + progress);
    }
    // Many open bins => prefer consolidating into existing (avoid new bins)
    if bin_residual != bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);
    } else {
        // New bin candidate: penalize slightly unless residual landscape is bad
        score += 20.0 - 10.0 * (mean_residual / cap).clamp(0.0, 1.0) * (0.5 + progress);
    }
    // Mean residual alignment: prefer bins whose post residual keeps mean reasonable
    score += ((pr - mean_residual) / cap).abs() * 8.0 * (0.3 + 0.7 * progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
