                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            // gen-187: near-miss gap scaled by progress
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-187: mid-stream tighter squeeze on residual just under next item
            if pr > 0.0 && miss > 2.0 && miss <= 5.0 && progress > 0.5 {
                score += 0.12 * (1.0 - (miss - 2.0) / 3.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        // NEW BIN candidate
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 4.0 * nx {
                    let rem = new_pr - 4.0 * nx;
                    if rem <= 4.0 { nb -= 0.18 * (1.0 - rem / 4.0) * (0.6 + 0.4 * progress); }
                }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
                // gen-187: exact multiple of next item = zero future dead space
                if new_pr % nx.max(1.0) == 0.0 { nb -= 0.3 * (0.5 + 0.5 * progress); }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
                // gen-187: residual variance control — fresh bin near mean scale
                if fitting_bins_count >= 2 && dev < 0.25 {
                    nb -= 0.2 * (1.0 - dev / 0.25);
                }
            }
            // gen-187: cap total dead space — stranded sliver below smallest items
            if new_pr < 0.04 * cap {
                nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
            }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        // gen-187: endgame compaction — prefer fresh bins when an open-bin
        // fit would strand a large share of capacity
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-187: late-stream consolidation for large items
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-187: mid-stream reusable-space coupling with mean residual
        if progress > 0.3 && progress < 0.85 && mean_residual > 1.0 && new_pr > 0.0 && new_pr >= mean_residual {
            let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
            if rem < 0.5 { nb -= 0.12 * (1.0 - progress * 0.4); }
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful" classes
    // (multiples of common item sizes / large chunks) are rewarded.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fit is always best
    } else if pr >= 50 {
        class_bonus -= 25.0; // big residual stays flexible
    } else if pr % 10 == 0 {
        class_bonus -= 12.0; // round class residual is reusable
    } else if pr < 10 {
        class_bonus += 8.0; // tiny dead space
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        let snug = (pr as f64 - next_item_size as f64) / cap;
        class_bonus -= 18.0 * (1.0 - snug); // reward leaving room exactly for next item
    } else if next_item_size > pr && next_item_size > 0 {
        class_bonus += 6.0; // this bin can't chain, mild penalty
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        class_bonus -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins are bad fits
    if bin_residual == bin_capacity {
        // New empty bin: attractive early, or when current fit is poor / lookahead won't fit
        let poor_fit = post_residual > 0 && (post_residual as f64) < 0.2 * cap;
        let chainable = next_item_size > 0 && next_item_size <= pr;
        if open_bins_count == 0 || poor_fit && !chainable {
            class_bonus -= 30.0;
        } else {
            class_bonus += 45.0; // prefer existing bins by default
        }
    }

    // Progression: late in the stream, tighten up (avoid sprawl of many half-empty bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64).sqrt() * 0.5;

    // Coupling with mean residual: penalize bins far from mean (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Penalty for large item into nearly-full bin creating slivers
    if item_size >= 70 && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score += class_bonus;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 800.0 ; }
    if next_item_size > 0 {
        let nx = next_item_size as f64 ;
        if post_residual == next_item_size {
            score -= 450.0 ;
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size ;
            score -= 120.0 * (1.0 - chain_residual as f64 / cap) ;
            if chain_residual <= 10 { score -= 80.0 ; }
            if chain_residual >= 20 && chain_residual <= 60 { score -= 20.0 ; }
            let cr = chain_residual as f64 ;
            // exact tiling with next item: zero future dead space
            if nx > 0.0 && (cr % nx . max (1.0)) < 1.0 { score -= 40.0 * (0.5 + 0.5 * progress) ; }
            if cr > 2.0 * nx && cr - 2.0 * nx <= 8.0 {
                score -= 30.0 * (1.0 - (cr - 2.0 * nx) / 8.0) ;
            }
            let wasted = cr / cap ;
            if wasted > 0.08 { score += 60.0 * wasted * (0.4 + 0.6 * progress) ; }
            // sliver chain residuals strand space when few bins remain
            if cr > 0.0 && cr <= 6.0 && fitting_bins_count <= 2 {
                score += 25.0 * (1.0 - cr / 6.0) * progress ;
            }
            // chain residual just below next item scale is nearly dead
            if cr > 0.0 && cr < nx {
                let band = nx - cr ;
                if band <= 12.0 { score += 30.0 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress) ; }
            }
            // deeper multi-tile lookahead with next item (from best)
            if cr > nx {
                let r2 = cr - nx ;
                if r2 <= 15.0 { score -= 25.0 * (1.0 - r2 / 15.0) ; }
                if r2 > nx {
                    let r3 = r2 - nx ;
                    if r3 <= 8.0 { score -= 15.0 * (1.0 - r3 / 8.0) ; }
                }
            }
            // near-multiple tiling of chain residual
            let k = (cr / nx . max (1.0)) . floor () ;
            if k >= 2.0 {
                let rem = cr - k * nx . max (1.0) ;
                if rem <= 3.0 { score -= 18.0 * (1.0 - rem / 3.0) * (0.6 + 0.4 * progress) ; }
            }
            // chain residual well below mean item scale strands space
            if mean_residual > 0.0 && cr > 0.0 && cr < mean_residual * 0.4 {
                score += 22.0 * (1.0 - cr / (mean_residual * 0.4)) * (0.5 + 0.5 * progress) ;
            }
            // NEW: chain residual below smallest plausible item scale is dead space
            if cr > 0.0 && cr < 0.06 * cap {
                score += 35.0 * (1.0 - cr / (0.06 * cap)) ;
            }
            // NEW: chain residual exactly consumes next item -> zero dead space
            if cr == 0.0 { score -= 60.0 ; }
            // NEW: mean-scale tiling of chain residual
            if mean_residual > 0.5 && cr >= mean_residual {
                let rem = cr - (cr / mean_residual) . floor () * mean_residual ;
                if rem <= 4.0 { score -= 18.0 * (1.0 - rem / 4.0) ; }
            }
        } else {
            let orphan = (post_residual as f64 - mean_residual) . max (0.0) ;
            score += 25.0 + 0.3 * orphan ;
            let gap = (nx - post_residual as f64) / cap ;
            if gap < 0.25 {
                score += 150.0 * (1.0 - gap / 0.25) * (1.0 - 0.5 * progress) ;
            }
            let miss = nx - post_residual as f64 ;
            if miss > 0.0 && miss <= 6.0 {
                score += 20.0 * (1.0 - miss / 6.0) * progress ;
            }
            if miss > 3.0 && miss <= 8.0 {
                score += 12.0 * (1.0 - (miss - 3.0) / 5.0) ;
            }
            // tiny near-miss gaps are the most recoverable
            if miss >= 1.0 && miss <= 2.0 { score += 35.0 * (1.0 - (miss - 1.0)) ; }
            // residual close to mean scale is reusable later
            if mean_residual > 0.5 && post_residual as f64 > 0.0 {
                let dev = ((post_residual as f64 - mean_residual) / mean_residual) . abs () ;
                if dev <= 0.05 { score -= 8.0 * (1.0 - dev / 0.05) ; }
                if dev > 0.6 { score += 12.0 * ((dev - 0.6) / 0.6) . min (1.0) ; }
            }
        }
    }
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score += 40.0 ;
        score -= 0.4 * item_size as f64 ;
        score -= 0.05 * mean_residual ;
        score += 50.0 * progress ;
        if fitting_bins_count == 1 { score += 250.0 ; }
        if fitting_bins_count >= 4 { score -= 40.0 ; }
        if next_item_size as f64 > 0.7 * cap { score -= 60.0 ; }
        let new_pr = (bin_capacity - item_size) as f64 ;
        if new_pr > 0.0 && mean_residual > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual } ;
            score += 120.0 * (1.0 - usable) * (0.5 + 0.5 * progress) ;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let sliver = (new_pr - next_item_size as f64) . max (0.0) ;
            if sliver > 0.0 && sliver < 0.04 * cap { score -= 60.0 ; }
        }
        if next_item_size > 0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64 ;
            if r == 0.0 { score -= 200.0 ; }
            else if r <= 5.0 { score -= 150.0 * (1.0 - r / 5.0) ; }
        }
        if next_item_size > 0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap ;
            score += 150.0 * miss . min (0.3) ;
        }
        score -= 8.0 * (1.0 - progress) ;
        if item_size as f64 >= 0.9 * cap { score -= 100.0 ; }
        // two- and three-step exact tiling of the fresh residual
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx ;
                if rem <= 4.0 { score -= 60.0 * (1.0 - rem / 4.0) ; }
            }
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx ;
                if rem <= 3.0 { score -= 40.0 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress) ; }
            }
        }
        // stranded sliver fresh residual below plausible item scale
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 90.0 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress) ;
        }
        // fresh residual near mean scale reduces dead-space risk
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs () ;
            if dev < 0.25 { score -= 35.0 * (1.0 - dev / 0.25) ; }
        }
        // late-stream: prefer fresh bin for large items over fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 40.0 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4) ;
        }
        // many open bins with a big item -> fresh bin is cheap
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 30.0 ; }
        // fresh residual that tiles exactly with the next item leaves zero dead space
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let k = (new_pr / nx . max (1.0)) . floor () ;
            if k >= 1.0 && new_pr - k * nx . max (1.0) == 0.0 {
                score -= 25.0 * (0.5 + 0.5 * progress) ;
            }
        }
        // fresh residual near-mean multiple tiling
        if mean_residual > 1.0 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round () ;
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 18.0 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0) ;
            }
        }
        // very late stream with few fitting bins: fresh bin is safe consolidation
        if progress > 0.85 && fitting_bins_count <= 2 { score += 40.0 * (progress - 0.85) / 0.15 ; }
        // NEW: pair-target lookahead — residual covering next item plus mean scale
        if next_item_size > 0 && mean_residual > 1.0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            let target = nx + mean_residual ;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 30.0 * (1.0 - (new_pr - target) / 2.0) ;
            }
        }
        // NEW: fresh residual just above next item but leaving a tiny tail
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64 ;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr ;
                if dead > 0.0 && dead < 0.05 * cap {
                    score += 30.0 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress) ;
                }
            }
        }
        // NEW: roomy fresh residual with many open bins is cheap early
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 15.0 * (1.0 - progress / 0.5) ;
        }
        // NEW: very large slack fresh bins late are wasteful
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap ;
            if slack > 0.4 { score += 35.0 * ((slack - 0.4) / 0.6) . min (1.0) ; }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * post_residual as f64 ;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 120.0 * (1.0 - 0.3 * progress) ;
        }
    }
    // gentle open-bin pressure early in the stream to avoid bin sprawl
    score += 3.0 * open_bins_count as f64 * (1.0 - progress) / (total_items . max (1) as f64).sqrt () ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are dead weight; penalize them quadratically.
    let min_item = 1u32;
    if post_residual < 10 && post_residual > 0 {
        // gap of 1..9 is nearly unusable -> strong penalty
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // perfect fit: reward heavily
        score -= 60.0;
    }

    // Reward leaving a gap that can exactly host the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new
    // bin only when it truly helps; when few bins open, consolidation wins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Prefer bins tighter than the mean residual (better fits).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    // Penalize the brand-new empty bin candidate mildly, unless the current
    // fit is terrible (large dead space) or it's the only option.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        if bad_fit && open_bins_count > 0 {
            score -= 20.0;
        } else if open_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, squeeze harder: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
