            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-189: fresh-bin residual that tiles with the item AFTER next is
        // unknowable, but a residual equal to the mean residual scale is the
        // most reusable — deepen the variance-alignment reward slightly and
        // extend the band so more reusable fresh bins get credit
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.35 { score -= 0.08 * (1.0 - dev_fresh / 0.35); }
        }
