        // leave a residual close to the next item size promise an immediate
        // tight follow-up fill; reward proportional to closeness
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if item_size as f64 >= 0.4 * cap && new_pr >= nx {
                let r = new_pr - nx;
