                    score -= 0.18 * (1.0 - r / (0.1 * cap)) * (0.6 + 0.4 * progress);
                }
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 30.0; // next item still fits here
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post residual to mean residual across open bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new bin unless residual would otherwise be tiny
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 20.0;
        }
    }

    // Prefer tighter fits overall (relative tightness)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    score
}

