            // proportionally to how close it is to being usable
            if chain_residual > 0.0 && chain_residual < nx {
                let near = 1.0 - chain_residual / nx . max (1.0);
                if near < 0.15 { score += 0.3 * (1.0 - near / 0.15) * (0.5 + 0.5 * progress); }
            }
            // gen-190: reward chain residuals that land within a tight band
            // of the mean residual scale — these are most likely to be
            // consumed by future items, reducing residual variance
            if mean_residual > 1.0 && chain_residual >= mean_residual {
                let dev = ((chain_residual - mean_residual) / mean_residual) . abs ();
                if dev < 0.12 { score -= 0.2 * (1.0 - dev / 0.12) * (0.6 + 0.4 * progress); }
            }
        } else {
