            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-190: dead-space parity gate — when every open fitting bin would
        // leave a residual that strands space just below the next item, prefer
        // the fresh bin whose post-residual clears the next item cleanly
        if fitting_bins_count >= 2 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let slack = (bin_capacity - item_size) as f64;
            if slack < nx && nx - slack <= 4.0 && new_pr >= nx {
                score -= 0.28 * (1.0 - (nx - slack) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
        // gen-190: late-stream exact-fill preference — near the end of the
        // stream there is little time to fill stranded residuals, so a fresh
        // bin whose residual is an exact multiple of the next item is
        // strongly preferred over fragmenting open bins
        if progress > 0.7 && next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx < 1.0 {
                score -= 0.25 * (1.0 - (new_pr - k * nx)) * ((progress - 0.7) / 0.3);
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= 4.0 * nx {
                let rem4 = chain_residual - 4.0 * nx;
                if rem4 <= 4.0 { score -= 0.2 * (1.0 - rem4 / 4.0) * (0.6 + 0.4 * progress); }
            }
            // gen-191: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            // gen-191: dead-space pressure — small stranded chain residuals
            // when few bins are open are costly
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6).min(1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if miss > 2.0 && miss <= 5.0 && progress > 0.5 {
                score += 0.12 * (1.0 - (miss - 2.0) / 3.0) * progress;
            }
            // gen-191: near-miss gap scaled by progress — late in the stream a
            // small gap below the next item is more costly
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    if bin_residual == bin_capacity {
        // NEW BIN candidate: decide when a fresh bin beats a poor fit.
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { nb -= 0.3; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.7 { nb -= 0.25 * (progress - 0.7) / 0.3; }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                    if rem == 0.0 { nb -= 0.3 * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem = new_pr - 2.0 * nx;
                    if rem <= 4.0 { nb -= 0.35 * (1.0 - rem / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem = new_pr - 3.0 * nx;
                    if rem <= 3.0 { nb -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 4.0 * nx {
                    let rem = new_pr - 4.0 * nx;
                    if rem <= 4.0 { nb -= 0.18 * (1.0 - rem / 4.0) * (0.6 + 0.4 * progress); }
                }
                if progress > 0.75 && new_pr - nx <= 0.12 * cap {
                    nb -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap));
                }
            } else {
                let gap = nx - new_pr;
                let miss = gap / cap;
                nb += 0.5 * miss.min(0.3);
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
            }
            if next_item_size == item_size && new_pr >= nx { nb -= 0.15; }
            if (new_pr % nx.max(1.0)).abs() < 1.0 { nb -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5).min(1.0); }
            if mean_residual > 1.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
                if rem < 0.5 && new_pr >= mean_residual && progress > 0.3 && progress < 0.85 {
                    nb -= 0.12 * (1.0 - progress * 0.4);
                }
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left > 0.0 && pair_left < mean_residual * 0.5 {
                    nb += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            nb -= 0.15 * (1.0 - progress / 0.5);
        }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 && next_item_size as f64 > new_pr { nb -= 0.25; }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            nb -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            nb += 0.15;
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        // gen-191: late-stream consolidation — prefer fresh bins for large
        // items that open bins cannot hold tightly
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-191: cap total dead space — penalize fresh bins whose residual
        // is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { nb += 0.8; }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: tiny residuals are unusable for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    } else if post_residual < 20 {
        score += 60.0;
    }

    // Reward residuals large enough to plausibly fit future items
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 40.0;
    }

    // Last-chance bin: avoid opening a new bin if fit is decent
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual < 30 {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if post_residual > 0 && post_residual < 10 {
            score += 200.0; // fresh bin with tiny item -> dead space later
        }
    }

    // Open-bins pressure: prefer consolidating into fewer bins
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: favor bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for tighter bins overall
    score += (bin_capacity as f64 - bin_residual as f64) * -0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items . max (1) as f64;
    let mut score = pr / cap;
    if post_residual == 0 { score -= 8.0; }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 { score -= 0.9; }
            if chain_residual >= 20.0 && chain_residual <= 60.0 { score -= 0.25; }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 { score -= 0.45 * (1.0 - r2 / 15.0); }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 { score -= 0.25 * (1.0 - r3 / 8.0); }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 { score += 0.4 * wasted * (0.4 + 0.6 * progress); }
            let k = (pr / nx) . round ();
            let mult_err = (pr - k * nx) . abs ();
            if k >= 2.0 && mult_err <= 2.0 { score -= 0.35 * (1.0 - mult_err / 2.0); }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 { score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress); }
            }
            if chain_residual >= nx && (chain_residual % nx . max (1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx . max (1.0)) . floor ();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 { score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress); }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem <= 4.0 { score -= 0.18 * (1.0 - rem / 4.0); }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx . max (1.0)) . floor () * nx . max (1.0);
                if rem_t <= 1.0 { score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress); }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual) . floor () * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual == 0.0 { score -= 0.6; }
            let tile_rem = chain_residual % nx . max (1.0);
            if tile_rem == 0.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
            // gen-191: two-step exact tiling — a chain residual that leaves
            // room for exactly two more copies of the next item is a very
            // efficient continuation; reward it more strongly than single tiling
            if chain_residual >= 2.0 * nx {
                let rem2 = chain_residual - 2.0 * nx;
                if rem2 == 0.0 { score -= 0.45 * (0.5 + 0.5 * progress); }
                else if rem2 <= 2.0 { score -= 0.28 * (1.0 - rem2 / 2.0) * (0.6 + 0.4 * progress); }
            }
            // gen-191: dead-space ceiling — chain residuals straddling just
            // above the next item (leaving a thin unusable sliver) strand space
            if chain_residual > nx && chain_residual - nx < 0.03 * cap {
                score += 0.3 * (1.0 - (chain_residual - nx) / (0.03 * cap)) * (0.6 + 0.4 * progress);
            }
        } else {
            let orphan = (pr - mean_residual) . max (0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            let gap = (nx - pr) / cap;
            if gap < 0.25 { score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5); }
            if (nx - pr) <= 3.0 { score += 1.0 * (1.0 - (nx - pr) / 3.0); }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev > 0.6 { score += 0.12 * ((dev - 0.6) / 0.6) . min (1.0); }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            let miss = nx - pr;
            if miss > 3.0 && miss <= 8.0 { score += 0.18 * (1.0 - (miss - 3.0) / 5.0); }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if miss >= 1.0 && miss <= 2.0 { score += 0.35 * (1.0 - (miss - 1.0)); }
            if mean_residual > 0.5 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual) . abs ();
                if dev <= 0.05 { score -= 0.1 * (1.0 - dev / 0.05); }
            }
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-191: near-miss severity ramp — a miss of exactly 1 unit is
            // the worst kind of fragmentation; escalate the penalty band
            if miss >= 1.0 && miss <= 4.0 {
                score += 0.2 * (1.0 - (miss - 1.0) / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz) . round ();
            if k >= 1.0 && (pr - k * isz) . abs () <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // NEW BIN candidate
        score = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        score -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { score += 2.5; }
        if fitting_bins_count >= 4 { score -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { score -= 0.6; }
        if item_size as f64 > 0.5 * cap && next_item_size as f64 <= pr { score -= 0.3; }
        if item_size as f64 >= 0.9 * cap { score -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack < 0.1 { score += 1.3 * (1.0 - slack / 0.1); }
        }
        if progress > 0.7 { score -= 0.25 * (progress - 0.7) / 0.3; }
        let new_pr = (bin_capacity - item_size) as f64;
        if next_item_size as f64 > 0.0 && new_pr >= next_item_size as f64 {
            let r = new_pr - next_item_size as f64;
            if r <= 5.0 { score -= 0.55 * (1.0 - r / 5.0); }
        }
        if next_item_size as f64 > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && 2.0 * nx - new_pr <= 6.0 {
                score -= 0.4 * (1.0 - (2.0 * nx - new_pr) / 6.0);
            }
            if new_pr < nx && nx - new_pr <= 8.0 {
                score += 0.35 * (1.0 - (nx - new_pr) / 8.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { score -= 0.3; }
        if fitting_bins_count >= 2 && fitting_bins_count <= 3 && progress > 0.3 && progress < 0.8 {
            let slack = new_pr / cap;
            if slack > 0.15 && slack < 0.45 { score -= 0.25; }
        }
        if next_item_size as f64 > 0.0 && new_pr > 0.0 && new_pr < next_item_size as f64 {
            let miss = (next_item_size as f64 - new_pr) / cap;
            score += 0.5 * miss . min (0.3);
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            score += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            score -= 0.15;
        }
        if new_pr > 0.0 && mean_residual > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr > nx {
                let rem = (new_pr - (new_pr / nx) . floor () * nx) / cap;
                if rem > 0.0 && rem < 0.03 * cap { score -= 0.3 * (1.0 - rem / (0.03 * cap)); }
            }
        }
        if open_bins_count >= 4 && item_size as f64 > 0.4 * cap && progress < 0.5 {
            score -= 0.15 * (1.0 - progress / 0.5);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let after = new_pr - nx;
                if after >= mean_residual . max (1.0) { score -= 0.18 * (1.0 - progress * 0.4); }
                if after > 0.0 && after < nx * 0.25 { score -= 0.12 * (1.0 - after / (nx * 0.25)); }
            }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { score += 0.6 * (progress - 0.85) / 0.15; }
        if mean_residual > 0.0 && new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let pair_left = new_pr - nx;
                if pair_left < mean_residual * 0.5 && pair_left > 0.0 {
                    score += 0.22 * (1.0 - pair_left / (mean_residual * 0.5)) * (0.6 + 0.4 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let fits_ahead = (new_pr / mean_residual . max (1.0)) . floor ();
            if fits_ahead >= 3.0 { score -= 0.18 * (1.0 - progress * 0.5) . min (1.0); }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 && slack < 0.5 && next_item_size as f64 > new_pr {
                score += 0.2 * (1.0 - (0.5 - slack) / 0.2);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 2.0 {
                let rem = new_pr - k * nx;
                if rem <= 2.0 { score -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let dev = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev <= 0.1 { score -= 0.15 * (1.0 - dev / 0.1); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if (new_pr % nx . max (1.0)) . abs () < 1.0 { score -= 0.2 * (0.5 + 0.5 * progress); }
        }
        if new_pr > 0.0 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr < nx && new_pr < 0.08 * cap {
                score += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
            }
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.55 * cap {
            score -= 0.2 * (item_size as f64 / cap - 0.55);
        }
        if progress > 0.75 && next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx && new_pr - nx <= 0.12 * cap { score -= 0.3 * (1.0 - (new_pr - nx) / (0.12 * cap)); }
        }
        if mean_residual > 0.5 && new_pr > 0.0 {
            let k = (new_pr / mean_residual) . round ();
            if k >= 2.0 && (new_pr - k * mean_residual) . abs () <= 3.0 {
                score -= 0.22 * (1.0 - (new_pr - k * mean_residual) . abs () / 3.0);
            }
        }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.3 { score -= 0.12 * ((slack - 0.3) / 0.7) . min (1.0); }
        }
        if progress < 0.4 && item_size as f64 > 0.4 * cap && mean_residual > 0.0 && new_pr < mean_residual {
            score += 0.15;
        }
        if new_pr > 0.0 && new_pr < 1.0 && progress > 0.5 { score += 0.8; }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                score -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr < nx {
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    score += pen * (0.6 + 0.4 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx {
                let rem = new_pr - 2.0 * nx;
                if rem <= 4.0 { score -= 0.35 * (1.0 - rem / 4.0); }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 3.0 * nx {
                let rem = new_pr - 3.0 * nx;
                if rem <= 3.0 { score -= 0.25 * (1.0 - rem / 3.0) * (0.5 + 0.5 * progress); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size > 0 {
            let best_open_slack = (bin_capacity - item_size) as f64 / cap;
            if best_open_slack > 0.25 {
                score -= 0.3 * ((best_open_slack - 0.25) / 0.75) . min (1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = (bin_capacity - item_size) as f64 / cap;
            if slack > 0.4 { score -= 0.35 * ((slack - 0.4) / 0.6) . min (1.0); }
        }
        if mean_residual > 1.0 && new_pr > 0.0 {
            let rem = new_pr - (new_pr / mean_residual) . floor () * mean_residual;
            if rem <= 1.5 { score -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    score += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let k = (new_pr / nx) . floor ();
            if k >= 1.0 && new_pr - k * nx == 0.0 {
                score -= 0.3 * (0.5 + 0.5 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual) . abs ();
            if dev_fresh < 0.25 { score -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            score += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { score -= 0.5; }
                else if r <= 2.0 { score -= 0.25 * (1.0 - r / 2.0); }
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            score -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        // gen-191: fresh-bin sliver guard — a fresh bin whose residual sits
        // just above the next item strands a tiny dead sliver; penalize more
        // sharply than the existing miss band when the sliver is under 4 units
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let sliver = new_pr - nx;
            if sliver > 0.0 && sliver < 4.0 {
                score += 0.35 * (1.0 - sliver / 4.0) * (0.6 + 0.4 * progress);
            }
        }
        // gen-191: two-copy tiling of fresh residual — residual that exactly
        // fits two copies of the next item guarantees zero dead space across
        // the next two placements; prefer such fresh bins
        if next_item_size > 0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            if new_pr >= 2.0 * nx && new_pr - 2.0 * nx == 0.0 {
                score -= 0.4 * (0.5 + 0.5 * progress);
            }
        }
        // gen-191: late-stream bin-count pressure — with many open bins late
        // in the stream, opening yet another bin usually fragments capacity;
        // dampen fresh-bin attractiveness unless the item is large
        if progress > 0.75 && open_bins_count >= 5 && item_size as f64 <= 0.5 * cap {
            score += 0.2 * (progress - 0.75) / 0.25;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
        } else {
            score += diff * 0.5;
        }
        // If this bin's post_residual can't fit the next item, mild penalty
        if post_residual < next_item_size {
            score += 30.0;
        }
    }

    // Tightness reward: small post_residual relative to capacity
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Penalize new-bin candidate when open bins could fit reasonably
    if bin_residual == bin_capacity {
        score += 200.0 + mean_residual * 0.5;
    }

    // Prefer bins with residuals below mean (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            if chain_residual <= 10.0 {
                score -= 0.9 * (1.0 - chain_residual / 10.0);
            }
            if chain_residual >= 20.0 && chain_residual <= 60.0 {
                score -= 0.25;
            }
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 {
                    score -= 0.45 * (1.0 - r2 / 15.0);
                }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 {
                        score -= 0.25 * (1.0 - r3 / 8.0);
                    }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 {
                score += 0.4 * wasted * (0.4 + 0.6 * progress);
            }
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 {
                score -= 0.35 * (1.0 - mult_err / 2.0);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 {
                    score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress);
                }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 {
                    score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress);
                }
            }
            if chain_residual >= nx {
                let rem_t = chain_residual - (chain_residual / nx.max(1.0)).floor() * nx.max(1.0);
                if rem_t <= 1.0 {
                    score -= 0.15 * (1.0 - rem_t) * (0.4 + 0.6 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual > 2.0 * mean_residual {
                let rem_m = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem_m > 4.0 && rem_m < mean_residual * 0.8 {
                    score += 0.12 * (rem_m / mean_residual) * (0.5 + 0.5 * progress);
                }
            }
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 {
                    score -= 0.18 * (1.0 - rem / 4.0);
                }
            }
            // mutation: exact-fill lookahead — chain residual that exactly
            // consumes the next item leaves zero dead space
            if chain_residual == 0.0 {
                score -= 0.6;
            }
            // mutation: reward chain residuals that tile perfectly with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 {
                score -= 0.2 * (0.5 + 0.5 * progress);
            }
            // mutation: dead-space pressure — small chain residuals strand
            // space when few bins remain open
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            let miss = nx - pr;
            let orphan = (pr - mean_residual).max(0.0);
            score += 0.25 + 0.003 * orphan + 0.55 * progress;
            if miss <= 3.0 {
                score += 1.0 * (1.0 - miss / 3.0);
            } else if miss <= 8.0 {
                score += 0.18 * (1.0 - (miss - 3.0) / 5.0);
            }
            let gap = miss / cap;
            if gap < 0.25 {
                score += 1.8 * (1.0 - gap / 0.25) * (1.0 - progress * 0.5);
            }
            if miss >= 1.0 && miss <= 2.0 {
                score += 0.35 * (1.0 - (miss - 1.0));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 {
                    score += 0.12 * ((dev - 0.6) / 0.6).min(1.0);
                } else if dev <= 0.05 {
                    score -= 0.1 * (1.0 - dev / 0.05);
                }
            }
            if pr > 0.0 && 2.0 * nx > pr && pr + nx <= cap {
                score += 0.1 * (1.0 - (2.0 * nx - pr) / (2.0 * nx));
            }
            // mutation: near-miss gap scaled by progress — later in the
            // stream, a small gap below the next item is more costly
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    score -= 0.1 * progress * (pr / cap);

    if bin_residual == bin_capacity {
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 {
                    // mutation: exact-fill fresh bin — guaranteed perfect follow-up
                    nb -= 0.5;
                } else if r <= 5.0 {
                    nb -= 0.55 * (1.0 - r / 5.0);
                } else if r <= 2.0 {
                    nb -= 0.25 * (1.0 - r / 2.0);
                }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                    if rem == 0.0 { nb -= 0.3 * (0.5 + 0.5 * progress); }
                }
                if new_pr >= 2.0 * nx {
                    let rem2 = new_pr - 2.0 * nx;
                    if rem2 <= 4.0 { nb -= 0.35 * (1.0 - rem2 / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem3 = new_pr - 3.0 * nx;
                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            if new_pr > nx && new_pr < 2.0 * nx {
                let dead = 2.0 * nx - new_pr;
                if dead < 0.05 * cap {
                    nb += 0.3 * (1.0 - dead / (0.05 * cap)) * (0.4 + 0.6 * progress);
                }
            }
            if mean_residual > 1.0 && new_pr > 0.0 {
                let rem = new_pr - (new_pr / mean_residual).floor() * mean_residual;
                if rem <= 1.5 { nb -= 0.25 * (1.0 - rem / 1.5) * (0.5 + 0.5 * progress); }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5); }
        }
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if progress > 0.6 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.25 {
                nb -= 0.3 * ((slack - 0.25) / 0.75).min(1.0) * (progress - 0.6) / 0.4;
            }
        }
        if progress > 0.8 && fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack > 0.4 { nb -= 0.35 * ((slack - 0.4) / 0.6).min(1.0); }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        if next_item_size > 0 && next_item_size == item_size && new_pr >= next_item_size as f64 {
            nb -= 0.15;
        }
        // mutation: dead-space-aware fresh-bin gate — fresh residual near the
        // mean residual scale reduces future dead space
        if fitting_bins_count >= 2 && mean_residual > 1.0 && new_pr > 0.0 {
            let dev_fresh = ((new_pr - mean_residual) / mean_residual).abs();
            if dev_fresh < 0.25 { nb -= 0.2 * (1.0 - dev_fresh / 0.25); }
        }
        // mutation: cap total dead space — penalize fresh bins whose residual
        // is a stranded sliver below the smallest plausible item
        if new_pr > 0.0 && new_pr < 0.04 * cap {
            nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
        }
        // mutation: late-stream consolidation — prefer fresh bins for large
        // items when open bins cannot hold them tightly
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post-residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fill is a jackpot.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or no open bins exist. Compare post_residual against mean residual.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // early on, opening bins is cheap; late, prefer consolidation
        let openness = 1.0 - early;
        score += 25.0 * (1.0 - openness);
        // if existing bins fit poorly (large post_residual), new bin looks better
        score -= (post_residual as f64 - mean_residual).max(0.0) * 0.5;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward placing into bins whose residual is above average (use them up)
        let diff = (bin_residual as f64) - mean_residual;
        score -= 0.3 * diff;
    }

    // Discourage hoarding many open bins with large residuals late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64 * progress;
    }

    // Penalize leaving awkward residuals (small but nonzero dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 8.0;
    }

    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr == nx {
            score -= 5.2;
        } else if pr > nx {
            let chain_residual = pr - nx;
            score -= 1.35 * (1.0 - chain_residual / cap);
            // tight chain residual: strong fill signal
            if chain_residual <= 10.0 {
                score -= 0.9 * (1.0 - chain_residual / 10.0) * 0.5;
            }
            if chain_residual >= 20.0 && chain_residual <= 60.0 {
                score -= 0.25;
            }
            // multi-step lookahead: residual fits next item repeatedly
            if chain_residual > nx {
                let r2 = chain_residual - nx;
                if r2 <= 15.0 {
                    score -= 0.45 * (1.0 - r2 / 15.0);
                }
                if r2 > nx {
                    let r3 = r2 - nx;
                    if r3 <= 8.0 {
                        score -= 0.25 * (1.0 - r3 / 8.0);
                    }
                }
            }
            let wasted = chain_residual / cap;
            if wasted > 0.05 {
                score += 0.4 * wasted * (0.4 + 0.6 * progress);
            }
            // tiling bonus: residual is a near-exact multiple of next item
            let k = (pr / nx).round();
            let mult_err = (pr - k * nx).abs();
            if k >= 2.0 && mult_err <= 2.0 {
                score -= 0.35 * (1.0 - mult_err / 2.0);
            }
            // small chain residual relative to mean residual: likely reusable
            if mean_residual > 0.0 && chain_residual > 0.0 && chain_residual < mean_residual * 0.4 {
                score += 0.3 * (1.0 - chain_residual / (mean_residual * 0.4)) * (0.5 + 0.5 * progress);
            }
            if mean_residual > 0.0 && chain_residual > 0.0 {
                let ratio = chain_residual / mean_residual;
                if ratio < 0.15 {
                    score += 0.22 * (1.0 - ratio / 0.15) * (0.4 + 0.6 * progress);
                }
            }
            if chain_residual >= nx && (chain_residual % nx.max(1.0)) < 1.5 {
                score -= 0.3 * (1.0 - progress * 0.3);
            }
            let kf = (chain_residual / nx.max(1.0)).floor();
            if kf >= 3.0 {
                let rem3 = chain_residual - kf * nx;
                if rem3 <= 3.0 {
                    score -= 0.22 * (1.0 - rem3 / 3.0) * (0.6 + 0.4 * progress);
                }
            }
            // dead-space penalty for slivers
            if chain_residual > 0.0 && chain_residual < 0.06 * cap {
                score += 0.35 * (1.0 - chain_residual / (0.06 * cap));
            }
            // gap band: residual that no future item can absorb cleanly
            if chain_residual > 0.0 && chain_residual < nx {
                let band = nx - chain_residual;
                if band <= 12.0 {
                    score += 0.28 * (1.0 - band / 12.0) * (0.5 + 0.5 * progress);
                }
            }
            // reward chain residuals that tile with the mean residual
            if mean_residual > 0.5 && chain_residual >= mean_residual {
                let rem = chain_residual - (chain_residual / mean_residual).floor() * mean_residual;
                if rem <= 4.0 {
                    score -= 0.18 * (1.0 - rem / 4.0);
                }
            }
            // gen-191: exact tiling of chain residual with next item
            let tile_rem = chain_residual % nx.max(1.0);
            if tile_rem == 0.0 {
                score -= 0.2 * (0.5 + 0.5 * progress);
            }
            if chain_residual == 0.0 {
                score -= 0.6;
            }
            // gen-191: small stranded chain residual with few fitting bins
            if chain_residual > 0.0 && chain_residual <= 6.0 && fitting_bins_count <= 2 {
                score += 0.15 * (1.0 - chain_residual / 6.0) * progress;
            }
        } else {
            // item doesn't leave room for next: penalize near-misses
            let miss = nx - pr;
            score += 0.25 + 0.55 * progress;
            if miss <= 3.0 {
                score += 1.0 * (1.0 - miss / 3.0);
            } else if miss <= 8.0 {
                score += 0.18 * (1.0 - (miss - 3.0) / 5.0);
            }
            // nearly saturated bin: fill it now rather than strand it
            if miss >= 1.0 && miss <= 2.0 {
                score += 0.35 * (1.0 - (miss - 1.0));
            }
            if pr > 0.0 && pr >= 0.5 * nx {
                score -= 0.08 * (pr / nx) * (1.0 - progress);
            }
            // penalize residuals far from the stream's typical leftover scale
            if mean_residual > 0.0 && pr > 0.0 {
                let dev = ((pr - mean_residual) / mean_residual).abs();
                if dev > 0.6 {
                    score += 0.12 * ((dev - 0.6) / 0.6).min(1.0);
                } else if dev <= 0.05 {
                    score -= 0.1 * (1.0 - dev / 0.05);
                }
            }
            // gen-191: near-miss gap scaled by progress
            if miss > 0.0 && miss <= 6.0 {
                score += 0.12 * (1.0 - miss / 6.0) * progress;
            }
            // gen-191: wide gap penalty — a big dead gap below next item
            let gap_frac = miss / cap;
            if gap_frac < 0.25 {
                score += 0.5 * (1.0 - gap_frac / 0.25) * (1.0 - progress * 0.5);
            }
        }
        // dead-space slivers below plausible item sizes
        if pr > 0.0 && pr < 10.0 {
            score += 0.8;
        } else if pr > 0.0 && pr < 25.0 {
            score += 0.25;
        }
        // item-size tiling check
        if pr > 0.0 && item_size > 0 {
            let isz = item_size as f64;
            let k = (pr / isz).round();
            if k >= 1.0 && (pr - k * isz).abs() <= 1.5 && k <= 4.0 {
                score -= 0.2 * (1.0 - progress * 0.3);
            }
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    if mean_residual > 0.0 {
        score -= 0.05 * ((mean_residual - bin_residual as f64) / cap);
    }

    // Mild open-bin pressure early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Mild stream-progress pressure: later in the stream, consolidate more.
    score -= 0.1 * progress * (pr / cap);

    if bin_residual == bin_capacity {
        // NEW-BIN candidate: decide when a fresh bin beats a poor fit.
        let new_pr = (bin_capacity - item_size) as f64;
        let mut nb = 0.9 - 0.4 * progress + 0.02 * open_bins_count as f64;
        nb -= 0.45 * item_size as f64 / cap;
        if fitting_bins_count == 1 { nb += 2.5; }
        if fitting_bins_count >= 4 { nb -= 0.4; }
        if next_item_size as f64 > 0.7 * cap { nb -= 0.6; }
        if item_size as f64 >= 0.9 * cap { nb -= 0.55; }
        if fitting_bins_count >= 2 {
            let slack = new_pr / cap;
            if slack < 0.1 { nb += 1.3 * (1.0 - slack / 0.1); }
            if slack > 0.3 { nb -= 0.12 * ((slack - 0.3) / 0.7).min(1.0); }
        }
        if progress > 0.85 && fitting_bins_count <= 2 { nb += 0.6 * (progress - 0.85) / 0.15; }
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if new_pr >= nx {
                let r = new_pr - nx;
                if r == 0.0 { nb -= 0.5; }
                else if r <= 5.0 { nb -= 0.55 * (1.0 - r / 5.0); }
                else if r <= 2.0 { nb -= 0.25 * (1.0 - r / 2.0); }
                if r >= mean_residual.max(1.0) { nb -= 0.18 * (1.0 - progress * 0.4); }
                if r > 0.0 && r < nx * 0.25 { nb -= 0.12 * (1.0 - r / (nx * 0.25)); }
                let k = (new_pr / nx).floor();
                if k >= 2.0 {
                    let rem = new_pr - k * nx;
                    if rem <= 2.0 { nb -= 0.28 * (1.0 - rem / 2.0) * (0.5 + 0.5 * progress); }
                }
                // pair-packing lookahead: residual hosts next item twice tightly
                if new_pr >= 2.0 * nx {
                    let rem2 = new_pr - 2.0 * nx;
                    if rem2 <= 4.0 { nb -= 0.35 * (1.0 - rem2 / 4.0); }
                }
                if new_pr >= 3.0 * nx {
                    let rem3 = new_pr - 3.0 * nx;
                    if rem3 <= 3.0 { nb -= 0.25 * (1.0 - rem3 / 3.0) * (0.5 + 0.5 * progress); }
                }
            } else {
                let miss = (nx - new_pr) / cap;
                nb += 0.5 * miss.min(0.3);
                if new_pr < 0.08 * cap {
                    nb += 0.45 * (1.0 - new_pr / (0.08 * cap)) * (0.7 + 0.3 * progress);
                }
                // dead gap just below next item: waste now
                let gap = nx - new_pr;
                if gap <= 10.0 {
                    let mut pen = 0.4 * (1.0 - gap / 10.0);
                    if mean_residual > 0.5 && new_pr >= 0.9 * mean_residual { pen *= 0.5; }
                    nb += pen * (0.6 + 0.4 * progress);
                }
            }
            // gen-191: exact-multiple fresh-bin residual — zero future dead space
            if new_pr > 0.0 {
                let k = (new_pr / nx).floor();
                if k >= 1.0 && new_pr - k * nx == 0.0 {
                    nb -= 0.3 * (0.5 + 0.5 * progress);
                }
            }
        }
        if mean_residual > 0.0 && new_pr > 0.0 {
            let usable = if new_pr >= mean_residual { 1.0 } else { new_pr / mean_residual };
            nb += 0.35 * (1.0 - usable) * (0.5 + 0.5 * progress);
            let k = (new_pr / mean_residual).round();
            if k >= 2.0 && (new_pr - k * mean_residual).abs() <= 3.0 {
                nb -= 0.22 * (1.0 - (new_pr - k * mean_residual).abs() / 3.0);
            }
            let dev = ((new_pr - mean_residual) / mean_residual).abs();
            if dev <= 0.1 { nb -= 0.15 * (1.0 - dev / 0.1); }
            let fits_ahead = (new_pr / mean_residual.max(1.0)).floor();
            if fits_ahead >= 3.0 { nb -= 0.18 * (1.0 - progress * 0.5); }
            // gen-191: fresh-bin residual near mean scale reduces dead-space risk
            if fitting_bins_count >= 2 && mean_residual > 1.0 && dev < 0.25 {
                nb -= 0.2 * (1.0 - dev / 0.25);
            }
            // gen-191: cap stranded slivers in fresh bins
            if new_pr < 0.04 * cap {
                nb += 0.5 * (1.0 - new_pr / (0.04 * cap)) * (0.5 + 0.5 * progress);
            }
        }
        // fresh-bin residual that exactly absorbs next item plus mean residual
        if next_item_size > 0 && mean_residual > 0.0 && new_pr > 0.0 {
            let nx = next_item_size as f64;
            let target = nx + mean_residual;
            if new_pr >= target && new_pr - target <= 2.0 {
                nb -= 0.3 * (1.0 - (new_pr - target) / 2.0);
            }
        }
        if open_bins_count >= 6 && item_size as f64 > 0.6 * cap { nb -= 0.3; }
        // gen-191: late-stream fresh-bin preference for large items over
        // fragmenting open bins
        if progress > 0.6 && fitting_bins_count >= 2 && item_size as f64 > 0.45 * cap {
            nb -= 0.22 * (item_size as f64 / cap - 0.45) * ((progress - 0.6) / 0.4);
        }
        score = score.min(nb);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 0.2 * pr / cap;
        if (next_item_size - post_residual) as f64 <= 4.0 {
            score += 0.65 * (1.0 - progress * 0.3);
        }
    }

    score
}
